  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p18', 9, 18, 'Bài 12a. Sử dụng hàm IF (mục 1)', 'Chủ đề 4. Ứng dụng tin học - a. Sử dụng bảng tính điện tử nâng cao', '1. Hàm IF (Quy tắc logic rẽ nhánh điều kiện).', FALSE, 'NLC (3.4.TC2) & NLE (5.2.TC2): Xây dựng biểu thức điều kiện logic để tự động hóa việc đánh giá và cảnh báo dữ liệu trên bảng tính. · AI.4 (9.D1.1): Hiểu nguyên lí ra quyết định tự động dựa trên quy tắc điều kiện (`Rule-based Decision`) — nền tảng của hệ thống hỗ trợ quyết định và AI.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 18: Bài 12a. Sử dụng hàm IF (mục 1)", "phase1_khoi_dong": "Theo quy tắc quản lí tài chính gia đình 50-30-20 (SGK trang 48), tổng chi tiêu cho các ''Nhu cầu thiết yếu'' (Ở, Ăn, Học tập, Y tế, Đi lại) không nên vượt quá 50% tổng thu nhập, và nhu cầu ''Mong muốn/Giải trí'' không quá 30%, dành 20% để ''Tiết kiệm''. Mẹ muốn bảng tính tự động hiện dòng chữ `''Nhiều quá''` nếu tỉ lệ chi vượt mức quy định, ngược lại thì hiện `''Hợp lí''`.", "phase2_kham_pha": "Đọc SGK 1. Hàm IF (Quy tắc logic rẽ nhánh điều kiện)., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Theo quy tắc quản lí tài chính gia đình 50-30-20 (SGK trang 48), tổng chi tiêu cho các ''Nhu cầu thiết yếu'' (Ở, Ăn, Học tập, Y tế, Đi lại) không nên vượt quá 50% tổng thu nhập, và nhu cầu ''Mong muốn/Giải trí'' không quá 30%, dành 20% để ''Tiết kiệm''. Mẹ muốn bảng tính tự động hiện dòng chữ `''Nhiều quá''` nếu tỉ lệ chi vượt mức quy định, ngược lại thì hiện `''Hợp lí''`.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["IF", "value_if_false", "ngoặc kép", "Tham số 1: `logical_test`", "Tham số 2: `value_if_true`", "Tham số 3: `value_if_false`"], "dragDrop": {"bucketA": "Ba tham số của hàm điều kiện IF", "bucketB": "Quy tắc quản lí tài chính 50-30-20 trong SGK Tin học 9", "items": [{"id": "G9_T18_DD1", "text": "`logical_test`: Biểu thức điều kiện kiểm tra (ví dụ `N3>50%` hoặc `B3>C3`)", "correctBox": "A", "targetLabel": "Ba tham số của hàm điều kiện IF", "points": 0.25}, {"id": "G9_T18_DD2", "text": "`value_if_true` (giá trị trả về khi điều kiện Đúng) và `value_if_false` (giá trị trả về khi điều kiện Sai)", "correctBox": "A", "targetLabel": "Ba tham số của hàm điều kiện IF", "points": 0.25}, {"id": "G9_T18_DD3", "text": "50% thu nhập dành cho Nhu cầu thiết yếu (`Needs`: Ăn, Ở, Đi lại, Học tập, Y tế)", "correctBox": "B", "targetLabel": "Quy tắc quản lí tài chính 50-30-20 trong SGK Tin học 9", "points": 0.25}, {"id": "G9_T18_DD4", "text": "30% thu nhập dành cho Mong muốn cá nhân (`Wants`: Giải trí, Du lịch, Mua sắm) và 20% dành cho Tiết kiệm (`Savings`)", "correctBox": "B", "targetLabel": "Quy tắc quản lí tài chính 50-30-20 trong SGK Tin học 9", "points": 0.25}]}, "fillBlanks": [{"statement": "Hàm [___] trong Excel dùng để kiểm tra một điều kiện (`logical_test`): nếu điều kiện đúng thì trả về một giá trị, nếu điều kiện sai thì trả về một giá trị khác.", "correctAnswer": "IF", "filledSentence": "Hàm «IF» trong Excel dùng để kiểm tra một điều kiện (`logical_test`): nếu điều kiện đúng thì trả về một giá trị, nếu điều kiện sai thì trả về một giá trị khác."}, {"statement": "Cú pháp chuẩn của hàm điều kiện là: `=IF(logical_test, [value_if_true], [[___]])`.", "correctAnswer": "value_if_false", "filledSentence": "Cú pháp chuẩn của hàm điều kiện là: `=IF(logical_test, [value_if_true], [«value_if_false»])`."}, {"statement": "Khi giá trị trả về trong `value_if_true` hoặc `value_if_false` là một chuỗi văn bản (ví dụ `''Nhiều quá''`, `''Hợp lí''`), ta bắt buộc phải đặt chuỗi văn bản đó trong cặp dấu [___].", "correctAnswer": "ngoặc kép", "filledSentence": "Khi giá trị trả về trong `value_if_true` hoặc `value_if_false` là một chuỗi văn bản (ví dụ `''Nhiều quá''`, `''Hợp lí''`), ta bắt buộc phải đặt chuỗi văn bản đó trong cặp dấu «ngoặc kép»."}], "matchingPairs": [{"left": "Tham số 1: `logical_test`", "right": "Biểu thức lôgic sử dụng các phép toán so sánh (`=`, `>`, `<`, `>=`, `<=`, `<>`)"}, {"left": "Tham số 2: `value_if_true`", "right": "Kết quả hàm `IF` trả về nếu `logical_test` có giá trị Đúng (`TRUE`)"}, {"left": "Tham số 3: `value_if_false`", "right": "Kết quả hàm `IF` trả về nếu `logical_test` có giá trị Sai (`FALSE`)"}], "discussionPrompt": "Theo quy tắc quản lí tài chính gia đình 50-30-20 (SGK trang 48), tổng chi tiêu cho các ''Nhu cầu thiết yếu'' (Ở, Ăn, Học tập, Y tế, Đi lại) không nên vượt quá 50% tổng thu nhập, và nhu cầu ''Mong muốn/Giải trí'' không quá 30%, dành 20% để ''Tiết kiệm''. Mẹ muốn bảng tính tự động hiện dòng chữ `''Nhiều quá''` nếu tỉ lệ chi vượt mức quy định, ngược lại thì hiện `''Hợp lí''`."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 18: Bài 12a. Sử dụng hàm IF (mục 1)", "description": "• Nhiệm vụ 1: Viết công thức hàm `IF` cho 3 bài toán thực tế: (1) Kiểm tra chi tiêu thiết yếu `N3` so với ngưỡng `50%`; (2) Kiểm tra `Tổng chi <= Tổng thu` để báo `''Cân đối''` hay `''Thâm hụt''`; (3) Xét kết quả tiết kiệm `>= 20%`.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.2.TC2)]: Vẽ sơ đồ khối biểu diễn luồng kiểm tra của hàm `IF` lồng nhau đánh giá 3 mức chi tiêu (`Ít quá`, `Hợp lí`, `Nhiều quá`).\n• Nhiệm vụ 3: [Tích hợp AI - AI.4 (9.D1.1)]: Liên hệ cấu trúc hàm `IF(logical_test, value_if_true, value_if_false)` trong Excel với cấu trúc rẽ nhánh `nếu ... thì ... nếu không ...` trong lập trình Scratch và hệ thống cảnh báo thông minh.", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p19', 9, 19, 'Bài 12a. Sử dụng hàm IF (mục 2 – thực hành)', 'Chủ đề 4. Ứng dụng tin học - a. Sử dụng bảng tính điện tử nâng cao', '2. Thực hành: Sử dụng hàm IF trong bảng tính.', TRUE, 'NLC (3.1.TC2): Thực hành xây dựng bảng phân tích quy tắc tài chính 50-30-20 tự động cảnh báo bằng hàm `IF`. · AI.2 (9.C2.1): Thiết lập thuật toán phân loại dữ liệu đầu vào thành các nhãn đánh giá đầu ra dựa trên ngưỡng điều kiện.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 19: Bài 12a. Sử dụng hàm IF (mục 2 – thực hành)", "phase1_khoi_dong": "Trên trang tính `Chi` của tệp `TaiChinhGiaDinh.xlsx` (SGK trang 50), nhóm em đã gom các khoản chi thành 2 nhóm: ''Nhu cầu thiết yếu'' (giới hạn 50% tổng thu) và ''Mong muốn'' (giới hạn 30% tổng thu). Cô giáo yêu cầu lập công thức tại cột `Đánh giá` bằng cả cách dùng 1 hàm `IF` (2 mức) và 2 hàm `IF` lồng nhau (3 mức).", "phase2_kham_pha": "Đọc SGK 2. Thực hành: Sử dụng hàm IF trong bảng tính., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Trên trang tính `Chi` của tệp `TaiChinhGiaDinh.xlsx` (SGK trang 50), nhóm em đã gom các khoản chi thành 2 nhóm: ''Nhu cầu thiết yếu'' (giới hạn 50% tổng thu) và ''Mong muốn'' (giới hạn 30% tổng thu). Cô giáo yêu cầu lập công thức tại cột `Đánh giá` bằng cả cách dùng 1 hàm `IF` (2 mức) và 2 hàm `IF` lồng nhau (3 mức).", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["sao chép", "hai (2)", "<>", "`=IF(N3>M3, \"Nhiều quá\", \"Hợp lí\")`"], "dragDrop": {"bucketA": "Công thức hàm IF tham chiếu linh hoạt tới ô ngưỡng chuẩn", "bucketB": "Công thức hàm IF lồng nhau phân loại 3 mức đánh giá", "items": [{"id": "G9_T19_DD1", "text": "Tại ô `O3` nhập `=IF(N3>M3, \"Nhiều quá\", \"Hợp lí\")` (với `M3` là ô chứa mức chuẩn `50%` và `M4` là `30%`)", "correctBox": "A", "targetLabel": "Công thức hàm IF tham chiếu linh hoạt tới ô ngưỡng chuẩn", "points": 0.25}, {"id": "G9_T19_DD2", "text": "Khi sao chép từ `O3` xuống `O4`, địa chỉ tương đối `N3>M3` tự động chuyển thành `N4>M4`", "correctBox": "A", "targetLabel": "Công thức hàm IF tham chiếu linh hoạt tới ô ngưỡng chuẩn", "points": 0.25}, {"id": "G9_T19_DD3", "text": "Tại ô `O3` nhập `=IF(N3>M3, \"Nhiều quá\", IF(N3<M3, \"Ít quá\", \"Hợp lí\"))`", "correctBox": "B", "targetLabel": "Công thức hàm IF lồng nhau phân loại 3 mức đánh giá", "points": 0.25}, {"id": "G9_T19_DD4", "text": "Đảm bảo đóng đủ 2 dấu ngoặc đơn `))` ở cuối công thức khi có 2 hàm `IF` lồng nhau", "correctBox": "B", "targetLabel": "Công thức hàm IF lồng nhau phân loại 3 mức đánh giá", "points": 0.25}]}, "fillBlanks": [{"statement": "Khi lưu ngưỡng tỉ lệ quy định (`50%`, `30%`) vào cột `M` (`M3`, `M4`) và tỉ lệ thực tế vào cột `N` (`N3`, `N4`), việc viết điều kiện `N3>M3` trong hàm `IF` giúp dễ dàng [___] công thức từ dòng 3 xuống dòng 4.", "correctAnswer": "sao chép", "filledSentence": "Khi lưu ngưỡng tỉ lệ quy định (`50%`, `30%`) vào cột `M` (`M3`, `M4`) và tỉ lệ thực tế vào cột `N` (`N3`, `N4`), việc viết điều kiện `N3>M3` trong hàm `IF` giúp dễ dàng «sao chép» công thức từ dòng 3 xuống dòng 4."}, {"statement": "Khi sử dụng 2 hàm `IF` lồng nhau trong cùng một công thức, ở cuối công thức phải có [___] dấu ngoặc đóng `))` tương ứng với 2 hàm `IF`.", "correctAnswer": "hai (2)", "filledSentence": "Khi sử dụng 2 hàm `IF` lồng nhau trong cùng một công thức, ở cuối công thức phải có «hai (2)» dấu ngoặc đóng `))` tương ứng với 2 hàm `IF`."}, {"statement": "Phép toán so sánh ''khác nhau'' trong công thức Excel được viết bằng cặp kí hiệu [___].", "correctAnswer": "<>", "filledSentence": "Phép toán so sánh ''khác nhau'' trong công thức Excel được viết bằng cặp kí hiệu «<>»."}], "matchingPairs": [{"left": "`=IF(N3>M3, \"Nhiều quá\", \"Hợp lí\")`", "right": "Đánh giá 2 trạng thái: vượt ngưỡng quy định (`Nhiều quá`) hoặc trong ngưỡng cho phép (`Hợp lí`)"}, {"left": "`=IF(N3>M3, \"Nhiều quá\", IF(N3<M3, \"Ít hơn\", \"Đúng mức\"))`", "right": "Đánh giá chi tiết 3 trạng thái: lớn hơn ngưỡng, nhỏ hơn ngưỡng và bằng đúng ngưỡng"}, {"left": "Định dạng có điều kiện (`Conditional Formatting`)", "right": "Tự động tô màu nổi bật (ví dụ nền đỏ chữ đậm) cho những ô có kết quả đánh giá là `''Nhiều quá''`"}], "discussionPrompt": "Trên trang tính `Chi` của tệp `TaiChinhGiaDinh.xlsx` (SGK trang 50), nhóm em đã gom các khoản chi thành 2 nhóm: ''Nhu cầu thiết yếu'' (giới hạn 50% tổng thu) và ''Mong muốn'' (giới hạn 30% tổng thu). Cô giáo yêu cầu lập công thức tại cột `Đánh giá` bằng cả cách dùng 1 hàm `IF` (2 mức) và 2 hàm `IF` lồng nhau (3 mức)."}'::jsonb, '{"title": "Thực hành Tiết 19: Bài 12a. Sử dụng hàm IF (mục 2 – Thực hành)", "sampleFileName": "Mau_ThucHanh_Tiet_19.docx", "sampleFileUrl": "/templates/thuchanh_k9_tiet19.dat", "steps": ["Thực hành trên tệp `TaiChinhGiaDinh.xlsx` (SGK trang 50–51): lập bảng tổng hợp theo quy tắc 50-30-20 trên trang tính `Chi` và sử dụng hàm `IF` (cả dạng đơn và dạng lồng nhau) tại cột `Đánh giá`.", "[Tích hợp NLS - NLC (3.1.TC2)]: Kết hợp hàm `IF` với `Conditional Formatting` để tự động tô màu xanh lá cho trạng thái `''Hợp lí''` và màu cam/đỏ cho trạng thái `''Nhiều quá''`.", "[Tích hợp AI - AI.2 (9.C2.1)]: Nhờ trợ lí AI thiết kế một công thức hàm `IF` lồng 3 cấp để đánh giá mức Tiết kiệm cuối tháng (`>= 20%`: `''Tốt''`; từ `10%` đến `< 20%`: `''Cần cố gắng''`; `< 10%`: `''Báo động''`)."], "rubric": [{"criterion": "Hoàn thành chính xác yêu cầu kỹ thuật: Thực hành trên tệp `TaiChinhGiaDinh.xlsx` (SGK trang 50–51): lập bảng tổng hợp theo quy tắc 50-30-20 trên trang tính `Chi` và sử dụng hàm `IF` (cả dạng đơn và dạng lồng nhau) tại cột `Đánh giá`.", "maxPoints": 5.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Tích hợp Năng lực số: [Tích hợp NLS - NLC (3.1.TC2)]: Kết hợp hàm `IF` với `Conditional Formatting` để tự động tô màu xanh lá cho trạng thái `''Hợp lí''` và màu cam/đỏ cho trạng thái `''Nhiều quá''`.", "maxPoints": 3.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Vận dụng AI có trách nhiệm & đặt tên tệp đúng chuẩn: [Tích hợp AI - AI.2 (9.C2.1)]: Nhờ trợ lí AI thiết kế một công thức hàm `IF` lồng 3 cấp để đánh giá mức Tiết kiệm cuối tháng (`>= 20%`: `''Tốt''`; từ `10%` đến `< 20%`: `''Cần cố gắng''`; `< 10%`: `''Báo động''`).", "maxPoints": 2.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}]}'::jsonb, '{"title": "Bài tập về nhà Tiết 19: Bài 12a. Sử dụng hàm IF (mục 2 – thực hành)", "description": "• Nhiệm vụ 1: Thực hành trên tệp `TaiChinhGiaDinh.xlsx` (SGK trang 50–51): lập bảng tổng hợp theo quy tắc 50-30-20 trên trang tính `Chi` và sử dụng hàm `IF` (cả dạng đơn và dạng lồng nhau) tại cột `Đánh giá`.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.1.TC2)]: Kết hợp hàm `IF` với `Conditional Formatting` để tự động tô màu xanh lá cho trạng thái `''Hợp lí''` và màu cam/đỏ cho trạng thái `''Nhiều quá''`.\n• Nhiệm vụ 3: [Tích hợp AI - AI.2 (9.C2.1)]: Nhờ trợ lí AI thiết kế một công thức hàm `IF` lồng 3 cấp để đánh giá mức Tiết kiệm cuối tháng (`>= 20%`: `''Tốt''`; từ `10%` đến `< 20%`: `''Cần cố gắng''`; `< 10%`: `''Báo động''`).", "acceptedFormats": ["image", "xlsx", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p20', 9, 20, 'Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 1)', 'Chủ đề 4. Ứng dụng tin học - a. Sử dụng bảng tính điện tử nâng cao', '1. Trang tính tổng hợp liên kết dữ liệu.', FALSE, 'NLA (1.3.TC2) & NLC (3.2.TC2): Tổ chức, kết nối và tích hợp dữ liệu động giữa nhiều trang tính trong cùng một sổ tính. · AI.2 (9.C3.1): Tối ưu hóa kiến trúc dữ liệu liên kết nhiều bảng (Multi-sheet / Relational Data) phục vụ bảng điều khiển phân tích tổng thể.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 20: Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 1)", "phase1_khoi_dong": "Trong tệp `TaiChinhGiaDinh.xlsx`, dữ liệu `Tổng thu` đang nằm ở ô `H7` của trang tính `Thu`, còn dữ liệu `Tổng chi` lại nằm ở ô `H9` của trang tính `Chi`. Bây giờ bố mẹ muốn có một trang tính đầu tiên tên là `Tổng hợp` để tự động lấy `Tổng thu` và `Tổng chi` từ hai trang tính kia sang so sánh và tính số tiền `Tiết kiệm`.", "phase2_kham_pha": "Đọc SGK 1. Trang tính tổng hợp liên kết dữ liệu., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Trong tệp `TaiChinhGiaDinh.xlsx`, dữ liệu `Tổng thu` đang nằm ở ô `H7` của trang tính `Thu`, còn dữ liệu `Tổng chi` lại nằm ở ô `H9` của trang tính `Chi`. Bây giờ bố mẹ muốn có một trang tính đầu tiên tên là `Tổng hợp` để tự động lấy `Tổng thu` và `Tổng chi` từ hai trang tính kia sang so sánh và tính số tiền `Tiết kiệm`.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["!", "nháy đơn ('' '')", "=B4-B5", "`=Thu!H7`", "`=Chi!H9`"], "dragDrop": {"bucketA": "Cú pháp tham chiếu liên trang tính đúng chuẩn", "bucketB": "Cách làm sai hoặc thiếu tính liên kết động", "items": [{"id": "G9_T20_DD1", "text": "Sử dụng dấu chấm than `!` ngăn cách giữa tên trang tính và địa chỉ ô: `=Thu!H7`, `=Chi!H9`", "correctBox": "A", "targetLabel": "Cú pháp tham chiếu liên trang tính đúng chuẩn", "points": 0.25}, {"id": "G9_T20_DD2", "text": "Nếu tên trang tính có dấu cách thì đặt tên trang tính trong cặp dấu nháy đơn: `=''Tổng thu''!H7`", "correctBox": "A", "targetLabel": "Cú pháp tham chiếu liên trang tính đúng chuẩn", "points": 0.25}, {"id": "G9_T20_DD3", "text": "Gõ tay con số tĩnh sang trang `Tổng hợp` khiến số liệu không tự cập nhật khi trang `Thu`, `Chi` thay đổi", "correctBox": "B", "targetLabel": "Cách làm sai hoặc thiếu tính liên kết động", "points": 0.25}, {"id": "G9_T20_DD4", "text": "Dùng dấu chấm `.` hoặc dấu gạch chéo `/` thay cho dấu chấm than `!` giữa tên trang tính và địa chỉ ô", "correctBox": "B", "targetLabel": "Cách làm sai hoặc thiếu tính liên kết động", "points": 0.25}]}, "fillBlanks": [{"statement": "Để tham chiếu đến một ô tính nằm ở trang tính khác trong cùng sổ tính Excel, ta viết theo cú pháp: `=Tên_trang_tính[___]Địa_chỉ_ô` (dấu chấm than ở giữa).", "correctAnswer": "!", "filledSentence": "Để tham chiếu đến một ô tính nằm ở trang tính khác trong cùng sổ tính Excel, ta viết theo cú pháp: `=Tên_trang_tính«!»Địa_chỉ_ô` (dấu chấm than ở giữa)."}, {"statement": "Nếu tên của trang tính cần tham chiếu có chứa khoảng trắng (dấu cách, ví dụ trang tính `Thu nhập`), thì tên trang tính phải được đặt trong cặp dấu [___] trước dấu chấm than (ví dụ `=''Thu nhập''!H7`).", "correctAnswer": "nháy đơn ('' '')", "filledSentence": "Nếu tên của trang tính cần tham chiếu có chứa khoảng trắng (dấu cách, ví dụ trang tính `Thu nhập`), thì tên trang tính phải được đặt trong cặp dấu «nháy đơn ('' '')» trước dấu chấm than (ví dụ `=''Thu nhập''!H7`)."}, {"statement": "Trên trang tính `Tổng hợp` (SGK trang 52), sau khi lấy được `Tổng thu` tại ô `B4` (`=Thu!H7`) và `Tổng chi` tại ô `B5` (`=Chi!H9`), số tiền `Tiết kiệm` (Chênh lệch thu – chi) tại ô `B6` được tính bằng công thức [___].", "correctAnswer": "=B4-B5", "filledSentence": "Trên trang tính `Tổng hợp` (SGK trang 52), sau khi lấy được `Tổng thu` tại ô `B4` (`=Thu!H7`) và `Tổng chi` tại ô `B5` (`=Chi!H9`), số tiền `Tiết kiệm` (Chênh lệch thu – chi) tại ô `B6` được tính bằng công thức «=B4-B5»."}], "matchingPairs": [{"left": "`=Thu!H7`", "right": "Lấy giá trị của ô `H7` nằm trên trang tính có tên là `Thu`"}, {"left": "`=Chi!H9`", "right": "Lấy giá trị của ô `H9` nằm trên trang tính có tên là `Chi`"}, {"left": "`=IF(B6<0, \"Chi vượt thu\", IF(B6/B4<20%, \"Tiết kiệm ít\", \"Đạt mục tiêu\"))`", "right": "Đánh giá tự động tình trạng cân đối thu chi và tỉ lệ tiết kiệm trên trang tính `Tổng hợp`"}], "discussionPrompt": "Trong tệp `TaiChinhGiaDinh.xlsx`, dữ liệu `Tổng thu` đang nằm ở ô `H7` của trang tính `Thu`, còn dữ liệu `Tổng chi` lại nằm ở ô `H9` của trang tính `Chi`. Bây giờ bố mẹ muốn có một trang tính đầu tiên tên là `Tổng hợp` để tự động lấy `Tổng thu` và `Tổng chi` từ hai trang tính kia sang so sánh và tính số tiền `Tiết kiệm`."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 20: Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 1)", "description": "• Nhiệm vụ 1: Thiết kế sơ đồ liên kết dữ liệu giữa 3 trang tính (`Thu` -> `Chi` -> `Tổng hợp`) trong sổ tính `TaiChinhGiaDinh.xlsx`, ghi rõ địa chỉ ô nguồn và công thức tại ô đích.\n• Nhiệm vụ 2: [Tích hợp NLS - NLA (1.3.TC2) & NLC (3.2.TC2)]: Viết bộ công thức hoàn chỉnh cho trang tính `Tổng hợp` gồm: `Tổng thu` (`=Thu!H7`), `Tổng chi` (`=Chi!H9`), `Tiết kiệm` (`=B4-B5`), `Tỉ lệ tiết kiệm %` (`=B6/B4`) và `Đánh giá cân đối` (dùng hàm `IF`).\n• Nhiệm vụ 3: [Tích hợp AI - AI.2 (9.C3.1)]: Hỏi trợ lí AI cách sử dụng hàm `SUM` tham chiếu xuyên qua nhiều trang tính (ví dụ tính tổng thu của cả 12 trang tính từ `Thang1` đến `Thang12` bằng cú pháp `=SUM(Thang1:Thang12!H7)`).", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p21', 9, 21, 'Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 2 – Thực hành)', 'Chủ đề 4. Ứng dụng tin học - a. Sử dụng bảng tính điện tử nâng cao', '2. Thực hành: Hoàn thiện bảng tính quản lí tài chính gia đình.', TRUE, 'NLC (3.2.TC2) & NLE (5.3.TC2): Tích hợp công thức liên trang tính, hàm điều kiện và biểu đồ trực quan để hoàn thiện sản phẩm quản lí tài chính số. · AI.1 (9.A3.1): Thực hành tự đặt mục tiêu tài chính cá nhân/gia đình và sử dụng công cụ số kết hợp AI để phân tích, điều chỉnh kế hoạch chi tiêu.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 21: Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 2 – Thực hành)", "phase1_khoi_dong": "Sổ tính `TaiChinhGiaDinh.xlsx` của nhóm em đã có số liệu ở trang `Thu`, trang `Chi` và bảng tóm tắt ở trang `Tổng hợp`. Để bố mẹ nhìn vào biết ngay tỉ trọng từng khoản thu/chi và so sánh tương quan Thu – Chi – Tiết kiệm, nhóm cần bổ sung các biểu đồ trực quan và hoàn thiện định dạng.", "phase2_kham_pha": "Đọc SGK 2. Thực hành: Hoàn thiện bảng tính quản lí tài chính gia đình., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Sổ tính `TaiChinhGiaDinh.xlsx` của nhóm em đã có số liệu ở trang `Thu`, trang `Chi` và bảng tóm tắt ở trang `Tổng hợp`. Để bố mẹ nhìn vào biết ngay tỉ trọng từng khoản thu/chi và so sánh tương quan Thu – Chi – Tiết kiệm, nhóm cần bổ sung các biểu đồ trực quan và hoàn thiện định dạng.", "xpReward": 50, "timeLimitMin": 15, "wordBank": [",", "Ctrl", "Mong muốn", "Trang tính `Thu`", "Trang tính `Chi`", "Trang tính `Tổng hợp`"], "dragDrop": {"bucketA": "Hoàn thiện công thức và định dạng dữ liệu số", "bucketB": "Trực quan hóa bằng Biểu đồ và Phân tích quyết định", "items": [{"id": "G9_T21_DD1", "text": "Sử dụng định dạng phân cách hàng nghìn (`Number` / `Accounting`) cho toàn bộ các cột Số tiền", "correctBox": "A", "targetLabel": "Hoàn thiện công thức và định dạng dữ liệu số", "points": 0.25}, {"id": "G9_T21_DD2", "text": "Thiết lập công thức tham chiếu liên trang tính `=Thu!H7`, `=Chi!H9` và hàm `IF` đánh giá trên trang `Tổng hợp`", "correctBox": "A", "targetLabel": "Hoàn thiện công thức và định dạng dữ liệu số", "points": 0.25}, {"id": "G9_T21_DD3", "text": "Vẽ biểu đồ hình quạt tròn (`Pie Chart`) biểu diễn cơ cấu tỉ lệ % các khoản thu và các khoản chi", "correctBox": "B", "targetLabel": "Trực quan hóa bằng Biểu đồ và Phân tích quyết định", "points": 0.25}, {"id": "G9_T21_DD4", "text": "Vẽ biểu đồ cột (`Column Chart`) so sánh Tổng thu, Tổng chi và đề xuất phương án điều chỉnh chi tiêu", "correctBox": "B", "targetLabel": "Trực quan hóa bằng Biểu đồ và Phân tích quyết định", "points": 0.25}]}, "fillBlanks": [{"statement": "Để các con số tiền tệ lớn (như `15000000`) dễ đọc hơn thành `15,000,000`, ta chọn vùng số liệu và sử dụng nút lệnh định dạng phân cách hàng nghìn [___] (`Comma Style`) trong nhóm `Number` (thẻ `Home`).", "correctAnswer": ",", "filledSentence": "Để các con số tiền tệ lớn (như `15000000`) dễ đọc hơn thành `15,000,000`, ta chọn vùng số liệu và sử dụng nút lệnh định dạng phân cách hàng nghìn «,» (`Comma Style`) trong nhóm `Number` (thẻ `Home`)."}, {"statement": "Khi vẽ biểu đồ hình quạt tròn thể hiện cơ cấu các khoản chi từ vùng `F3:F8` (Tên khoản chi) và `H3:H8` (Tổng tiền), ta nhấn giữ phím [___] để chọn hai vùng rời nhau và không chọn dòng Tổng cộng `H9`.", "correctAnswer": "Ctrl", "filledSentence": "Khi vẽ biểu đồ hình quạt tròn thể hiện cơ cấu các khoản chi từ vùng `F3:F8` (Tên khoản chi) và `H3:H8` (Tổng tiền), ta nhấn giữ phím «Ctrl» để chọn hai vùng rời nhau và không chọn dòng Tổng cộng `H9`."}, {"statement": "Nếu trên trang `Tổng hợp`, ô `Tiết kiệm` (`=B4-B5`) nhỏ hơn 20% `Tổng thu`, gia đình cần xem lại biểu đồ cơ cấu chi tiêu để cắt giảm các khoản thuộc nhóm [___] cá nhân.", "correctAnswer": "Mong muốn", "filledSentence": "Nếu trên trang `Tổng hợp`, ô `Tiết kiệm` (`=B4-B5`) nhỏ hơn 20% `Tổng thu`, gia đình cần xem lại biểu đồ cơ cấu chi tiêu để cắt giảm các khoản thuộc nhóm «Mong muốn» cá nhân."}], "matchingPairs": [{"left": "Trang tính `Thu`", "right": "Ghi chép nhật ký các khoản thu (`Data Validation`), thống kê bằng `COUNTIF`, `SUMIF` và vẽ biểu đồ quạt tròn cơ cấu thu"}, {"left": "Trang tính `Chi`", "right": "Ghi chép nhật ký chi tiêu, thống kê `COUNTIF`, `SUMIF`, đánh giá quy tắc 50-30-20 bằng hàm `IF` và vẽ biểu đồ cơ cấu chi"}, {"left": "Trang tính `Tổng hợp`", "right": "Liên kết `Tổng thu` (`=Thu!H7`), `Tổng chi` (`=Chi!H9`), tính `Tiết kiệm`, đánh giá bằng hàm `IF` và vẽ biểu đồ cột cân đối"}], "discussionPrompt": "Sổ tính `TaiChinhGiaDinh.xlsx` của nhóm em đã có số liệu ở trang `Thu`, trang `Chi` và bảng tóm tắt ở trang `Tổng hợp`. Để bố mẹ nhìn vào biết ngay tỉ trọng từng khoản thu/chi và so sánh tương quan Thu – Chi – Tiết kiệm, nhóm cần bổ sung các biểu đồ trực quan và hoàn thiện định dạng."}'::jsonb, '{"title": "Thực hành Tiết 21: Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 2 – Thực hành)", "sampleFileName": "BaiTap_Tiet_21_Lop_9.xlsx", "sampleFileUrl": "/templates/thuchanh_k9_tiet21.dat", "steps": ["Thực hành hoàn thiện trọn vẹn tệp `TaiChinhGiaDinh.xlsx` theo yêu cầu SGK trang 53–54, bổ sung biểu đồ cơ cấu thu, biểu đồ cơ cấu chi và biểu đồ cân đối thu – chi trên trang `Tổng hợp`.", "[Tích hợp NLS - NLC (3.2.TC2) & NLE (5.3.TC2)]: Dựa trên kết quả trang `Tổng hợp` và trang `Chi` vừa làm, hãy viết báo cáo ngắn (4 dòng) đề xuất kế hoạch điều chỉnh chi tiêu tháng tới để đạt mục tiêu tiết kiệm tối thiểu 20%.", "[Tích hợp AI - AI.1 (9.A3.1)]: Nhờ trợ lí AI đóng vai ''Chuyên gia tư vấn tài chính gia đình'', phân tích bảng tổng hợp thu chi của nhóm em và gợi ý 3 mẹo tiết kiệm chi phí sinh hoạt thiết thực cho học sinh lớp 9."], "rubric": [{"criterion": "Hoàn thành chính xác yêu cầu kỹ thuật: Thực hành hoàn thiện trọn vẹn tệp `TaiChinhGiaDinh.xlsx` theo yêu cầu SGK trang 53–54, bổ sung biểu đồ cơ cấu thu, biểu đồ cơ cấu chi và biểu đồ cân đối thu – chi trên trang `Tổng hợp`.", "maxPoints": 5.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Tích hợp Năng lực số: [Tích hợp NLS - NLC (3.2.TC2) & NLE (5.3.TC2)]: Dựa trên kết quả trang `Tổng hợp` và trang `Chi` vừa làm, hãy viết báo cáo ngắn (4 dòng) đề xuất kế hoạch điều chỉnh chi tiêu tháng tới để đạt mục tiêu tiết kiệm tối thiểu 20%.", "maxPoints": 3.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Vận dụng AI có trách nhiệm & đặt tên tệp đúng chuẩn: [Tích hợp AI - AI.1 (9.A3.1)]: Nhờ trợ lí AI đóng vai ''Chuyên gia tư vấn tài chính gia đình'', phân tích bảng tổng hợp thu chi của nhóm em và gợi ý 3 mẹo tiết kiệm chi phí sinh hoạt thiết thực cho học sinh lớp 9.", "maxPoints": 2.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}]}'::jsonb, '{"title": "Bài tập về nhà Tiết 21: Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình (mục 2 – Thực hành)", "description": "• Nhiệm vụ 1: Thực hành hoàn thiện trọn vẹn tệp `TaiChinhGiaDinh.xlsx` theo yêu cầu SGK trang 53–54, bổ sung biểu đồ cơ cấu thu, biểu đồ cơ cấu chi và biểu đồ cân đối thu – chi trên trang `Tổng hợp`.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.2.TC2) & NLE (5.3.TC2)]: Dựa trên kết quả trang `Tổng hợp` và trang `Chi` vừa làm, hãy viết báo cáo ngắn (4 dòng) đề xuất kế hoạch điều chỉnh chi tiêu tháng tới để đạt mục tiêu tiết kiệm tối thiểu 20%.\n• Nhiệm vụ 3: [Tích hợp AI - AI.1 (9.A3.1)]: Nhờ trợ lí AI đóng vai ''Chuyên gia tư vấn tài chính gia đình'', phân tích bảng tổng hợp thu chi của nhóm em và gợi ý 3 mẹo tiết kiệm chi phí sinh hoạt thiết thực cho học sinh lớp 9.", "acceptedFormats": ["image", "xlsx", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p22', 9, 22, 'Bài 14. Giải quyết vấn đề (mục 1)', 'Chủ đề 5. Giải quyết vấn đề với sự trợ giúp của máy tính', '1. Khái niệm và 5 bước trong quy trình giải quyết vấn đề.', FALSE, 'NLE (5.2.TC2 & 5.4.TC2): Lập quy trình giải quyết vấn đề có hệ thống và đánh giá hiệu quả của giải pháp. · AI.1 (9.A1.1) & AI.4 (9.D1.1): Hiểu quy trình 5 bước giải quyết vấn đề của con người làm nền tảng định hướng khi giao nhiệm vụ cho máy tính và AI.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 22: Bài 14. Giải quyết vấn đề (mục 1)", "phase1_khoi_dong": "Để chuẩn bị cho kì thi tuyển sinh vào lớp 10 đạt kết quả cao nhất, bạn Minh không học một cách ngẫu hứng mà ngồi xuống xác định rõ mục tiêu điểm số, kiểm tra xem mình đang yếu phần kiến thức nào, lập kế hoạch ôn tập từng tuần, bắt tay vào học theo lịch và cuối mỗi tháng tự làm đề thi thử để rút kinh nghiệm.", "phase2_kham_pha": "Đọc SGK 1. Khái niệm và 5 bước trong quy trình giải quyết vấn đề., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Để chuẩn bị cho kì thi tuyển sinh vào lớp 10 đạt kết quả cao nhất, bạn Minh không học một cách ngẫu hứng mà ngồi xuống xác định rõ mục tiêu điểm số, kiểm tra xem mình đang yếu phần kiến thức nào, lập kế hoạch ôn tập từng tuần, bắt tay vào học theo lịch và cuối mỗi tháng tự làm đề thi thử để rút kinh nghiệm.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["năm (5)", "Phân tích", "Đánh giá", "Bước 1 & Bước 2 (Tìm hiểu & Phân tích)", "Bước 3 & Bước 4 (Lựa chọn & Thực hiện)", "Bước 5 (Đánh giá kết quả)"], "dragDrop": {"bucketA": "Giai đoạn Chuẩn bị & Lựa chọn (Bước 1, 2, 3)", "bucketB": "Giai đoạn Triển khai & Kiểm chứng (Bước 4, 5)", "items": [{"id": "G9_T22_DD1", "text": "Bước 1: Tìm hiểu vấn đề (Xác định rõ cái đã cho và mục tiêu cần đạt) & Bước 2: Phân tích vấn đề (Chia nhỏ thành các phần dễ xử lí)", "correctBox": "A", "targetLabel": "Giai đoạn Chuẩn bị & Lựa chọn (Bước 1, 2, 3)", "points": 0.25}, {"id": "G9_T22_DD2", "text": "Bước 3: Lựa chọn giải pháp (Đề xuất các phương án khả thi và chọn phương án tối ưu nhất)", "correctBox": "A", "targetLabel": "Giai đoạn Chuẩn bị & Lựa chọn (Bước 1, 2, 3)", "points": 0.25}, {"id": "G9_T22_DD3", "text": "Bước 4: Thực hiện giải pháp (Triển khai từng bước theo phương án đã chọn để tạo ra kết quả)", "correctBox": "B", "targetLabel": "Giai đoạn Triển khai & Kiểm chứng (Bước 4, 5)", "points": 0.25}, {"id": "G9_T22_DD4", "text": "Bước 5: Đánh giá kết quả (Kiểm tra kết quả đạt được so với mục tiêu, rút kinh nghiệm và cải tiến)", "correctBox": "B", "targetLabel": "Giai đoạn Triển khai & Kiểm chứng (Bước 4, 5)", "points": 0.25}]}, "fillBlanks": [{"statement": "Quá trình giải quyết một vấn đề trong học tập và đời sống thường gồm [___] bước cơ bản theo trình tự logic.", "correctAnswer": "năm (5)", "filledSentence": "Quá trình giải quyết một vấn đề trong học tập và đời sống thường gồm «năm (5)» bước cơ bản theo trình tự logic."}, {"statement": "Ở Bước 2 ([___] vấn đề), chúng ta tìm mối liên hệ giữa cái đã biết với cái cần tìm và chia vấn đề lớn phức tạp thành những vấn đề nhỏ hơn.", "correctAnswer": "Phân tích", "filledSentence": "Ở Bước 2 («Phân tích» vấn đề), chúng ta tìm mối liên hệ giữa cái đã biết với cái cần tìm và chia vấn đề lớn phức tạp thành những vấn đề nhỏ hơn."}, {"statement": "Ở Bước 5 ([___] kết quả), nếu phát hiện kết quả chưa đạt yêu cầu hoặc chưa tối ưu, ta cần quay lại điều chỉnh giải pháp ở các bước trước.", "correctAnswer": "Đánh giá", "filledSentence": "Ở Bước 5 («Đánh giá» kết quả), nếu phát hiện kết quả chưa đạt yêu cầu hoặc chưa tối ưu, ta cần quay lại điều chỉnh giải pháp ở các bước trước."}], "matchingPairs": [{"left": "Bước 1 & Bước 2 (Tìm hiểu & Phân tích)", "right": "Làm rõ yêu cầu bài toán, điều kiện ràng buộc và phân rã bài toán thành các nhiệm vụ con"}, {"left": "Bước 3 & Bước 4 (Lựa chọn & Thực hiện)", "right": "So sánh ưu nhược điểm các cách giải để chọn giải pháp tốt nhất rồi tiến hành thực hiện"}, {"left": "Bước 5 (Đánh giá kết quả)", "right": "Đối chiếu sản phẩm đầu ra với mục tiêu ban đầu để nghiệm thu hoặc cải tiến"}], "discussionPrompt": "Để chuẩn bị cho kì thi tuyển sinh vào lớp 10 đạt kết quả cao nhất, bạn Minh không học một cách ngẫu hứng mà ngồi xuống xác định rõ mục tiêu điểm số, kiểm tra xem mình đang yếu phần kiến thức nào, lập kế hoạch ôn tập từng tuần, bắt tay vào học theo lịch và cuối mỗi tháng tự làm đề thi thử để rút kinh nghiệm."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 22: Bài 14. Giải quyết vấn đề (mục 1)", "description": "• Nhiệm vụ 1: Áp dụng quy trình 5 bước giải quyết vấn đề để lập kế hoạch chi tiết cho nhiệm vụ: ''Nâng cao điểm số môn Tin học và Toán trong học kì II''.\n• Nhiệm vụ 2: [Tích hợp NLS - NLE (5.2.TC2 & 5.4.TC2)]: Chọn một vấn đề thực tế tại trường học (như giảm thiểu rác thải nhựa hoặc quản lí mượn trả sách thư viện), mô tả cụ thể công việc ở từng bước từ Bước 1 đến Bước 5 và công cụ số sử dụng.\n• Nhiệm vụ 3: [Tích hợp AI - AI.1 (9.A1.1) & AI.4 (9.D1.1)]: Thực hành dùng AI hỗ trợ Bước 3 (gợi ý 3 giải pháp cho vấn đề của nhóm), sau đó tự nhóm thực hiện Bước 5 (phản biện, đánh giá ưu/nhược điểm từng giải pháp của AI).", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p23', 9, 23, 'Bài 14. Giải quyết vấn đề (mục 2)', 'Chủ đề 5. Giải quyết vấn đề với sự trợ giúp của máy tính', '2. Mô tả giải pháp dưới dạng thuật toán (sơ đồ khối và ngôn ngữ tự nhiên).', FALSE, 'NLC (3.4.TC2) & NLE (5.2.TC2): Biểu diễn giải pháp giải quyết vấn đề dưới dạng thuật toán tuần tự, rẽ nhánh, lặp bằng ngôn ngữ tự nhiên hoặc sơ đồ khối. · AI.4 (9.D1.1): Hiểu cách xây dựng cấu trúc thuật toán logic để điều khiển máy tính, robot hoặc hệ thống tự động.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 23: Bài 14. Giải quyết vấn đề (mục 2)", "phase1_khoi_dong": "Sau khi lựa chọn được giải pháp ở Bước 3, làm thế nào để diễn đạt giải pháp đó thật rõ ràng, mạch lạc theo từng bước để một người khác hoặc một chiếc máy tính/robot cứ làm đúng theo trình tự đó là ra kết quả?", "phase2_kham_pha": "Đọc SGK 2. Mô tả giải pháp dưới dạng thuật toán (sơ đồ khối và ngôn ngữ tự nhiên)., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Sau khi lựa chọn được giải pháp ở Bước 3, làm thế nào để diễn đạt giải pháp đó thật rõ ràng, mạch lạc theo từng bước để một người khác hoặc một chiếc máy tính/robot cứ làm đúng theo trình tự đó là ra kết quả?", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["thuật toán", "sơ đồ khối", "thoi", "Hình Ô van & Hình Bình hành", "Hình Chữ nhật", "Hình Thoi & Mũi tên"], "dragDrop": {"bucketA": "Quy ước các hình trong Sơ đồ khối thuật toán", "bucketB": "Các cấu trúc điều khiển trong mô tả thuật toán", "items": [{"id": "G9_T23_DD1", "text": "Hình Ô van (Elip): Bắt đầu / Kết thúc thuật toán; Hình Bình hành: Nhập / Xuất dữ liệu", "correctBox": "A", "targetLabel": "Quy ước các hình trong Sơ đồ khối thuật toán", "points": 0.25}, {"id": "G9_T23_DD2", "text": "Hình Chữ nhật: Thực hiện phép tính / gán giá trị; Hình Thoi: Kiểm tra điều kiện (Đúng / Sai)", "correctBox": "A", "targetLabel": "Quy ước các hình trong Sơ đồ khối thuật toán", "points": 0.25}, {"id": "G9_T23_DD3", "text": "Cấu trúc Tuần tự: Thực hiện các bước nối tiếp nhau theo chiều mũi tên từ trên xuống dưới", "correctBox": "B", "targetLabel": "Các cấu trúc điều khiển trong mô tả thuật toán", "points": 0.25}, {"id": "G9_T23_DD4", "text": "Cấu trúc Rẽ nhánh (từ Hình Thoi tách nhánh Đúng/Sai) và Cấu trúc Lặp (mũi tên quay lại bước trước)", "correctBox": "B", "targetLabel": "Các cấu trúc điều khiển trong mô tả thuật toán", "points": 0.25}]}, "fillBlanks": [{"statement": "Một giải pháp được mô tả thành dãy hữu hạn các bước sắp xếp theo trình tự xác định sao cho sau khi thực hiện hết các bước đó thì đạt được mục tiêu gọi là một [___].", "correctAnswer": "thuật toán", "filledSentence": "Một giải pháp được mô tả thành dãy hữu hạn các bước sắp xếp theo trình tự xác định sao cho sau khi thực hiện hết các bước đó thì đạt được mục tiêu gọi là một «thuật toán»."}, {"statement": "Hai cách thông dụng để biểu diễn thuật toán là: liệt kê các bước (dùng ngôn ngữ tự nhiên) và dùng [___].", "correctAnswer": "sơ đồ khối", "filledSentence": "Hai cách thông dụng để biểu diễn thuật toán là: liệt kê các bước (dùng ngôn ngữ tự nhiên) và dùng «sơ đồ khối»."}, {"statement": "Trong sơ đồ khối, hình [___] dùng để biểu diễn thao tác kiểm tra điều kiện (có 1 mũi tên đi vào và 2 mũi tên đi ra ứng với Đúng và Sai).", "correctAnswer": "thoi", "filledSentence": "Trong sơ đồ khối, hình «thoi» dùng để biểu diễn thao tác kiểm tra điều kiện (có 1 mũi tên đi vào và 2 mũi tên đi ra ứng với Đúng và Sai)."}], "matchingPairs": [{"left": "Hình Ô van & Hình Bình hành", "right": "Ô van: Bắt đầu / Kết thúc; Bình hành: Nhập dữ liệu đầu vào (Input) hoặc Thông báo kết quả đầu ra (Output)"}, {"left": "Hình Chữ nhật", "right": "Thực hiện các thao tác xử lí, tính toán hoặc gán giá trị (ví dụ: `Tổng ← a + b`)"}, {"left": "Hình Thoi & Mũi tên", "right": "Hình thoi: Kiểm tra điều kiện rẽ nhánh/lặp; Mũi tên: Chỉ hướng thực hiện tiếp theo của thuật toán"}], "discussionPrompt": "Sau khi lựa chọn được giải pháp ở Bước 3, làm thế nào để diễn đạt giải pháp đó thật rõ ràng, mạch lạc theo từng bước để một người khác hoặc một chiếc máy tính/robot cứ làm đúng theo trình tự đó là ra kết quả?"}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 23: Bài 14. Giải quyết vấn đề (mục 2)", "description": "• Nhiệm vụ 1: Mô tả thuật toán (bằng cả 2 cách: Liệt kê các bước và Vẽ sơ đồ khối) cho bài toán: ''Kiểm tra một học sinh có đỗ tốt nghiệp hay không khi nhập Điểm tổng kết (đỗ nếu Điểm >= 5.0)''.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.2.TC2)]: Sử dụng công cụ `Shapes` trong Word hoặc PowerPoint để vẽ sơ đồ khối chuẩn cho thuật toán ''Uớc lượng chi tiêu quy tắc 50-30-20'' hoặc ''Tính tổng các số tự nhiên từ 1 đến n''.\n• Nhiệm vụ 3: [Tích hợp AI - AI.4 (9.D1.1)]: Cung cấp mô tả các bước giải một bài toán thực tế cho AI và yêu cầu AI kiểm tra xem thuật toán đã xét đủ mọi trường hợp rẽ nhánh (Đúng/Sai) và điều kiện dừng hay chưa.", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p24', 9, 24, 'Bài 15. Bài toán Tin học (mục 1)', 'Chủ đề 5. Giải quyết vấn đề với sự trợ giúp của máy tính', '1. Khái niệm bài toán Tin học và xác định Input/Output.', FALSE, 'NLC (3.4.TC2) & NLE (5.1.TC2): Xác định yếu tố Đầu vào (Input) và Đầu ra (Output) để đặc tả bài toán giao cho máy tính. · AI.4 (9.D1.1): Trình bày vai trò của con người trong việc phát biểu bài toán và xác định dữ liệu đầu vào / kết quả đầu ra cho hệ thống máy tính và AI.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 24: Bài 15. Bài toán Tin học (mục 1)", "phase1_khoi_dong": "Ở môn Toán, khi nói đến ''bài toán'' ta thường nghĩ ngay đến việc tính giá trị biểu thức hay chứng minh hình học. Nhưng trong Tin học, việc ''In danh sách học sinh giỏi từ bảng điểm'', ''Tìm đường đi ngắn nhất trên bản đồ'' hay ''Tính tiền lương tháng cho công nhân'' cũng đều được gọi là ''Bài toán tin học''.", "phase2_kham_pha": "Đọc SGK 1. Khái niệm bài toán Tin học và xác định Input/Output., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Ở môn Toán, khi nói đến ''bài toán'' ta thường nghĩ ngay đến việc tính giá trị biểu thức hay chứng minh hình học. Nhưng trong Tin học, việc ''In danh sách học sinh giỏi từ bảng điểm'', ''Tìm đường đi ngắn nhất trên bản đồ'' hay ''Tính tiền lương tháng cho công nhân'' cũng đều được gọi là ''Bài toán tin học''.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["bài toán", "Đầu vào", "thuật toán", "Bài toán: Tính tiền lương làm việc theo giờ"], "dragDrop": {"bucketA": "Đầu vào (Input) của bài toán tin học", "bucketB": "Đầu ra (Output) của bài toán tin học", "items": [{"id": "G9_T24_DD1", "text": "Hai số thực `a, b` (chiều dài và chiều rộng của hình chữ nhật được nhập vào)", "correctBox": "A", "targetLabel": "Đầu vào (Input) của bài toán tin học", "points": 0.25}, {"id": "G9_T24_DD2", "text": "Danh sách điểm trung bình của 40 học sinh lớp 9A", "correctBox": "A", "targetLabel": "Đầu vào (Input) của bài toán tin học", "points": 0.25}, {"id": "G9_T24_DD3", "text": "Chu vi `C` và diện tích `S` của hình chữ nhật sau khi tính toán", "correctBox": "B", "targetLabel": "Đầu ra (Output) của bài toán tin học", "points": 0.25}, {"id": "G9_T24_DD4", "text": "Số lượng học sinh đạt danh hiệu Học sinh Giỏi có Điểm trung bình >= 8.0", "correctBox": "B", "targetLabel": "Đầu ra (Output) của bài toán tin học", "points": 0.25}]}, "fillBlanks": [{"statement": "Trong tin học, [___] là một công việc hay một nhiệm vụ cần giải quyết mà con người có thể giao cho máy tính thực hiện.", "correctAnswer": "bài toán", "filledSentence": "Trong tin học, «bài toán» là một công việc hay một nhiệm vụ cần giải quyết mà con người có thể giao cho máy tính thực hiện."}, {"statement": "Để phát biểu chặt chẽ một bài toán tin học, ta cần xác định rõ hai yếu tố: [___] (`Input` - những gì đã cho) và Đầu ra (`Output` - những gì cần tìm).", "correctAnswer": "Đầu vào", "filledSentence": "Để phát biểu chặt chẽ một bài toán tin học, ta cần xác định rõ hai yếu tố: «Đầu vào» (`Input` - những gì đã cho) và Đầu ra (`Output` - những gì cần tìm)."}, {"statement": "Một nhiệm vụ chỉ có thể trở thành bài toán giao cho máy tính giải quyết khi con người xây dựng được [___] (dãy các bước hữu hạn, rõ ràng) để dẫn từ Đầu vào đến Đầu ra.", "correctAnswer": "thuật toán", "filledSentence": "Một nhiệm vụ chỉ có thể trở thành bài toán giao cho máy tính giải quyết khi con người xây dựng được «thuật toán» (dãy các bước hữu hạn, rõ ràng) để dẫn từ Đầu vào đến Đầu ra."}], "matchingPairs": [{"left": "Bài toán: Tìm ước chung lớn nhất của 2 số nguyên dương", "right": "Input: Hai số nguyên dương `m, n` <-> Output: Ước chung lớn nhất của `m` và `n`"}, {"left": "Bài toán: Giải phương trình bậc nhất `ax + b = 0` (`a ≠ 0`)", "right": "Input: Hai hệ số thực `a` (`a ≠ 0`) và `b` <-> Output: Nghiệm `x = -b / a`"}, {"left": "Bài toán: Tính tiền lương làm việc theo giờ", "right": "Input: Số giờ làm việc `t` và mức thù lao một giờ `a` <-> Output: Tổng số tiền lương nhận được"}], "discussionPrompt": "Ở môn Toán, khi nói đến ''bài toán'' ta thường nghĩ ngay đến việc tính giá trị biểu thức hay chứng minh hình học. Nhưng trong Tin học, việc ''In danh sách học sinh giỏi từ bảng điểm'', ''Tìm đường đi ngắn nhất trên bản đồ'' hay ''Tính tiền lương tháng cho công nhân'' cũng đều được gọi là ''Bài toán tin học''."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 24: Bài 15. Bài toán Tin học (mục 1)", "description": "• Nhiệm vụ 1: Lập bảng xác định rõ Tên bài toán, Đầu vào (`Input`) và Đầu ra (`Output`) cho 4 bài toán thực tế: (1) Tính tiền điện bậc thang; (2) Xếp loại học lực cuối năm; (3) Kiểm tra một số nguyên dương có phải số chẵn không; (4) Tìm giá trị nhỏ nhất trong dãy số.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Từ bài toán quản lí tài chính gia đình ở Chủ đề 4a, hãy phát biểu thành 1 bài toán tin học với đặc tả đầy đủ `Input` và `Output`.\n• Nhiệm vụ 3: [Tích hợp AI - AI.4 (9.D1.1)]: Thực hành thiết kế một câu lệnh Prompt cho AI theo mô hình Bài toán Tin học: chỉ rõ `[INPUT DATA]` (Dữ liệu đầu vào cung cấp cho AI) và `[OUTPUT FORMAT]` (Định dạng kết quả đầu ra mong muốn).", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p25', 9, 25, 'Bài 15. Bài toán Tin học (mục 2)', 'Chủ đề 5. Giải quyết vấn đề với sự trợ giúp của máy tính', '2. Quy trình con người giao bài toán cho máy tính giải quyết (4 bước).', FALSE, 'NLC (3.4.TC2) & NLE (5.1.TC2): Lập kế hoạch phát triển chương trình theo 4 bước chuẩn và thiết kế bộ kiểm thử gỡ lỗi. · AI.4 (9.D2.1): Thiết kế và thực hiện các bộ kiểm thử (Test cases) để đánh giá, kiểm증 và cải tiến thuật toán/chương trình.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 25: Bài 15. Bài toán Tin học (mục 2)", "phase1_khoi_dong": "Khi muốn nhờ máy tính giải bài toán ''Tính tiền lương làm việc theo giờ cho công nhân'', chúng ta không thể chỉ nói miệng với chiếc máy tính là ''Hãy tính lương đi!'' mà phải trải qua một quy trình chuẩn để biến ý tưởng của con người thành phần mềm chạy đúng trên máy.", "phase2_kham_pha": "Đọc SGK 2. Quy trình con người giao bài toán cho máy tính giải quyết (4 bước)., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Khi muốn nhờ máy tính giải bài toán ''Tính tiền lương làm việc theo giờ cho công nhân'', chúng ta không thể chỉ nói miệng với chiếc máy tính là ''Hãy tính lương đi!'' mà phải trải qua một quy trình chuẩn để biến ý tưởng của con người thành phần mềm chạy đúng trên máy.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["bốn (4)", "chương trình", "Kiểm thử", "Bước 2: Tìm thuật toán"], "dragDrop": {"bucketA": "Giai đoạn Thiết kế trên giấy (Bước 1 & Bước 2)", "bucketB": "Giai đoạn Cài đặt trên máy tính (Bước 3 & Bước 4)", "items": [{"id": "G9_T25_DD1", "text": "Bước 1: Xác định bài toán — Chỉ rõ Đầu vào (`Input`) và Đầu ra (`Output`)", "correctBox": "A", "targetLabel": "Giai đoạn Thiết kế trên giấy (Bước 1 & Bước 2)", "points": 0.25}, {"id": "G9_T25_DD2", "text": "Bước 2: Tìm thuật toán — Mô tả các bước giải bằng liệt kê hoặc sơ đồ khối", "correctBox": "A", "targetLabel": "Giai đoạn Thiết kế trên giấy (Bước 1 & Bước 2)", "points": 0.25}, {"id": "G9_T25_DD3", "text": "Bước 3: Viết chương trình — Chuyển thuật toán thành các câu lệnh trong ngôn ngữ lập trình (như Scratch, Python)", "correctBox": "B", "targetLabel": "Giai đoạn Cài đặt trên máy tính (Bước 3 & Bước 4)", "points": 0.25}, {"id": "G9_T25_DD4", "text": "Bước 4: Kiểm thử và gỡ lỗi — Chạy thử với các bộ dữ liệu `Input` đa dạng để phát hiện và sửa lỗi", "correctBox": "B", "targetLabel": "Giai đoạn Cài đặt trên máy tính (Bước 3 & Bước 4)", "points": 0.25}]}, "fillBlanks": [{"statement": "Quy trình con người giao bài toán cho máy tính giải quyết gồm [___] bước: Xác định bài toán -> Tìm thuật toán -> Viết chương trình -> Kiểm thử và gỡ lỗi.", "correctAnswer": "bốn (4)", "filledSentence": "Quy trình con người giao bài toán cho máy tính giải quyết gồm «bốn (4)» bước: Xác định bài toán -> Tìm thuật toán -> Viết chương trình -> Kiểm thử và gỡ lỗi."}, {"statement": "Ở Bước 3 (Viết [___]), người lập trình dịch từng bước của thuật toán đã thiết kế sang các câu lệnh mà máy tính có thể hiểu và thực thi được.", "correctAnswer": "chương trình", "filledSentence": "Ở Bước 3 (Viết «chương trình»), người lập trình dịch từng bước của thuật toán đã thiết kế sang các câu lệnh mà máy tính có thể hiểu và thực thi được."}, {"statement": "Ở Bước 4 ([___] và gỡ lỗi), ta chạy chương trình với nhiều bộ dữ liệu thử nghiệm (`Test cases`) để đối chiếu kết quả thực tế với kết quả mong đợi.", "correctAnswer": "Kiểm thử", "filledSentence": "Ở Bước 4 («Kiểm thử» và gỡ lỗi), ta chạy chương trình với nhiều bộ dữ liệu thử nghiệm (`Test cases`) để đối chiếu kết quả thực tế với kết quả mong đợi."}], "matchingPairs": [{"left": "Bước 1: Xác định bài toán (`Input` / `Output`)", "right": "Tương ứng với Bước 1 (Tìm hiểu vấn đề) trong quy trình giải quyết vấn đề của con người"}, {"left": "Bước 2: Tìm thuật toán", "right": "Tương ứng với Bước 2 & Bước 3 (Phân tích vấn đề & Lựa chọn giải pháp)"}, {"left": "Bước 3: Viết chương trình & Bước 4: Kiểm thử, gỡ lỗi", "right": "Tương ứng với Bước 4 (Thực hiện giải pháp) & Bước 5 (Đánh giá kết quả)"}], "discussionPrompt": "Khi muốn nhờ máy tính giải bài toán ''Tính tiền lương làm việc theo giờ cho công nhân'', chúng ta không thể chỉ nói miệng với chiếc máy tính là ''Hãy tính lương đi!'' mà phải trải qua một quy trình chuẩn để biến ý tưởng của con người thành phần mềm chạy đúng trên máy."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 25: Bài 15. Bài toán Tin học (mục 2)", "description": "• Nhiệm vụ 1: Thực hiện đầy đủ Bước 1 (Xác định Input/Output), Bước 2 (Vẽ sơ đồ khối thuật toán) và thiết kế bộ 3 Test cases chuẩn bị cho Bước 4 của bài toán ''Tính tiền lương theo giờ (có tính giờ làm thêm gấp 1.5 lần khi > 40 giờ)''.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Lập bảng ánh xạ so sánh từng bước giữa ''Quy trình 5 bước giải quyết vấn đề (Bài 14)'' và ''Quy trình 4 bước giải bài toán trên máy tính (Bài 15)''.\n• Nhiệm vụ 3: [Tích hợp AI - AI.4 (9.D2.1)]: Yêu cầu AI tạo 5 bộ dữ liệu kiểm thử (`Test cases`: gồm trường hợp thường, trường hợp biên và trường hợp đặc biệt) cho bài toán ''Tìm giá trị lớn nhất trong dãy số'' để chuẩn bị cho bài thực hành Tiết 26–27.", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p26', 9, 26, 'Bài 16. Thực hành: Lập chương trình máy tính. (nhiệm vụ 1)', 'Chủ đề 5. Giải quyết vấn đề với sự trợ giúp của máy tính', 'Nhiệm vụ 1: Lập chương trình Scratch tính tiền lương.', TRUE, 'NLC (3.4.TC2) & NLE (5.1.TC2): Lập chương trình máy tính sử dụng cấu trúc điều khiển rẽ nhánh và kiểm thử với các bộ dữ liệu chuẩn. · AI.2 (9.C2.1) & AI.4 (9.D2.1): Vận dụng tư duy lập trình để tạo công cụ tính toán tự động và kiểm thử đánh giá chất lượng phần mềm.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 26: Bài 16. Thực hành: Lập chương trình máy tính. (nhiệm vụ 1)", "phase1_khoi_dong": "Theo quy định trả lương tuần (SGK trang 68): định mức làm việc chuẩn là `40` giờ/tuần với mức thù lao `a` đồng/giờ. Nếu số giờ làm việc `t <= 40` thì `Tiền lương = t * a`; nếu làm vượt quá 40 giờ (`t > 40`) thì mỗi giờ làm thêm được tính bằng `1.5` lần mức thù lao chuẩn: `Tiền lương = (40 + (t - 40) * 1.5) * a`.", "phase2_kham_pha": "Đọc SGK Nhiệm vụ 1: Lập chương trình Scratch tính tiền lương., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Theo quy định trả lương tuần (SGK trang 68): định mức làm việc chuẩn là `40` giờ/tuần với mức thù lao `a` đồng/giờ. Nếu số giờ làm việc `t <= 40` thì `Tiền lương = t * a`; nếu làm vượt quá 40 giờ (`t > 40`) thì mỗi giờ làm thêm được tính bằng `1.5` lần mức thù lao chuẩn: `Tiền lương = (40 + (t - 40) * 1.5) * a`.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["a", "nếu không", "2300", "Kiểm thử biên tại `t = 40`"], "dragDrop": {"bucketA": "Khối lệnh nhập dữ liệu Input (t, a) và biến nhớ", "bucketB": "Khối lệnh xử lí rẽ nhánh tính lương và xuất Output", "items": [{"id": "G9_T26_DD1", "text": "Tạo 3 biến nhớ trong nhóm `Các biến số`: `t` (số giờ làm), `a` (thù lao 1 giờ), `Tong_luong` (hoặc `s`)", "correctBox": "A", "targetLabel": "Khối lệnh nhập dữ liệu Input (t, a) và biến nhớ", "points": 0.25}, {"id": "G9_T26_DD2", "text": "Dùng cặp lệnh `hỏi (Nhập số giờ làm việc t:) và đợi`", "correctBox": "B", "targetLabel": "Khối lệnh xử lí rẽ nhánh tính lương và xuất Output", "points": 0.25}, {"id": "G9_T26_DD3", "text": "Dùng khối `nếu <(t) > (40)> thì [đặt Tong_luong thành ((40 + (t - 40) * 1.5) * a)] nếu không [đặt Tong_luong thành (t * a)]`", "correctBox": "B", "targetLabel": "Khối lệnh xử lí rẽ nhánh tính lương và xuất Output", "points": 0.25}, {"id": "G9_T26_DD4", "text": "Dùng khối `nói (kết hợp (Tổng tiền lương là: ) (Tong_luong)) trong (5) giây` để thông báo kết quả", "correctBox": "B", "targetLabel": "Khối lệnh xử lí rẽ nhánh tính lương và xuất Output", "points": 0.25}]}, "fillBlanks": [{"statement": "Trong bài toán tính tiền lương theo giờ (SGK trang 68), hai đại lượng Đầu vào (`Input`) cần nhập từ bàn phím là số giờ làm việc `t` và mức thù lao một giờ [___].", "correctAnswer": "a", "filledSentence": "Trong bài toán tính tiền lương theo giờ (SGK trang 68), hai đại lượng Đầu vào (`Input`) cần nhập từ bàn phím là số giờ làm việc `t` và mức thù lao một giờ «a»."}, {"statement": "Để kiểm tra hai trường hợp `t > 40` (có làm thêm giờ) và `t <= 40` (không vượt định mức), ta sử dụng khối lệnh cấu trúc rẽ nhánh dạng đủ: `nếu <...> thì ... [___] ...`.", "correctAnswer": "nếu không", "filledSentence": "Để kiểm tra hai trường hợp `t > 40` (có làm thêm giờ) và `t <= 40` (không vượt định mức), ta sử dụng khối lệnh cấu trúc rẽ nhánh dạng đủ: `nếu <...> thì ... «nếu không» ...`."}, {"statement": "Với `a = 50` (nghìn đồng/giờ): nếu `t = 30` giờ thì `Tong_luong = 30 * 50 = 1500`; còn nếu `t = 44` giờ (vượt 4 giờ) thì `Tong_luong = (40 + 4 * 1.5) * 50 = [___]` (nghìn đồng).", "correctAnswer": "2300", "filledSentence": "Với `a = 50` (nghìn đồng/giờ): nếu `t = 30` giờ thì `Tong_luong = 30 * 50 = 1500`; còn nếu `t = 44` giờ (vượt 4 giờ) thì `Tong_luong = (40 + 4 * 1.5) * 50 = «2300»` (nghìn đồng)."}], "matchingPairs": [{"left": "Nhánh `t <= 40` (Làm việc trong định mức chuẩn)", "right": "Công thức tính: `Tong_luong = t * a`"}, {"left": "Nhánh `t > 40` (Có số giờ làm thêm `t - 40` tính hệ số `1.5`)", "right": "Công thức tính: `Tong_luong = (40 + (t - 40) * 1.5) * a`"}, {"left": "Kiểm thử biên tại `t = 40`", "right": "Cả hai công thức đều phải cho cùng một kết quả là `40 * a`"}], "discussionPrompt": "Theo quy định trả lương tuần (SGK trang 68): định mức làm việc chuẩn là `40` giờ/tuần với mức thù lao `a` đồng/giờ. Nếu số giờ làm việc `t <= 40` thì `Tiền lương = t * a`; nếu làm vượt quá 40 giờ (`t > 40`) thì mỗi giờ làm thêm được tính bằng `1.5` lần mức thù lao chuẩn: `Tiền lương = (40 + (t - 40) * 1.5) * a`."}'::jsonb, '{"title": "Thực hành Tiết 26: Bài 16. Thực hành: Lập chương trình máy tính (Nhiệm vụ 1)", "sampleFileName": "Mau_ThucHanh_Tiet_26.docx", "sampleFileUrl": "/templates/thuchanh_k9_tiet26.dat", "steps": ["Thực hành trên máy tính: Tạo và lưu hoàn chỉnh chương trình `TinhTienLuong.sb3` theo hướng dẫn SGK trang 68–69, chạy kiểm thử với 3 bộ dữ liệu và ghi lại kết quả.", "[Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Nâng cấp chương trình `TinhTienLuong.sb3` thêm bước kiểm tra dữ liệu đầu vào: nếu `t <= 0` hoặc `a <= 0` thì thông báo `''Vui lòng nhập số dương hợp lệ!''`.", "[Tích hợp AI - AI.2 (9.C2.1) & AI.4 (9.D2.1)]: So sánh cách giải bài toán ''Tính tiền lương theo giờ'' bằng chương trình Scratch với việc dùng hàm `=IF(t>40, (40+(t-40)*1.5)*a, t*a)` trong bảng tính Excel đã học ở Bài 12a."], "rubric": [{"criterion": "Hoàn thành chính xác yêu cầu kỹ thuật: Thực hành trên máy tính: Tạo và lưu hoàn chỉnh chương trình `TinhTienLuong.sb3` theo hướng dẫn SGK trang 68–69, chạy kiểm thử với 3 bộ dữ liệu và ghi lại kết quả.", "maxPoints": 5.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Tích hợp Năng lực số: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Nâng cấp chương trình `TinhTienLuong.sb3` thêm bước kiểm tra dữ liệu đầu vào: nếu `t <= 0` hoặc `a <= 0` thì thông báo `''Vui lòng nhập số dương hợp lệ!''`.", "maxPoints": 3.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Vận dụng AI có trách nhiệm & đặt tên tệp đúng chuẩn: [Tích hợp AI - AI.2 (9.C2.1) & AI.4 (9.D2.1)]: So sánh cách giải bài toán ''Tính tiền lương theo giờ'' bằng chương trình Scratch với việc dùng hàm `=IF(t>40, (40+(t-40)*1.5)*a, t*a)` trong bảng tính Excel đã học ở Bài 12a.", "maxPoints": 2.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}]}'::jsonb, '{"title": "Bài tập về nhà Tiết 26: Bài 16. Thực hành: Lập chương trình máy tính. (nhiệm vụ 1)", "description": "• Nhiệm vụ 1: Thực hành trên máy tính: Tạo và lưu hoàn chỉnh chương trình `TinhTienLuong.sb3` theo hướng dẫn SGK trang 68–69, chạy kiểm thử với 3 bộ dữ liệu và ghi lại kết quả.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Nâng cấp chương trình `TinhTienLuong.sb3` thêm bước kiểm tra dữ liệu đầu vào: nếu `t <= 0` hoặc `a <= 0` thì thông báo `''Vui lòng nhập số dương hợp lệ!''`.\n• Nhiệm vụ 3: [Tích hợp AI - AI.2 (9.C2.1) & AI.4 (9.D2.1)]: So sánh cách giải bài toán ''Tính tiền lương theo giờ'' bằng chương trình Scratch với việc dùng hàm `=IF(t>40, (40+(t-40)*1.5)*a, t*a)` trong bảng tính Excel đã học ở Bài 12a.", "acceptedFormats": ["image", "xlsx", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p27', 9, 27, 'Bài 16. Thực hành: Lập chương trình máy tính. (nhiệm vụ 2)', 'Chủ đề 5. Giải quyết vấn đề với sự trợ giúp của máy tính', 'Nhiệm vụ 2: Lập chương trình Scratch tìm giá trị lớn nhất trong dãy số.', TRUE, 'NLC (3.4.TC2) & NLE (5.1.TC2): Lập trình xử lí dãy dữ liệu bằng vòng lặp và gỡ lỗi thuật toán qua kiểm thử thực nghiệm. · AI.2 (9.C3.1): Cải thiện thuật toán để xử lí đúng các trường hợp dữ liệu biên hoặc dữ liệu âm bất thường.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 27: Bài 16. Thực hành: Lập chương trình máy tính. (nhiệm vụ 2)", "phase1_khoi_dong": "Trong SGK trang 70 (`Nhiệm vụ 2`), một chương trình tìm số lớn nhất (`Max`) của dãy số hoạt động như sau: đầu tiên đặt `Max = 0`, sau đó lặp lại việc nhập từng số `so` trong dãy, nếu `so > Max` thì cập nhật `Max = so`. Khi thử với dãy số dương `(4, 9, 2, 7)` chương trình tìm ra `Max = 9` rất đúng. Nhưng khi thử với dãy toàn số âm `(-5, -2, -8)` thì chương trình lại báo `Max = 0` (trong khi số `0` không hề có trong dãy và số lớn nhất phải là `-2`)!", "phase2_kham_pha": "Đọc SGK Nhiệm vụ 2: Lập chương trình Scratch tìm giá trị lớn nhất trong dãy số., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Trong SGK trang 70 (`Nhiệm vụ 2`), một chương trình tìm số lớn nhất (`Max`) của dãy số hoạt động như sau: đầu tiên đặt `Max = 0`, sau đó lặp lại việc nhập từng số `so` trong dãy, nếu `so > Max` thì cập nhật `Max = so`. Khi thử với dãy số dương `(4, 9, 2, 7)` chương trình tìm ra `Max = 9` rất đúng. Nhưng khi thử với dãy toàn số âm `(-5, -2, -8)` thì chương trình lại báo `Max = 0` (trong khi số `0` không hề có trong dãy và số lớn nhất phải là `-2`)!", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["lớn nhất", "Max", "âm (< 0)"], "dragDrop": {"bucketA": "Thuật toán tìm Max theo từng bước chuẩn", "bucketB": "Phát hiện và gỡ lỗi lôgic qua Kiểm thử (Testing)", "items": [{"id": "G9_T27_DD1", "text": "Nhập số đầu tiên của dãy và khởi tạo `Max` bằng chính giá trị số đầu tiên đó", "correctBox": "A", "targetLabel": "Thuật toán tìm Max theo từng bước chuẩn", "points": 0.25}, {"id": "G9_T27_DD2", "text": "Trong vòng lặp các số tiếp theo: kiểm tra `nếu <(so) > (Max)> thì [đặt Max thành (so)]`", "correctBox": "A", "targetLabel": "Thuật toán tìm Max theo từng bước chuẩn", "points": 0.25}, {"id": "G9_T27_DD3", "text": "Kiểm thử với dãy số nguyên dương `(3, 15, 8, 12)`", "correctBox": "B", "targetLabel": "Phát hiện và gỡ lỗi lôgic qua Kiểm thử (Testing)", "points": 0.25}, {"id": "G9_T27_DD4", "text": "Kiểm thử với dãy toàn số âm `(-10, -3, -7)`", "correctBox": "B", "targetLabel": "Phát hiện và gỡ lỗi lôgic qua Kiểm thử (Testing)", "points": 0.25}]}, "fillBlanks": [{"statement": "Trong thuật toán tìm giá trị lớn nhất của một dãy số, biến `Max` dùng để lưu giá trị [___] tìm được tính đến thời điểm hiện tại.", "correctAnswer": "lớn nhất", "filledSentence": "Trong thuật toán tìm giá trị lớn nhất của một dãy số, biến `Max` dùng để lưu giá trị «lớn nhất» tìm được tính đến thời điểm hiện tại."}, {"statement": "Mỗi khi nhập thêm một số mới (`so`), ta dùng khối lệnh rẽ nhánh dạng khuyết: `nếu <(so) > ([___])> thì [đặt Max thành (so)]` để cập nhật giá trị lớn nhất.", "correctAnswer": "Max", "filledSentence": "Mỗi khi nhập thêm một số mới (`so`), ta dùng khối lệnh rẽ nhánh dạng khuyết: `nếu <(so) > («Max»)> thì [đặt Max thành (so)]` để cập nhật giá trị lớn nhất."}, {"statement": "Nếu khởi tạo `đặt [Max] thành (0)` trước khi nhập dãy số, chương trình sẽ cho kết quả SAI khi tất cả các số trong dãy đều là số [___].", "correctAnswer": "âm (< 0)", "filledSentence": "Nếu khởi tạo `đặt [Max] thành (0)` trước khi nhập dãy số, chương trình sẽ cho kết quả SAI khi tất cả các số trong dãy đều là số «âm (< 0)»."}], "matchingPairs": [{"left": "Bộ kiểm thử 1: Dãy số tự nhiên dương `(5, 12, 9, 20, 4)`", "right": "Kiểm tra khả năng tìm `Max` trong trường hợp thông thường (`Max = 20`)"}, {"left": "Bộ kiểm thử 2: Dãy số thập phân `(2.5, 7.8, 7.85, 3.1)`", "right": "Kiểm tra chương trình có xử lí đúng các số thực có phần thập phân hay không (`Max = 7.85`)"}, {"left": "Bộ kiểm thử 3: Dãy toàn các số âm `(-15, -4, -9, -25)`", "right": "Kiểm tra lỗi khởi tạo biến `Max`; kết quả đúng phải là `Max = -4` (không phải `0`)"}], "discussionPrompt": "Trong SGK trang 70 (`Nhiệm vụ 2`), một chương trình tìm số lớn nhất (`Max`) của dãy số hoạt động như sau: đầu tiên đặt `Max = 0`, sau đó lặp lại việc nhập từng số `so` trong dãy, nếu `so > Max` thì cập nhật `Max = so`. Khi thử với dãy số dương `(4, 9, 2, 7)` chương trình tìm ra `Max = 9` rất đúng. Nhưng khi thử với dãy toàn số âm `(-5, -2, -8)` thì chương trình lại báo `Max = 0` (trong khi số `0` không hề có trong dãy và số lớn nhất phải là `-2`)!"}'::jsonb, '{"title": "Thực hành Tiết 27: Bài 16. Thực hành: Lập chương trình máy tính (Nhiệm vụ 2)", "sampleFileName": "Mau_ThucHanh_Tiet_27.docx", "sampleFileUrl": "/templates/thuchanh_k9_tiet27.dat", "steps": ["Thực hành tạo chương trình `TimGiaTriLonNhat.sb3` trong Scratch, chạy kiểm thử với cả 3 bộ dữ liệu trong SGK trang 70 (số tự nhiên, số thập phân, số âm) và sửa lại chương trình để chạy đúng với cả dãy toàn số âm.", "[Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Chỉnh sửa chương trình vừa làm để sau khi nhập xong dãy số, nhân vật thông báo đồng thời cả Giá trị lớn nhất (`Max`) và Giá trị nhỏ nhất (`Min`) của dãy số.", "[Tích hợp AI - AI.2 (9.C3.1)]: Thảo luận với AI về cách xử lí ngoại lệ khi người dùng gõ nhầm một chữ cái bất kỳ (không phải số và cũng không phải từ `''kết thúc''`) trong lúc nhập dãy số."], "rubric": [{"criterion": "Hoàn thành chính xác yêu cầu kỹ thuật: Thực hành tạo chương trình `TimGiaTriLonNhat.sb3` trong Scratch, chạy kiểm thử với cả 3 bộ dữ liệu trong SGK trang 70 (số tự nhiên, số thập phân, số âm) và sửa lại chương trình để chạy đúng với cả dãy toàn số âm.", "maxPoints": 5.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Tích hợp Năng lực số: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Chỉnh sửa chương trình vừa làm để sau khi nhập xong dãy số, nhân vật thông báo đồng thời cả Giá trị lớn nhất (`Max`) và Giá trị nhỏ nhất (`Min`) của dãy số.", "maxPoints": 3.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}, {"criterion": "Vận dụng AI có trách nhiệm & đặt tên tệp đúng chuẩn: [Tích hợp AI - AI.2 (9.C3.1)]: Thảo luận với AI về cách xử lí ngoại lệ khi người dùng gõ nhầm một chữ cái bất kỳ (không phải số và cũng không phải từ `''kết thúc''`) trong lúc nhập dãy số.", "maxPoints": 2.0, "note": "Đạt chuẩn kỹ năng theo yêu cầu của Thầy Trương"}]}'::jsonb, '{"title": "Bài tập về nhà Tiết 27: Bài 16. Thực hành: Lập chương trình máy tính. (nhiệm vụ 2)", "description": "• Nhiệm vụ 1: Thực hành tạo chương trình `TimGiaTriLonNhat.sb3` trong Scratch, chạy kiểm thử với cả 3 bộ dữ liệu trong SGK trang 70 (số tự nhiên, số thập phân, số âm) và sửa lại chương trình để chạy đúng với cả dãy toàn số âm.\n• Nhiệm vụ 2: [Tích hợp NLS - NLC (3.4.TC2) & NLE (5.1.TC2)]: Chỉnh sửa chương trình vừa làm để sau khi nhập xong dãy số, nhân vật thông báo đồng thời cả Giá trị lớn nhất (`Max`) và Giá trị nhỏ nhất (`Min`) của dãy số.\n• Nhiệm vụ 3: [Tích hợp AI - AI.2 (9.C3.1)]: Thảo luận với AI về cách xử lí ngoại lệ khi người dùng gõ nhầm một chữ cái bất kỳ (không phải số và cũng không phải từ `''kết thúc''`) trong lúc nhập dãy số.", "acceptedFormats": ["image", "xlsx", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p28', 9, 28, 'Bài 17. Tin học và thế giới nghề nghiệp (mục 1)', 'Chủ đề 6. Hướng nghiệp với tin học', '1. Các nhóm nghề nghiệp chính trong lĩnh vực Tin học.', FALSE, 'NLE (5.4.TC2) & NLA (1.1.TC2): Khai thác thông tin hướng nghiệp để định hướng lựa chọn tổ hợp môn học và nhóm nghề Tin học phù hợp. · AI.1 (9.A3.3): Phân tích những thay đổi sâu sắc do Trí tuệ nhân tạo (AI) mang lại cho các ngành nghề và xác định kỹ năng cốt lõi để làm việc cùng AI.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 28: Bài 17. Tin học và thế giới nghề nghiệp (mục 1)", "phase1_khoi_dong": "Chuẩn bị bước vào lớp 10 THPT, khi đăng ký môn Tin học theo Chương trình GDPT 2018, nhà trường phát phiếu cho học sinh lựa chọn một trong hai định hướng: ''Khoa học máy tính (CS)'' hoặc ''Tin học ứng dụng (ICT)''. Nhiều bạn băn khoăn chưa rõ hai định hướng này khác nhau thế nào và dẫn tới những nhóm nghề nào trong tương lai.", "phase2_kham_pha": "Đọc SGK 1. Các nhóm nghề nghiệp chính trong lĩnh vực Tin học., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Chuẩn bị bước vào lớp 10 THPT, khi đăng ký môn Tin học theo Chương trình GDPT 2018, nhà trường phát phiếu cho học sinh lựa chọn một trong hai định hướng: ''Khoa học máy tính (CS)'' hoặc ''Tin học ứng dụng (ICT)''. Nhiều bạn băn khoăn chưa rõ hai định hướng này khác nhau thế nào và dẫn tới những nhóm nghề nào trong tương lai.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["ứng dụng", "Phát triển", "mạng", "Nhóm nghề Phát triển phần mềm", "Nhóm nghề Quản trị và thiết kế cơ sở dữ liệu"], "dragDrop": {"bucketA": "Định hướng Khoa học máy tính (Computer Science - CS)", "bucketB": "Định hướng Tin học ứng dụng (Applied Informatics - ICT)", "items": [{"id": "G9_T28_DD1", "text": "Tập trung nghiên cứu thuật toán, cấu trúc dữ liệu, viết chương trình, phát triển phần mềm và Trí tuệ nhân tạo", "correctBox": "A", "targetLabel": "Định hướng Khoa học máy tính (Computer Science - CS)", "points": 0.25}, {"id": "G9_T28_DD2", "text": "Phù hợp với học sinh yêu thích tư duy logic toán học, giải quyết bài toán lập trình và kiến tạo công nghệ mới", "correctBox": "A", "targetLabel": "Định hướng Khoa học máy tính (Computer Science - CS)", "points": 0.25}, {"id": "G9_T28_DD3", "text": "Tập trung khai thác phần mềm thiết kế đồ họa, chỉnh sửa ảnh/video, thiết kế web và quản lí cơ sở dữ liệu ứng dụng", "correctBox": "B", "targetLabel": "Định hướng Tin học ứng dụng (Applied Informatics - ICT)", "points": 0.25}, {"id": "G9_T28_DD4", "text": "Phù hợp với học sinh yêu thích ứng dụng công cụ số để sáng tạo nội dung đa phương tiện và tự động hóa công việc", "correctBox": "B", "targetLabel": "Định hướng Tin học ứng dụng (Applied Informatics - ICT)", "points": 0.25}]}, "fillBlanks": [{"statement": "Trong Chương trình Giáo dục phổ thông 2018 ở cấp THPT, môn Tin học được phân hóa thành hai định hướng chính là: Khoa học máy tính và Tin học [___].", "correctAnswer": "ứng dụng", "filledSentence": "Trong Chương trình Giáo dục phổ thông 2018 ở cấp THPT, môn Tin học được phân hóa thành hai định hướng chính là: Khoa học máy tính và Tin học «ứng dụng»."}, {"statement": "Nhóm nghề [___] phần mềm (`Software Development`) có công việc đặc thù là phân tích yêu cầu, thiết kế, lập trình, kiểm thử và sản phẩm chính là các hệ điều hành, phần mềm ứng dụng, trò chơi, ứng dụng di động.", "correctAnswer": "Phát triển", "filledSentence": "Nhóm nghề «Phát triển» phần mềm (`Software Development`) có công việc đặc thù là phân tích yêu cầu, thiết kế, lập trình, kiểm thử và sản phẩm chính là các hệ điều hành, phần mềm ứng dụng, trò chơi, ứng dụng di động."}, {"statement": "Nhóm nghề Quản trị hệ thống và [___] máy tính có sản phẩm chính là một hệ thống mạng và máy chủ hoạt động ổn định, thông suốt, an toàn bảo mật 24/7.", "correctAnswer": "mạng", "filledSentence": "Nhóm nghề Quản trị hệ thống và «mạng» máy tính có sản phẩm chính là một hệ thống mạng và máy chủ hoạt động ổn định, thông suốt, an toàn bảo mật 24/7."}], "matchingPairs": [{"left": "Nhóm nghề Phát triển phần mềm", "right": "Công việc: Phân tích, thiết kế, lập trình, kiểm thử <-> Sản phẩm: Các phần mềm hệ thống, ứng dụng web/di động, mô hình AI"}, {"left": "Nhóm nghề Quản trị và thiết kế cơ sở dữ liệu", "right": "Công việc: Thiết kế cấu trúc dữ liệu, sao lưu, tối ưu truy vấn <-> Sản phẩm: Kho cơ sở dữ liệu an toàn, toàn vẹn, truy xuất nhanh"}, {"left": "Nhóm nghề Quản trị hệ thống & An toàn thông tin", "right": "Công việc: Cài đặt, cấu hình mạng, giám sát tường lửa, chống tấn công mạng <-> Sản phẩm: Hệ thống mạng và thông tin vận hành thông suốt, bảo mật"}], "discussionPrompt": "Chuẩn bị bước vào lớp 10 THPT, khi đăng ký môn Tin học theo Chương trình GDPT 2018, nhà trường phát phiếu cho học sinh lựa chọn một trong hai định hướng: ''Khoa học máy tính (CS)'' hoặc ''Tin học ứng dụng (ICT)''. Nhiều bạn băn khoăn chưa rõ hai định hướng này khác nhau thế nào và dẫn tới những nhóm nghề nào trong tương lai."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 28: Bài 17. Tin học và thế giới nghề nghiệp (mục 1)", "description": "• Nhiệm vụ 1: Lập bảng tổng hợp 4 nhóm nghề Tin học tiêu biểu (Phát triển phần mềm; Quản trị & thiết kế CSDL; Quản trị hệ thống & mạng; Thiết kế đồ họa & truyền thông đa phương tiện): nêu rõ Công việc đặc thù, Sản phẩm chính và Định hướng THPT tương ứng.\n• Nhiệm vụ 2: [Tích hợp NLS - NLE (5.4.TC2) & NLA (1.1.TC2)]: Tự đánh giá sở thích, năng lực của bản thân sau khi học xong Chủ đề 4a (Bảng tính ứng dụng) và Chủ đề 5 (Giải quyết vấn đề & Lập trình) để viết bản định hướng lựa chọn ''Khoa học máy tính'' hay ''Tin học ứng dụng'' ở lớp 10.\n• Nhiệm vụ 3: [Tích hợp AI - AI.1 (9.A3.3)]: Trao đổi với AI để lập danh sách ''5 Kỹ năng của Chuyên gia Công nghệ tương lai'' giúp làm chủ AI thay vì bị AI thay thế.", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;
INSERT INTO public.curriculum_periods (
  id, grade, period_num, title, topic, content_desc, is_practical, digital_competency, worksheet_data, practical_task_data, homework_data
) VALUES (
  'k9-p29', 9, 29, 'Bài 17. Tin học và thế giới nghề nghiệp (mục 2)', 'Chủ đề 6. Hướng nghiệp với tin học', '2. Đặc điểm nghề nghiệp Tin học và Bình đẳng giới trong công nghệ.', FALSE, 'NLB (2.3.TC2) & NLE (5.4.TC2): Thảo luận về cơ hội phát triển năng lực số bình đẳng và định hướng lộ trình học tập cá nhân. · AI.1 (9.A3.3) & AI.3 (9.B3.1): Phân tích cơ hội nghề nghiệp trong kỷ nguyên số và xóa bỏ định kiến/thành kiến giới trong công nghệ và AI.', '{"title": "Phiếu Khám phá Cặp đôi Tiết 29: Bài 17. Tin học và thế giới nghề nghiệp (mục 2)", "phase1_khoi_dong": "Trong buổi tọa đàm hướng nghiệp cuối năm lớp 9, một chuyên gia công nghệ chia sẻ rằng: ngày nay người làm nghề Tin học không chỉ làm việc ở các công ty phần mềm (như FPT, Viettel, Google) mà còn làm việc ở hầu hết các ngân hàng, bệnh viện, trường học, cơ quan nhà nước; và tỉ lệ các nữ kỹ sư, nữ giám đốc dự án công nghệ đang ngày càng tăng cao.", "phase2_kham_pha": "Đọc SGK 2. Đặc điểm nghề nghiệp Tin học và Bình đẳng giới trong công nghệ., phân vai cùng bạn khám phá kiến thức cốt lõi.", "phase3_luyen_tap": "Cùng bạn hoàn thành bảng phân loại dữ liệu, điền khuyết và nối cặp kiến thức trên máy.", "phase4_van_dung": "Trong buổi tọa đàm hướng nghiệp cuối năm lớp 9, một chuyên gia công nghệ chia sẻ rằng: ngày nay người làm nghề Tin học không chỉ làm việc ở các công ty phần mềm (như FPT, Viettel, Google) mà còn làm việc ở hầu hết các ngân hàng, bệnh viện, trường học, cơ quan nhà nước; và tỉ lệ các nữ kỹ sư, nữ giám đốc dự án công nghệ đang ngày càng tăng cao.", "xpReward": 50, "timeLimitMin": 15, "wordBank": ["chuyển đổi", "tự học", "bình đẳng", "Bình đẳng giới trong nghề nghiệp Tin học"], "dragDrop": {"bucketA": "Đặc điểm môi trường làm việc và yêu cầu của nghề Tin học", "bucketB": "Bình đẳng giới và vai trò của phụ nữ trong ngành Công nghệ", "items": [{"id": "G9_T29_DD1", "text": "Nhu cầu nhân lực cao ở cả các công ty CNTT chuyên nghiệp lẫn mọi cơ quan, ngân hàng, bệnh viện, doanh nghiệp", "correctBox": "A", "targetLabel": "Đặc điểm môi trường làm việc và yêu cầu của nghề Tin học", "points": 0.25}, {"id": "G9_T29_DD2", "text": "Môi trường làm việc năng động, có thể làm việc từ xa toàn cầu nhưng đòi hỏi tinh thần tự học cập nhật công nghệ suốt đời", "correctBox": "A", "targetLabel": "Đặc điểm môi trường làm việc và yêu cầu của nghề Tin học", "points": 0.25}, {"id": "G9_T29_DD3", "text": "Cả nam và nữ đều có năng lực tư duy logic, sáng tạo và cơ hội thăng tiến bình đẳng trong mọi vị trí nghề nghiệp Tin học", "correctBox": "B", "targetLabel": "Bình đẳng giới và vai trò của phụ nữ trong ngành Công nghệ", "points": 0.25}, {"id": "G9_T29_DD4", "text": "Phụ nữ có nhiều thế mạnh về sự tỉ mỉ, kiên trì, thấu cảm người dùng (UI/UX, Kiểm thử QA, Phân tích nghiệp vụ BA, Quản lí dự án)", "correctBox": "B", "targetLabel": "Bình đẳng giới và vai trò của phụ nữ trong ngành Công nghệ", "points": 0.25}]}, "fillBlanks": [{"statement": "Người làm nghề tin học có thể làm việc tại các doanh nghiệp chuyên về công nghệ thông tin hoặc tại bộ phận CNTT của mọi cơ quan, tổ chức để vận hành hệ thống và thúc đẩy [___] số.", "correctAnswer": "chuyển đổi", "filledSentence": "Người làm nghề tin học có thể làm việc tại các doanh nghiệp chuyên về công nghệ thông tin hoặc tại bộ phận CNTT của mọi cơ quan, tổ chức để vận hành hệ thống và thúc đẩy «chuyển đổi» số."}, {"statement": "Do công nghệ kĩ thuật số và Trí tuệ nhân tạo thay đổi và phát triển không ngừng mỗi ngày, phẩm chất quan trọng hàng đầu của người làm nghề tin học là khả năng [___] suốt đời.", "correctAnswer": "tự học", "filledSentence": "Do công nghệ kĩ thuật số và Trí tuệ nhân tạo thay đổi và phát triển không ngừng mỗi ngày, phẩm chất quan trọng hàng đầu của người làm nghề tin học là khả năng «tự học» suốt đời."}, {"statement": "Lĩnh vực tin học là ngành lao động trí óc dựa trên tri thức, tư duy và kỹ năng mềm, do đó hoàn toàn phù hợp và mang lại cơ hội thành công [___] cho cả nam và nữ.", "correctAnswer": "bình đẳng", "filledSentence": "Lĩnh vực tin học là ngành lao động trí óc dựa trên tri thức, tư duy và kỹ năng mềm, do đó hoàn toàn phù hợp và mang lại cơ hội thành công «bình đẳng» cho cả nam và nữ."}], "matchingPairs": [{"left": "Doanh nghiệp chuyên về CNTT (Công ty phần mềm, viễn thông)", "right": "Trực tiếp nghiên cứu, sản xuất phần mềm, cung cấp dịch vụ đám mây, an ninh mạng, giải pháp AI cho khách hàng"}, {"left": "Bộ phận CNTT trong các tổ chức (Ngân hàng, Bệnh viện, Trường học, Nhà máy)", "right": "Vận hành hệ thống mạng nội bộ, quản trị cơ sở dữ liệu, hỗ trợ kỹ thuật và triển khai phần mềm nghiệp vụ"}, {"left": "Bình đẳng giới trong nghề nghiệp Tin học", "right": "Xóa bỏ định kiến giới; khuyến khích học sinh nữ tự tin theo đuổi các ngành STEM, Khoa học máy tính và Tin học ứng dụng"}], "discussionPrompt": "Trong buổi tọa đàm hướng nghiệp cuối năm lớp 9, một chuyên gia công nghệ chia sẻ rằng: ngày nay người làm nghề Tin học không chỉ làm việc ở các công ty phần mềm (như FPT, Viettel, Google) mà còn làm việc ở hầu hết các ngân hàng, bệnh viện, trường học, cơ quan nhà nước; và tỉ lệ các nữ kỹ sư, nữ giám đốc dự án công nghệ đang ngày càng tăng cao."}'::jsonb, NULL, '{"title": "Bài tập về nhà Tiết 29: Bài 17. Tin học và thế giới nghề nghiệp (mục 2)", "description": "• Nhiệm vụ 1: Viết một bài giới thiệu ngắn (150 chữ) hoặc thiết kế 3 trang chiếu trình bày ý kiến cá nhân của em về 1 nhóm nghề Tin học mà em ấn tượng nhất (Công việc, Sản phẩm, Yêu cầu kỹ năng và Cơ hội phát triển).\n• Nhiệm vụ 2: [Tích hợp NLS - NLB (2.3.TC2) & NLE (5.4.TC2)]: Xây dựng ''Bản Kế hoạch Hành động Hướng nghiệp Tin học Lớp 9 -> Lớp 10'': xác định định hướng sẽ chọn ở lớp 10 (`CS` hay `ICT`), các kỹ năng số và ngoại ngữ cần rèn luyện trong dịp hè.\n• Nhiệm vụ 3: [Tích hợp AI - AI.1 (9.A3.3) & AI.3 (9.B3.1)]: Thực hành phỏng vấn hướng nghiệp cùng AI: đóng vai ứng viên học sinh lớp 9 trò chuyện với AI (đóng vai Chuyên gia hướng nghiệp công nghệ) để khám phá lộ trình trở thành Kỹ sư CNTT / Chuyên gia ứng dụng số và lan tỏa thông điệp bình đẳng giới trong kỷ nguyên AI.", "acceptedFormats": ["image", "docx"], "dueInDays": 7}'::jsonb
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, topic = EXCLUDED.topic, content_desc = EXCLUDED.content_desc, is_practical = EXCLUDED.is_practical, digital_competency = EXCLUDED.digital_competency, worksheet_data = EXCLUDED.worksheet_data, practical_task_data = EXCLUDED.practical_task_data, homework_data = EXCLUDED.homework_data;

-- 2. NGÂN HÀNG 812 CÂU HỎI LUYỆN TẬP PHÂN HÓA (3 BIẾT - 2 HIỂU - 2 VẬN DỤNG)
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-1', 'k6-p01', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Những gì con người thu nhận được về thế giới xung quanh và về chính mình, mang lại sự hiểu biết cho con người được gọi là [___] và giúp con người đưa ra những lựa chọn hợp lí."', '["thông tin", "dữ liệu", "vật mang tin", "Dữ liệu"]'::jsonb, 0, 'Theo SGK Tin học 6: Những gì con người thu nhận được về thế giới xung quanh và về chính mình, mang lại sự hiểu biết cho con người được gọi là «thông tin» và giúp con người đưa ra những lựa chọn hợp lí.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-2', 'k6-p01', 2, 'Nhận biết', 'Phát biểu nào sau đây định nghĩa đúng nhất về thông tin theo SGK Tin học 6?', '["Các con số, chữ viết và kí hiệu được in trên trang sách giáo khoa.", "Những hiểu biết mà con người có được về thế giới xung quanh và về chính mình.", "Các phương tiện như thẻ nhớ, ổ cứng máy tính hoặc đĩa quang.", "Mọi âm thanh phát ra từ loa phát thanh của trường học."]'::jsonb, 1, 'Theo SGK Tin học 6 Kết nối tri thức, thông tin là tất cả những gì mang lại sự hiểu biết cho con người về thế giới xung quanh và về chính bản thân mình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-3', 'k6-p01', 3, 'Nhận biết', 'Dữ liệu trong Tin học được biểu diễn dưới những dạng cơ bản nào sau đây?', '["Chỉ bao gồm các con số toán học và bảng tính.", "Chỉ bao gồm các trang giấy vở và thẻ nhớ điện tử.", "Văn bản (chữ và số), hình ảnh và âm thanh.", "Sự suy nghĩ và cảm xúc bên trong bộ não con người."]'::jsonb, 2, 'Dữ liệu là thông tin dưới dạng được chứa trong vật mang tin, thường thể hiện dưới ba dạng cơ bản là văn bản (chữ, số), hình ảnh và âm thanh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-4', 'k6-p01', 4, 'Thông hiểu', 'Trong tình huống ''Dòng chữ Giữ im lặng được in trên tấm biển gỗ treo ở thư viện'', vật mang tin là gì?', '["Dòng chữ Giữ im lặng.", "Quy định không được nói chuyện ồn ào trong thư viện.", "Tấm biển gỗ treo ở thư viện.", "Học sinh đang đọc sách trong thư viện."]'::jsonb, 2, 'Tấm biển gỗ là phương tiện vật chất chứa dòng chữ (dữ liệu), nên tấm biển gỗ chính là vật mang tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-5', 'k6-p01', 5, 'Thông hiểu', 'Phương án nào sau đây là ví dụ về việc thông tin giúp con người đưa ra quyết định đúng đắn?', '["Xem lịch thi học kì trên bảng tin nhà trường để lập kế hoạch ôn tập đúng môn học.", "Cất quyển vở ghi chép vào trong cặp sách mà không mở ra xem.", "Chụp ảnh một tấm biển chỉ đường bằng tiếng nước ngoài mà mình hoàn toàn không hiểu.", "Mua một chiếc thẻ nhớ mới nhưng chưa lưu bất kì tệp tin nào vào trong đó."]'::jsonb, 0, 'Khi đọc lịch thi và hiểu được ngày thi từng môn (thu nhận thông tin), học sinh đưa ra quyết định lập kế hoạch ôn tập phù hợp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-6', 'k6-p01', 6, 'Vận dụng', 'Nhận định nào sau đây phản ánh đúng mối quan hệ giữa thông tin và dữ liệu?', '["Thông tin và dữ liệu là hai khái niệm hoàn toàn giống hệt nhau trong mọi trường hợp.", "Dữ liệu là cái chứa đựng thông tin, còn thông tin là ý nghĩa rút ra được từ dữ liệu đó.", "Có thể lưu trữ trực tiếp suy nghĩ của con người vào thẻ nhớ mà không cần chuyển thành dữ liệu.", "Mọi dữ liệu đều mang lại thông tin giống hệt nhau cho tất cả mọi người trên thế giới."]'::jsonb, 1, 'Dữ liệu là hình thức thể hiện (chữ, số, hình, âm) lưu trên vật mang tin, còn thông tin là nội dung, ý nghĩa mà con người hiểu được từ dữ liệu đó.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-1-7', 'k6-p01', 7, 'Vận dụng', 'Khi ứng dụng dịch thuật hoặc nhận diện hình ảnh AI quét một biển báo giao thông để báo cho người lái xe, bức ảnh chụp biển báo đóng vai trò gì?', '["Là vật mang tin bằng kim loại.", "Là dữ liệu đầu vào để hệ thống phân tích và trích xuất thông tin.", "Là quyết định cuối cùng của người lái xe.", "Là phần cứng màn hình của điện thoại thông minh."]'::jsonb, 1, 'Theo Khung năng lực AI (6.A2.1), bức ảnh chụp là dữ liệu đầu vào giúp công cụ AI nhận diện và cung cấp thông tin hỗ trợ con người.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-1', 'k6-p02', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Con người tiếp nhận thông tin từ thế giới bên ngoài thông qua năm [___] như mắt nhìn, tai nghe, mũi ngửi, lưỡi nếm và da cảm nhận."', '["giác quan", "xử lí thông tin", "lưu trữ thông tin", "Thu nhận thông tin"]'::jsonb, 0, 'Theo SGK Tin học 6: Con người tiếp nhận thông tin từ thế giới bên ngoài thông qua năm «giác quan» như mắt nhìn, tai nghe, mũi ngửi, lưỡi nếm và da cảm nhận.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-2', 'k6-p02', 2, 'Nhận biết', 'Quá trình xử lí thông tin của con người bao gồm bốn hoạt động cơ bản nào sau đây?', '["Nhập phím, in ấn, sao chép và xóa tệp tin.", "Thu nhận, lưu trữ, xử lí và truyền thông tin.", "Quan sát, vẽ tranh, ca hát và tập thể dục.", "Mua sắm, cất giữ, sửa chữa và vận chuyển hàng hóa."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 2, bốn hoạt động cơ bản của quá trình xử lí thông tin là: thu nhận, lưu trữ, xử lí và truyền (trao đổi) thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-3', 'k6-p02', 3, 'Nhận biết', 'Con người trực tiếp thu nhận thông tin từ thế giới xung quanh bằng cách nào?', '["Thông qua năm giác quan (thị giác, thính giác, khứu giác, vị giác, xúc giác).", "Chỉ thông qua việc đọc sách giáo khoa tại trường học.", "Chỉ thông qua bàn phím và chuột máy tính.", "Thông qua việc nói chuyện một mình trong phòng kín."]'::jsonb, 0, 'Năm giác quan của con người là các bộ phận trực tiếp thu nhận thông tin từ môi trường đưa về bộ não.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-4', 'k6-p02', 4, 'Thông hiểu', 'Hành động nào sau đây là ví dụ điển hình của hoạt động ''Lưu trữ thông tin''?', '["Ngửi thấy mùi thơm của món ăn mẹ đang nấu dưới bếp.", "Ghi chép công thức Toán học quan trọng vào sổ tay học tập.", "Nhắn tin nhắc bạn mang theo dụng cụ học tập vào sáng mai.", "So sánh giá tiền của hai quyển truyện tranh để chọn mua quyển rẻ hơn."]'::jsonb, 1, 'Ghi chép công thức vào sổ tay là việc đưa thông tin vào vật mang tin để cất giữ và xem lại khi cần, tức là lưu trữ thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-5', 'k6-p02', 5, 'Thông hiểu', 'Khi em nhìn thấy đám mây đen kéo đến, nhớ lại kinh nghiệm trời sắp mưa to và quyết định chạy ra thu quần áo vào nhà, việc ''suy luận trời sắp mưa và quyết định thu quần áo'' là hoạt động gì?', '["Thu nhận thông tin.", "Lưu trữ thông tin.", "Xử lí thông tin.", "Truyền thông tin."]'::jsonb, 2, 'Việc kết hợp dấu hiệu đám mây đen với kiến thức có sẵn để suy luận và ra quyết định hành động chính là hoạt động xử lí thông tin của bộ não.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-6', 'k6-p02', 6, 'Vận dụng', 'Hành động nào dưới đây thể hiện hoạt động ''Truyền thông tin''?', '["Lớp trưởng đứng trước lớp thông báo lịch lao động vệ sinh cuối tuần cho cả lớp nghe.", "Học sinh chăm chú nhìn lên màn hình máy chiếu để xem video bài giảng.", "Học sinh suy nghĩ tìm lời giải cho câu hỏi đố vui của thầy giáo.", "Học sinh đánh dấu trang sách đang đọc dở bằng một mảnh giấy nhỏ."]'::jsonb, 0, 'Lớp trưởng thông báo cho cả lớp nghe là chia sẻ, phát đi thông tin từ người này sang người khác, thuộc hoạt động truyền thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-2-7', 'k6-p02', 7, 'Vận dụng', 'Khi em nói câu lệnh ''Hãy đặt báo thức lúc 6 giờ sáng'' với trợ lí ảo AI trên điện thoại, bước micro điện thoại thu âm giọng nói của em tương ứng với hoạt động nào của con người?', '["Hoạt động truyền thông tin đi xa.", "Hoạt động thu nhận thông tin (như tai người nghe âm thanh).", "Hoạt động in ấn văn bản ra giấy.", "Hoạt động xóa bỏ dữ liệu cũ."]'::jsonb, 1, 'Theo Khung năng lực AI (6.A1.1), micro thu nhận âm thanh giọng nói đóng vai trò tương tự thính giác của con người trong bước thu nhận thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-1', 'k6-p03', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Các thiết bị như bàn phím, chuột, máy quét hay webcam giúp máy tính thực hiện bước [___] từ con người và môi trường bên ngoài."', '["thu nhận thông tin", "liên tục", "truyền thông tin", "Thiết bị vào (Bàn phím, Chuột, Micro)"]'::jsonb, 0, 'Theo SGK Tin học 6: Các thiết bị như bàn phím, chuột, máy quét hay webcam giúp máy tính thực hiện bước «thu nhận thông tin» từ con người và môi trường bên ngoài.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-2', 'k6-p03', 2, 'Nhận biết', 'Trong máy tính, nhóm thiết bị nào sau đây chuyên dùng để thu nhận thông tin (nhập dữ liệu vào máy)?', '["Màn hình, máy in và loa phát thanh.", "Bàn phím, chuột, micro và camera (webcam).", "Máy chiếu và tai nghe nhạc.", "Dây nguồn điện và quạt tản nhiệt."]'::jsonb, 1, 'Bàn phím, chuột, micro và camera là các thiết bị đầu vào giúp máy tính tiếp nhận chữ viết, thao tác, âm thanh và hình ảnh từ bên ngoài.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-3', 'k6-p03', 3, 'Nhận biết', 'Bộ phận nào trong máy tính đảm nhận chức năng lưu trữ dữ liệu lâu dài ngay cả khi đã tắt nguồn điện?', '["Chuột quang học.", "Bàn phím máy tính.", "Ổ đĩa cứng (hoặc thẻ nhớ, USB).", "Loa máy tính."]'::jsonb, 2, 'Ổ đĩa cứng, thẻ nhớ và USB là các thiết bị lưu trữ giúp cất giữ tệp dữ liệu lâu dài không bị mất khi tắt máy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-4', 'k6-p03', 4, 'Thông hiểu', 'Khi em nghe một bài giảng tiếng Anh phát ra từ loa máy tính và nhìn hình ảnh minh họa trên màn hình, máy tính đang thực hiện bước nào đối với em?', '["Thu nhận dữ liệu từ bàn phím.", "Truyền (xuất) thông tin ra cho con người tiếp nhận.", "Xóa toàn bộ dữ liệu trong ổ đĩa cứng.", "Quét mã vạch sản phẩm trong siêu thị."]'::jsonb, 1, 'Loa và màn hình là các thiết bị đầu ra, thực hiện truyền tải thông tin âm thanh và hình ảnh từ máy tính đến giác quan của người dùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-5', 'k6-p03', 5, 'Thông hiểu', 'Ưu điểm nào sau đây giải thích vì sao thư viện số trên máy tính có thể thay thế hàng chục kệ sách giấy khổng lồ?', '["Máy tính có khả năng lưu trữ lượng dữ liệu cực kì lớn trong một thiết bị nhỏ gọn.", "Máy tính có trọng lượng nặng hơn các kệ sách gỗ.", "Máy tính không cần sử dụng năng lượng điện để hoạt động.", "Máy tính chỉ lưu được các con số chứ không lưu được chữ viết."]'::jsonb, 0, 'Nhờ các thiết bị nhớ dung lượng lớn, một ổ cứng nhỏ gọn có thể lưu trữ hàng triệu trang sách, hình ảnh và video.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-6', 'k6-p03', 6, 'Vận dụng', 'Trong quá trình sử dụng máy tính ở phòng thực hành Tin học, hành vi nào sau đây tuân thủ đúng quy tắc bảo vệ thiết bị (TC1.4.1)?', '["Đập mạnh vào bàn phím và lắc chuột khi máy tính đang xử lí chậm.", "Tắt máy tính đúng quy trình (Shut down) và không tự ý rút dây cáp màn hình khi máy đang chạy.", "Mang nước ngọt và đồ ăn sáng đặt ngay lên trên bàn phím máy tính.", "Tự ý rút nóng USB khi máy tính đang sao chép tệp dữ liệu dở dang."]'::jsonb, 1, 'Tắt máy đúng quy trình và giữ gìn thiết bị cẩn thận giúp bảo vệ phần cứng máy tính và tránh hỏng dữ liệu đang lưu trữ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-3-7', 'k6-p03', 7, 'Vận dụng', 'Một ứng dụng AI học phát âm tiếng Anh hoạt động theo trình tự: (1) Học sinh đọc vào micro -> (2) Phần mềm AI chấm điểm độ chính xác -> (3) Hiển thị số điểm lên màn hình. Bước (2) tương ứng với hoạt động nào của máy tính?', '["Hoạt động thu nhận dữ liệu đầu vào.", "Hoạt động xử lí dữ liệu của máy tính.", "Hoạt động lưu trữ vào đĩa CD.", "Hoạt động ngắt kết nối mạng."]'::jsonb, 1, 'Theo mô hình xử lí thông tin (6.C1.1), việc phần mềm AI phân tích giọng đọc và tính toán điểm số chính là bước xử lí dữ liệu bên trong máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-1', 'k6-p04', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong máy tính, mỗi kí hiệu 0 hoặc 1 dùng để biểu diễn thông tin được gọi là một [___] và đây là đơn vị nhỏ nhất để biểu diễn và lưu trữ thông tin."', '["bit", "dãy bit", "số hóa", "Bit (Binary digit)"]'::jsonb, 0, 'Theo SGK Tin học 6: Trong máy tính, mỗi kí hiệu 0 hoặc 1 dùng để biểu diễn thông tin được gọi là một «bit» và đây là đơn vị nhỏ nhất để biểu diễn và lưu trữ thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-2', 'k6-p04', 2, 'Nhận biết', 'Máy tính sử dụng những kí hiệu nào để biểu diễn và lưu trữ mọi loại thông tin bên trong bộ nhớ?', '["Hai mươi chín chữ cái trong bảng chữ cái tiếng Việt.", "Mười chữ số từ 0 đến 9 của hệ thập phân.", "Chỉ hai kí hiệu là 0 và 1.", "Các nốt nhạc Đồ, Rê, Mi, Pha, Son, La, Si."]'::jsonb, 2, 'Theo SGK Tin học 6 Bài 3, mọi thông tin trong máy tính đều được biểu diễn bằng các dãy bit chỉ gồm hai kí hiệu 0 và 1.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-3', 'k6-p04', 3, 'Nhận biết', 'Một ''bit'' trong Tin học được hiểu là gì?', '["Một tệp văn bản dài 10 trang giấy.", "Đơn vị nhỏ nhất để biểu diễn và lưu trữ thông tin, tương ứng với một kí hiệu 0 hoặc 1.", "Một thiết bị phần cứng gắn bên ngoài màn hình máy tính.", "Một phần mềm dùng để vẽ tranh trên máy tính."]'::jsonb, 1, 'Bit (viết tắt của Binary digit) là đơn vị nhỏ nhất biểu diễn thông tin trong máy tính, chỉ nhận giá trị 0 hoặc 1.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-4', 'k6-p04', 4, 'Thông hiểu', 'Giả sử để biểu diễn hình ảnh đen trắng trên lưới ô vuông, ta quy ước ô đen là 1 và ô trắng là 0. Dãy bit ''11001'' biểu diễn hàng ô vuông nào sau đây?', '["Đen - Đen - Trắng - Trắng - Đen.", "Trắng - Trắng - Đen - Đen - Trắng.", "Đen - Trắng - Đen - Trắng - Đen.", "Đen - Đen - Đen - Trắng - Trắng."]'::jsonb, 0, 'Theo đúng thứ tự từng bit: 1 (Đen), 1 (Đen), 0 (Trắng), 0 (Trắng), 1 (Đen).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-5', 'k6-p04', 5, 'Thông hiểu', 'Số tự nhiên 5 trong hệ thập phân khi được biểu diễn sang hệ nhị phân (dãy bit) theo quy tắc SGK Tin học 6 là dãy nào sau đây?', '["100", "101", "110", "111"]'::jsonb, 1, 'Trong hệ nhị phân: 0 là 0, 1 là 1, 2 là 10, 3 là 11, 4 là 100, và 5 được biểu diễn là 101 (vì 1×4 + 0×2 + 1×1 = 5).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-6', 'k6-p04', 6, 'Vận dụng', 'Phát biểu nào sau đây là ĐÚNG khi nói về cách máy tính xử lí âm thanh và hình ảnh?', '["Máy tính cất giữ trực tiếp cuộn băng nhựa và tờ giấy ảnh vào trong CPU.", "Âm thanh và hình ảnh đều được số hóa thành các dãy bit (0 và 1) để máy tính xử lí.", "Máy tính chỉ chuyển văn bản thành dãy bit, còn âm thanh thì không chuyển thành dãy bit được.", "Con người phải tự đọc từng số 0 và 1 trên màn hình mỗi khi nghe nhạc."]'::jsonb, 1, 'Mọi dữ liệu văn bản, hình ảnh, âm thanh khi đưa vào máy tính đều được số hóa thành dãy bit để CPU xử lí, sau đó chuyển ngược lại thành hình ảnh, âm thanh trên màn hình và loa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-4-7', 'k6-p04', 7, 'Vận dụng', 'Khi một phần mềm AI nhận diện khuôn mặt học sinh qua camera điểm danh, bản chất máy tính đang làm việc với dữ liệu gì của bức ảnh?', '["Máy tính nhìn bằng mắt sinh học giống hệt con người.", "Máy tính phân tích ma trận các điểm ảnh đã được số hóa thành các con số và dãy bit.", "Máy tính in bức ảnh ra giấy rồi dùng thước kẻ đo.", "Máy tính chỉ đọc tên tệp ảnh chứ không phân tích nội dung ảnh."]'::jsonb, 1, 'Theo Khung năng lực AI (6.D1.1), hệ thống thị giác máy tính và AI xử lí bức ảnh thông qua các giá trị số (dãy bit) biểu diễn màu sắc và độ sáng của từng điểm ảnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-1', 'k6-p05', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong lưu trữ dữ liệu máy tính, 1 Byte (viết tắt là B) luôn bằng một dãy gồm [___] bit ghép lại với nhau."', '["8", "1000", "1 Kilobyte (KB)", "1 Megabyte (MB)"]'::jsonb, 0, 'Theo SGK Tin học 6: Trong lưu trữ dữ liệu máy tính, 1 Byte (viết tắt là B) luôn bằng một dãy gồm «8» bit ghép lại với nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-2', 'k6-p05', 2, 'Nhận biết', 'Một Byte (1 B) bằng bao nhiêu bit?', '["2 bit.", "8 bit.", "10 bit.", "1000 bit."]'::jsonb, 1, 'Theo quy ước chuẩn trong Tin học (SGK Tin học 6 Bài 3), 1 Byte = 8 bit.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-3', 'k6-p05', 3, 'Nhận biết', 'Thứ tự nào sau đây sắp xếp đúng các đơn vị đo dung lượng thông tin theo chiều TĂNG DẦN?', '["B, MB, KB, GB, TB.", "bit, B, KB, MB, GB, TB.", "TB, GB, MB, KB, B, bit.", "bit, KB, B, GB, MB, TB."]'::jsonb, 1, 'Thứ tự tăng dần chính xác là: bit -> Byte (B) -> Kilobyte (KB) -> Megabyte (MB) -> Gigabyte (GB) -> Terabyte (TB).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-4', 'k6-p05', 4, 'Thông hiểu', 'Theo cách tính xấp xỉ thập phân trong SGK Tin học 6, 1 Gigabyte (1 GB) tương đương khoảng bao nhiêu Megabyte (MB)?', '["Xấp xỉ 8 MB.", "Xấp xỉ 100 MB.", "Xấp xỉ 1000 MB.", "Xấp xỉ 1000000 MB."]'::jsonb, 2, 'Mỗi đơn vị liền kề từ Byte trở lên (KB, MB, GB, TB) gấp đơn vị đứng ngay trước nó xấp xỉ 1000 lần (chính xác nhị phân là 1024 lần), nên 1 GB ≈ 1000 MB.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-5', 'k6-p05', 5, 'Thông hiểu', 'Một chiếc USB có dung lượng 8 GB (tính xấp xỉ 8000 MB) có thể chứa được tối đa khoảng bao nhiêu tệp bài hát MP3, biết mỗi bài hát có dung lượng trung bình 4 MB?', '["Khoảng 20 bài hát.", "Khoảng 200 bài hát.", "Khoảng 2000 bài hát.", "Khoảng 32000 bài hát."]'::jsonb, 2, 'Số bài hát lưu được tối đa là: 8000 MB : 4 MB = 2000 bài hát.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-6', 'k6-p05', 6, 'Vận dụng', 'Trong các tệp tin dưới đây, tệp tin nào có dung lượng LỚN NHẤT?', '["Tệp văn bản BaiTap.docx có dung lượng 500 KB.", "Tệp hình ảnh PhongCanh.jpg có dung lượng 4 MB.", "Tệp video BaiGiang.mp4 có dung lượng 1.5 GB.", "Tệp ghi chú NhacNho.txt có dung lượng 800 Byte."]'::jsonb, 2, 'Ta đổi về cùng đơn vị: 800 B < 500 KB < 4 MB < 1.5 GB (≈ 1500 MB), do đó tệp video 1.5 GB có dung lượng lớn nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-5-7', 'k6-p05', 7, 'Vận dụng', 'Khi em sử dụng công cụ AI tạo hình ảnh hoặc video học tập, ứng dụng báo ''Thiết bị không đủ bộ nhớ trống để tải tệp 500 MB''. Em cần kiểm tra và xử lí như thế nào cho hợp lí?', '["Kiểm tra dung lượng trống của ổ đĩa/thẻ nhớ, xóa bớt các tệp rác không cần thiết hoặc chọn tải tệp ở độ phân giải vừa phải.", "Tắt màn hình đi rồi bật lại ngay lập tức mà không kiểm tra bộ nhớ.", "Gõ thêm thật nhiều chữ vào bàn phím để mở rộng ổ cứng.", "Rút dây chuột máy tính ra khỏi cổng kết nối."]'::jsonb, 0, 'Theo năng lực số (TC1.1.2) và năng lực AI (6.C3.1), người dùng cần kiểm tra dung lượng bộ nhớ trống và dọn dẹp tệp thừa hoặc chọn chất lượng tệp phù hợp với dung lượng thiết bị.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-1', 'k6-p06', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Hai hay nhiều máy tính và các thiết bị số được kết nối với nhau để truyền thông tin và dùng chung tài nguyên tạo thành một [___] hoàn chỉnh."', '["mạng máy tính", "USB", "tiết kiệm", "Mạng giao thông đường bộ"]'::jsonb, 0, 'Theo SGK Tin học 6: Hai hay nhiều máy tính và các thiết bị số được kết nối với nhau để truyền thông tin và dùng chung tài nguyên tạo thành một «mạng máy tính» hoàn chỉnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-2', 'k6-p06', 2, 'Nhận biết', 'Phát biểu nào sau đây nêu đúng khái niệm về mạng máy tính?', '["Một chiếc máy tính để bàn có gắn thêm loa và màn hình cỡ lớn.", "Hai hay nhiều máy tính và các thiết bị được kết nối để truyền thông tin cho nhau tạo thành một mạng máy tính.", "Tập hợp các bàn ghế và bảng viết được xếp ngay ngắn trong phòng học.", "Một phần mềm dùng để gõ văn bản tiếng Việt trên máy tính."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 4, hai hay nhiều máy tính và thiết bị được kết nối để truyền thông tin cho nhau tạo thành một mạng máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-3', 'k6-p06', 3, 'Nhận biết', 'Điểm chung cơ bản nhất của mọi loại mạng (như mạng đường bộ, mạng ống nước, mạng máy tính) là gì?', '["Đều dùng để vận chuyển nước sạch đến từng hộ gia đình.", "Đều là sự kết nối các thành phần với nhau để chia sẻ và vận chuyển/truyền tải thứ gì đó từ nơi này đến nơi khác.", "Đều chỉ hoạt động khi có sóng điện thoại di động.", "Đều không cần bất kì đường dẫn hay thiết bị kết nối nào."]'::jsonb, 1, 'Bản chất chung của mạng lưới là kết nối các điểm nút lại với nhau để trao đổi, luân chuyển và chia sẻ tài nguyên.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-4', 'k6-p06', 4, 'Thông hiểu', 'Lợi ích nào sau đây thuộc về việc ''Chia sẻ thiết bị phần cứng'' trong mạng máy tính?', '["Nhắn tin hỏi bài tập về nhà với bạn cùng lớp.", "Cả phòng làm việc gồm 10 máy tính cùng in tài liệu trên một chiếc máy in duy nhất.", "Tải một bức ảnh phong cảnh đẹp về màn hình nền.", "Nghe nhạc bằng tai nghe cá nhân cắm trực tiếp vào điện thoại của mình."]'::jsonb, 1, 'Máy in là thiết bị phần cứng; việc 10 máy tính cùng sử dụng 1 máy in qua mạng là chia sẻ thiết bị phần cứng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-5', 'k6-p06', 5, 'Thông hiểu', 'Trong phòng thực hành Tin học đã kết nối mạng LAN, cách làm nào nhanh nhất để cô giáo gửi tệp ''DeKiemTra.docx'' tới tất cả 35 máy tính học sinh?', '["In ra 35 tờ giấy rồi phát cho học sinh gõ lại từ đầu.", "Dùng 1 chiếc USB cắm lần lượt vào từng máy tính từ máy số 1 đến máy số 35.", "Chia sẻ tệp tin đó qua mạng máy tính phòng học để cả 35 máy cùng nhận được ngay lập tức.", "Đọc to từng câu cho học sinh chép vào vở."]'::jsonb, 2, 'Nhờ lợi ích chia sẻ dữ liệu của mạng máy tính, giáo viên có thể gửi hoặc chia sẻ thư mục qua mạng cho cả 35 máy cùng lúc chỉ trong vài giây.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-6', 'k6-p06', 6, 'Vận dụng', 'Trường hợp nào sau đây KHÔNG phải là mạng máy tính?', '["Hai máy tính xách tay kết nối với nhau qua Bluetooth để truyền tệp ảnh.", "Các máy tính trong thư viện nhà trường kết nối chung vào một bộ chuyển mạch (Switch).", "Hai chiếc máy tính để bàn đặt cạnh nhau trên một chiếc bàn gỗ nhưng không hề có kết nối dây hay sóng không dây nào.", "Điện thoại thông minh, ti vi thông minh và máy tính bảng trong gia đình cùng kết nối vào một bộ phát Wi-Fi."]'::jsonb, 2, 'Hai máy tính đặt cạnh nhau nhưng không có bất kì kết nối truyền thông tin nào với nhau thì chỉ là các máy tính rời rạc, chưa tạo thành mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-6-7', 'k6-p06', 7, 'Vận dụng', 'Trong một ngôi nhà thông minh (Smart Home), cảm biến nhiệt độ phòng khách gửi dữ liệu qua mạng Wi-Fi cho hệ thống điều khiển AI để tự động chỉnh máy điều hòa mát hơn. Ví dụ này minh họa điều gì?', '["Các thiết bị thông minh kết nối mạng để truyền dữ liệu và phối hợp xử lí tự động.", "Máy điều hòa tự hoạt động mà không cần điện năng.", "Cảm biến nhiệt độ là một chiếc máy in văn bản.", "Nhà thông minh không sử dụng mạng máy tính."]'::jsonb, 0, 'Theo Khung năng lực AI (6.A1.2), các thiết bị thông minh và AI kết nối qua mạng để trao đổi dữ liệu cảm biến và điều khiển thiết bị tự động.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-1', 'k6-p07', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Một mạng máy tính bao gồm ba thành phần chính là: các thiết bị đầu cuối, các [___] và phần mềm mạng."', '["thiết bị kết nối", "không dây", "phần mềm mạng", "Thiết bị đầu cuối"]'::jsonb, 0, 'Theo SGK Tin học 6: Một mạng máy tính bao gồm ba thành phần chính là: các thiết bị đầu cuối, các «thiết bị kết nối» và phần mềm mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-2', 'k6-p07', 2, 'Nhận biết', 'Ba thành phần chính cấu tạo nên một mạng máy tính là gì?', '["Bàn phím, chuột và màn hình máy tính.", "Thiết bị đầu cuối, thiết bị kết nối và phần mềm mạng.", "Dữ liệu, thông tin và vật mang tin.", "Loa, tai nghe và micro thu âm."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 4, một mạng máy tính gồm 3 thành phần chính: các thiết bị đầu cuối, các thiết bị kết nối và phần mềm mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-3', 'k6-p07', 3, 'Nhận biết', 'Thiết bị nào sau đây thuộc nhóm ''Thiết bị kết nối'' trong mạng máy tính?', '["Điện thoại thông minh của học sinh.", "Máy in văn phòng.", "Bộ chuyển mạch (Switch) và bộ thu phát Wi-Fi (Access Point).", "Màn hình máy chiếu."]'::jsonb, 2, 'Switch, Access Point, Router, Modem và dây cáp mạng là các thiết bị kết nối làm nhiệm vụ nối các thiết bị đầu cuối lại với nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-4', 'k6-p07', 4, 'Thông hiểu', 'Thiết bị nào sau đây thuộc nhóm ''Thiết bị đầu cuối''?', '["Dây cáp mạng xoắn đôi.", "Máy tính xách tay, máy tính bảng và điện thoại thông minh.", "Bộ chia cổng mạng Switch 24 cổng.", "Cáp quang biển quốc tế."]'::jsonb, 1, 'Máy tính xách tay, máy tính bảng, điện thoại thông minh, máy in là các thiết bị đầu cuối nằm ở điểm đầu/cuối của đường truyền mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-5', 'k6-p07', 5, 'Thông hiểu', 'Phương thức kết nối nào sau đây sử dụng sóng điện từ (không nhìn thấy bằng mắt thường) để truyền dữ liệu giữa các thiết bị?', '["Kết nối bằng cáp đồng xoắn đôi.", "Kết nối bằng cáp quang học.", "Kết nối không dây (Wi-Fi, Bluetooth).", "Kết nối bằng dây cáp máy in cổng USB."]'::jsonb, 2, 'Wi-Fi và Bluetooth sử dụng sóng vô tuyến (sóng điện từ) để truyền nhận dữ liệu không cần dây dẫn vật lí.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-6', 'k6-p07', 6, 'Vận dụng', 'Khi ngồi trên ô tô khách hoặc tàu hỏa đang di chuyển, hành khách muốn kết nối điện thoại vào mạng của xe thì nên dùng phương thức kết nối nào?', '["Kết nối không dây qua bộ phát Wi-Fi trên xe.", "Kéo dây cáp mạng dài hàng chục kilomet từ nhà theo xe.", "Dùng dây cáp nối vào máy in để bàn.", "Không thể kết nối mạng trên các phương tiện giao thông."]'::jsonb, 0, 'Trên các phương tiện di chuyển như ô tô, tàu hỏa, máy bay, kết nối không dây (Wi-Fi/4G/5G) là giải pháp linh hoạt và phù hợp nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-7-7', 'k6-p07', 7, 'Vận dụng', 'Khi em sử dụng một trợ lí học tập AI trực tuyến (như tra cứu từ điển AI hoặc dịch thuật đám mây) ở nơi công cộng, quy tắc kết nối mạng nào sau đây giúp bảo vệ an toàn thông tin (TC1.5.1, 6.D2.1)?', '["Tự động kết nối vào mọi mạng Wi-Fi lạ không có mật khẩu và nhập ngay tài khoản cá nhân.", "Chỉ kết nối vào mạng Wi-Fi tin cậy (có mật khẩu rõ ràng của trường học/gia đình) và kiểm tra tín hiệu kết nối ổn định.", "Cắt đứt dây cáp mạng của phòng thực hành để chuyển sang dùng Wi-Fi.", "Tắt phần mềm diệt virus mỗi khi bật kết nối Wi-Fi."]'::jsonb, 1, 'Kết nối vào mạng Wi-Fi tin cậy có mật khẩu bảo vệ giúp đảm bảo đường truyền ổn định cho ứng dụng đám mây/AI và tránh nguy cơ bị đánh cắp dữ liệu trên mạng Wi-Fi giả mạo.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-1', 'k6-p08', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Internet là mạng liên kết các [___] trên khắp thế giới lại với nhau thành một hệ thống thông tin khổng lồ."', '["mạng máy tính", "tương tác", "không chủ sở hữu", "Tính toàn cầu"]'::jsonb, 0, 'Theo SGK Tin học 6: Internet là mạng liên kết các «mạng máy tính» trên khắp thế giới lại với nhau thành một hệ thống thông tin khổng lồ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-2', 'k6-p08', 2, 'Nhận biết', 'Internet được định nghĩa chính xác là gì trong SGK Tin học 6?', '["Một mạng máy tính chỉ kết nối các máy tính trong phạm vi một trường học.", "Mạng liên kết các mạng máy tính trên khắp thế giới.", "Một phần mềm dùng để vẽ sơ đồ tư duy trên máy tính.", "Một chiếc ổ đĩa cứng dung lượng lớn đặt tại Mĩ."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 5, Internet là mạng liên kết các mạng máy tính trên khắp thế giới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-3', 'k6-p08', 3, 'Nhận biết', 'Bốn đặc điểm chính của Internet được nêu trong SGK Tin học 6 là gì?', '["Tính cục bộ, tính một chiều, tính đắt đỏ và tính độc quyền.", "Tính toàn cầu, tính tương tác, tính dễ tiếp cận và tính không chủ sở hữu.", "Tính nhỏ gọn, tính không dây, tính miễn phí hoàn toàn và tính cá nhân.", "Tính cố định, tính bảo mật tuyệt đối, tính ngoại tuyến và tính đóng kín."]'::jsonb, 1, 'Bốn đặc điểm cơ bản của Internet gồm: Tính toàn cầu, tính tương tác, tính dễ tiếp cận và tính không chủ sở hữu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-4', 'k6-p08', 4, 'Thông hiểu', 'Khi em đọc một bài giảng trên trang web học tập và có thể bấm nút gửi câu hỏi thảo luận trực tiếp với thầy giáo và các bạn khác, điều đó thể hiện đặc điểm nào của Internet?', '["Tính không chủ sở hữu.", "Tính tương tác.", "Tính một chiều.", "Tính ngoại tuyến."]'::jsonb, 1, 'Khả năng trao đổi, phản hồi hai chiều tức thời giữa người dùng với hệ thống và với những người dùng khác chính là tính tương tác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-5', 'k6-p08', 5, 'Thông hiểu', 'Ai là người sở hữu toàn bộ mạng Internet trên thế giới?', '["Một tỉ phú công nghệ tại nước Mĩ.", "Tổ chức Liên Hợp Quốc sở hữu riêng toàn bộ máy tính trên Internet.", "Không một cá nhân hay tổ chức nào sở hữu toàn bộ mạng Internet (tính không chủ sở hữu).", "Công ty sản xuất màn hình máy tính."]'::jsonb, 2, 'Internet hình thành từ sự kết nối tự nguyện của các mạng máy tính khắp thế giới, được quản lí tiêu chuẩn chung bởi các tổ chức quốc tế nhưng không thuộc sở hữu riêng của ai.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-6', 'k6-p08', 6, 'Vận dụng', 'Để máy tính ở nhà có thể truy cập được vào mạng Internet, gia đình em cần thực hiện việc gì sau đây?', '["Chỉ cần mua một chiếc bàn phím mới có đèn phát sáng.", "Đăng kí và thuê bao đường truyền từ một nhà cung cấp dịch vụ Internet (ISP).", "Cắm máy tính nối trực tiếp với chiếc quạt điện trong phòng.", "Xóa hết các tệp văn bản trong ổ đĩa cứng."]'::jsonb, 1, 'Muốn kết nối vào Internet, người dùng phải thông qua một nhà cung cấp dịch vụ Internet (ISP - Internet Service Provider).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-8-7', 'k6-p08', 7, 'Vận dụng', 'Nhờ đặc điểm nào của Internet mà một học sinh ở vùng nông thôn Việt Nam vẫn có thể truy cập kho bài giảng quốc tế và sử dụng các công cụ trợ lí học tập AI hiện đại?', '["Tính toàn cầu và tính dễ tiếp cận của Internet.", "Tính chỉ hoạt động trong giờ hành chính.", "Tính chỉ truyền được văn bản đen trắng.", "Tính giới hạn trong một tòa nhà duy nhất."]'::jsonb, 0, 'Theo Khung năng lực số (TC1.2.2) và AI (6.A1.1), tính toàn cầu và tính dễ tiếp cận của Internet giúp thu hẹp khoảng cách địa lí, đưa tri thức và công nghệ AI đến mọi học sinh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-1', 'k6-p09', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Internet cung cấp một kho [___] khổng lồ về mọi lĩnh vực khoa học, lịch sử, văn hóa giúp học sinh tự học và mở rộng hiểu biết."', '["tri thức", "trao đổi thông tin", "điều độ", "Học tập trực tuyến (E-learning)"]'::jsonb, 0, 'Theo SGK Tin học 6: Internet cung cấp một kho «tri thức» khổng lồ về mọi lĩnh vực khoa học, lịch sử, văn hóa giúp học sinh tự học và mở rộng hiểu biết.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-2', 'k6-p09', 2, 'Nhận biết', 'Hoạt động nào sau đây thể hiện lợi ích của Internet trong lĩnh vực ''Học tập và bồi dưỡng kiến thức''?', '["Chơi trò chơi điện tử bạo lực suốt đêm không ngủ.", "Truy cập trang web học tập để xem video bài giảng và tra cứu từ điển trực tuyến.", "Đăng các thông tin chưa kiểm chứng để trêu chọc người khác.", "Mở cùng lúc 20 trang web quảng cáo không liên quan đến bài học."]'::jsonb, 1, 'Xem video bài giảng và tra cứu từ điển trực tuyến là khai thác kho học liệu trên Internet để nâng cao kiến thức học tập.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-3', 'k6-p09', 3, 'Nhận biết', 'Khi bố mẹ sử dụng ứng dụng ngân hàng trên điện thoại có kết nối Internet để nộp học phí và trả tiền điện hàng tháng, bố mẹ đang khai thác lợi ích nào của Internet?', '["Dịch vụ thanh toán và giao dịch trực tuyến tiện ích.", "Chế tạo linh kiện phần cứng máy tính.", "Sửa chữa đường ống nước trong nhà.", "Vẽ tranh sơn dầu trên vải."]'::jsonb, 0, 'Internet hỗ trợ các dịch vụ tài chính, ngân hàng, mua sắm và hành chính công trực tuyến giúp tiết kiệm thời gian đi lại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-4', 'k6-p09', 4, 'Thông hiểu', 'Phương thức liên lạc nào trên Internet cho phép hai người ở hai quốc gia khác nhau vừa nói chuyện vừa nhìn thấy hình ảnh trực tiếp của nhau?', '["Gửi thư viết tay qua đường bưu điện truyền thống.", "Cuộc gọi video (Video call) qua các ứng dụng kết nối Internet.", "Ghi âm giọng nói vào thẻ nhớ rồi cất trong ngăn kéo.", "Soạn thảo văn bản trên phần mềm không kết nối mạng."]'::jsonb, 1, 'Dịch vụ gọi video qua Internet truyền tải đồng thời cả dữ liệu âm thanh và hình ảnh theo thời gian thực giữa người dùng ở mọi khoảng cách.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-5', 'k6-p09', 5, 'Thông hiểu', 'Cách sử dụng Internet nào sau đây là lành mạnh, hiệu quả và phù hợp với lứa tuổi học sinh THCS?', '["Chỉ dùng Internet để xem các video vô bổ và bỏ quên giờ học bài.", "Kết hợp tra cứu tư liệu học tập, trao đổi bài với bạn bè và giải trí lành mạnh đúng thời gian quy định.", "Chia sẻ mật khẩu tài khoản học tập của mình cho người lạ trên mạng.", "Ngồi dán mắt vào màn hình liên tục 5 giờ liền trong phòng tối."]'::jsonb, 1, 'Sử dụng Internet đúng mục đích học tập, giao tiếp văn minh và kiểm soát thời gian hợp lí là biểu hiện của năng lực số (TC1.2.3).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-6', 'k6-p09', 6, 'Vận dụng', 'Lợi ích nào của Internet giúp một bác sĩ ở bệnh viện tuyến huyện có thể hội chẩn ca bệnh khó với các chuyên gia y tế đầu ngành ở Hà Nội ngay tức khắc?', '["Khả năng truyền tải dữ liệu (hình ảnh X-quang, hồ sơ bệnh án) và hội họp trực tuyến từ xa qua Internet.", "Khả năng làm tăng dung lượng ổ cứng máy tính.", "Khả năng tự động in hóa đơn tiền điện.", "Khả năng tắt nguồn máy tính từ xa."]'::jsonb, 0, 'Internet cho phép truyền hồ sơ y tế số hóa và tổ chức hội chẩn khám chữa bệnh từ xa (Telemedicine) nhanh chóng, kịp thời.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-9-7', 'k6-p09', 7, 'Vận dụng', 'Khi sử dụng một công cụ gia sư AI trên Internet để hỗ trợ học môn Tin học và Ngoại ngữ, cách dùng nào sau đây mang lại lợi ích thực sự cho em (6.A3.1)?', '["Nhờ AI làm hộ toàn bộ bài tập về nhà rồi chép nguyên văn vào vở mà không đọc hiểu.", "Nhờ AI giải thích các khái niệm chưa hiểu rõ, gợi ý ví dụ minh họa và luyện phản xạ hỏi đáp để tự nắm vững bài học.", "Dùng AI để tạo các tin nhắn trêu đùa gửi vào nhóm lớp.", "Tin tưởng tuyệt đối mọi câu trả lời của AI mà không bao giờ đối chiếu với sách giáo khoa."]'::jsonb, 1, 'Theo Khung năng lực AI (6.A3.1), sử dụng AI như một người trợ lí giải thích khái niệm và luyện tập giúp phát triển tư duy tự học, thay vì phụ thuộc làm hộ bài tập.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-1', 'k6-p10', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Loại văn bản tích hợp nhiều dạng dữ liệu (văn bản, hình ảnh, âm thanh, video) và chứa các siêu liên kết dẫn tới tài liệu khác được gọi là [___] trên Internet."', '["siêu văn bản", "website", "WWW", "Siêu liên kết (Hyperlink)"]'::jsonb, 0, 'Theo SGK Tin học 6: Loại văn bản tích hợp nhiều dạng dữ liệu (văn bản, hình ảnh, âm thanh, video) và chứa các siêu liên kết dẫn tới tài liệu khác được gọi là «siêu văn bản» trên Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-2', 'k6-p10', 2, 'Nhận biết', 'Siêu văn bản (Hypertext) khác với văn bản thông thường trên trang giấy ở điểm cốt lõi nào?', '["Siêu văn bản chỉ chứa toàn các con số 0 và 1.", "Siêu văn bản tích hợp nhiều dạng dữ liệu (chữ, ảnh, âm thanh, video) và chứa các siêu liên kết tới các siêu văn bản khác.", "Siêu văn bản không thể hiển thị trên màn hình máy tính.", "Siêu văn bản chỉ viết được bằng tiếng Anh."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 6, siêu văn bản là loại văn bản tích hợp nhiều dạng dữ liệu khác nhau và các siêu liên kết (Hyperlink).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-3', 'k6-p10', 3, 'Nhận biết', 'Một ''Website'' được hiểu là gì?', '["Một chiếc cáp mạng nối từ máy tính đến bộ phát Wi-Fi.", "Tập hợp một hoặc nhiều trang web có liên quan được tổ chức dưới một địa chỉ truy cập chung.", "Một phần mềm soạn thảo văn bản như Microsoft Word.", "Một thiết bị lưu trữ dữ liệu gắn ngoài."]'::jsonb, 1, 'Website là tập hợp một hoặc nhiều trang web liên quan thuộc cùng một tổ chức/cá nhân và có chung một địa chỉ truy cập.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-4', 'k6-p10', 4, 'Thông hiểu', 'Trang đầu tiên hiện ra khi người dùng gõ địa chỉ của một website (ví dụ: https://moet.gov.vn) vào trình duyệt được gọi là gì?', '["Trang cuối (Endpage).", "Trang chủ (Homepage).", "Trang nháp (Draftpage).", "Phần mềm mạng."]'::jsonb, 1, 'Khi truy cập vào địa chỉ tên miền chính của một website, trang web mặc định mở ra đầu tiên luôn được gọi là Trang chủ (Homepage).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-5', 'k6-p10', 5, 'Thông hiểu', 'Trong các phần mềm sau đây, phần mềm nào là một Trình duyệt web (Web Browser)?', '["Microsoft Word.", "Google Chrome (hoặc Mozilla Firefox, Microsoft Edge).", "Windows File Explorer.", "Unikey."]'::jsonb, 1, 'Google Chrome, Mozilla Firefox, Microsoft Edge, Cốc Cốc, Safari là các phần mềm trình duyệt web chuyên dùng để truy cập WWW.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-6', 'k6-p10', 6, 'Vận dụng', 'Dấu hiệu trực quan nào cho biết một đối tượng trên trang web có gắn siêu liên kết khi em đưa con trỏ chuột tới đó?', '["Màn hình máy tính tự động tắt nguồn.", "Con trỏ chuột chuyển từ hình mũi tên sang hình bàn tay chỉ ngón trỏ.", "Bàn phím phát ra tiếng kêu bíp liên tục.", "Trang web tự động bị xóa khỏi máy tính."]'::jsonb, 1, 'Trên các trình duyệt web, khi di chuột qua vùng có gắn siêu liên kết (Hyperlink), con trỏ chuột sẽ đổi thành biểu tượng bàn tay.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-10-7', 'k6-p10', 7, 'Vận dụng', 'Khi em dùng trình duyệt web truy cập một trang bách khoa toàn thư bằng tiếng Anh để tìm hiểu khoa học, tính năng thông minh nào tích hợp trên trình duyệt hiện đại có thể giúp em đọc hiểu nhanh nội dung trang web đó (6.C2.1)?', '["Tính năng dịch trang web tự động hoặc trợ lí AI tóm tắt nội dung trang web.", "Tính năng tăng độ sáng đèn bàn phím.", "Tính năng định dạng ổ đĩa cứng.", "Tính năng kiểm tra dây cáp mạng."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C2.1), các trình duyệt web hiện đại tích hợp công cụ dịch tự động bằng AI và tóm tắt trang web giúp học sinh tiếp cận nguồn học liệu đa ngôn ngữ hiệu quả.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-1', 'k6-p11', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để truy cập một website khi đã biết địa chỉ chính xác, ta gõ địa chỉ đó vào [___] của trình duyệt web rồi nhấn phím Enter."', '["thanh địa chỉ", "thẻ", "đánh dấu trang", "Nút Back (Mũi tên sang trái)"]'::jsonb, 0, 'Theo SGK Tin học 6: Để truy cập một website khi đã biết địa chỉ chính xác, ta gõ địa chỉ đó vào «thanh địa chỉ» của trình duyệt web rồi nhấn phím Enter.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-2', 'k6-p11', 2, 'Nhận biết', 'Để truy cập vào trang web Báo Thiếu niên Tiền phong và Nhi đồng, em cần gõ địa chỉ `https://thieunien.vn` vào vị trí nào của trình duyệt?', '["Thanh trạng thái ở góc dưới màn hình.", "Thanh địa chỉ (Address bar) ở phía trên của cửa sổ trình duyệt.", "Phần mềm Paint vẽ hình.", "Thùng rác (Recycle Bin) trên màn hình nền."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 6, để mở một website đã biết địa chỉ, người dùng nhập địa chỉ đó vào thanh địa chỉ của trình duyệt và nhấn Enter.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-3', 'k6-p11', 3, 'Nhận biết', 'Trên thanh công cụ của trình duyệt web, nút có biểu tượng mũi tên quay sang trái (Back) dùng để làm gì?', '["Xóa vĩnh viễn trình duyệt web khỏi máy tính.", "Quay trở lại trang web vừa duyệt trước đó.", "Tắt nguồn màn hình máy tính.", "In trang web ra máy in."]'::jsonb, 1, 'Nút Back giúp người dùng quay lùi lại trang web vừa mở ngay trước trang hiện tại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-4', 'k6-p11', 4, 'Thông hiểu', 'Biểu tượng hình ngôi sao nằm ở cuối thanh địa chỉ trên trình duyệt Google Chrome hoặc Microsoft Edge có chức năng gì?', '["Đánh dấu trang web hiện tại vào danh sách yêu thích (Bookmark) để mở lại nhanh khi cần.", "Chỉnh độ phân giải của màn hình máy tính.", "Kiểm tra dung lượng ổ cứng C:.", "Đổi phông chữ của hệ điều hành."]'::jsonb, 0, 'Nhấp vào biểu tượng ngôi sao (Bookmark this tab) giúp lưu địa chỉ trang web vào thanh dấu trang để truy cập nhanh trong các lần sau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-5', 'k6-p11', 5, 'Thông hiểu', 'Muốn mở thêm một thẻ (Tab) mới trống trên cửa sổ trình duyệt web đang làm việc, em có thể dùng tổ hợp phím tắt nào?', '["Ctrl + T.", "Ctrl + P.", "Alt + F4.", "Shift + Delete."]'::jsonb, 0, 'Trên hầu hết các trình duyệt web thông dụng, tổ hợp phím Ctrl + T (hoặc nhấp dấu + trên thanh tiêu đề thẻ) dùng để mở một thẻ mới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-6', 'k6-p11', 6, 'Vận dụng', 'Khi đang đọc bài học trên một trang web mà hình ảnh bị lỗi chưa tải hết do mạng chập chờn, em nên nhấn nút nào trên trình duyệt?', '["Nút Đóng cửa sổ (dấu X màu đỏ).", "Nút Tải lại trang (Reload/Refresh - biểu tượng mũi tên cong vòng tròn hoặc phím F5).", "Nút Thu nhỏ cửa sổ (Minimize).", "Nút Mở thư mục tệp tin."]'::jsonb, 1, 'Nút Reload/Refresh (hoặc phím F5) giúp trình duyệt gửi yêu cầu tải lại toàn bộ nội dung trang web hiện tại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-11-7', 'k6-p11', 7, 'Vận dụng', 'Khi em sử dụng tính năng AI tích hợp trên trình duyệt để tóm tắt nhanh một bài báo khoa học dài trên web, hành động nào sau đây thể hiện tư duy phản biện và đánh giá thông tin tốt (6.C3.1)?', '["Sao chép ngay đoạn tóm tắt của AI mà không cần đọc bài báo gốc.", "Đọc lướt nội dung chính trên trang web gốc để kiểm tra xem bản tóm tắt của AI có đúng số liệu và đúng ý tác giả hay không.", "Xóa địa chỉ trang web gốc đi để không ai kiểm tra được.", "Tin rằng AI không bao giờ tóm tắt thiếu ý."]'::jsonb, 1, 'Theo Khung năng lực AI (6.C3.1), học sinh cần đối chiếu kết quả do AI tóm tắt với văn bản gốc trên trang web uy tín để đảm bảo tính chính xác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-1', 'k6-p12', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Công cụ hỗ trợ tìm kiếm thông tin trên Internet theo yêu cầu của người dùng thông qua các từ khóa được gọi là [___] (Search Engine)."', '["máy tìm kiếm", "từ khóa", "ngoặc kép", "Máy tìm kiếm (Search Engine)"]'::jsonb, 0, 'Theo SGK Tin học 6: Công cụ hỗ trợ tìm kiếm thông tin trên Internet theo yêu cầu của người dùng thông qua các từ khóa được gọi là «máy tìm kiếm» (Search Engine).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-2', 'k6-p12', 2, 'Nhận biết', 'Công dụng chính của Máy tìm kiếm (Search Engine) trên Internet là gì?', '["Soạn thảo và in ấn văn bản thay cho phần mềm Word.", "Giúp người dùng tìm kiếm thông tin trên Internet nhanh chóng thông qua các từ khóa.", "Sửa chữa các linh kiện phần cứng bị hỏng bên trong máy tính.", "Ngắt kết nối mạng của các máy tính khác trong phòng."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 7, máy tìm kiếm là công cụ giúp tìm kiếm thông tin trên Internet dưới dạng văn bản, hình ảnh, video dựa trên từ khóa của người dùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-3', 'k6-p12', 3, 'Nhận biết', 'Địa chỉ nào sau đây là địa chỉ của một Máy tìm kiếm thông dụng nhất hiện nay?', '["https://www.google.com (hoặc https://www.bing.com).", "C:\\Users\\Admin\\Documents.", "Control Panel -> Network.", "Microsoft PowerPoint."]'::jsonb, 0, 'Google (`google.com`), Bing (`bing.com`), Yahoo (`yahoo.com`) là các máy tìm kiếm phổ biến trên thế giới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-4', 'k6-p12', 4, 'Thông hiểu', 'Giả sử em cần tìm thông tin về ''Cách trồng và chăm sóc hoa hồng tại nhà'', từ khóa nào sau đây là phù hợp và hiệu quả nhất?', '["Hoa.", "Cách trồng chăm sóc hoa hồng.", "Trồng cây gì ở đâu.", "Nhà em có một vườn hoa rất đẹp."]'::jsonb, 1, 'Từ khóa ''Cách trồng chăm sóc hoa hồng'' ngắn gọn, chứa đầy đủ đối tượng (''hoa hồng'') và nội dung cần tìm (''cách trồng chăm sóc'').'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-5', 'k6-p12', 5, 'Thông hiểu', 'Khi đặt cụm từ khóa vào trong cặp dấu ngoặc kép, ví dụ `"Kết nối tri thức với cuộc sống"`, máy tìm kiếm sẽ thực hiện điều gì?', '["Xóa toàn bộ các trang web có cụm từ đó.", "Tìm và hiển thị các trang web chứa chính xác cụm từ nằm trong dấu ngoặc kép theo đúng thứ tự từ.", "Chỉ tìm các trang web bằng tiếng Anh.", "Chỉ tìm các tệp âm thanh MP3."]'::jsonb, 1, 'Dấu ngoặc kép giúp thu hẹp phạm vi tìm kiếm, bắt buộc kết quả phải chứa đúng nguyên văn cụm từ được đóng ngoặc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-6', 'k6-p12', 6, 'Vận dụng', 'Kết quả mà máy tìm kiếm trả về trên màn hình sau khi ta nhấn Enter thường bao gồm những gì?', '["Chỉ duy nhất một con số.", "Danh sách các liên kết (tiêu đề trang web, địa chỉ URL và đoạn trích ngắn nội dung chứa từ khóa).", "Toàn bộ ổ cứng của máy chủ Google.", "Một tờ giấy được in tự động ra khỏi màn hình."]'::jsonb, 1, 'Trang kết quả tìm kiếm hiển thị danh sách các mục, mỗi mục gồm tiêu đề trang web (gắn siêu liên kết), địa chỉ trang web và vài dòng mô tả tóm tắt.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-12-7', 'k6-p12', 7, 'Vận dụng', 'Điểm khác biệt khi em đặt câu hỏi cho công cụ tìm kiếm tích hợp AI so với gõ từ khóa trên máy tìm kiếm truyền thống là gì (6.A2.1)?', '["Máy tìm kiếm truyền thống khớp các từ khóa chính, còn công cụ AI có thể hiểu thêm câu hỏi tự nhiên có ngữ cảnh và tổng hợp câu trả lời gợi ý.", "Công cụ AI không cần kết nối mạng Internet.", "Máy tìm kiếm truyền thống chỉ hoạt động vào ban đêm.", "Công cụ AI chỉ tìm được hình ảnh chứ không tìm được chữ."]'::jsonb, 0, 'Theo Khung năng lực AI (6.A2.1), bên cạnh kĩ năng chọn từ khóa chuẩn cho máy tìm kiếm, học sinh nhận biết được AI xử lí ngôn ngữ tự nhiên để hiểu ngữ cảnh câu hỏi.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-1', 'k6-p13', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trên trang kết quả của máy tìm kiếm, để chỉ hiển thị các bức ảnh liên quan đến từ khóa, ta nhấp chuột vào thẻ [___] (Images) nằm ngay dưới khung nhập từ khóa."', '["Hình ảnh", "Save image as...", "nguồn trích dẫn", "Thẻ Tất cả (All)"]'::jsonb, 0, 'Theo SGK Tin học 6: Trên trang kết quả của máy tìm kiếm, để chỉ hiển thị các bức ảnh liên quan đến từ khóa, ta nhấp chuột vào thẻ «Hình ảnh» (Images) nằm ngay dưới khung nhập từ khóa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-2', 'k6-p13', 2, 'Nhận biết', 'Sau khi gõ từ khóa `Chùa Bút Tháp Bắc Ninh` vào máy tìm kiếm Google và nhấn Enter, muốn xem riêng các bức ảnh về ngôi chùa này, em chọn mục nào?', '["Cài đặt (Settings).", "Hình ảnh (Images).", "Bản đồ (Maps).", "Mua sắm (Shopping)."]'::jsonb, 1, 'Thẻ ''Hình ảnh'' (Images) trên máy tìm kiếm giúp lọc và hiển thị chuyên biệt các kết quả dưới dạng hình ảnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-3', 'k6-p13', 3, 'Nhận biết', 'Thao tác đúng để lưu một bức ảnh tìm được trên trang web về thư mục của em trên ổ đĩa D: là gì?', '["Nhấp chuột phải vào bức ảnh -> chọn ''Save image as...'' (Lưu hình ảnh thành...) -> chọn ổ đĩa D: và thư mục -> nhấn Save.", "Nhấn phím Delete trên bàn phím.", "Tắt trình duyệt web đi rồi bật lại.", "Gõ tên bức ảnh vào thanh địa chỉ."]'::jsonb, 0, 'Lệnh ''Save image as...'' trong bảng chọn chuột phải cho phép tải tệp hình ảnh từ trang web về lưu trong thư mục chỉ định trên máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-4', 'k6-p13', 4, 'Thông hiểu', 'Để sao chép một đoạn văn bản ngắn từ trang web sang tệp soạn thảo Word trên máy tính, em thực hiện trình tự nào sau đây?', '["Bôi đen đoạn văn bản trên web -> nhấn Ctrl + C -> mở tệp Word -> nhấn Ctrl + V (và ghi rõ nguồn).", "Nhấp đúp chuột vào nút Back của trình duyệt.", "Nhấn tổ hợp phím Alt + F4.", "Đổi tên trình duyệt web."]'::jsonb, 0, 'Tổ hợp phím Ctrl + C dùng để sao chép (Copy) phần văn bản đã chọn và Ctrl + V dùng để dán (Paste) vào tài liệu đích.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-5', 'k6-p13', 5, 'Thông hiểu', 'Khi lựa chọn trang web trong danh sách kết quả tìm kiếm để lấy số liệu làm bài tập Lịch sử - Địa lí, em nên ưu tiên chọn trang nào?', '["Một trang quảng cáo bán hàng không rõ tác giả.", "Trang cổng thông tin điện tử của tỉnh, trang báo chính thống hoặc trang bách khoa giáo dục uy tín.", "Một bình luận ẩn danh trên mạng xã hội.", "Một trang web có tiêu đề giật gân sai chính tả."]'::jsonb, 1, 'Theo năng lực số (TC1.1.2), người học cần chọn lọc thông tin từ các nguồn chính thống, có cơ quan chủ quản và tác giả rõ ràng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-6', 'k6-p13', 6, 'Vận dụng', 'Việc ghi chú ''Nguồn: Cổng thông tin điện tử tỉnh Bắc Ninh'' ở cuối bức ảnh hoặc đoạn trích dẫn trong bài thu hoạch của em thể hiện điều gì?', '["Làm cho bài viết bị trừ điểm.", "Thể hiện sự trung thực trong học tập, tôn trọng bản quyền tác giả và giúp người đọc kiểm chứng nguồn tin.", "Làm hỏng tệp văn bản.", "Là việc làm không cần thiết."]'::jsonb, 1, 'Trích dẫn nguồn đầy đủ là nguyên tắc đạo đức số và tôn trọng bản quyền khi khai thác thông tin từ Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-13-7', 'k6-p13', 7, 'Vận dụng', 'Khi tìm kiếm hình ảnh tư liệu lịch sử trên Internet, vì sao em cần phân biệt giữa ''ảnh chụp tư liệu thật'' và ''ảnh minh họa do AI vẽ lại'' (6.C2.1)?', '["Vì ảnh do AI tạo sinh có thể thêm thắt các chi tiết tưởng tượng không đúng với sự thật lịch sử.", "Vì ảnh AI không thể lưu vào ổ cứng máy tính.", "Vì ảnh chụp thật không có màu sắc.", "Vì máy tìm kiếm cấm tìm ảnh lịch sử."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C2.1), hình ảnh do AI tạo sinh chỉ mang tính minh họa/sáng tạo và có thể sai lệch chi tiết lịch sử, nên cần ghi rõ chú thích hoặc chọn ảnh tư liệu gốc xác thực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-1', 'k6-p14', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Dịch vụ chuyển thư dưới dạng số hóa qua mạng máy tính và Internet được gọi là [___] (hay viết tắt tiếng Anh là Email)."', '["thư điện tử", "@", "tên đăng nhập", "Tên đăng nhập (Username)"]'::jsonb, 0, 'Theo SGK Tin học 6: Dịch vụ chuyển thư dưới dạng số hóa qua mạng máy tính và Internet được gọi là «thư điện tử» (hay viết tắt tiếng Anh là Email).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-2', 'k6-p14', 2, 'Nhận biết', 'Ưu điểm nào sau đây là của dịch vụ Thư điện tử (Email) so với thư bưu điện truyền thống?', '["Có thể gửi kèm một chiếc xe đạp thật qua đường dây mạng.", "Thời gian chuyển thư gần như tức thời, chi phí thấp, có thể gửi đồng thời cho nhiều người và đính kèm tệp dữ liệu số.", "Không cần dùng đến máy tính hay điện thoại vẫn đọc được thư.", "Phải dán tem giấy lên màn hình máy tính trước khi bấm nút gửi."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 8, ưu điểm nổi bật của thư điện tử là tốc độ chuyển thư cực nhanh, chi phí thấp, gửi cùng lúc cho nhiều người và gửi kèm tệp tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-3', 'k6-p14', 3, 'Nhận biết', 'Cấu trúc tổng quát đúng của một địa chỉ thư điện tử là gì?', '["`<Tên_miền>#<Tên_đăng_nhập>`.", "`<Tên_đăng_nhập>@<Tên_miền>`.", "`www.<Tên_đăng_nhập>.com`.", "`<Tên_đăng_nhập> <Mật_khẩu>`."]'::jsonb, 1, 'Mọi địa chỉ thư điện tử đều có cấu trúc `<Tên_đăng_nhập>@<Tên_miền>`, ngăn cách bởi kí hiệu `@`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-4', 'k6-p14', 4, 'Thông hiểu', 'Trong các chuỗi kí tự dưới đây, chuỗi nào là một địa chỉ thư điện tử hợp lệ?', '["`www.vietnamnet.vn`.", "`tranvanbinh 6a@gmail.com` (có khoảng trắng).", "`tranvanbinh6a@gmail.com`.", "`tranvanbinh6a#gmail.com`."]'::jsonb, 2, 'Địa chỉ thư điện tử hợp lệ phải có kí hiệu `@` ngăn cách giữa tên đăng nhập và tên miền, đồng thời không được chứa dấu cách (khoảng trắng).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-5', 'k6-p14', 5, 'Thông hiểu', 'Hai hộp thư điện tử `minhanh@gmail.com` và `minhanh@yahoo.com` là hai địa chỉ như thế nào?', '["Là cùng một hộp thư duy nhất vì có chung tên đăng nhập `minhanh`.", "Là hai địa chỉ hộp thư hoàn toàn khác nhau vì thuộc hai nhà cung cấp dịch vụ có tên miền khác nhau (`gmail.com` và `yahoo.com`).", "Cả hai địa chỉ đều bị lỗi không dùng được.", "Là địa chỉ của hai trang web bán hàng."]'::jsonb, 1, 'Do khác phần tên miền đứng sau dấu `@` nên đây là hai tài khoản thư điện tử độc lập thuộc hai nhà cung cấp dịch vụ khác nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-6', 'k6-p14', 6, 'Vận dụng', 'Thành phần nào của tài khoản thư điện tử cần được giữ bí mật tuyệt đối, không tiết lộ cho người lạ?', '["Địa chỉ thư điện tử của mình.", "Mật khẩu (Password) đăng nhập hộp thư điện tử.", "Tên nhà cung cấp dịch vụ Gmail.", "Kí hiệu `@` trong địa chỉ thư."]'::jsonb, 1, 'Địa chỉ thư điện tử dùng để cho người khác gửi thư tới mình, còn mật khẩu phải giữ bí mật tuyệt đối để không ai xâm nhập trái phép hộp thư.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-14-7', 'k6-p14', 7, 'Vận dụng', 'Nhờ ứng dụng công nghệ Trí tuệ nhân tạo (AI) nào mà hộp thư điện tử có thể tự động phát hiện và ngăn chặn hàng tỉ bức thư quảng cáo độc hại, lừa đảo mỗi ngày (6.B1.1)?', '["Bộ lọc thư rác thông minh (AI Spam Filter) phân tích nội dung và nguồn gửi.", "Quạt làm mát bộ nguồn máy tính.", "Phần mềm vẽ hình Paint.", "Cáp mạng xoắn đôi."]'::jsonb, 0, 'Theo Khung năng lực AI (6.B1.1), bộ lọc thư rác thông minh là một trong những ứng dụng AI phổ biến và lâu đời nhất giúp bảo vệ an toàn cho người dùng Email.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-1', 'k6-p15', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi soạn một bức thư điện tử mới, dòng tóm tắt ngắn gọn nội dung chính của bức thư được viết vào ô [___] (Subject) để người nhận biết ngay mục đích thư."', '["Chủ đề", "chiếc kẹp giấy", "đăng xuất", "Trả lời thư (Reply)"]'::jsonb, 0, 'Theo SGK Tin học 6: Khi soạn một bức thư điện tử mới, dòng tóm tắt ngắn gọn nội dung chính của bức thư được viết vào ô «Chủ đề» (Subject) để người nhận biết ngay mục đích thư.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-2', 'k6-p15', 2, 'Nhận biết', 'Trong cửa sổ soạn thư điện tử của Gmail, địa chỉ email của người sẽ nhận bức thư được gõ vào ô nào?', '["Ô Chủ đề (Subject).", "Ô Đến / Người nhận (To).", "Ô Tìm kiếm trong thư.", "Ô Mật khẩu."]'::jsonb, 1, 'Ô ''Đến'' (To) là nơi nhập địa chỉ thư điện tử của một hoặc nhiều người nhận chính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-3', 'k6-p15', 3, 'Nhận biết', 'Biểu tượng hình ''Chiếc kẹp giấy'' trên thanh công cụ soạn thư điện tử dùng để thực hiện chức năng gì?', '["Xóa bức thư đang soạn vào thùng rác.", "Đính kèm tệp tin (văn bản, hình ảnh, bài tập...) từ máy tính vào bức thư.", "Đăng xuất khỏi tài khoản thư điện tử.", "Đổi mật khẩu của hộp thư."]'::jsonb, 1, 'Biểu tượng chiếc kẹp giấy (Attach files) là kí hiệu chuẩn quốc tế dùng để đính kèm tệp tin vào thư điện tử.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-4', 'k6-p15', 4, 'Thông hiểu', 'Khi nhận được thư thông báo lịch họp nhóm từ lớp trưởng, muốn gửi toàn bộ nội dung bức thư đó cho một bạn khác trong tổ cùng đọc, em chọn chức năng nào?', '["Chuyển tiếp (Forward).", "Xóa thư (Delete).", "Báo cáo thư rác (Report spam).", "Soạn thư trống mới từ đầu."]'::jsonb, 0, 'Chức năng Chuyển tiếp (Forward) giúp gửi tiếp bức thư đã nhận (kèm các tệp đính kèm có sẵn) tới địa chỉ của người nhận thứ ba.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-5', 'k6-p15', 5, 'Thông hiểu', 'Dòng Chủ đề (Subject) nào sau đây được viết đúng quy cách và lịch sự nhất khi em gửi bài thực hành Tin học cho thầy giáo?', '["`Thầy chấm ngay cho em nhé!!!`", "`Nộp bài thực hành Bài 8 - Trần Minh Khôi - Lớp 6A`", "`alo 123456`", "Để trống hoàn toàn không ghi gì cả."]'::jsonb, 1, 'Dòng chủ đề cần ngắn gọn, lịch sự, nêu rõ mục đích thư, tên bài, họ tên học sinh và lớp để giáo viên dễ quản lí.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-6', 'k6-p15', 6, 'Vận dụng', 'Sau khi đọc và gửi thư điện tử xong trên máy tính ở phòng thực hành Tin học của trường, việc làm nào sau đây là BẮT BUỘC để đảm bảo an toàn?', '["Chỉ cần tắt công tắc màn hình rồi đi về.", "Thực hiện Đăng xuất (Sign out / Log out) khỏi tài khoản thư điện tử của mình trước khi rời máy.", "Lưu mật khẩu của mình lên màn hình nền cho lần sau đỡ phải gõ.", "Rút dây bàn phím ra khỏi máy tính."]'::jsonb, 1, 'Nếu không đăng xuất trên máy tính dùng chung, người ngồi máy sau có thể mở hộp thư của em để đọc trộm hoặc gửi thư mạo danh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-15-7', 'k6-p15', 7, 'Vận dụng', 'Khi soạn thư điện tử, trình soạn thảo có tính năng thông minh gạch chân màu đỏ dưới các từ viết sai chính tả hoặc gợi ý từ ngữ hoàn chỉnh (6.A2.1). Em nên tận dụng tính năng này như thế nào?', '["Quan sát các vị trí được gợi ý để sửa lỗi chính tả, đảm bảo bức thư gửi đi chỉn chu và chuẩn tiếng Việt.", "Nhắm mắt bấm nút Gửi ngay không cần nhìn màn hình.", "Cố tình viết sai chính tả nhiều hơn.", "Xóa hết nội dung thư."]'::jsonb, 0, 'Theo Khung năng lực AI (6.A2.1), việc kết hợp công cụ kiểm tra chính tả tự động với sự rà soát của bản thân giúp nâng cao chất lượng giao tiếp số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-1', 'k6-p16', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Các đoạn mã hoặc chương trình máy tính xấu có khả năng tự nhân bản, phá hoại dữ liệu hoặc đánh cắp thông tin khi ta tải tệp lạ trên Internet được gọi chung là [___] hoặc phần mềm độc hại."', '["virus máy tính", "bắt nạt", "bố mẹ", "Lừa đảo trên mạng (Phishing/Scam)"]'::jsonb, 0, 'Theo SGK Tin học 6: Các đoạn mã hoặc chương trình máy tính xấu có khả năng tự nhân bản, phá hoại dữ liệu hoặc đánh cắp thông tin khi ta tải tệp lạ trên Internet được gọi chung là «virus máy tính» hoặc phần mềm độc hại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-2', 'k6-p16', 2, 'Nhận biết', 'Đâu KHÔNG phải là nguy cơ mất an toàn khi sử dụng Internet?', '["Máy tính bị nhiễm virus do tải các phần mềm bẻ khóa không rõ nguồn gốc.", "Bị kẻ xấu lừa đảo lấy cắp thông tin cá nhân qua các đường link trúng thưởng giả.", "Tra cứu bài giảng trên cổng học liệu chính thức của nhà trường với sự hướng dẫn của thầy cô.", "Bị bắt nạt, xúc phạm tinh thần trên mạng xã hội."]'::jsonb, 2, 'Tra cứu bài giảng trên cổng học liệu chính thức của nhà trường là hoạt động học tập lành mạnh, an toàn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-3', 'k6-p16', 3, 'Nhận biết', 'Khi nhận được một bức thư điện tử từ địa chỉ lạ có đính kèm tệp `QuaTangBiMat.exe`, em nên làm gì?', '["Mở ngay tệp đính kèm đó ra xem bên trong có gì.", "Chuyển tiếp bức thư đó cho tất cả các bạn trong lớp cùng mở.", "Tuyệt đối không mở tệp đính kèm lạ và xóa bức thư đó (hoặc báo thư rác) vì tệp `.exe` lạ rất dễ chứa virus.", "Tắt phần mềm diệt virus đi để mở tệp cho nhanh."]'::jsonb, 2, 'Theo SGK Tin học 6 Bài 9, quy tắc an toàn quan trọng là không mở thư điện tử và tệp đính kèm từ người lạ để tránh lây nhiễm virus máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-4', 'k6-p16', 4, 'Thông hiểu', 'Biểu hiện nào sau đây cho thấy một học sinh đang có nguy cơ bị ''Nghiện Internet và trò chơi trực tuyến''?', '["Mỗi ngày dành 30 phút tra cứu tài liệu học tập rồi tắt máy đi đá bóng với bạn.", "Thường xuyên thức khuya chơi game nhiều giờ liền, cáu gắt khi bố mẹ nhắc tắt máy và kết quả học tập sa sút.", "Sử dụng máy tính để vẽ sơ đồ tư duy ôn tập học kì.", "Gửi thư điện tử chúc mừng sinh nhật ông bà."]'::jsonb, 1, 'Dành quá nhiều thời gian cho trò chơi trên mạng, sao nhãng học tập và ảnh hưởng sức khỏe tâm sinh lí là dấu hiệu điển hình của nghiện Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-5', 'k6-p16', 5, 'Thông hiểu', 'Nếu chẳng may em hoặc bạn của em bị một nhóm người trên mạng nhắn tin đe dọa, nói xấu (bắt nạt qua mạng), cách ứng xử nào sau đây là ĐÚNG NHẤT?', '["Giữ kín một mình, lo sợ không dám nói với ai và làm theo mọi yêu cầu của kẻ bắt nạt.", "Nhắn tin chửi bới lại thật nặng nề trên mạng.", "Không trả lời kẻ bắt nạt, lưu lại bằng chứng (chụp màn hình) và báo ngay cho bố mẹ, thầy cô giáo để được bảo vệ.", "Đập vỡ máy tính của gia đình."]'::jsonb, 2, 'Khi gặp bắt nạt qua mạng (TC1.4.1), học sinh tuyệt đối không im lặng chịu đựng một mình mà cần lưu bằng chứng và báo ngay cho người lớn tin cậy (bố mẹ, thầy cô).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-6', 'k6-p16', 6, 'Vận dụng', 'Để bảo vệ máy tính khỏi sự tấn công của virus và phần mềm độc hại khi truy cập Internet, ta cần thực hiện biện pháp kĩ thuật nào?', '["Lau màn hình máy tính bằng khăn ướt mỗi ngày.", "Cài đặt phần mềm diệt virus uy tín, bật tường lửa và cập nhật thường xuyên.", "Dán băng dính che bàn phím máy tính.", "Đặt máy tính ở gần cửa sổ."]'::jsonb, 1, 'Phần mềm diệt virus và tường lửa là lá chắn kĩ thuật giúp phát hiện, ngăn chặn mã độc xâm nhập từ Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-16-7', 'k6-p16', 7, 'Vận dụng', 'Khi xem một đoạn video trên mạng thấy một nhân vật nổi tiếng quảng cáo thuốc chữa bách bệnh hoặc kêu gọi nộp tiền nhận thưởng, vì sao em cần nghi ngờ đó là sản phẩm giả mạo bằng AI (6.B2.1)?', '["Vì kẻ xấu có thể dùng công nghệ Deepfake AI ghép mặt và nhại giọng người nổi tiếng để lừa đảo người xem.", "Vì người nổi tiếng không bao giờ dùng Internet.", "Vì video trên mạng đều không có âm thanh.", "Vì máy tính không thể phát được video thật."]'::jsonb, 0, 'Theo Khung năng lực AI (6.B2.1), học sinh cần nhận thức được nguy cơ công nghệ Deepfake bị lạm dụng để tạo video/âm thanh giả mạo nhằm lừa đảo trên không gian mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-1', 'k6-p17', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Những thông tin gắn liền với một con người cụ thể như họ tên, ngày sinh, địa chỉ nhà, số điện thoại, trường lớp, ảnh chụp riêng tư được gọi là [___] và cần được bảo vệ cẩn thận."', '["thông tin cá nhân", "mạnh", "suy nghĩ kĩ", "Mật khẩu mạnh (Strong Password)"]'::jsonb, 0, 'Theo SGK Tin học 6: Những thông tin gắn liền với một con người cụ thể như họ tên, ngày sinh, địa chỉ nhà, số điện thoại, trường lớp, ảnh chụp riêng tư được gọi là «thông tin cá nhân» và cần được bảo vệ cẩn thận.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-2', 'k6-p17', 2, 'Nhận biết', 'Trong các mật khẩu dưới đây, mật khẩu nào được đánh giá là MẬT KHẨU MẠNH và an toàn nhất?', '["`12345678`.", "`abcdef`.", "`nguyenvanan`.", "`HocTapTot#6A25`."]'::jsonb, 3, 'Mật khẩu `HocTapTot#6A25` có độ dài trên 8 kí tự, kết hợp đầy đủ chữ hoa (`H`, `T`, `A`), chữ thường (`oc`, `ap`, `ot`), chữ số (`6`, `2`, `5`) và kí hiệu đặc biệt (`#`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-3', 'k6-p17', 3, 'Nhận biết', 'Thông tin nào sau đây thuộc về ''Thông tin cá nhân'' cần hạn chế công khai tràn lan trên Internet?', '["Công thức tính chu vi hình tròn trong sách giáo khoa Toán.", "Họ tên đầy đủ, ngày sinh, địa chỉ nhà riêng, số điện thoại gia đình và lịch trình đi lại hàng ngày của em.", "Tên thủ đô của các quốc gia Đông Nam Á.", "Quy tắc gõ bàn phím bằng 10 ngón tay."]'::jsonb, 1, 'Họ tên, ngày sinh, địa chỉ nhà, số điện thoại và lịch trình cá nhân là thông tin riêng tư; nếu lộ lọt có thể bị kẻ xấu lợi dụng gây mất an toàn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-4', 'k6-p17', 4, 'Thông hiểu', 'Hành động nào sau đây là ĐÚNG quy tắc bảo vệ tài khoản và mật khẩu?', '["Viết mật khẩu ra mảnh giấy rồi dán ngay lên màn hình máy tính ở phòng thực hành.", "Dùng chung một mật khẩu cực dễ nhớ cho tất cả mọi tài khoản và nói cho cả lớp cùng biết.", "Giữ bí mật mật khẩu (chỉ chia sẻ với bố mẹ khi cần thiết), định kì thay đổi mật khẩu và không lưu mật khẩu trên máy tính công cộng.", "Gửi mật khẩu qua tin nhắn cho người lạ tự xưng là nhân viên trò chơi."]'::jsonb, 2, 'Theo SGK Tin học 6 Bài 9, mật khẩu cần được giữ bí mật, không lưu trên máy dùng chung và không cung cấp cho người lạ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-5', 'k6-p17', 5, 'Thông hiểu', 'Khi em chụp được một bức ảnh hài hước của bạn cùng lớp, trước khi muốn đăng bức ảnh đó lên nhóm mạng xã hội, em cần làm gì để tôn trọng quyền riêng tư (TC1.4.2)?', '["Cứ đăng lên ngay để mọi người vào bình luận trêu chọc bạn.", "Hỏi ý kiến bạn và chỉ chia sẻ nếu bạn đồng ý vui vẻ, tuyệt đối không đăng ảnh làm ảnh hưởng danh dự của bạn.", "Chỉnh sửa ảnh cho xấu hơn rồi đăng ẩn danh.", "Gửi ảnh đó cho các trang web lạ."]'::jsonb, 1, 'Bảo vệ thông tin cá nhân không chỉ là bảo vệ mình mà còn phải tôn trọng quyền riêng tư và hình ảnh của người khác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-6', 'k6-p17', 6, 'Vận dụng', 'Vì sao SGK Tin học 6 khuyên chúng ta phải ''Suy nghĩ kĩ trước khi chia sẻ bất kì điều gì lên Internet''?', '["Vì thông tin một khi đã đưa lên Internet sẽ lan truyền rất nhanh, có thể bị người khác lưu lại và rất khó xóa bỏ hoàn toàn.", "Vì chia sẻ thông tin làm bàn phím nhanh bị mòn.", "Vì Internet chỉ cho phép mỗi người đăng 1 bài duy nhất trong đời.", "Vì máy tính sẽ bị sập nguồn ngay khi bấm nút chia sẻ."]'::jsonb, 0, 'Do tính toàn cầu và khả năng sao chép tức thời trên Internet, thông tin đã đăng tải rất khó kiểm soát và thu hồi triệt để.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-17-7', 'k6-p17', 7, 'Vận dụng', 'Khi sử dụng một ứng dụng chỉnh sửa ảnh hoặc chatbot AI miễn phí trên mạng, quy tắc an toàn dữ liệu nào sau đây là đúng đắn nhất (6.B3.1)?', '["Tải toàn bộ ảnh căn cước công dân và sổ hộ khẩu gia đình lên cho AI xem.", "Không cung cấp thông tin định danh cá nhân nhạy cảm, mật khẩu hay giấy tờ riêng tư của gia đình cho các công cụ AI trực tuyến.", "Nhập mật khẩu email của mình vào khung chat để nhờ AI kiểm tra độ mạnh.", "Cho phép ứng dụng lạ truy cập toàn bộ danh bạ và tin nhắn riêng tư."]'::jsonb, 1, 'Theo Khung năng lực AI (6.B3.1), dữ liệu nhập vào các công cụ AI công cộng có thể được lưu trữ trên máy chủ bên ngoài, nên tuyệt đối không nhập thông tin cá nhân nhạy cảm hay mật khẩu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-1', 'k6-p18', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Sơ đồ tư duy là phương pháp trình bày thông tin một cách [___] thông qua việc kết hợp từ khóa, đường nối phân nhánh, màu sắc và hình ảnh minh họa."', '["trực quan", "chủ đề chính", "từ khóa", "Chủ đề trung tâm"]'::jsonb, 0, 'Theo SGK Tin học 6: Sơ đồ tư duy là phương pháp trình bày thông tin một cách «trực quan» thông qua việc kết hợp từ khóa, đường nối phân nhánh, màu sắc và hình ảnh minh họa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-2', 'k6-p18', 2, 'Nhận biết', 'Sơ đồ tư duy (Mind Map) là gì?', '["Một đoạn văn bản dài nhiều trang không có tiêu đề.", "Một cách trình bày thông tin trực quan bằng cách sử dụng từ khóa, hình ảnh, màu sắc và các đường nối phân nhánh từ chủ đề trung tâm.", "Một bảng gồm toàn các con số thống kê tài chính.", "Một thiết bị phần cứng gắn trong thùng máy tính."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 10, sơ đồ tư duy là phương pháp trình bày thông tin trực quan giúp tổ chức và hệ thống hóa kiến thức hiệu quả.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-3', 'k6-p18', 3, 'Nhận biết', 'Trong sơ đồ tư duy, thành phần nào được đặt ở vị trí chính giữa (trung tâm) của sơ đồ?', '["Một chi tiết phụ nhỏ nhất của bài học.", "Chủ đề chính (ý tưởng trung tâm) của sơ đồ.", "Họ tên và chữ kí của người vẽ.", "Danh mục tài liệu tham khảo."]'::jsonb, 1, 'Chủ đề chính luôn được đặt ở vị trí trung tâm, từ đó các nhánh chính và nhánh phụ tỏa ra xung quanh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-4', 'k6-p18', 4, 'Thông hiểu', 'Khi ghi nội dung lên các nhánh của sơ đồ tư duy, nguyên tắc nào sau đây là ĐÚNG?', '["Chép nguyên văn từng đoạn văn dài 5-6 dòng lên nhánh.", "Sử dụng các từ khóa hoặc cụm từ khóa ngắn gọn, súc tích kết hợp biểu tượng/hình ảnh.", "Chỉ dùng một màu mực đen duy nhất cho tất cả các nhánh và viết chữ thật nhỏ.", "Không viết bất kì chữ nào lên nhánh."]'::jsonb, 1, 'Sử dụng từ khóa ngắn gọn, màu sắc phân biệt và hình ảnh minh họa giúp bộ não nắm bắt ý chính nhanh chóng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-5', 'k6-p18', 5, 'Thông hiểu', 'Hoạt động nào sau đây rất phù hợp để ứng dụng Sơ đồ tư duy trong học tập?', '["Tóm tắt kiến thức trọng tâm của một chương học và lập kế hoạch cho buổi dã ngoại của lớp.", "Tăng tốc độ vòng quay của ổ đĩa cứng.", "Diệt virus máy tính.", "Cài đặt lại hệ điều hành Windows."]'::jsonb, 0, 'Sơ đồ tư duy đặc biệt hiệu quả khi dùng để tóm tắt bài học, hệ thống hóa kiến thức, lên kế hoạch và động não tìm ý tưởng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-6', 'k6-p18', 6, 'Vận dụng', 'So với việc vẽ sơ đồ tư duy bằng phần mềm trên máy tính, việc vẽ sơ đồ tư duy thủ công trên giấy có ưu điểm gì?', '["Có thể thực hiện ngay ở bất kì đâu chỉ với giấy và bút màu, tự do sáng tạo nét vẽ theo ý thích mà không phụ thuộc thiết bị điện tử.", "Tự động gửi qua thư điện tử mà không cần máy quét hay chụp ảnh.", "Dễ dàng kéo thả di chuyển vị trí các nhánh mà không cần tẩy xóa.", "Tự động đính kèm tệp video chuyển động vào trang giấy."]'::jsonb, 0, 'Vẽ trên giấy có ưu điểm là linh hoạt, không cần thiết bị công nghệ và giúp người vẽ tự do phác thảo nét vẽ, hình minh họa tay.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-18-7', 'k6-p18', 7, 'Vận dụng', 'Khi em muốn nhờ một công cụ trợ lí AI gợi ý dàn ý ôn tập môn Khoa học tự nhiên lớp 6, việc yêu cầu AI ''Hãy liệt kê các nhánh chính và từ khóa nhánh phụ theo cấu trúc sơ đồ tư duy'' giúp ích gì (6.A2.1)?', '["Giúp kết quả trả về được phân cấp rõ ràng (Chủ đề chính -> Nhánh cấp 1 -> Nhánh cấp 2) để em dễ dàng nắm bắt cấu trúc bài học.", "Làm cho máy tính tự động in ra giấy màu.", "Xóa bỏ các bài học cũ trong sách giáo khoa.", "Biến văn bản thành tệp âm thanh."]'::jsonb, 0, 'Theo Khung năng lực AI (6.A2.1), việc định hướng cấu trúc đầu ra theo dạng phân nhánh từ khóa giúp AI trình bày thông tin mạch lạc, hệ thống.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-1', 'k6-p19', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi sử dụng phần mềm tạo sơ đồ tư duy trên máy tính, người dùng có thể dễ dàng [___] nội dung, di chuyển vị trí các nhánh hoặc đổi màu sắc mà không phải vẽ lại từ đầu như trên giấy."', '["chỉnh sửa", "Insert", "hình ảnh", "Phím Insert / Tab trên phần mềm Mind Map"]'::jsonb, 0, 'Theo SGK Tin học 6: Khi sử dụng phần mềm tạo sơ đồ tư duy trên máy tính, người dùng có thể dễ dàng «chỉnh sửa» nội dung, di chuyển vị trí các nhánh hoặc đổi màu sắc mà không phải vẽ lại từ đầu như trên giấy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-2', 'k6-p19', 2, 'Nhận biết', 'Đâu là một phần mềm chuyên dụng dùng để tạo sơ đồ tư duy trên máy tính được giới thiệu trong chương trình Tin học 6?', '["Windows Media Player.", "FreeMind (hoặc XMind, iMindMap, EdrawMind).", "Unikey.", "Calculator."]'::jsonb, 1, 'FreeMind, XMind, iMindMap, EdrawMind là các phần mềm thông dụng hỗ trợ thiết kế sơ đồ tư duy trên máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-3', 'k6-p19', 3, 'Nhận biết', 'Ưu điểm nào sau đây CHỈ CÓ ở sơ đồ tư duy tạo bằng phần mềm máy tính mà sơ đồ vẽ tay trên giấy truyền thống không thực hiện được?', '["Sử dụng nhiều màu sắc khác nhau cho các nhánh.", "Viết các từ khóa ngắn gọn trên từng nhánh.", "Gắn siêu liên kết (Hyperlink) trực tiếp vào nhánh để khi nhấp chuột sẽ mở trang web hoặc tệp video minh họa.", "Đặt chủ đề chính ở vị trí trung tâm."]'::jsonb, 2, 'Chỉ trên phần mềm máy tính mới có thể gắn siêu liên kết điện tử, tệp âm thanh/video và thu gọn/mở rộng nhánh động.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-4', 'k6-p19', 4, 'Thông hiểu', 'Trên các phần mềm sơ đồ tư duy thông dụng, để sửa lại chữ (từ khóa) của một nhánh đã tạo, em thực hiện thao tác nào?', '["Nhấp đúp chuột vào nhánh đó (hoặc chọn nhánh rồi nhấn phím F2) và gõ lại nội dung mới.", "Khởi động lại máy tính.", "Xóa bỏ toàn bộ phần mềm.", "Rút dây chuột ra khỏi máy tính."]'::jsonb, 0, 'Nhấp đúp chuột vào nhánh (hoặc nhấn phím sửa văn bản) cho phép chỉnh sửa trực tiếp từ khóa trên nhánh đó.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-5', 'k6-p19', 5, 'Thông hiểu', 'Khi đang chọn một nhánh chính cấp 1 trên phần mềm sơ đồ tư duy, muốn tạo thêm một nhánh phụ cấp 2 tỏa ra từ nhánh đó, em thường nhấn phím nào?', '["Phím Delete.", "Phím Insert (hoặc nhấp biểu tượng dấu `+` thêm nhánh con).", "Phím Esc.", "Phím Caps Lock."]'::jsonb, 1, 'Phím Insert (hoặc Tab / dấu `+` tùy phần mềm) được dùng để thêm một nhánh con cấp thấp hơn từ nhánh hiện tại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-6', 'k6-p19', 6, 'Vận dụng', 'Để xóa một nhánh bị thừa trong sơ đồ tư duy trên phần mềm, em thực hiện thao tác nào?', '["Nhấp chuột chọn nhánh cần xóa rồi nhấn phím Delete trên bàn phím.", "Nhấn tổ hợp phím Ctrl + S.", "Nhấn tổ hợp phím Ctrl + P.", "Nhấp chuột vào nút Phóng to cửa sổ."]'::jsonb, 0, 'Chọn đối tượng nhánh cần bỏ rồi nhấn phím Delete là thao tác chuẩn để xóa nhánh thừa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-19-7', 'k6-p19', 7, 'Vận dụng', 'Khi sử dụng tính năng AI tích hợp trong các phần mềm sơ đồ tư duy hiện đại để ''Tự động gợi ý thêm nhánh con'', học sinh cần làm gì để đảm bảo chất lượng bài học (6.C1.1)?', '["Giữ nguyên tất cả các nhánh AI tạo ra dù có những nhánh vượt ngoài chương trình lớp 6.", "Đọc kiểm tra từng nhánh AI gợi ý, đối chiếu với sách giáo khoa để giữ lại từ khóa đúng, xóa nhánh thừa và chỉnh sửa theo ngôn ngữ hiểu biết của mình.", "Không bao giờ lưu tệp vào máy tính.", "Xóa luôn chủ đề trung tâm."]'::jsonb, 1, 'Theo Khung năng lực AI (6.C1.1), người học cần làm chủ công cụ: chọn lọc, biên tập lại gợi ý của AI sao cho bám sát yêu cầu bài học trong SGK.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-1', 'k6-p20', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Việc thay đổi diện mạo của các chữ cái, con số như phông chữ, cỡ chữ, kiểu chữ đậm/nghiêng và màu sắc trong phần mềm soạn thảo được gọi là [___] kí tự."', '["định dạng", "đoạn", "Nhóm lệnh Font (trong thẻ Home)", "Nhóm lệnh Paragraph (trong thẻ Home)"]'::jsonb, 0, 'Theo SGK Tin học 6: Việc thay đổi diện mạo của các chữ cái, con số như phông chữ, cỡ chữ, kiểu chữ đậm/nghiêng và màu sắc trong phần mềm soạn thảo được gọi là «định dạng» kí tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-2', 'k6-p20', 2, 'Nhận biết', 'Định dạng văn bản trong phần mềm soạn thảo có tác dụng gì?', '["Tự động dịch văn bản từ tiếng Việt sang tiếng Pháp.", "Thay đổi hình thức trình bày giúp văn bản đẹp, rõ ràng, dễ đọc và dễ nhớ các ý chính hơn mà không làm thay đổi nội dung.", "Tăng dung lượng bộ nhớ RAM của máy tính.", "Kết nối máy tính vào mạng Wi-Fi."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 11, định dạng văn bản là trình bày các phần văn bản nhằm mục đích cho văn bản đẹp và dễ đọc hơn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-3', 'k6-p20', 3, 'Nhận biết', 'Thuộc tính nào sau đây thuộc về ''Định dạng kí tự''?', '["Lề trên và lề dưới của trang giấy A4.", "Phông chữ (Font), cỡ chữ (Size), kiểu chữ đậm/nghiêng/gạch chân và màu chữ.", "Hướng giấy thẳng đứng (Portrait) hay nằm ngang (Landscape).", "Khoảng cách giữa đoạn văn trên và đoạn văn dưới."]'::jsonb, 1, 'Phông chữ, cỡ chữ, kiểu chữ và màu chữ tác động trực tiếp lên diện mạo của từng kí tự nên thuộc nhóm định dạng kí tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-4', 'k6-p20', 4, 'Thông hiểu', 'Trên dải lệnh Home của phần mềm Microsoft Word, các nút lệnh Căn trái (Align Left), Căn giữa (Center), Căn phải (Align Right) và Căn đều hai bên (Justify) nằm trong nhóm lệnh nào?', '["Nhóm lệnh Font.", "Nhóm lệnh Paragraph (Đoạn văn bản).", "Nhóm lệnh Insert.", "Nhóm lệnh View."]'::jsonb, 1, 'Căn lề văn bản áp dụng cho cả đoạn văn nên nằm trong nhóm lệnh Paragraph của thẻ Home.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-5', 'k6-p20', 5, 'Thông hiểu', 'Để thiết lập khổ giấy A4 và căn chỉnh lề trang in (Margins) cho văn bản, em mở thẻ nào trên thanh công cụ của phần mềm Word?', '["Thẻ Layout (hoặc Page Layout).", "Thẻ Help.", "Thẻ Review.", "Thẻ Animations."]'::jsonb, 0, 'Các lệnh thiết lập trang văn bản như Margins (Lề trang), Orientation (Hướng trang), Size (Khổ giấy) nằm trong nhóm Page Setup của thẻ Layout (Page Layout).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-6', 'k6-p20', 6, 'Vận dụng', 'Khi trình bày một trang văn bản hành chính hoặc bài thu hoạch học tập, nguyên tắc thẩm mỹ nào sau đây là hợp lí nhất?', '["Mỗi dòng dùng một phông chữ và một màu sắc cầu vồng khác nhau.", "Sử dụng thống nhất phông chữ dễ đọc (như Times New Roman, Arial, Calibri), cỡ chữ phần thân bài khoảng 11-14pt, tiêu đề lớn hơn và in đậm.", "Toàn bộ bài viết đều dùng cỡ chữ 36pt và gạch chân tất cả các dòng.", "Đặt lề trái bằng 0 cm để chữ sát mép giấy."]'::jsonb, 1, 'Sự thống nhất về phông chữ, phân cấp rõ cỡ chữ giữa tiêu đề và nội dung giúp văn bản chuyên nghiệp, dễ theo dõi (TC1.3.1).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-20-7', 'k6-p20', 7, 'Vận dụng', 'Khi soạn thảo bài viết cho ''Sổ lưu niệm lớp 6A'' trên Word, công cụ trợ lí thông minh (như Microsoft Editor tích hợp AI) hiển thị đường gạch chân răng cưa dưới một từ. Điều đó giúp ích gì cho em (6.C2.1)?', '["Cảnh báo từ đó có thể bị gõ sai chính tả hoặc khoảng cách dấu câu chưa chuẩn để em kiểm tra và sửa lại ngay.", "Báo hiệu bàn phím sắp hỏng.", "Tự động tắt máy tính sau 1 phút.", "Xóa toàn bộ đoạn văn vừa gõ."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C2.1), công cụ kiểm tra chính tả và ngữ pháp thông minh hỗ trợ phát hiện lỗi gõ phím để văn bản đạt độ chuẩn xác cao.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-1', 'k6-p21', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trình bày thông tin ở dạng bảng giúp thông tin được sắp xếp theo các hàng và cột một cách cô đọng, giúp người đọc dễ tìm kiếm và dễ [___] các dữ liệu với nhau."', '["so sánh", "Insert", "Table Tools", "Insert Above / Insert Below"]'::jsonb, 0, 'Theo SGK Tin học 6: Trình bày thông tin ở dạng bảng giúp thông tin được sắp xếp theo các hàng và cột một cách cô đọng, giúp người đọc dễ tìm kiếm và dễ «so sánh» các dữ liệu với nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-2', 'k6-p21', 2, 'Nhận biết', 'Ưu điểm nổi bật của việc trình bày thông tin ở dạng bảng trong văn bản là gì?', '["Làm cho tệp văn bản có dung lượng lớn gấp 100 lần.", "Thông tin được trình bày cô đọng, rõ ràng theo hàng và cột, giúp dễ tìm kiếm và dễ so sánh, tổng hợp.", "Không cần phải gõ chữ vào máy tính.", "Tự động biến văn bản thành đoạn phim hoạt hình."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 12, trình bày thông tin dạng bảng giúp nội dung cô đọng, trực quan, dễ tra cứu và so sánh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-3', 'k6-p21', 3, 'Nhận biết', 'Để tạo một bảng mới trong phần mềm soạn thảo văn bản Microsoft Word, em thực hiện thao tác nào sau đây?', '["Chọn thẻ Home -> chọn Font.", "Chọn thẻ Insert -> chọn Table -> kéo chuột chọn số cột và số hàng cần tạo.", "Chọn thẻ View -> chọn Zoom.", "Chọn thẻ File -> chọn Print."]'::jsonb, 1, 'Lệnh tạo bảng (Table) luôn nằm trong dải lệnh Insert (Chèn) của phần mềm soạn thảo văn bản.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-4', 'k6-p21', 4, 'Thông hiểu', 'Trong thẻ Layout của nhóm Table Tools, nút lệnh `Insert Below` có tác dụng gì?', '["Chèn thêm một hàng mới vào ngay phía dưới hàng đang đặt con trỏ.", "Chèn thêm một hàng mới vào phía trên hàng hiện tại.", "Xóa toàn bộ bảng khỏi trang văn bản.", "Gộp hai cột lại với nhau."]'::jsonb, 0, 'Trong nhóm Rows & Columns: `Insert Above` là chèn hàng lên trên, còn `Insert Below` là chèn hàng xuống dưới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-5', 'k6-p21', 5, 'Thông hiểu', 'Để gộp 3 ô liên tiếp trên dòng tiêu đề của bảng thành 1 ô lớn duy nhất, sau khi bôi đen 3 ô đó, em chọn lệnh nào trong thẻ Layout (Table Tools)?', '["Split Cells.", "Merge Cells.", "Delete Columns.", "Insert Left."]'::jsonb, 1, 'Lệnh `Merge Cells` dùng để gộp nhiều ô đã chọn thành một ô duy nhất; còn `Split Cells` dùng để tách ô.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-6', 'k6-p21', 6, 'Vận dụng', 'Trong nhóm lệnh Alignment (Căn chỉnh) của thẻ Layout (Table Tools), có bao nhiêu vị trí căn lề văn bản bên trong một ô của bảng?', '["Chỉ có 2 vị trí (Trái và Phải).", "Có 9 vị trí căn chỉnh (kết hợp giữa Trên/Giữa/Dưới theo chiều dọc và Trái/Giữa/Phải theo chiều ngang).", "Chỉ có 1 vị trí duy nhất.", "Có 100 vị trí."]'::jsonb, 1, 'Khác với đoạn văn thông thường, một ô trong bảng có không gian 2 chiều (ngang và dọc) nên nhóm Alignment cung cấp 9 nút căn chỉnh (ví dụ: Align Center là chính giữa cả chiều ngang và chiều dọc).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-21-7', 'k6-p21', 7, 'Vận dụng', 'Khi em muốn nhờ công cụ trợ lí AI tạo giúp một mẫu Thời khóa biểu hoặc Danh sách nhóm để copy vào Word, câu lệnh (Prompt) nào sau đây sẽ cho kết quả chuẩn nhất (6.A2.1)?', '["''Hãy trình bày kết quả dưới dạng bảng gồm 5 cột: STT, Họ tên, Ngày sinh, Sở thích, Ước mơ''.", "''Hãy viết một bài thơ thật dài''.", "''Hãy vẽ một bức tranh phong cảnh''.", "''Đừng dùng bảng biểu''."]'::jsonb, 0, 'Theo Khung năng lực AI (6.A2.1), việc chỉ định rõ cấu trúc dạng bảng và tên các cột trong câu lệnh giúp AI xuất dữ liệu có cấu trúc chuẩn, dễ dàng sao chép sang bảng Word.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-1', 'k6-p22', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để tô màu nền làm nổi bật hàng tiêu đề đầu tiên của bảng, sau khi bôi đen hàng đó, ta mở thẻ Design (trong Table Tools) và nhấp vào nút lệnh [___] có hình chiếc thùng sơn."', '["Shading", "Align Center", "Insert", "Shading (Thẻ Design)"]'::jsonb, 0, 'Theo SGK Tin học 6: Để tô màu nền làm nổi bật hàng tiêu đề đầu tiên của bảng, sau khi bôi đen hàng đó, ta mở thẻ Design (trong Table Tools) và nhấp vào nút lệnh «Shading» có hình chiếc thùng sơn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-2', 'k6-p22', 2, 'Nhận biết', 'Trong nhóm thẻ Table Tools, muốn tô màu nền cho hàng tiêu đề của bảng, em sử dụng nút lệnh nào trong thẻ Design?', '["Borders.", "Shading.", "Merge Cells.", "Delete."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 12, nút lệnh Shading (biểu tượng thùng sơn đổ màu) trong thẻ Design dùng để tô màu nền cho các ô được chọn trong bảng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-3', 'k6-p22', 3, 'Nhận biết', 'Khi con trỏ chuột đang đặt ở ô cuối cùng (góc dưới bên phải) của bảng, nếu em nhấn phím `Tab` trên bàn phím thì điều gì sẽ xảy ra?', '["Toàn bộ bảng bị xóa mất.", "Phần mềm tự động chèn thêm một hàng mới vào cuối bảng và đưa con trỏ sang ô đầu tiên của hàng mới đó.", "Máy tính tự động in trang văn bản ra giấy.", "Phần mềm Word tự động đóng lại."]'::jsonb, 1, 'Một mẹo thực hành rất tiện lợi trong Word là khi đang ở ô cuối cùng của bảng, nhấn phím `Tab` sẽ tự động tạo thêm 1 hàng mới ở dưới cùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-4', 'k6-p22', 4, 'Thông hiểu', 'Để căn chỉnh nội dung văn bản trong hàng tiêu đề bảng nằm chính giữa ô theo cả chiều ngang và chiều dọc, em chọn nút nào trong nhóm Alignment (thẻ Layout)?', '["Align Top Left (Trên cùng bên trái).", "Align Center (Chính giữa).", "Align Bottom Right (Dưới cùng bên phải).", "Delete Rows."]'::jsonb, 1, 'Nút `Align Center` (nằm ở vị trí trung tâm trong 9 nút căn lề ô của nhóm Alignment) giúp căn nội dung vào chính giữa ô cả chiều ngang lẫn chiều dọc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-5', 'k6-p22', 5, 'Thông hiểu', 'Khi muốn kẻ đường viền bao quanh bảng bằng nét đôi đậm đẹp mắt, em sử dụng công cụ nào trong thẻ Design của Table Tools?', '["Nhóm lệnh Borders (chọn kiểu đường viền Border Styles, độ dày Line Weight và áp dụng trong Borders).", "Nhóm lệnh Font.", "Nút lệnh Split Table.", "Nút lệnh Find."]'::jsonb, 0, 'Các công cụ thiết lập kiểu nét kẻ, độ dày nét kẻ và màu đường viền bảng đều nằm trong nhóm Borders của thẻ Design.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-6', 'k6-p22', 6, 'Vận dụng', 'Trong bảng ''Danh sách thành viên tổ 1'', cách căn lề dữ liệu nào sau đây trong các cột là chuẩn mực và dễ nhìn nhất (TC1.3.2)?', '["Cột ''STT'' và ''Ngày sinh'' căn giữa; cột ''Họ và tên'' và ''Sở thích'' căn trái; hàng tiêu đề căn giữa và in đậm.", "Tất cả mọi cột đều căn phải sát mép.", "Hàng tiêu đề để chữ nhỏ hơn các hàng dữ liệu.", "Không kẻ đường viền và không phân biệt hàng tiêu đề."]'::jsonb, 0, 'Theo quy chuẩn trình bày bảng biểu văn bản, các mã số/STT/ngày tháng có độ dài đều nhau nên căn giữa, còn họ tên và diễn giải văn bản nên căn trái để thẳng lề đọc tự nhiên.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-22-7', 'k6-p22', 7, 'Vận dụng', 'Tính năng `Table Styles` (Mẫu bảng thiết kế sẵn) và `AutoFit` trong phần mềm soạn thảo văn bản hỗ trợ người dùng như thế nào (6.C2.1)?', '["Giúp tự động phối màu hài hòa cho bảng và tự động căn chỉnh độ rộng các cột vừa vặn với nội dung hoặc trang giấy chỉ bằng 1 cú nhấp chuột.", "Tự động xóa bớt tên các bạn trong tổ.", "Làm cho bảng không thể in ra giấy được.", "Chuyển bảng văn bản thành tệp âm thanh."]'::jsonb, 0, 'Sử dụng các công cụ định dạng thông minh như Table Styles và AutoFit giúp tiết kiệm thời gian và đảm bảo tính thẩm mỹ đồng bộ cho bảng biểu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-1', 'k6-p23', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong phần mềm Microsoft Word, các nút lệnh `Find` (Tìm kiếm) và `Replace` (Thay thế) nằm ở nhóm lệnh [___] ở góc bên phải của dải lệnh Home."', '["Editing", "Replace with", "Ctrl + H", "Find (Tổ hợp phím Ctrl + F)"]'::jsonb, 0, 'Theo SGK Tin học 6: Trong phần mềm Microsoft Word, các nút lệnh `Find` (Tìm kiếm) và `Replace` (Thay thế) nằm ở nhóm lệnh «Editing» ở góc bên phải của dải lệnh Home.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-2', 'k6-p23', 2, 'Nhận biết', 'Trong phần mềm soạn thảo văn bản Microsoft Word, nhóm lệnh chứa công cụ `Find` (Tìm kiếm) và `Replace` (Thay thế) nằm ở thẻ nào?', '["Thẻ Insert.", "Thẻ Home (nhóm lệnh Editing ở ngoài cùng bên phải).", "Thẻ Layout.", "Thẻ Design."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 13, hai lệnh Find và Replace nằm trong nhóm Editing của thẻ Home.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-3', 'k6-p23', 3, 'Nhận biết', 'Tổ hợp phím tắt nào dùng để mở nhanh khung Tìm kiếm (`Find`) trong phần mềm Word?', '["Ctrl + F.", "Ctrl + S.", "Ctrl + P.", "Ctrl + Z."]'::jsonb, 0, 'Ctrl + F (Find) là tổ hợp phím tắt chuẩn để mở công cụ tìm kiếm từ khóa trong văn bản và trình duyệt.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-4', 'k6-p23', 4, 'Thông hiểu', 'Trong hộp thoại `Find and Replace` (mở bằng nút Replace hoặc Ctrl + H), ô `Find what` dùng để nhập thông tin gì?', '["Nhập tên tệp văn bản mới.", "Nhập từ hoặc cụm từ cũ đang có trong văn bản mà ta muốn tìm để sửa.", "Nhập từ mới sẽ dùng để thay vào.", "Nhập số trang cần in."]'::jsonb, 1, 'Ô `Find what` là nơi gõ cụm từ cần tìm kiếm, còn ô `Replace with` là nơi gõ cụm từ mới dùng để thay thế.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-5', 'k6-p23', 5, 'Thông hiểu', 'Nếu muốn thay thế tự động tất cả mọi cụm từ `Lớp 6B` thành `Lớp 6A` trong toàn bộ tệp văn bản chỉ bằng một lần nhấp chuột, em chọn nút nào trong hộp thoại Find and Replace?', '["Find Next.", "Cancel.", "Replace All.", "More."]'::jsonb, 2, 'Nút `Replace All` thực hiện thay thế đồng loạt tất cả các vị trí khớp với từ khóa tìm kiếm trong toàn bộ văn bản.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-6', 'k6-p23', 6, 'Vận dụng', 'Nếu sau khi lỡ nhấn nút `Replace All`, em phát hiện có một số từ bị thay thế nhầm không như ý muốn, em có thể nhấn ngay tổ hợp phím nào để khôi phục (Hoàn tác - Undo) lại trạng thái trước đó?', '["Ctrl + Z (hoặc nút Undo trên thanh công cụ truy cập nhanh).", "Ctrl + C.", "Ctrl + V.", "Alt + F4."]'::jsonb, 0, 'Tổ hợp phím Ctrl + Z (Undo) giúp hủy bỏ thao tác vừa thực hiện để trả văn bản về nguyên trạng ngay trước khi bấm Replace All.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-23-7', 'k6-p23', 7, 'Vận dụng', 'Vì sao khi biên tập văn bản (kể cả văn bản do AI hỗ trợ tạo nháp), việc kết hợp giữa công cụ `Find` và kiểm tra ngữ cảnh câu văn lại rất quan trọng (6.C2.1)?', '["Vì công cụ tìm kiếm cơ bản chỉ so khớp mặt chữ (kí tự), nên con người cần xem xét ngữ cảnh câu văn để tránh thay thế nhầm các từ đồng âm hoặc từ ghép.", "Vì máy tính không biết đọc chữ tiếng Việt.", "Vì lệnh Find sẽ xóa mất ổ đĩa cứng.", "Vì lệnh Replace làm đổi màu màn hình."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C2.1), hiểu được giới hạn của việc khớp mẫu kí tự tự động giúp người dùng chọn cụm từ khóa đủ dài hoặc duyệt từng vị trí (`Find Next` -> `Replace`) để đảm bảo chính xác về ngữ nghĩa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-1', 'k6-p24', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi chèn một bức ảnh kỉ niệm vào trang văn bản Word, để có thể di chuyển bức ảnh linh hoạt và cho các dòng chữ bao quanh bức ảnh gọn gàng, ta sử dụng chức năng [___] (Bố trí văn bản quanh ảnh) trong thẻ Picture Format."', '["Wrap Text", "Page Break", "Tìm kiếm và thay thế", "Insert -> Cover Page / Page Break"]'::jsonb, 0, 'Theo SGK Tin học 6: Khi chèn một bức ảnh kỉ niệm vào trang văn bản Word, để có thể di chuyển bức ảnh linh hoạt và cho các dòng chữ bao quanh bức ảnh gọn gàng, ta sử dụng chức năng «Wrap Text» (Bố trí văn bản quanh ảnh) trong thẻ Picture Format.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-2', 'k6-p24', 2, 'Nhận biết', 'Để tạo một cuốn ''Sổ lưu niệm lớp 6A'' hoàn chỉnh trên phần mềm soạn thảo văn bản, em cần kết hợp những dạng dữ liệu và đối tượng nào đã học?', '["Chỉ gõ toàn chữ đen không có bảng và không có ảnh.", "Kết hợp hài hòa văn bản đã định dạng, sơ đồ tư duy, hình ảnh minh họa và bảng danh sách thành viên.", "Chỉ chèn duy nhất một bảng trống.", "Chỉ vẽ một hình tròn."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 14, bài thực hành tổng hợp yêu cầu kết hợp toàn bộ kĩ năng: sơ đồ tư duy, định dạng văn bản, chèn ảnh và trình bày bảng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-3', 'k6-p24', 3, 'Nhận biết', 'Khi chèn một bức ảnh vào trang văn bản, muốn kéo bức ảnh đặt ở góc phải và cho các dòng chữ tự động dàn đều bên trái bức ảnh, em chọn thiết lập nào?', '["Chọn bức ảnh -> vào thẻ Picture Format -> chọn Wrap Text -> chọn Square (hoặc Tight).", "Nhấn phím Delete.", "Mở hộp thoại Replace.", "Đổi khổ giấy sang A5."]'::jsonb, 0, 'Chức năng `Wrap Text` (với các tùy chọn `Square`, `Tight`, `Top and Bottom`...) giúp điều chỉnh cách văn bản bao quanh hình ảnh linh hoạt.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-4', 'k6-p24', 4, 'Thông hiểu', 'Thao tác nào giúp ngắt kết thúc trang bìa để chuyển ngay sang đầu trang thứ hai viết lời giới thiệu một cách chuyên nghiệp nhất?', '["Nhấn phím Spacebar (dấu cách) 500 lần.", "Nhấn tổ hợp phím `Ctrl + Enter` (hoặc chọn `Insert -> Page Break`).", "Nhấn phím Backspace.", "Tắt máy tính đi bật lại."]'::jsonb, 1, 'Lệnh `Page Break` (`Ctrl + Enter`) giúp ngắt sang trang mới cố định, không bị xô lệch dòng khi chỉnh sửa nội dung trang trước.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-5', 'k6-p24', 5, 'Thông hiểu', 'Để đánh số trang tự động cho cuốn Sổ lưu niệm giúp người đọc dễ theo dõi, em chọn lệnh nào trên thanh công cụ?', '["Chọn thẻ Insert -> chọn Page Number -> chọn vị trí đặt số trang (như Bottom of Page).", "Tự gõ số 1, 2, 3 vào giữa các đoạn văn.", "Chọn thẻ Home -> chọn Font Size.", "Chọn thẻ View -> chọn Ruler."]'::jsonb, 0, 'Lệnh `Insert -> Page Number` giúp đánh số trang tự động và đồng bộ ở phần đầu trang hoặc chân trang cho toàn bộ tài liệu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-6', 'k6-p24', 6, 'Vận dụng', 'Trong bước rà soát hoàn thiện cuốn Sổ lưu niệm, nếu phát hiện cụm từ `Niên khóa 2025 - 2026` bị gõ nhầm thành `Niên khóa 2024 - 2025` ở nhiều trang, em nên dùng công cụ nào để sửa nhanh nhất?', '["Công cụ Tìm kiếm và Thay thế (`Find and Replace` - Ctrl + H).", "Công cụ chèn bảng (`Insert Table`).", "Công cụ đổi hướng trang (`Orientation`).", "Công cụ vẽ sơ đồ tư duy."]'::jsonb, 0, 'Công cụ `Replace` (Ctrl + H) giúp tìm và sửa đồng loạt cụm từ bị nhầm ở mọi trang văn bản chỉ trong một thao tác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-24-7', 'k6-p24', 7, 'Vận dụng', 'Khi hoàn thiện sản phẩm số của nhóm và có sử dụng công cụ AI hỗ trợ gợi ý câu thơ hoặc hình vẽ trang trí trang bìa, hành xử nào sau đây thể hiện trách nhiệm và đạo đức số (6.D2.1)?', '["Kiểm duyệt kĩ nội dung cho phù hợp lứa tuổi học trò, bảo vệ thông tin riêng tư của các bạn và ghi chú rõ phần có sử dụng sự hỗ trợ của công cụ AI.", "Đăng công khai số điện thoại của tất cả phụ huynh trong lớp lên các trang web lạ.", "Lấy bài của nhóm khác đổi tên thành bài của nhóm mình.", "Không kiểm tra lại lỗi chính tả trước khi nộp."]'::jsonb, 0, 'Theo Khung năng lực AI (6.D2.1), tính minh bạch, trách nhiệm kiểm duyệt nội dung và bảo mật dữ liệu cá nhân là yêu cầu cốt lõi khi xuất bản sản phẩm số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-1', 'k6-p25', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong Tin học, một dãy hữu hạn các chỉ dẫn rõ ràng, có thứ tự sao cho khi thực hiện theo đúng các chỉ dẫn đó ta giải quyết được nhiệm vụ đã cho được gọi là [___] (Algorithm)."', '["thuật toán", "Đầu vào", "sơ đồ khối", "Hình chữ nhật trong sơ đồ khối"]'::jsonb, 0, 'Theo SGK Tin học 6: Trong Tin học, một dãy hữu hạn các chỉ dẫn rõ ràng, có thứ tự sao cho khi thực hiện theo đúng các chỉ dẫn đó ta giải quyết được nhiệm vụ đã cho được gọi là «thuật toán» (Algorithm).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-2', 'k6-p25', 2, 'Nhận biết', 'Phát biểu nào sau đây định nghĩa ĐÚNG NHẤT về thuật toán theo SGK Tin học 6?', '["Thuật toán là một chiếc máy tính xách tay hiện đại.", "Thuật toán là một dãy các chỉ dẫn rõ ràng, có trình tự sao cho khi thực hiện những chỉ dẫn này người ta giải quyết được vấn đề hoặc nhiệm vụ đã cho.", "Thuật toán là một trang web dùng để đọc báo trực tuyến.", "Thuật toán là tên gọi khác của bàn phím máy tính."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 15, thuật toán là dãy các chỉ dẫn rõ ràng, có trình tự nhằm giải quyết một vấn đề hoặc nhiệm vụ xác định.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-3', 'k6-p25', 3, 'Nhận biết', 'Trong bài toán ''Tính trung bình cộng của hai số tự nhiên x và y'', Đầu vào (Input) và Đầu ra (Output) là gì?', '["Đầu vào là trung bình cộng; Đầu ra là hai số x và y.", "Đầu vào là hai số x, y; Đầu ra là giá trị trung bình cộng của x và y.", "Đầu vào là số 2; Đầu ra là số 0.", "Không có đầu vào và không có đầu ra."]'::jsonb, 1, 'Dữ liệu đã cho ban đầu (hai số x và y) là Đầu vào (Input); kết quả cần tìm (trung bình cộng `(x + y) : 2`) là Đầu ra (Output).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-4', 'k6-p25', 4, 'Thông hiểu', 'Khi mô tả thuật toán bằng sơ đồ khối theo quy ước trong SGK Tin học 6, ''Hình thoi'' được dùng để biểu diễn thao tác nào?', '["Bắt đầu hoặc kết thúc thuật toán.", "Kiểm tra điều kiện (So sánh Đúng / Sai).", "Phép gán hoặc tính toán cộng trừ nhân chia.", "Chỉ hướng đi của dòng dữ liệu."]'::jsonb, 1, 'Trong sơ đồ khối chuẩn của SGK Tin học 6: Hình thoi biểu diễn kiểm tra điều kiện; Hình chữ nhật biểu diễn bước xử lí/tính toán; Hình ô van biểu diễn bắt đầu/kết thúc hoặc nhập/xuất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-5', 'k6-p25', 5, 'Thông hiểu', 'Trong sơ đồ khối mô tả thuật toán, ''Hình chữ nhật'' có ý nghĩa gì?', '["Biểu thị bước xử lí, tính toán hoặc thực hiện một hành động xác định.", "Biểu thị câu hỏi kiểm tra điều kiện Đúng/Sai.", "Biểu thị hướng di chuyển giữa các khối.", "Biểu thị việc tắt nguồn máy tính."]'::jsonb, 0, 'Hình chữ nhật trong sơ đồ khối luôn đại diện cho các bước thực hiện phép tính hoặc xử lí công việc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-6', 'k6-p25', 6, 'Vận dụng', 'Cho các bước pha một cốc nước cam bị xáo trộn như sau: (1) Vắt cam lấy nước vào cốc; (2) Rửa sạch quả cam và cắt đôi; (3) Thêm đường, khuấy đều và thưởng thức. Thứ tự đúng của thuật toán là gì?', '["(1) -> (2) -> (3).", "(2) -> (1) -> (3).", "(3) -> (2) -> (1).", "(2) -> (3) -> (1)."]'::jsonb, 1, 'Theo trình tự hợp lí: Phải rửa sạch và cắt đôi quả cam (2) trước, sau đó mới vắt lấy nước vào cốc (1), rồi cuối cùng thêm đường khuấy đều (3).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-25-7', 'k6-p25', 7, 'Vận dụng', 'Khi ứng dụng bản đồ thông minh tích hợp AI tìm đường đi ngắn nhất từ nhà em đến trường học, hệ thống AI đã thực hiện thuật toán với Input và Output nào (6.C1.1)?', '["Input: Vị trí nhà em, vị trí trường học và dữ liệu bản đồ giao thông; Output: Lộ trình đường đi ngắn nhất và thời gian di chuyển dự kiến.", "Input: Chiếc cặp sách; Output: Quyển vở ghi bài.", "Input: Thời gian di chuyển; Output: Tên hiệu trưởng nhà trường.", "Không sử dụng thuật toán nào cả."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C1.1), hệ thống bản đồ AI nhận dữ liệu đầu vào là điểm đi, điểm đến, tình trạng giao thông và chạy thuật toán tìm đường để xuất ra lộ trình tối ưu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-1', 'k6-p26', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong thuật toán, cấu trúc mà các bước được thực hiện lần lượt nối tiếp nhau theo một thứ tự duy nhất từ trên xuống dưới được gọi là cấu trúc [___] cơ bản."', '["tuần tự", "rẽ nhánh", "đủ", "Cấu trúc tuần tự"]'::jsonb, 0, 'Theo SGK Tin học 6: Trong thuật toán, cấu trúc mà các bước được thực hiện lần lượt nối tiếp nhau theo một thứ tự duy nhất từ trên xuống dưới được gọi là cấu trúc «tuần tự» cơ bản.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-2', 'k6-p26', 2, 'Nhận biết', 'Cấu trúc tuần tự trong thuật toán có đặc điểm gì?', '["Các bước được thực hiện lần lượt theo đúng thứ tự liệt kê từ đầu đến cuối, không có bước kiểm tra điều kiện rẽ nhánh.", "Luôn phải có ít nhất một hình thoi kiểm tra điều kiện.", "Lặp đi lặp lại một công việc 100 lần.", "Thực hiện bước cuối cùng trước rồi mới quay lại bước đầu tiên."]'::jsonb, 0, 'Theo SGK Tin học 6 Bài 16, cấu trúc tuần tự thực hiện các bước lần lượt theo một trình tự duy nhất từ đầu đến cuối.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-3', 'k6-p26', 3, 'Nhận biết', 'Khi nào ta cần sử dụng ''Cấu trúc rẽ nhánh'' trong thuật toán?', '["Khi mọi bước đều làm giống hệt nhau trong mọi hoàn cảnh.", "Khi phải dựa vào một điều kiện cụ thể (Đúng hoặc Sai) để quyết định lựa chọn bước thực hiện tiếp theo.", "Khi muốn tắt màn hình máy tính.", "Khi chỉ cần cộng hai số đã biết."]'::jsonb, 1, 'Cấu trúc rẽ nhánh được dùng khi hành động tiếp theo phụ thuộc vào kết quả kiểm tra một điều kiện Đúng hay Sai.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-4', 'k6-p26', 4, 'Thông hiểu', 'Phát biểu nào sau đây minh họa cho cấu trúc ''Rẽ nhánh dạng thiếu''?', '["Nếu chiều nay trời nắng ráo thì em sẽ ra sân tập đá bóng.", "Nếu số a chia hết cho 2 thì thông báo a là số chẵn, không thì thông báo a là số lẻ.", "Bước 1: Mở vở -> Bước 2: Cầm bút -> Bước 3: Viết bài.", "Lặp lại 5 lần động tác vươn thở."]'::jsonb, 0, 'Câu ''Nếu chiều nay trời nắng ráo thì em sẽ ra sân tập đá bóng'' chỉ nêu hành động khi điều kiện Đúng mà không nêu nhánh ''không thì...'', nên là rẽ nhánh dạng thiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-5', 'k6-p26', 5, 'Thông hiểu', 'Trong bài toán kiểm tra tính hợp lệ của phép chia `a : b`: ''Nếu b = 0 thì thông báo Không chia được cho 0, không thì tính thương c = a : b''. Đây là cấu trúc gì?', '["Cấu trúc tuần tự.", "Cấu trúc rẽ nhánh dạng thiếu.", "Cấu trúc rẽ nhánh dạng đủ.", "Không phải là thuật toán."]'::jsonb, 2, 'Biểu thức có đầy đủ hai nhánh xử lí cho cả trường hợp `b = 0` (Đúng) và `b ≠ 0` (Sai / Không thì), nên là cấu trúc rẽ nhánh dạng đủ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-6', 'k6-p26', 6, 'Vận dụng', 'Trong sơ đồ khối của cấu trúc rẽ nhánh, từ khối Hình thoi (kiểm tra điều kiện) luôn có mấy mũi tên đi ra tương ứng với các kết quả kiểm tra?', '["Chỉ có 1 mũi tên duy nhất.", "Có 2 mũi tên đi ra tương ứng với hai nhánh kết quả: `Đúng` (Yes/True) và `Sai` (No/False).", "Có 5 mũi tên đi ra.", "Không có mũi tên nào đi ra."]'::jsonb, 1, 'Mọi điều kiện kiểm tra trong hình thoi chỉ nhận một trong hai giá trị Đúng hoặc Sai, nên luôn có 2 nhánh mũi tên `Đúng` và `Sai` đi ra.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-26-7', 'k6-p26', 7, 'Vận dụng', 'Một chiếc quạt thông minh tích hợp cảm biến AI trong phòng học được lập trình: ''Nếu phát hiện có người trong phòng và nhiệt độ > 28°C thì bật quạt, không thì tắt quạt''. Quy tắc này thể hiện điều gì (6.D1.1)?', '["Hệ thống thông minh/AI sử dụng cấu trúc điều khiển rẽ nhánh dựa trên dữ liệu cảm biến để tự động ra quyết định.", "Chiếc quạt chạy ngẫu nhiên không theo quy tắc nào.", "Chiếc quạt chỉ hoạt động vào mùa đông.", "Cảm biến không liên quan đến thuật toán."]'::jsonb, 0, 'Theo Khung năng lực AI (6.D1.1), cấu trúc rẽ nhánh là nền tảng logic giúp các hệ thống tự động và AI phản ứng thông minh trước sự thay đổi của dữ liệu môi trường.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-1', 'k6-p27', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi trong thuật toán có một hoặc một nhóm thao tác cần phải thực hiện lặp đi lặp lại nhiều lần, ta sử dụng cấu trúc [___] để mô tả thuật toán ngắn gọn và rõ ràng."', '["lặp", "kiểm tra điều kiện", "Lặp với số lần biết trước", "Lặp với số lần chưa biết trước"]'::jsonb, 0, 'Theo SGK Tin học 6: Khi trong thuật toán có một hoặc một nhóm thao tác cần phải thực hiện lặp đi lặp lại nhiều lần, ta sử dụng cấu trúc «lặp» để mô tả thuật toán ngắn gọn và rõ ràng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-2', 'k6-p27', 2, 'Nhận biết', 'Ba cấu trúc điều khiển cơ bản dùng để biểu diễn mọi thuật toán trong Tin học là gì?', '["Nhập, Xuất và Lưu trữ.", "Cấu trúc tuần tự, cấu trúc rẽ nhánh và cấu trúc lặp.", "Văn bản, Hình ảnh và Âm thanh.", "Bàn phím, Chuột và Màn hình."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 16, ba cấu trúc điều khiển cơ bản của thuật toán là: cấu trúc tuần tự, cấu trúc rẽ nhánh và cấu trúc lặp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-3', 'k6-p27', 3, 'Nhận biết', 'Hoạt động nào sau đây trong đời sống hàng ngày thể hiện rõ nhất ''Cấu trúc lặp''?', '["Nếu trời mưa thì mặc áo mưa.", "Chép phạt hoặc luyện viết một từ tiếng Anh mới lặp đi lặp lại đủ 10 dòng vào vở.", "Nhìn đồng hồ xem bây giờ là mấy giờ.", "Bấm công tắc bật bóng đèn 1 lần."]'::jsonb, 1, 'Việc viết đi viết lại cùng một từ tiếng Anh cho đến khi đủ 10 dòng chính là thực hiện cấu trúc lặp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-4', 'k6-p27', 4, 'Thông hiểu', 'Dấu hiệu nhận biết dễ nhất của ''Cấu trúc lặp'' khi quan sát một sơ đồ khối thuật toán là gì?', '["Không có bất kì hình chữ nhật nào trong sơ đồ.", "Có đường mũi tên đi từ bước thực hiện công việc vòng quay ngược trở lại phía trước khối hình thoi kiểm tra điều kiện.", "Tất cả các mũi tên đều chỉ đi thẳng một mạch từ trên xuống dưới.", "Chỉ có duy nhất một hình ô van."]'::jsonb, 1, 'Trong sơ đồ khối, cấu trúc lặp luôn tạo thành một vòng khép kín có mũi tên quay ngược lại bước kiểm tra điều kiện (hình thoi).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-5', 'k6-p27', 5, 'Thông hiểu', 'Xét thuật toán: ''Bước 1: Đặt biến Đếm = 0; Bước 2: Chừng nào Đếm < 4 thì lặp lại (Vẽ 1 đoạn thẳng dài 5cm -> Quay phải 90 độ -> Tăng Đếm thêm 1)''. Khi thuật toán dừng lại, nhân vật đã vẽ được hình gì?', '["Một đường thẳng dài 20 cm.", "Một hình vuông có 4 cạnh bằng nhau (mỗi cạnh 5 cm).", "Một hình tam giác đều.", "Một hình tròn."]'::jsonb, 1, 'Vòng lặp thực hiện đúng 4 lần (khi Đếm = 0, 1, 2, 3), mỗi lần vẽ 1 cạnh và quay góc vuông 90 độ nên tạo thành một hình vuông khép kín.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-6', 'k6-p27', 6, 'Vận dụng', 'Trong cấu trúc lặp, thành phần nào giúp thuật toán không bị chạy lặp mãi mãi không bao giờ kết thúc?', '["Điều kiện kiểm tra để dừng vòng lặp (và sự thay đổi tiến tới điều kiện dừng sau mỗi lần lặp).", "Màu sắc của hình chữ nhật.", "Độ lớn của phông chữ.", "Tên của tệp văn bản."]'::jsonb, 0, 'Mỗi vòng lặp bắt buộc phải có điều kiện dừng hợp lí để khi hoàn thành nhiệm vụ, điều kiện lặp chuyển sang trạng thái kết thúc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-27-7', 'k6-p27', 7, 'Vận dụng', 'Khi một robot hút bụi thông minh tích hợp AI làm việc theo thuật toán: ''Lặp lại việc di chuyển hút bụi và tránh vật cản cho đến khi đã quét sạch toàn bộ diện tích sàn hoặc pin yếu < 15% thì quay về trạm sạc''. Điều kiện dừng của vòng lặp này là gì (6.C3.1)?', '["Đã quét sạch toàn bộ diện tích sàn hoặc mức pin < 15%.", "Khi robot mới bắt đầu khởi động.", "Khi trong nhà bật đèn sáng.", "Robot không bao giờ dừng lại."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C3.1), các thiết bị tự hành AI hoạt động trong vòng lặp cảm biến - xử lí liên tục và dừng lại khi đạt mục tiêu (sạch sàn) hoặc chạm ngưỡng an toàn (pin < 15%).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-1', 'k6-p28', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để máy tính có thể thực hiện được một thuật toán, con người cần diễn đạt thuật toán đó bằng một [___] (Programming Language) mà máy tính có thể hiểu được."', '["ngôn ngữ lập trình", "chương trình máy tính", "trực quan", "Thuật toán (Algorithm)"]'::jsonb, 0, 'Theo SGK Tin học 6: Để máy tính có thể thực hiện được một thuật toán, con người cần diễn đạt thuật toán đó bằng một «ngôn ngữ lập trình» (Programming Language) mà máy tính có thể hiểu được.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-2', 'k6-p28', 2, 'Nhận biết', 'Chương trình máy tính là gì theo định nghĩa trong SGK Tin học 6?', '["Là bản vẽ sơ đồ tư duy bằng bút màu trên giấy A4.", "Là mô tả của một thuật toán bằng một ngôn ngữ mà máy tính có thể ''hiểu'' và thực hiện được (ngôn ngữ lập trình).", "Là các thiết bị phần cứng như màn hình, chuột và bàn phím.", "Là một bức thư điện tử gửi qua mạng."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 17, chương trình máy tính là tập hợp các câu lệnh mô tả thuật toán bằng ngôn ngữ lập trình để máy tính thực hiện được.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-3', 'k6-p28', 3, 'Nhận biết', 'Công cụ nào đóng vai trò là phương tiện giao tiếp giúp con người viết ra các chương trình để điều khiển máy tính?', '["Ngôn ngữ lập trình (như Scratch, Python, Pascal, C++...).", "Phần mềm xem ảnh.", "Dây cáp mạng xoắn đôi.", "Thẻ nhớ USB."]'::jsonb, 0, 'Ngôn ngữ lập trình là ngôn ngữ chuyên dụng dùng để viết chương trình máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-4', 'k6-p28', 4, 'Thông hiểu', 'Ngôn ngữ lập trình trực quan Scratch giúp học sinh lớp 6 tạo chương trình máy tính bằng cách nào?', '["Gõ hàng nghìn dòng mã nhị phân 0 và 1.", "Kéo thả và lắp ghép các khối lệnh (Blocks) có sẵn theo đúng trình tự thuật toán.", "Hàn các mạch điện tử bằng mỏ hàn.", "Vẽ bảng trên phần mềm Microsoft Word."]'::jsonb, 1, 'Scratch là môi trường lập trình trực quan, cho phép tạo chương trình bằng thao tác kéo thả và lắp ghép các khối lệnh màu sắc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-5', 'k6-p28', 5, 'Thông hiểu', 'Trong chương trình Scratch, khi nhiều khối lệnh được ghép nối tiếp nhau từ trên xuống dưới thành một khối liền mạch, máy tính sẽ thực hiện chúng theo thứ tự nào?', '["Thực hiện ngẫu nhiên khối nào trước cũng được.", "Thực hiện lần lượt từng khối lệnh theo thứ tự từ trên xuống dưới (tương ứng với cấu trúc tuần tự của thuật toán).", "Thực hiện từ khối dưới cùng ngược lên khối trên cùng.", "Chỉ thực hiện khối lệnh ở giữa."]'::jsonb, 1, 'Máy tính luôn thực thi các câu lệnh trong kịch bản chương trình tuần tự từ trên xuống dưới theo đúng luồng điều khiển.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-6', 'k6-p28', 6, 'Vận dụng', 'So sánh giữa ''Thuật toán'' và ''Chương trình máy tính'', phát biểu nào sau đây là ĐÚNG?', '["Thuật toán là cách giải quyết vấn đề (con người hiểu), còn chương trình máy tính là bản thể hiện thuật toán đó bằng ngôn ngữ lập trình để máy tính thực thi.", "Có thể viết chương trình máy tính mà không cần biết máy tính phải làm các bước gì.", "Thuật toán chỉ dùng cho môn Toán, không liên quan đến máy tính.", "Chương trình máy tính chính là chiếc ổ đĩa cứng."]'::jsonb, 0, 'Thuật toán là linh hồn (ý tưởng và các bước giải), còn chương trình máy tính là hình thức biểu đạt thuật toán bằng ngôn ngữ lập trình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-28-7', 'k6-p28', 7, 'Vận dụng', 'Các ứng dụng Trí tuệ nhân tạo (AI) như phần mềm dịch ngôn ngữ hay nhận diện khuôn mặt được tạo ra như thế nào (6.D1.1)?', '["Do các kĩ sư phần mềm lập trình nên từ các thuật toán AI và huấn luyện trên dữ liệu bằng các ngôn ngữ lập trình.", "Tự nhiên sinh ra trong ổ cứng mà không cần chương trình máy tính.", "Chỉ là một bức ảnh tĩnh không có câu lệnh.", "Không sử dụng bất kì thuật toán hay ngôn ngữ lập trình nào."]'::jsonb, 0, 'Theo Khung năng lực AI (6.D1.1), mọi hệ thống AI đều là các chương trình máy tính đặc biệt được xây dựng bằng ngôn ngữ lập trình kết hợp thuật toán học máy và dữ liệu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-1', 'k6-p29', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong giao diện phần mềm Scratch, nơi người lập trình kéo các khối lệnh thả vào và ghép nối chúng lại với nhau để tạo thành chương trình được gọi là [___] (hay Vùng lập trình)."', '["vùng kịch bản", "lá cờ xanh", "Điều khiển", "Nhóm lệnh Chuyển động (Motion)"]'::jsonb, 0, 'Theo SGK Tin học 6: Trong giao diện phần mềm Scratch, nơi người lập trình kéo các khối lệnh thả vào và ghép nối chúng lại với nhau để tạo thành chương trình được gọi là «vùng kịch bản» (hay Vùng lập trình).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-2', 'k6-p29', 2, 'Nhận biết', 'Trong phần mềm lập trình trực quan Scratch, khu vực hiển thị nhân vật (như chú Mèo) di chuyển, nói chuyện và biểu diễn kết quả của chương trình được gọi là gì?', '["Thanh tiêu đề.", "Sân khấu (Stage).", "Thùng rác.", "Hộp thoại in ấn."]'::jsonb, 1, 'Theo SGK Tin học 6 Bài 17, Sân khấu (Stage) là nơi hiển thị phông nền, nhân vật và mọi hoạt động kết quả khi chương trình chạy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-3', 'k6-p29', 3, 'Nhận biết', 'Khối lệnh `Khi bấm vào (Lá cờ xanh)` dùng để mở đầu chương trình nằm trong nhóm lệnh nào của Scratch?', '["Nhóm Sự kiện (Events).", "Nhóm Âm thanh (Sound).", "Nhóm Các phép toán (Operators).", "Nhóm Biến số (Variables)."]'::jsonb, 0, 'Khối lệnh `Khi bấm vào lá cờ xanh` (When green flag clicked) thuộc nhóm lệnh Sự kiện (Events - màu vàng).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-4', 'k6-p29', 4, 'Thông hiểu', 'Muốn lập trình cho nhân vật Mèo hiển thị dòng chữ `Chào mừng bạn đến với lớp 6A!` trong 3 giây trên sân khấu, em chọn khối lệnh nào?', '["Khối lệnh `di chuyển 10 bước` trong nhóm Chuyển động.", "Khối lệnh `nói [Chào mừng bạn đến với lớp 6A!] trong (3) giây` trong nhóm Hiển thị (Looks).", "Khối lệnh `xoay 15 độ` trong nhóm Chuyển động.", "Khối lệnh `dừng lại tất cả` trong nhóm Điều khiển."]'::jsonb, 1, 'Các khối lệnh cho nhân vật nói hoặc suy nghĩ hiển thị chữ trên sân khấu nằm trong nhóm Hiển thị (Looks - màu tím).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-5', 'k6-p29', 5, 'Thông hiểu', 'Các khối lệnh thể hiện cấu trúc rẽ nhánh (`nếu ... thì ...`) và cấu trúc lặp (`lặp lại ...`) trong Scratch nằm ở nhóm lệnh nào?', '["Nhóm Hiển thị (Looks).", "Nhóm Điều khiển (Control).", "Nhóm Chuyển động (Motion).", "Nhóm Cảm biến (Sensing)."]'::jsonb, 1, 'Nhóm lệnh Điều khiển (Control - màu cam) cung cấp đầy đủ các khối lệnh điều khiển luồng thực thi như `đợi`, `lặp lại`, `liên tục`, `nếu...thì...`, `nếu...thì...không thì...`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-6', 'k6-p29', 6, 'Vận dụng', 'Để tháo rời một khối lệnh bị ghép nhầm ở cuối kịch bản chương trình và xóa bỏ nó trong Scratch, em thực hiện thao tác nào?', '["Kéo khối lệnh đó tách rời ra khỏi kịch bản rồi thả ngược về Vùng khối lệnh bên trái (hoặc nhấp chuột phải vào khối lệnh chọn Xóa khối).", "Rút nguồn điện của máy tính.", "Gõ phím Enter 10 lần.", "Tắt màn hình máy tính."]'::jsonb, 0, 'Trong Scratch, người dùng chỉ cần kéo khối lệnh cần bỏ thả về lại vùng chứa khối lệnh bên trái (hoặc nhấn phím Delete / chọn Xóa khối) là xóa được ngay.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-6-29-7', 'k6-p29', 7, 'Vận dụng', 'Khi em lập trình một nhân vật ''Trợ lí ảo AI nhí'' trên Scratch sử dụng khối lệnh `hỏi [Bạn tên là gì?] và đợi` kết hợp khối `nếu <trả lời = Tin học> thì nói [Môn học rất thú vị!]`, chương trình đã mô phỏng nguyên lí nào (6.C2.1)?', '["Nguyên lí tương tác Thu nhận dữ liệu đầu vào (Input từ bàn phím) -> Xử lí kiểm tra điều kiện rẽ nhánh -> Xuất phản hồi đầu ra (Output trên sân khấu).", "Nguyên lí định dạng bảng biểu trong Word.", "Nguyên lí kết nối cáp mạng có dây.", "Nguyên lí tắt máy tính tự động."]'::jsonb, 0, 'Theo Khung năng lực AI (6.C2.1), kịch bản tương tác hỏi - đáp có điều kiện trên Scratch giúp học sinh trực tiếp trải nghiệm cách một chương trình máy tính/chatbot tiếp nhận Input, xử lí theo thuật toán và phản hồi Output.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-1', 'k7-p01', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Thiết bị [___] (`Input device`) có chức năng tiếp nhận thông tin từ thế giới bên ngoài (văn bản, âm thanh, hình ảnh, thao tác điều khiển) và chuyển thành dữ liệu số đưa vào máy tính."', '["vào", "ra", "cảm ứng", "Micro & Webcam"]'::jsonb, 0, 'Theo SGK Tin học 7: Thiết bị «vào» (`Input device`) có chức năng tiếp nhận thông tin từ thế giới bên ngoài (văn bản, âm thanh, hình ảnh, thao tác điều khiển) và chuyển thành dữ liệu số đưa vào máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-2', 'k7-p01', 2, 'Nhận biết', 'Chức năng chung của các ''Thiết bị vào'' (`Input devices`) của máy tính là gì?', '["In dữ liệu ra giấy A4", "Thu nhận thông tin từ con người hoặc môi trường bên ngoài và chuyển thành dữ liệu dạng số đưa vào máy tính", "Phát âm thanh ra phòng học", "Lưu trữ điện năng dự phòng"]'::jsonb, 1, 'Thiết bị vào tiếp nhận dữ liệu văn bản, âm thanh, hình ảnh, cử chỉ từ bên ngoài và mã hóa thành dữ liệu số cho bộ xử lí.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-3', 'k7-p01', 3, 'Nhận biết', 'Nhóm thiết bị nào sau đây CHỈ toàn là các thiết bị vào (`Input devices`)?', '["Bàn phím, chuột, máy in", "Bàn phím, chuột, micro, máy quét (`Scanner`), webcam", "Màn hình, loa, máy chiếu", "Loa, chuột, máy chiếu"]'::jsonb, 1, 'Bàn phím, chuột, micro, máy quét và webcam đều làm nhiệm vụ đưa dữ liệu từ ngoài vào máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-4', 'k7-p01', 4, 'Thông hiểu', 'Nhóm thiết bị nào sau đây CHỈ toàn là các thiết bị ra (`Output devices`)?', '["Màn hình thông thường, loa, máy in, máy chiếu", "Màn hình, bàn phím, micro", "Máy in, chuột, webcam", "Đầu đọc mã vạch, loa, máy in"]'::jsonb, 0, 'Màn hình, loa, máy in và máy chiếu đều xuất thông tin từ máy tính ra dưới dạng hình ảnh, âm thanh, bản in.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-5', 'k7-p01', 5, 'Thông hiểu', 'Thiết bị nào sau đây kết hợp CẢ HAI chức năng của thiết bị vào và thiết bị ra?', '["Chuột quang có dây", "Màn hình cảm ứng (`Touchscreen`) trên máy tính bảng hoặc ki-ốt tra cứu thông tin", "Bàn phím cơ", "Loa thùng"]'::jsonb, 1, 'Màn hình cảm ứng vừa hiển thị thông tin (ra) vừa nhận lệnh chạm tay trực tiếp (vào).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-6', 'k7-p01', 6, 'Vận dụng', 'Khi cô giáo muốn chiếu bài giảng từ máy tính xách tay lên phông màn lớn trên bục giảng cho cả lớp 40 học sinh cùng quan sát, cô cần kết nối máy tính với thiết bị ra nào?', '["Máy quét (`Scanner`)", "Máy chiếu (`Projector`)", "Đầu đọc mã vạch", "Micro thu âm"]'::jsonb, 1, 'Máy chiếu (`Projector`) nhận tín hiệu hình ảnh từ máy tính và phóng to lên màn chiếu cho tập thể cùng xem.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-1-7', 'k7-p01', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.A1.1), loa thông minh tích hợp trợ lí ảo AI sử dụng cặp thiết bị vào – ra nào để giao tiếp bằng giọng nói với con người?', '["Dùng Micro (thiết bị vào) để nghe câu lệnh giọng nói của người dùng và dùng Loa (thiết bị ra) để phát câu trả lời", "Dùng Bàn phím và Máy in", "Dùng Chuột và Máy quét", "Không cần thiết bị vào – ra"]'::jsonb, 0, 'Micro thu nhận âm thanh giọng nói đầu vào cho AI nhận dạng, sau khi xử lí xong AI phản hồi giọng nói qua Loa đầu ra.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-1', 'k7-p02', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi kết nối chuột, bàn phím, máy in với thân máy tính, mỗi loại đầu cắm chỉ khớp với một loại [___] kết nối tương ứng (như cổng `USB`, cổng `HDMI`, cổng `VGA`)."', '["cổng", "USB", "HDMI", "Cổng kết nối `USB`"]'::jsonb, 0, 'Theo SGK Tin học 7: Khi kết nối chuột, bàn phím, máy in với thân máy tính, mỗi loại đầu cắm chỉ khớp với một loại «cổng» kết nối tương ứng (như cổng `USB`, cổng `HDMI`, cổng `VGA`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-2', 'k7-p02', 2, 'Nhận biết', 'Hành động nào sau đây là ĐÚNG quy tắc an toàn khi sử dụng các thiết bị máy tính?', '["Đặt ly nước đá có đọng hơi nước ngay trên thân máy tính xách tay", "Giữ bàn làm việc khô ráo, không ăn uống sát bàn phím và lau chùi màn hình bằng khăn mềm khô chuyên dụng", "Dùng bút bi ấn mạnh vào màn hình tinh thể lỏng (LCD)", "Rút dây nguồn máy tính bằng cách cầm dây giật mạnh từ xa"]'::jsonb, 1, 'Nước và chất lỏng dẫn điện gây chập cháy bảng mạch, còn vật nhọn làm vỡ tấm nền màn hình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-3', 'k7-p02', 3, 'Nhận biết', 'Cổng kết nối nào trên thân máy tính thường được sử dụng để cắm chuột có dây, bàn phím có dây và ổ nhớ flash?', '["Cổng `USB`", "Cổng `VGA`", "Lỗ cắm tai nghe tròn 3.5mm", "Cổng mạng `RJ45`"]'::jsonb, 0, 'Cổng `USB` (`Universal Serial Bus`) là cổng kết nối ngoại vi tiêu chuẩn cho chuột, bàn phím, máy in, USB flash.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-4', 'k7-p02', 4, 'Thông hiểu', 'Sự khác biệt ưu việt của cáp kết nối `HDMI` so với cáp `VGA` truyền thống khi nối máy tính với máy chiếu hoặc tivi là gì?', '["Cáp `VGA` truyền được âm thanh còn `HDMI` thì không", "Cáp `HDMI` truyền được đồng thời cả hình ảnh chất lượng cao và âm thanh chỉ trên 1 sợi cáp duy nhất, trong khi cáp `VGA` chỉ truyền được hình ảnh", "Cáp `HDMI` phải vặn ốc hai bên đầu cắm", "Cáp `HDMI` chỉ dùng cho chuột máy tính"]'::jsonb, 1, '`HDMI` (`High-Definition Multimedia Interface`) truyền cả tín hiệu video số sắc nét và âm thanh đa kênh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-5', 'k7-p02', 5, 'Thông hiểu', 'Khi lắp đặt một bộ máy tính mới, vì sao người dùng không sợ cắm nhầm dây bàn phím `USB` vào lỗ cắm tai nghe hay cổng `HDMI`?', '["Vì mỗi loại cổng kết nối (`USB`, `HDMI`, `VGA`, Audio) được thiết kế với hình dáng, kích thước và kí hiệu hoàn toàn khác nhau, chỉ đầu cắm đúng chuẩn và đúng chiều mới lắp vừa", "Vì tất cả các cổng đều tròn giống nhau", "Vì máy tính không có cổng kết nối", "Vì dây cáp tự động đổi hình dạng"]'::jsonb, 0, 'Thiết kế chuẩn hóa cơ học giúp mỗi loại giắc cắm chỉ khớp với đúng cổng tương ứng và đúng chiều.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-6', 'k7-p02', 6, 'Vận dụng', 'Nếu màn hình máy tính bật nguồn (đèn báo sáng) nhưng hiện thông báo `''No Signal''` (Không có tín hiệu) dù thân máy tính (`Case`) đang chạy, nguyên nhân thường gặp nhất là gì?', '["Bàn phím bị kẹt phím `Space`", "Dây cáp truyền tín hiệu hình ảnh (`HDMI` hoặc `VGA`) nối giữa thân máy tính và màn hình bị lỏng hoặc tuột", "Loa máy tính đang tắt âm lượng", "Chuột hết pin"]'::jsonb, 1, 'Thông báo `''No Signal''` trên màn hình cho biết màn hình có điện nhưng chưa nhận được tín hiệu hình ảnh qua cáp `HDMI`/`VGA` từ thân máy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-2-7', 'k7-p02', 7, 'Vận dụng', 'Về mặt an toàn dữ liệu và quyền riêng tư khi sử dụng webcam và micro trên máy tính kết nối Internet, thói quen nào sau đây là TỐT NHẤT?', '["Bật webcam và micro liên tục 24/24 giờ kể cả khi không học trực tuyến", "Tắt hoặc đóng nắp che vật lí webcam và tắt micro khi kết thúc cuộc họp/buổi học trực tuyến để phòng ngừa phần mềm độc hại quay lén, nghe lén", "Dán băng keo đục lên màn hình", "Cắt đứt dây bàn phím"]'::jsonb, 1, 'Chủ động tắt hoặc che webcam/micro khi không sử dụng giúp bảo vệ quyền riêng tư trước nguy cơ bị mã độc chiếm quyền điều khiển thiết bị vào.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-1', 'k7-p03', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Phần mềm máy tính được chia thành hai loại chính là: [___] điều hành và phần mềm ứng dụng."', '["hệ", "ứng dụng", "Hệ điều hành cho máy tính cá nhân", "Phần mềm ứng dụng phục vụ học tập & công việc"]'::jsonb, 0, 'Theo SGK Tin học 7: Phần mềm máy tính được chia thành hai loại chính là: «hệ» điều hành và phần mềm ứng dụng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-2', 'k7-p03', 2, 'Nhận biết', 'Phần mềm nào đóng vai trò trung gian kết nối giữa Người sử dụng, Phần mềm ứng dụng và Thiết bị phần cứng của máy tính?', '["Phần mềm vẽ tranh `Paint`", "Hệ điều hành (`Operating System`)", "Phần mềm gõ văn bản `Word`", "Trò chơi dò mìn"]'::jsonb, 1, 'Hệ điều hành trực tiếp quản lí phần cứng và tạo môi trường nền tảng cho các phần mềm ứng dụng và người dùng tương tác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-3', 'k7-p03', 3, 'Nhận biết', 'Nhóm nào sau đây CHỈ bao gồm tên của các Hệ điều hành?', '["`Windows`, `Linux`, `macOS`, `Android`, `iOS`", "`Windows`, `Word`, `Excel`, `PowerPoint`", "`Android`, `Google Chrome`, `Zalo`, `Facebook`", "`Linux`, `Scratch`, `Paint`, `Unikey`"]'::jsonb, 0, '`Windows`, `Linux`, `macOS` là các hệ điều hành máy tính phổ biến; `Android`, `iOS` là các hệ điều hành thiết bị di động.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-4', 'k7-p03', 4, 'Thông hiểu', 'Nhóm nào sau đây CHỈ bao gồm tên của các Phần mềm ứng dụng?', '["`Windows 11`, `Android`, `iOS`", "`Microsoft Word`, `Microsoft Excel`, `PowerPoint`, `Google Chrome`, `Scratch`", "`macOS`, `Ubuntu`, `Linux`", "`Windows`, `macOS`, `Excel`"]'::jsonb, 1, '`Word`, `Excel`, `PowerPoint`, `Chrome`, `Scratch` đều là các phần mềm ứng dụng phục vụ công việc cụ thể của người dùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-5', 'k7-p03', 5, 'Thông hiểu', 'Đâu KHÔNG phải là chức năng của Hệ điều hành?', '["Quản lí, điều phối hoạt động của bộ xử lí, bộ nhớ và các thiết bị vào – ra", "Quản lí hệ thống tệp và thư mục lưu trữ trên ổ đĩa", "Cung cấp môi trường để cài đặt và chạy các phần mềm ứng dụng", "Chế tạo ra bàn phím và màn hình bằng nhựa"]'::jsonb, 3, 'Hệ điều hành là phần mềm điều khiển và quản lí hệ thống, không phải là nhà máy sản xuất linh kiện vật lí.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-6', 'k7-p03', 6, 'Vận dụng', 'Phát biểu nào sau đây nêu ĐÚNG sự khác biệt giữa Hệ điều hành và Phần mềm ứng dụng?', '["Phần mềm ứng dụng phải được cài trước rồi mới cài Hệ điều hành lên trên", "Máy tính bắt buộc phải có Hệ điều hành mới hoạt động được, còn Phần mềm ứng dụng được cài đặt tùy theo nhu cầu công việc của từng người dùng và chạy trên nền Hệ điều hành", "Hệ điều hành và Phần mềm ứng dụng hoàn toàn giống hệt nhau", "Một máy tính chỉ cài được tối đa 1 phần mềm ứng dụng"]'::jsonb, 1, 'Hệ điều hành là phần mềm hệ thống thiết yếu bắt buộc phải có; phần mềm ứng dụng phụ thuộc vào hệ điều hành và lựa chọn theo nhu cầu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-3-7', 'k7-p03', 7, 'Vận dụng', 'Hiện nay, các hệ điều hành hiện đại (như `Windows 11`, `Android`, `iOS`) tích hợp sẵn các trợ lí AI (như `Copilot`, `Google Assistant`, `Siri`) nhằm mục đích gì?', '["Để làm máy tính không mở được tệp văn bản", "Giúp người dùng điều khiển thiết bị, tìm kiếm tệp và mở các phần mềm ứng dụng nhanh chóng bằng ngôn ngữ tự nhiên hoặc giọng nói", "Để xóa toàn bộ phần mềm ứng dụng", "Để ngắt kết nối màn hình"]'::jsonb, 1, 'Trợ lí AI tích hợp trong hệ điều hành nâng cao trải nghiệm tương tác thông minh giữa người dùng với toàn bộ hệ thống máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-1', 'k7-p04', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Tên một tệp tin thường gồm hai phần là phần tên chính và phần [___] (Extension), được ngăn cách với nhau bởi dấu chấm `.`."', '["mở rộng (phần đuôi)", "hệ", "không", "`.docx` / `.xlsx` / `.pptx`"]'::jsonb, 0, 'Theo SGK Tin học 7: Tên một tệp tin thường gồm hai phần là phần tên chính và phần «mở rộng (phần đuôi)» (Extension), được ngăn cách với nhau bởi dấu chấm `.`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-2', 'k7-p04', 2, 'Nhận biết', 'Trong tên tệp `KeHoach_TruongHocXanh.docx`, phần mở rộng (Extension) của tệp là gì và nó có ý nghĩa gì?', '["Phần mở rộng là `KeHoach`; cho biết ngày tạo tệp", "Phần mở rộng là `.docx` (hoặc `docx`); cho biết đây là tệp văn bản được tạo và xử lí bởi phần mềm soạn thảo văn bản `Microsoft Word`", "Phần mở rộng là `Xanh`; cho biết màu của chữ", "Không có phần mở rộng"]'::jsonb, 1, 'Phần đứng sau dấu chấm cuối cùng (`.docx`) là phần mở rộng, giúp hệ điều hành nhận biết loại tệp văn bản Word.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-3', 'k7-p04', 3, 'Nhận biết', 'Tệp dữ liệu nào sau đây được tạo ra và mở bằng phần mềm bảng tính `Microsoft Excel`?', '["`DanhSachCay.xlsx`", "`BaiHat.mp3`", "`AnhLop7A.png`", "`TroChoi.sb3`"]'::jsonb, 0, '`.xlsx` là phần mở rộng mặc định của tệp bảng tính Microsoft Excel.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-4', 'k7-p04', 4, 'Thông hiểu', 'Khi em dùng phần mềm `Paint` vẽ một bức tranh rồi lưu lại, hoặc chụp ảnh bằng máy ảnh kĩ thuật số, tệp tạo ra thường có phần mở rộng nào?', '["`.docx` hoặc `.txt`", "`.jpg` (`.jpeg`), `.png` hoặc `.bmp`", "`.mp3` hoặc `.wav`", "`.exe`"]'::jsonb, 1, '`.jpg`, `.png`, `.bmp` là các định dạng tệp dữ liệu hình ảnh đồ họa phổ biến nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-5', 'k7-p04', 5, 'Thông hiểu', 'Ghép nối nào sau đây giữa ''Loại tệp (Phần mở rộng)'' và ''Phần mềm ứng dụng'' là ĐÚNG?', '["`.pptx` — Phần mềm lập trình `Scratch`", "`.mp4` — Phần mềm trình chiếu `PowerPoint`", "`.sb3` — Phần mềm lập trình trực quan `Scratch`", "`.mp3` — Phần mềm vẽ `Paint`"]'::jsonb, 2, 'Tệp dự án lập trình Scratch 3.0 có phần mở rộng là `.sb3`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-6', 'k7-p04', 6, 'Vận dụng', 'Trong hệ điều hành Windows, tên tệp nào sau đây là KHÔNG HỢP LỆ (bị hệ điều hành từ chối vì chứa kí tự cấm)?', '["`Bai_Tap_Tin_Hoc_7.docx`", "`HoiThao:2026?.pptx` (chứa dấu hai chấm `:` và dấu hỏi chấm `?`)", "`BangDiem_HocKi1.xlsx`", "`AnhKyYeu2026.jpg`"]'::jsonb, 1, 'Windows cấm 9 kí tự đặc biệt trong tên tệp và thư mục: `\ / : * ? " < > |`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-4-7', 'k7-p04', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C1.1), khi em muốn tải một bức ảnh lên công cụ AI nhận diện thực vật để hỏi tên loài cây trong dự án ''Trường học xanh'', em cần chọn tệp có phần mở rộng nào?', '["Tệp âm thanh `.mp3`", "Tệp chương trình `.exe`", "Tệp hình ảnh `.jpg` hoặc `.png`", "Tệp nén `.zip`"]'::jsonb, 2, 'Công cụ thị giác máy tính (Computer Vision AI) nhận đầu vào là các tệp hình ảnh chuẩn như `.jpg`, `.png`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-1', 'k7-p05', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Các tệp chương trình phần mềm ứng dụng (như tệp `.exe` trong thư mục `Program Files`) thực chất cũng là [___] được lưu trữ trên ổ đĩa máy tính, vì vậy tuyệt đối không được tự ý xóa hay di chuyển chúng."', '["dữ liệu", "nội dung", "virus (mã độc)", "Sao lưu cục bộ (`Local Backup`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Các tệp chương trình phần mềm ứng dụng (như tệp `.exe` trong thư mục `Program Files`) thực chất cũng là «dữ liệu» được lưu trữ trên ổ đĩa máy tính, vì vậy tuyệt đối không được tự ý xóa hay di chuyển chúng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-2', 'k7-p05', 2, 'Nhận biết', 'Phát biểu nào sau đây là ĐÚNG khi nói về các tệp chương trình phần mềm được cài đặt trong máy tính?', '["Tệp chương trình không chiếm dung lượng ổ đĩa", "Tệp chương trình cũng là dữ liệu được lưu trữ trên thiết bị nhớ của máy tính và có thể bị sao chép, xóa hoặc bị virus làm hỏng", "Người dùng nên xóa hết các tệp trong thư mục `C:\\Windows` cho nhẹ máy", "Tệp chương trình là thiết bị phần cứng"]'::jsonb, 1, 'Mọi chương trình phần mềm đều được lưu dưới dạng các tệp dữ liệu trên ổ đĩa; cần bảo vệ và không tự ý xóa các tệp hệ thống.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-3', 'k7-p05', 3, 'Nhận biết', 'Cách đặt tên tệp nào sau đây là KHOA HỌC, rõ ràng và giúp tìm kiếm nhanh nhất cho bài trình chiếu môn Tin học lớp 7 Bài 4?', '["`baigido.pptx`", "`11111.pptx`", "`TinHoc7_Bai4_MangXaHoi.pptx`", "`moi_sua_lai_lan_cuoi_2.pptx`"]'::jsonb, 2, 'Tên tệp `TinHoc7_Bai4_MangXaHoi.pptx` cho biết ngay môn học, khối lớp, số bài và chủ đề nội dung mà không cần mở tệp ra xem.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-4', 'k7-p05', 4, 'Thông hiểu', 'Khi tổ chức lưu trữ tài liệu học tập của các môn Toán, Ngữ văn, Tiếng Anh, Tin học trong năm học lớp 7, cách tạo cây thư mục nào hợp lí nhất?', '["Không tạo thư mục nào, ném tất cả vào ổ `C:\\`", "Tạo thư mục gốc `HocTap_Lop7`, bên trong tạo các thư mục con riêng cho từng môn: `Toan`, `NguVan`, `TiengAnh`, `TinHoc`", "Tạo 100 thư mục rỗng đặt tên từ 1 đến 100", "Lưu tất cả vào thùng rác `Recycle Bin`"]'::jsonb, 1, 'Tổ chức cây thư mục phân cấp theo từng môn học giúp phân loại ngăn nắp, dễ quản lí và tra cứu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-5', 'k7-p05', 5, 'Thông hiểu', 'Hành động tạo thêm một bản sao của các tệp dữ liệu quan trọng và lưu ở một nơi an toàn khác (như ổ cứng rời hoặc Google Drive) được gọi là gì?', '["Định dạng đĩa (`Format`)", "Sao lưu dữ liệu (`Backup`)", "Xóa dữ liệu (`Delete`)", "Đổi tên dữ liệu (`Rename`)"]'::jsonb, 1, 'Sao lưu (`Backup`) đảm bảo khi máy tính chính gặp sự cố hỏng ổ cứng thì ta vẫn khôi phục lại được dữ liệu từ bản sao.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-6', 'k7-p05', 6, 'Vận dụng', 'Để phòng tránh nguy cơ virus máy tính xâm nhập và phá hủy dữ liệu, em cần thực hiện biện pháp nào?', '["Tắt tường lửa và gỡ bỏ phần mềm diệt virus", "Bật phần mềm diệt virus (như `Windows Security`), không nháy vào các đường dẫn lạ, không tải tệp `.exe` trôi nổi và quét virus USB trước khi mở", "Mở mọi tệp đính kèm từ email người lạ gửi tới", "Không bao giờ cập nhật hệ điều hành"]'::jsonb, 1, 'Kết hợp phần mềm diệt virus với ý thức cảnh giác trước tệp/liên kết lạ là lá chắn bảo vệ dữ liệu hiệu quả nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-5-7', 'k7-p05', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C2.1), việc đặt tên tệp và thư mục rõ nghĩa, có cấu trúc (ví dụ: `DuAnXanh_KhaoSatCay_Lop7A.xlsx`) giúp ích gì khi sử dụng các công cụ tìm kiếm thông minh và trợ lí AI trên máy tính?', '["Làm AI không đọc được tệp", "Giúp công cụ tìm kiếm và trợ lí AI nhận diện đúng ngữ cảnh, chủ đề của tệp chỉ qua tên gọi để truy xuất chính xác tức thời theo yêu cầu của người dùng", "Làm tăng kích thước màn hình", "Giúp máy tính không cần dùng điện"]'::jsonb, 1, 'Đặt tên tệp giàu thông tin ngữ nghĩa (Semantic Naming) giúp cả con người lẫn thuật toán tìm kiếm truy vấn cực nhanh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-1', 'k7-p06', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Tổ hợp phím tắt dùng để Sao chép (`Copy`) tệp/thư mục là `Ctrl + C`, dùng để Cắt/Di chuyển (`Cut`) là [___], và dùng để Dán (`Paste`) là `Ctrl + V`."', '["Ctrl + X", "F2", "Thùng rác", "`Ctrl + C` -> `Ctrl + V` (`Copy` -> `Paste`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Tổ hợp phím tắt dùng để Sao chép (`Copy`) tệp/thư mục là `Ctrl + C`, dùng để Cắt/Di chuyển (`Cut`) là «Ctrl + X», và dùng để Dán (`Paste`) là `Ctrl + V`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-2', 'k7-p06', 2, 'Nhận biết', 'Để DI CHUYỂN tệp `KhaoSatCay.xlsx` từ thư mục `Download` sang thư mục `DuAn_TruongHocXanh\BangTinh` (không để lại bản dư thừa ở `Download`), em dùng cặp lệnh nào?', '["`Copy` (`Ctrl + C`) và `Paste` (`Ctrl + V`)", "`Cut` (`Ctrl + X`) và `Paste` (`Ctrl + V`)", "`Rename` (`F2`) và `Delete`", "`Ctrl + P` và `Ctrl + S`"]'::jsonb, 1, 'Cặp lệnh `Cut` (`Ctrl + X`) và `Paste` (`Ctrl + V`) dùng để di chuyển tệp hoặc thư mục từ vị trí này sang vị trí khác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-3', 'k7-p06', 3, 'Nhận biết', 'Để tạo thêm một bản sao lưu dự phòng của thư mục `DuAn_TruongHocXanh` từ ổ đĩa `D:` sang chiếc `USB` cá nhân (giữ nguyên thư mục gốc ở ổ `D:`), em dùng cặp lệnh nào?', '["`Cut` (`Ctrl + X`) và `Paste` (`Ctrl + V`)", "`Copy` (`Ctrl + C`) và `Paste` (`Ctrl + V`)", "`Delete`", "`Rename`"]'::jsonb, 1, 'Sao lưu cần giữ nguyên bản gốc ở ổ `D:` và tạo thêm bản sao trên `USB` nên phải dùng `Copy` (`Ctrl + C`) và `Paste` (`Ctrl + V`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-4', 'k7-p06', 4, 'Thông hiểu', 'Khi em đang mở tệp `BaoCao.pptx` trên màn hình PowerPoint để chỉnh sửa, nếu em quay ra `File Explorer` nhấn phím `Delete` để xóa tệp `BaoCao.pptx` thì điều gì sẽ xảy ra?', '["Máy tính tự động tắt nguồn", "Hệ điều hành hiện thông báo `File In Use` (Tệp đang được sử dụng bởi chương trình khác) và không cho phép xóa cho đến khi đóng tệp đó lại", "Tệp bị đổi thành tệp âm thanh", "Tất cả các tệp khác bị xóa theo"]'::jsonb, 1, 'Hệ điều hành bảo vệ tệp đang mở không bị xóa hoặc đổi tên giữa chừng để tránh lỗi mất dữ liệu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-5', 'k7-p06', 5, 'Thông hiểu', 'Muốn chọn đồng thời 3 tệp ảnh `CayBang.jpg`, `CayPhuong.jpg`, `CayHoaSua.jpg` nằm xen kẽ cách xa nhau trong một thư mục, em kết hợp nháy chuột với giữ phím nào?', '["Phím `Ctrl`", "Phím `Esc`", "Phím `Tab`", "Phím `Caps Lock`"]'::jsonb, 0, 'Giữ phím `Ctrl` khi nháy chuột cho phép chọn nhiều tệp/thư mục rời rạc không nằm cạnh nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-6', 'k7-p06', 6, 'Vận dụng', 'Trong lúc sắp xếp thư mục, nếu em lỡ tay xóa nhầm một thư mục quan trọng bằng phím `Delete`, cách nhanh nhất để lấy lại ngay lập tức là gì?', '["Mua máy tính mới", "Nhấn ngay tổ hợp phím `Ctrl + Z` (`Undo`) hoặc mở `Recycle Bin` (Thùng rác), nháy chuột phải vào thư mục đó và chọn `Restore`", "Nhấn tổ hợp phím `Alt + F4`", "Đổi hình nền máy tính"]'::jsonb, 1, '`Ctrl + Z` hoàn tác lệnh xóa vừa thực hiện, hoặc `Restore` trong `Recycle Bin` khôi phục tệp/thư mục về đúng vị trí cũ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-6-7', 'k7-p06', 7, 'Vận dụng', 'Để tìm nhanh một tệp có chữ `TruongHocXanh` nằm ở đâu đó trong ổ đĩa `D:` mà em quên mất nằm ở thư mục con nào, em sử dụng công cụ gì trong cửa sổ `File Explorer`?', '["Ô tìm kiếm `Search` ở góc trên bên phải cửa sổ `File Explorer` (hoặc nhấn `Ctrl + F`)", "Nút `New folder`", "Nút `Rename`", "Phần mềm `Paint`"]'::jsonb, 0, 'Ô `Search` trong `File Explorer` giúp tìm kiếm nhanh tệp và thư mục theo tên hoặc phần mở rộng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-1', 'k7-p07', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "[___] (`Social Network`) là dịch vụ kết nối các thành viên có cùng đặc điểm cá nhân hoặc sở thích trên Internet để giao lưu, chia sẻ thông tin không phân biệt không gian và thời gian."', '["Mạng xã hội", "hội nghị", "chia sẻ", "Thư điện tử (`Gmail`, `Outlook`)"]'::jsonb, 0, 'Theo SGK Tin học 7: «Mạng xã hội» (`Social Network`) là dịch vụ kết nối các thành viên có cùng đặc điểm cá nhân hoặc sở thích trên Internet để giao lưu, chia sẻ thông tin không phân biệt không gian và thời gian.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-2', 'k7-p07', 2, 'Nhận biết', 'Đâu là định nghĩa ĐÚNG NHẤT về ''Mạng xã hội'' (`Social Network`) trên Internet?', '["Là một phần mềm chỉ dùng để vẽ hình học không cần kết nối mạng", "Là một hệ thống thông tin cung cấp cho cộng đồng người dùng mạng các dịch vụ lưu trữ, cung cấp, sử dụng, tìm kiếm, chia sẻ và trao đổi thông tin với nhau", "Là một thiết bị phần cứng gắn trong thùng máy tính", "Là một loại dây cáp mạng"]'::jsonb, 1, 'Mạng xã hội là nền tảng trực tuyến kết nối các thành viên để giao tiếp, chia sẻ nội dung và tương tác cộng đồng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-3', 'k7-p07', 3, 'Nhận biết', 'Nhóm nào sau đây gồm các ứng dụng/website là Mạng xã hội và kênh giao tiếp trực tuyến?', '["`Facebook`, `Zalo`, `YouTube`, `Instagram`", "`Microsoft Word`, `Excel`, `Paint`", "`Windows 10`, `Linux`, `macOS`", "`Unikey`, `WinRAR`, `Calculator`"]'::jsonb, 0, '`Facebook`, `Zalo`, `YouTube`, `Instagram` là các nền tảng mạng xã hội phổ biến.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-4', 'k7-p07', 4, 'Thông hiểu', 'Đâu KHÔNG phải là chức năng cơ bản của mạng xã hội?', '["Kết nối bạn bè, người thân và các nhóm cùng sở thích học tập", "Chia sẻ bài viết, hình ảnh, video và bình luận trao đổi thông tin", "Nhắn tin và gọi video trực tuyến", "Tự động sửa chữa bàn phím bị gãy phím vật lí"]'::jsonb, 3, 'Mạng xã hội là dịch vụ phần mềm trên Internet, không thể sửa chữa hỏng hóc cơ học của phần cứng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-5', 'k7-p07', 5, 'Thông hiểu', 'Một người đăng thông tin bịa đặt lên mạng xã hội rằng ''Đập thủy điện bị vỡ'' để câu lượt xem (`View`), gây hoang mang cho hàng nghìn người dân địa phương. Hậu quả của hành vi sai trái này là gì?', '["Được mọi người khen ngợi", "Gây rối loạn trật tự xã hội, ảnh hưởng xấu đến cộng đồng và người đăng tin sẽ bị cơ quan chức năng xử phạt nghiêm khắc theo quy định của pháp luật", "Không có hậu quả gì vì mạng là ảo", "Được mạng xã hội thưởng tiền"]'::jsonb, 1, 'Tung tin giả gây hoang mang dư luận là hành vi vi phạm pháp luật (Luật An ninh mạng) và bị xử phạt hành chính hoặc hình sự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-6', 'k7-p07', 6, 'Vận dụng', 'Khi lớp em cần tổ chức một buổi thảo luận nhóm trực tuyến vào tối Chủ nhật có cả âm thanh, hình ảnh trực tiếp và chia sẻ màn hình bài trình chiếu, công cụ nào phù hợp nhất?', '["Phần mềm hội nghị/học trực tuyến như `Google Meet`, `Zoom` hoặc `Microsoft Teams`", "Phần mềm `Paint`", "Phần mềm `Notepad`", "Máy tính bỏ túi `Calculator`"]'::jsonb, 0, 'Các nền tảng `Google Meet`, `Zoom`, `MS Teams` hỗ trợ phòng họp trực tuyến đa phương tiện và chia sẻ màn hình thời gian thực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-7-7', 'k7-p07', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.A3.1), thuật toán AI đề xuất nội dung trên mạng xã hội có thể gây ra nguy cơ gì nếu người dùng thiếu cảnh giác?', '["Giúp máy tính tiết kiệm pin", "Khiến người dùng bị cuốn vào việc lướt xem liên tục gây mất thời gian học tập, hoặc chỉ nhìn thấy một chiều thông tin (hiệu ứng bong bóng lọc) và dễ tiếp cận các thông tin sai lệch giật gân", "Làm tăng tốc độ gõ phím", "Tự động làm hết bài tập về nhà"]'::jsonb, 1, 'Thuật toán AI ưu tiên các nội dung gây chúý mạnh để giữ chân người dùng, nên cần chủ động kiểm soát thời gian và chọn lọc kênh thông tin giáo dục lành mạnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-1', 'k7-p08', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trên mạng xã hội, ba chế độ quyền riêng tư phổ biến nhất cho một bài đăng là: `Công khai` (`Public` - ai cũng xem được), `Bạn bè` (`Friends` - chỉ bạn bè trong danh sách xem được) và [___] (`Only me` - chỉ bản thân người đăng xem được)."', '["Chỉ mình tôi", "hỏi (xin phép)", "đăng xuất", "Chế độ `Công khai` (`Public`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Trên mạng xã hội, ba chế độ quyền riêng tư phổ biến nhất cho một bài đăng là: `Công khai` (`Public` - ai cũng xem được), `Bạn bè` (`Friends` - chỉ bạn bè trong danh sách xem được) và «Chỉ mình tôi» (`Only me` - chỉ bản thân người đăng xem được).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-2', 'k7-p08', 2, 'Nhận biết', 'Khi đăng một bài viết kỷ niệm cá nhân lên mạng xã hội mà em chỉ muốn những người đã kết bạn với mình nhìn thấy (người lạ không xem được), em chọn chế độ quyền riêng tư nào?', '["`Công khai` (`Public`)", "`Bạn bè` (`Friends`)", "`Tất cả mọi người trên thế giới`", "`Quảng cáo`"]'::jsonb, 1, 'Chế độ `Bạn bè` (`Friends`) giới hạn phạm vi hiển thị bài viết chỉ trong danh sách bạn bè đã được xác nhận.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-3', 'k7-p08', 3, 'Nhận biết', 'Thao tác nào sau đây là BẮT BUỘC để bảo vệ tài khoản khi em đăng nhập mạng xã hội hoặc email trên máy tính phòng thực hành của trường?', '["Lưu mật khẩu tự động vào trình duyệt cho người sau dùng tiếp", "Đăng xuất (`Log out` / `Sign out`) hoàn toàn khỏi tài khoản và không chọn lưu mật khẩu trên trình duyệt trước khi rời khỏi máy", "Tắt màn hình mà không đăng xuất", "Ghi mật khẩu ra giấy dán lên màn hình"]'::jsonb, 1, 'Trên máy tính dùng chung, nếu không đăng xuất (`Log out`), người sử dụng máy tiếp theo sẽ truy cập được vào toàn bộ tài khoản của em.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-4', 'k7-p08', 4, 'Thông hiểu', 'Khi nhận được một đường dẫn (`Link`) lạ qua tin nhắn mạng xã hội với lời mời `''Bấm vào đây và đăng nhập tài khoản để nhận quà miễn phí''`, em nên làm gì?', '["Nháy vào ngay và nhập tên đăng nhập, mật khẩu", "Tuyệt đối không nháy vào đường dẫn lạ đó vì đây là bẫy lừa đảo (`Phishing`) nhằm đánh cắp mật khẩu tài khoản", "Chuyển tiếp đường dẫn đó cho 20 người bạn", "Cung cấp thêm số điện thoại của bố mẹ"]'::jsonb, 1, 'Các đường dẫn tặng quà bất thường yêu cầu đăng nhập tài khoản là thủ đoạn phổ biến nhất để chiếm đoạt tài khoản mạng xã hội.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-5', 'k7-p08', 5, 'Thông hiểu', 'Mật khẩu nào sau đây được đánh giá là MẬT KHẨU MẠNH và an toàn nhất cho tài khoản mạng xã hội?', '["`123456`", "`nguyenvanan`", "`TrH_Xanh@2026!` (độ dài từ 8 kí tự trở lên, kết hợp chữ hoa, chữ thường, chữ số và kí tự đặc biệt)", "`password`"]'::jsonb, 2, 'Mật khẩu mạnh cần đủ độ dài (>= 8 kí tự) và kết hợp chữ hoa, chữ thường, số, kí tự đặc biệt, không dùng ngày sinh hay dãy số dễ đoán.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-6', 'k7-p08', 6, 'Vận dụng', 'Trước khi đăng tải bài viết giới thiệu dự án ''Trường học xanh'' của tổ lên kênh thông tin của lớp, các thành viên cần kiểm tra điều gì?', '["Không cần kiểm tra gì cả", "Kiểm tra tính chính xác của nội dung, lỗi chính tả, ngôn từ lịch sự, hình ảnh rõ đẹp và được sự đồng ý của các bạn trong ảnh", "Viết toàn bằng kí hiệu mật mã không ai đọc được", "Chèn thêm các tin đồn không kiểm chứng"]'::jsonb, 1, 'Kiểm duyệt kỹ nội dung và hình ảnh trước khi đăng thể hiện văn hóa và trách nhiệm của người chia sẻ thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-8-7', 'k7-p08', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.B2.1), khi thấy một video trên mạng xã hội có dấu hiệu khuôn mặt nhân vật bị nhấp nháy bất thường và phát ngôn kỳ lạ (nghi do AI Deepfake tạo ra), thái độ đúng đắn là gì?', '["Bấm chia sẻ ngay lập tức kèm lời bình luận tiêu cực", "Tuyệt đối không chia sẻ, không bình luận hùa theo, kiểm chứng từ nguồn báo chí chính thống và báo cáo (`Report`) nội dung giả mạo", "Tải video về đăng lại trên trang của mình", "Tin tưởng tuyệt đối vào video đó"]'::jsonb, 1, 'Không tiếp tay phát tán nội dung giả mạo Deepfake và chủ động báo cáo vi phạm giúp giữ gìn môi trường mạng an toàn, lành mạnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-1', 'k7-p09', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi giao tiếp trên mạng, dù không nhìn thấy mặt nhau trực tiếp nhưng phía sau màn hình vẫn là những con người thật, vì vậy ta phải luôn giữ thái độ [___] và lịch sự như ngoài đời thực."', '["tôn trọng", "bắt nạt", "báo (thông báo)", "Quy tắc giao tiếp văn minh (`Netiquette`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Khi giao tiếp trên mạng, dù không nhìn thấy mặt nhau trực tiếp nhưng phía sau màn hình vẫn là những con người thật, vì vậy ta phải luôn giữ thái độ «tôn trọng» và lịch sự như ngoài đời thực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-2', 'k7-p09', 2, 'Nhận biết', 'Nguyên tắc vàng nào cần ghi nhớ khi giao tiếp và ứng xử trong môi trường mạng?', '["''Trên mạng không ai biết mình nên nói năng thô lỗ thế nào cũng được''", "''Hãy ứng xử văn minh, lịch sự và tôn trọng người khác trên mạng giống như khi giao tiếp trực tiếp ngoài đời thực''", "''Luôn dùng từ ngữ viết tắt mật mã để thầy cô không đọc hiểu được''", "''Thấy ai có ý kiến khác mình là phải công kích ngay''"]'::jsonb, 1, 'Văn hóa ứng xử trên mạng (`Netiquette`) đòi hỏi sự tôn trọng, lịch sự và nhân văn như trong giao tiếp trực tiếp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-3', 'k7-p09', 3, 'Nhận biết', 'Hành vi nào sau đây được xác định là ''Bắt nạt qua mạng'' (`Cyberbullying`)?', '["Nhắn tin nhắc bạn lịch kiểm tra học kì môn Tin học", "Cố ý ghép ảnh chế giễu ngoại hình của bạn, đăng lên nhóm chat và rủ rê nhiều người vào bình luận miệt thị, cô lập bạn", "Góp ý chân thành, riêng tư khi thấy bài trình chiếu của bạn có lỗi chính tả", "Chia sẻ tài liệu ôn tập cho cả tổ"]'::jsonb, 1, 'Cố ý làm nhục, chế giễu, đe dọa hoặc cô lập người khác qua phương tiện điện tử là hành vi bắt nạt qua mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-4', 'k7-p09', 4, 'Thông hiểu', 'Khi em đang tìm tài liệu trên mạng mà vô tình xuất hiện một cửa sổ quảng cáo chứa hình ảnh bạo lực hoặc nội dung xấu độc không phù hợp lứa tuổi, em nên làm gì?', '["Nháy chuột vào xem tiếp rồi gửi cho các bạn cùng lớp", "Đóng ngay cửa sổ đó lại, không chia sẻ cho ai và báo cho bố mẹ hoặc thầy cô giáo giúp chặn trang web đó", "Tải về lưu vào máy tính", "Làm theo hướng dẫn trên trang web xấu đó"]'::jsonb, 1, 'Chủ động thoát khỏi nội dung độc hại và báo cho người lớn là cách tự bảo vệ an toàn tinh thần trên mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-5', 'k7-p09', 5, 'Thông hiểu', 'Nếu bản thân em bị một tài khoản trên mạng liên tục nhắn tin đe dọa, xúc phạm, cách xử lí nào sau đây là ĐÚNG ĐẮN và AN TOÀN nhất?', '["Giấu kín chuyện đó một mình và lo sợ không dám đi học", "Hẹn gặp riêng kẻ đó ở nơi vắng vẻ để cãi nhau", "Không nhắn tin đôi co đáp trả; chụp ảnh màn hình lưu bằng chứng, sử dụng tính năng Chặn (`Block`)/Báo cáo (`Report`) và kể ngay cho bố mẹ, thầy cô giáo để được bảo vệ", "Lập tài khoản giả đi bắt nạt một người khác"]'::jsonb, 2, 'Lưu bằng chứng, chặn liên lạc và tìm kiếm sự hỗ trợ từ cha mẹ, thầy cô là quy trình xử lí chuẩn mực nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-6', 'k7-p09', 6, 'Vận dụng', 'Khi gửi một bức thư điện tử (`Email`) nộp bài tập cho cô giáo chủ nhiệm, cách viết nào sau đây thể hiện sự LỊCH SỰ, CÓ VĂN HÓA?', '["Không ghi tiêu đề thư, không chào hỏi, chỉ đính kèm tệp rồi bấm gửi", "Ghi rõ tiêu đề thư (`[Tin học 7A] Bài thực hành 3 - Nguyễn Văn An`), mở đầu có lời chào cô lễ phép, nội dung rõ ràng và cuối thư có lời cảm ơn, kính chúc", "Viết toàn bằng chữ IN HOA và ngôn ngữ teen code", "Gửi thư trống không có nội dung"]'::jsonb, 1, 'Thư điện tử gửi thầy cô cần có tiêu đề rõ ràng, lời chào mở đầu, nội dung lễ phép và lời kết chuẩn mực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-9-7', 'k7-p09', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.B2.2), hành động nào thể hiện đạo đức số khi sử dụng các công cụ tạo ảnh hoặc tạo văn bản bằng AI?', '["Dùng AI viết những lời bình luận xúc phạm bạn bè tự động", "Dùng AI tạo hình ảnh minh họa tích cực cho chiến dịch ''Nói không với bạo lực học đường và bắt nạt qua mạng''", "Dùng AI tạo ảnh giả mạo nói xấu bạn cùng lớp", "Dùng AI tạo tin nhắn lừa đảo"]'::jsonb, 1, 'Hướng công nghệ và AI vào việc lan tỏa thông điệp nhân văn, tích cực là biểu hiện của công dân số có văn hóa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-1', 'k7-p10', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Việc sử dụng Internet, mạng xã hội hoặc trò chơi trực tuyến quá mức đến mức mất khả năng tự kiểm soát thời gian và ảnh hưởng nghiêm trọng đến học tập, sức khỏe, cuộc sống được gọi là bệnh [___] Internet."', '["nghiện", "xấu / phạm pháp", "tự", "Tác hại về Thể chất"]'::jsonb, 0, 'Theo SGK Tin học 7: Việc sử dụng Internet, mạng xã hội hoặc trò chơi trực tuyến quá mức đến mức mất khả năng tự kiểm soát thời gian và ảnh hưởng nghiêm trọng đến học tập, sức khỏe, cuộc sống được gọi là bệnh «nghiện» Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-2', 'k7-p10', 2, 'Nhận biết', 'Biểu hiện nào sau đây là dấu hiệu rõ rệt nhất của chứng ''Nghiện Internet''?', '["Dùng máy tính 45 phút mỗi tối để tra cứu bài học và làm bài tập Tin học rồi tắt máy đi ngủ đúng giờ", "Dành hàng chục giờ mỗi ngày để chơi game/lướt mạng, bỏ ăn bỏ ngủ, học tập sa sút và nổi cáu khi không được dùng thiết bị", "Gửi email nộp bài cho cô giáo mỗi tuần 1 lần", "Tham gia câu lạc bộ bóng rổ của trường vào mỗi buổi chiều"]'::jsonb, 1, 'Mất kiểm soát thời gian sử dụng Internet gây tổn hại sức khỏe, tâm lí và học tập là đặc trưng của nghiện Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-3', 'k7-p10', 3, 'Nhận biết', 'Tác hại nào sau đây KHÔNG phải do nghiện Internet gây ra?', '["Suy giảm thị lực, cong vẹo cột sống và thiếu ngủ trầm trọng", "Mất tập trung trong giờ học, điểm số tụt dốc", "Tăng cường sự gắn kết, thấu hiểu và trò chuyện trực tiếp với ông bà, cha mẹ", "Tăng nguy cơ bị lừa đảo hoặc bị lôi kéo vào các hội nhóm xấu trên mạng"]'::jsonb, 2, 'Nghiện Internet làm người mắc thu mình trong thế giới ảo và xa rời giao tiếp trực tiếp với gia đình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-4', 'k7-p10', 4, 'Thông hiểu', 'Cách làm nào sau đây giúp học sinh PHÒNG TRÁNH bệnh nghiện Internet hiệu quả nhất?', '["Mang điện thoại vào chăn xem từ 10 giờ đêm đến 3 giờ sáng", "Xây dựng thời gian biểu sinh hoạt khoa học: quy định rõ thời lượng dùng máy tính mỗi ngày, tắt thông báo các ứng dụng giải trí khi đang học và tích cực chơi thể thao, đọc sách", "Xóa hết các phần mềm học tập và chỉ giữ lại trò chơi", "Ngồi trước màn hình máy tính suốt 8 tiếng ngày Chủ nhật"]'::jsonb, 1, 'Quản lí thời gian tự giác kết hợp các hoạt động thể chất, xã hội ngoài đời thực là chìa khóa phòng tránh nghiện mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-5', 'k7-p10', 5, 'Thông hiểu', 'Nếu nhận thấy người bạn thân của mình bắt đầu có dấu hiệu mê chơi game trực tuyến đến mức thường xuyên ngủ gật trên lớp và quên làm bài tập, em nên làm gì?', '["Rủ bạn trốn học đi chơi game cùng", "Chê cười và xa lánh bạn", "Chân thành khuyên nhủ, rủ bạn cùng học nhóm, cùng tham gia đá cầu/chơi thể thao giờ ra chơi và nhờ thầy cô, gia đình hỗ trợ nếu bạn chưa tự thoát ra được", "Làm hộ toàn bộ bài tập cho bạn để bạn rảnh thời gian chơi game"]'::jsonb, 2, 'Sự quan tâm, đồng hành rủ bạn tham gia hoạt động thực tế lành mạnh giúp bạn lấy lại cân bằng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-6', 'k7-p10', 6, 'Vận dụng', 'Theo Khung năng lực số (TC1.4.3), tính năng nào trên các hệ điều hành và thiết bị thông minh hiện nay hỗ trợ người dùng tự theo dõi và giới hạn thời gian sử dụng màn hình mỗi ngày?', '["`Screen Time` / `Digital Wellbeing` (Thời gian sử dụng màn hình & Sức khỏe số)", "`Paint`", "`Calculator`", "`Recycle Bin`"]'::jsonb, 0, 'Công cụ `Screen Time` / `Digital Wellbeing` thống kê thời gian dùng từng ứng dụng và đặt hẹn giờ giới hạn mỗi ngày.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-10-7', 'k7-p10', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.B1.2), nguyên tắc sử dụng công cụ AI nào giúp học sinh phát triển lành mạnh, tránh lệ thuộc thụ động?', '["Dùng AI trò chuyện thay cho mọi người bạn ngoài đời thực và nhờ AI làm hộ hết bài tập", "Luôn tự mình suy nghĩ, đọc sách và thảo luận với thầy cô, bạn bè trước; chỉ dùng AI như công cụ tra cứu, gợi ý trong khung thời gian hợp lí", "Bật AI suốt ngày đêm", "Tin rằng thế giới ảo quan trọng hơn gia đình"]'::jsonb, 1, 'Giữ vững tư duy độc lập và ưu tiên các mối quan hệ thực tế giúp học sinh làm chủ công nghệ mà không bị lệ thuộc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-1', 'k7-p11', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Giao của một cột và một hàng trên trang tính tạo thành một [___] tính; địa chỉ của nó được viết theo thứ tự `<Tên cột><Tên hàng>` (ví dụ: `C4`)."', '["ô", "vùng", "Hộp tên / Thanh công thức", "Địa chỉ ô tính (ví dụ: `D5`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Giao của một cột và một hàng trên trang tính tạo thành một «ô» tính; địa chỉ của nó được viết theo thứ tự `<Tên cột><Tên hàng>` (ví dụ: `C4`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-2', 'k7-p11', 2, 'Nhận biết', 'Trên trang tính Excel, địa chỉ của ô tính nằm tại giao của cột `E` và hàng `12` được viết như thế nào?', '["`12E`", "`E12`", "`E:12`", "`E-12`"]'::jsonb, 1, 'Địa chỉ ô tính luôn được viết theo quy tắc: Tên cột (chữ cái) viết trước, Tên hàng (chữ số) viết sau: `E12`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-3', 'k7-p11', 3, 'Nhận biết', 'Cách viết nào sau đây biểu diễn ĐÚNG địa chỉ của vùng dữ liệu hình chữ nhật từ ô `A3` đến ô `F10`?', '["`A3-F10`", "`A3;F10`", "`A3:F10`", "`A3..F10`"]'::jsonb, 2, 'Địa chỉ vùng dữ liệu gồm địa chỉ ô góc trên bên trái và ô góc dưới bên phải, ngăn cách bởi dấu hai chấm `:` (`A3:F10`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-4', 'k7-p11', 4, 'Thông hiểu', 'Thành phần nào trên màn hình Excel hiển thị địa chỉ của ô tính hiện thời đang được chọn?', '["Thanh trạng thái (`Status Bar`)", "Hộp tên (`Name Box`)", "Thanh tiêu đề (`Title Bar`)", "Thanh cuộn (`Scroll Bar`)"]'::jsonb, 1, 'Hộp tên (`Name Box`) nằm ở góc trên bên trái (bên trái thanh công thức) hiển thị địa chỉ của ô đang chọn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-5', 'k7-p11', 5, 'Thông hiểu', 'Khi nội dung văn bản nhập vào một ô tính quá dài và tràn sang ô bên cạnh, ngoài cách kéo rộng cột, em có thể dùng nút lệnh nào trong thẻ `Home` để chữ tự động xuống dòng trong cùng một ô?', '["`Wrap Text`", "`Copy`", "`Italic`", "`Sort`"]'::jsonb, 0, 'Nút `Wrap Text` trong nhóm `Alignment` (thẻ `Home`) giúp văn bản tự động xuống dòng vừa với độ rộng của cột.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-6', 'k7-p11', 6, 'Vận dụng', 'Muốn sửa một vài chữ cái bên trong ô tính đang có dữ liệu mà KHÔNG làm mất toàn bộ nội dung cũ, em thực hiện thao tác nào?', '["Chọn ô đó và nhấn phím `Delete`", "Nháy đúp chuột vào ô tính đó (hoặc chọn ô rồi nháy chuột vào Thanh công thức `Formula Bar` / nhấn phím `F2`)", "Chọn ô đó và gõ đè chữ mới ngay", "Tắt phần mềm Excel"]'::jsonb, 1, 'Nháy đúp chuột (hoặc nhấn `F2` / sửa trên `Formula Bar`) đưa con trỏ soạn thảo vào bên trong ô để chỉnh sửa từng kí tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-11-7', 'k7-p11', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C1.2), lợi ích của việc tổ chức dữ liệu khảo sát thành bảng có các cột rõ ràng (`STT`, `Tên cây`, `Chiều cao`, `Đơn giá`) là gì?', '["Làm cho máy tính không đọc được số", "Tạo ra bộ dữ liệu có cấu trúc chuẩn (`Structured Data`) giúp phần mềm bảng tính và các công cụ AI dễ dàng thống kê, phân tích", "Để không cần lưu tệp", "Chỉ để tô màu cho vui"]'::jsonb, 1, 'Dữ liệu có cấu trúc dạng hàng – cột là nền tảng cho mọi hoạt động tính toán tự động và phân tích dữ liệu AI.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-1', 'k7-p12', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để tự động điều chỉnh độ rộng của một cột vừa khít với dữ liệu dài nhất có trong cột đó (`AutoFit`), ta đưa trỏ chuột vào vạch ngăn cách bên phải tên cột và [___] chuột."', '["nháy đúp", "Insert", "Ctrl + S", "Nháy chuột phải vào tên cột/hàng -> `Insert`"]'::jsonb, 0, 'Theo SGK Tin học 7: Để tự động điều chỉnh độ rộng của một cột vừa khít với dữ liệu dài nhất có trong cột đó (`AutoFit`), ta đưa trỏ chuột vào vạch ngăn cách bên phải tên cột và «nháy đúp» chuột.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-2', 'k7-p12', 2, 'Nhận biết', 'Trong phần mềm Excel, muốn thay đổi độ rộng của cột `B` để hiển thị đầy đủ tên các loài cây không bị che khuất, em đưa con trỏ chuột tới vị trí nào rồi kéo thả?', '["Đưa vào giữa ô `B5`", "Đưa vào vạch ngăn cách bên phải tiêu đề cột `B` (giữa cột `B` và cột `C`) trên thanh tiêu đề cột khi trỏ chuột biến thành mũi tên hai chiều rồi kéo sang phải", "Đưa vào góc màn hình", "Đưa vào nút `Save`"]'::jsonb, 1, 'Kéo vạch biên bên phải tên cột (hoặc nháy đúp vào đó) giúp thay đổi độ rộng của cột tương ứng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-3', 'k7-p12', 3, 'Nhận biết', 'Trong khi nhập bảng danh sách cây của dự án ''Trường học xanh'', em phát hiện bị bỏ sót một loại cây ở giữa dòng 4 và dòng 5. Để chèn thêm 1 hàng trống mới vào vị trí dòng 5, em làm thế nào?', '["Gõ đè lên dòng 5", "Nháy nút phải chuột vào tiêu đề hàng số `5` (bên lề trái) và chọn lệnh `Insert`", "Xóa hết từ dòng 5 trở xuống", "Tạo một tệp Excel mới"]'::jsonb, 1, 'Nháy chuột phải vào số thứ tự hàng `5` và chọn `Insert` sẽ chèn thêm một hàng mới ngay phía trên hàng 5.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-4', 'k7-p12', 4, 'Thông hiểu', 'Khi muốn xóa bỏ hoàn toàn cột `C` đang bị dư thừa trên trang tính, thao tác nào sau đây là ĐÚNG?', '["Chỉ chọn ô `C1` rồi nhấn phím `Space`", "Nháy nút phải chuột vào tiêu đề cột chữ `C` và chọn lệnh `Delete`", "Đổi màu chữ cột `C` sang màu trắng", "Thu hẹp cột `C` lại"]'::jsonb, 1, 'Nháy chuột phải vào tên cột chữ `C` -> chọn `Delete` sẽ xóa hẳn cột đó và dồn các cột bên phải sang.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-5', 'k7-p12', 5, 'Thông hiểu', 'Để điền tự động dãy số thứ tự `1, 2, 3, 4...` trong cột `STT` bằng tay cầm điền tự động (`Fill Handle` - dấu cộng màu đen ở góc dưới bên phải vùng chọn), trước khi kéo chuột em nên chọn như thế nào?', '["Chỉ chọn 1 ô trống", "Nhập `1` và `2` vào hai ô đầu tiên liên tiếp, sau đó kéo chuột bôi đen CẢ HAI ô đó rồi mới kéo dấu cộng đen ở góc dưới bên phải xuống dưới", "Chỉ nhập chữ `''STT''` rồi kéo", "Nhấn phím `Delete` rồi kéo"]'::jsonb, 1, 'Chọn cả 2 ô chứa `1` và `2` giúp Excel nhận biết quy luật tăng dần mỗi bước 1 đơn vị để điền tiếp `3, 4, 5...`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-6', 'k7-p12', 6, 'Vận dụng', 'Ở chế độ mặc định của Excel (khi người dùng chưa bấm nút căn lề), dữ liệu kiểu Văn bản (chữ) và dữ liệu kiểu Số khi nhập vào ô tính sẽ tự động căn lề như thế nào?', '["Cả chữ và số đều căn giữa", "Dữ liệu Văn bản tự động căn thẳng lề trái, còn dữ liệu Số tự động căn thẳng lề phải của ô tính", "Dữ liệu Văn bản căn phải, dữ liệu Số căn trái", "Tất cả đều nằm lệch lên trên"]'::jsonb, 1, 'Excel tự động căn trái đối với Văn bản (`Text`) và căn phải đối với Số (`Number`) / Ngày tháng (`Date`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-12-7', 'k7-p12', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C2.3), nguyên tắc nhập liệu nào giúp bảng dữ liệu ''Trường học xanh'' sẵn sàng cho việc tính toán tự động và phân tích bằng AI?', '["Gộp chung tên cây, số lượng và đơn giá vào cùng 1 ô duy nhất", "Mỗi thông tin (`STT`, `Tên cây`, `Số lượng`, `Đơn giá`) đặt ở một cột riêng biệt, và trong các cột số liệu (`Số lượng`, `Đơn giá`) chỉ nhập số thuần túy không kèm chữ đơn vị", "Mỗi dòng nhập lệch sang một cột khác nhau", "Bỏ trống ngẫu nhiên các ô tiêu đề"]'::jsonb, 1, 'Tách riêng từng thuộc tính ra từng cột và giữ thuần nhất kiểu dữ liệu số trên cột số là nguyên tắc vàng khi xây dựng bảng dữ liệu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-1', 'k7-p13', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong phần mềm bảng tính, mọi công thức tính toán đều bắt buộc phải bắt đầu bằng kí hiệu dấu [___]."', '["=", "* (dấu sao)", "địa chỉ", "Phép nhân `*` & Phép chia `/`"]'::jsonb, 0, 'Theo SGK Tin học 7: Trong phần mềm bảng tính, mọi công thức tính toán đều bắt buộc phải bắt đầu bằng kí hiệu dấu «=».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-2', 'k7-p13', 2, 'Nhận biết', 'Kí hiệu nào bắt buộc phải gõ ĐẦU TIÊN khi nhập một công thức tính toán vào ô tính trong Excel?', '["Dấu cộng `+`", "Dấu sao `*`", "Dấu bằng `=`", "Dấu hai chấm `:`"]'::jsonb, 2, 'Dấu `=` ở đầu báo cho phần mềm bảng tính biết nội dung tiếp theo là một công thức cần tính toán.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-3', 'k7-p13', 3, 'Nhận biết', 'Trong phần mềm bảng tính Excel, các phép toán Nhân, Chia và Lũy thừa lần lượt được kí hiệu bằng những dấu nào?', '["`x`, `:`, `^`", "`*`, `/`, `^`", "`.`, `:`, `*`", "`*`, `\\`, `%`"]'::jsonb, 1, 'Excel quy ước: dấu `*` là phép nhân, dấu `/` là phép chia và dấu `^` là phép nâng lên lũy thừa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-4', 'k7-p13', 4, 'Thông hiểu', 'Giả sử ô `A1` chứa số `10`, ô `B1` chứa số `5`. Nếu tại ô `C1` ta nhập `A1+B1` (không có dấu `=`) rồi nhấn `Enter` thì kết quả hiển thị trong ô `C1` là gì?', '["`15`", "`A1+B1`", "`50`", "`#VALUE!`"]'::jsonb, 1, 'Vì thiếu dấu `=` ở đầu nên Excel hiểu `A1+B1` là dữ liệu kiểu văn bản và giữ nguyên chuỗi kí tự đó.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-5', 'k7-p13', 5, 'Thông hiểu', 'Cho ô `A2 = 4`, `B2 = 6`, `C2 = 2`. Kết quả của công thức `=A2+B2/C2` là bao nhiêu?', '["`5`", "`7` (vì thực hiện phép chia `6 / 2 = 3` trước, rồi cộng `4 + 3 = 7`)", "`12`", "`8`"]'::jsonb, 1, 'Theo thứ tự ưu tiên phép toán, phép chia `/` được thực hiện trước phép cộng `+`: `4 + (6/2) = 4 + 3 = 7`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-6', 'k7-p13', 6, 'Vận dụng', 'Ưu điểm vượt trội của việc viết công thức sử dụng ĐỊA CHỈ Ô (như `=C4*D4`) so với viết số trực tiếp (như `=15*20`) là gì?', '["Không có sự khác biệt nào", "Khi sửa đổi giá trị số trong ô `C4` hoặc `D4`, kết quả của công thức `=C4*D4` sẽ TỰ ĐỘNG cập nhật lại ngay lập tức mà không cần sửa công thức", "Làm cho phông chữ to hơn", "Không cần nhấn Enter"]'::jsonb, 1, 'Tính toán tự động dựa trên địa chỉ ô là tính năng cốt lõi giúp bảng tính cập nhật kết quả tức thời.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-13-7', 'k7-p13', 7, 'Vận dụng', 'Biểu thức toán học $\frac{x + y}{x - y}$ (với `x` ở ô `A3` và `y` ở ô `B3`) được viết thành công thức Excel nào sau đây là ĐÚNG?', '["`=A3+B3/A3-B3`", "`=(A3+B3)/(A3-B3)`", "`=[A3+B3]/[A3-B3]`", "`=(A3+B3):(A3-B3)`"]'::jsonb, 1, 'Cả tử số và mẫu số đều là phép cộng/trừ nên phải đặt trong cặp dấu ngoặc tròn `( )` và dùng dấu chia `/` ở giữa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-1', 'k7-p14', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi sao chép một ô chứa công thức có địa chỉ ô sang vị trí mới, các địa chỉ ô trong công thức sẽ [___] điều chỉnh theo đúng vị trí tương đối giữa ô chứa công thức và các ô tham chiếu."', '["tự động", "=C9*D9", "cộng (+)", "Sao chép từ `E4` (`=C4*D4`) xuống `E5`"]'::jsonb, 0, 'Theo SGK Tin học 7: Khi sao chép một ô chứa công thức có địa chỉ ô sang vị trí mới, các địa chỉ ô trong công thức sẽ «tự động» điều chỉnh theo đúng vị trí tương đối giữa ô chứa công thức và các ô tham chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-2', 'k7-p14', 2, 'Nhận biết', 'Tại ô `E4` có công thức `=C4*D4`. Khi sao chép công thức này từ ô `E4` xuống ô `E8`, công thức tại ô `E8` sẽ tự động đổi thành gì?', '["`=C4*D4`", "`=C8*D8`", "`=E8*D8`", "`=C5*D5`"]'::jsonb, 1, 'Khi sao chép từ hàng 4 xuống hàng 8 (cùng cột E), chỉ số hàng của các địa chỉ ô trong công thức tự động đổi từ 4 thành 8: `=C8*D8`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-3', 'k7-p14', 3, 'Nhận biết', 'Tại ô `B6` có công thức tính tổng 3 tháng: `=B3+B4+B5`. Khi sao chép công thức này từ ô `B6` sang phải đến ô `D6`, công thức tại ô `D6` sẽ là gì?', '["`=B3+B4+B5`", "`=C3+C4+C5`", "`=D3+D4+D5`", "`=D6+D6+D6`"]'::jsonb, 2, 'Khi sao chép ngang từ cột `B` sang cột `D`, chỉ số hàng (3, 4, 5) giữ nguyên còn tên cột tự động đổi từ `B` sang `D`: `=D3+D4+D5`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-4', 'k7-p14', 4, 'Thông hiểu', 'Khi đưa con trỏ chuột vào chấm vuông nhỏ ở góc dưới bên phải của ô đang chọn (`Fill Handle`) để kéo sao chép công thức, con trỏ chuột chuyển sang hình dạng nào?', '["Hình dấu cộng màu trắng béo", "Hình dấu cộng mảnh màu đen (`+`)", "Hình mũi tên bốn chiều", "Hình bàn tay"]'::jsonb, 1, 'Con trỏ dấu cộng mảnh màu đen ở góc dưới bên phải ô là biểu tượng của công cụ điền/sao chép tự động `Fill Handle`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-5', 'k7-p14', 5, 'Thông hiểu', 'Tại ô `C2` có công thức `=10*5` (không chứa địa chỉ ô nào). Nếu sao chép công thức từ ô `C2` xuống ô `C6` thì tại ô `C6` có kết quả là bao nhiêu?', '["`0`", "`50` (vì công thức không có địa chỉ ô nên giữ nguyên là `=10*5`)", "`60`", "`#REF!`"]'::jsonb, 1, 'Các hằng số (`10`, `5`) trong công thức không thay đổi khi sao chép công thức.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-6', 'k7-p14', 6, 'Vận dụng', 'Khi chọn một ô có chứa công thức (ví dụ ô `E4`), trong ô tính hiển thị giá trị kết quả (`300`), còn công thức gốc (`=C4*D4`) sẽ hiển thị ở đâu trên màn hình?', '["Hiển thị trên Thanh công thức (`Formula Bar`)", "Hiển thị trong Hộp tên (`Name Box`)", "Hiển thị ở Thanh trạng thái dưới cùng", "Biến mất hoàn toàn không xem lại được"]'::jsonb, 0, 'Thanh công thức (`Formula Bar`) luôn hiển thị công thức gốc của ô đang được chọn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-14-7', 'k7-p14', 7, 'Vận dụng', 'Tính năng tự động thay đổi địa chỉ tương ứng khi sao chép công thức của phần mềm bảng tính mang lại lợi ích cốt lõi nào?', '["Bắt người dùng phải gõ từng dòng", "Giúp người dùng chỉ cần lập công thức 1 lần ở dòng đầu tiên rồi sao chép nhanh cho hàng trăm, hàng nghìn dòng dữ liệu tương tự với độ chính xác tuyệt đối", "Chỉ dùng được cho 2 dòng", "Làm giảm dung lượng ổ cứng"]'::jsonb, 1, 'Sao chép công thức tự động điều chỉnh địa chỉ giúp tiết kiệm thời gian gấp hàng trăm lần và loại bỏ sai sót gõ nhầm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-1', 'k7-p15', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong bảng tính dự toán kinh phí trồng cây (SGK trang 37), nếu cột `C` là `Số lượng` và cột `D` là `Đơn giá`, thì công thức tính `Thành tiền` tại ô `E4` là [___]."', '["=C4*D4", "Phần trăm (Percentage)", "Ctrl + S", "Công thức `=C4*D4`"]'::jsonb, 0, 'Theo SGK Tin học 7: Trong bảng tính dự toán kinh phí trồng cây (SGK trang 37), nếu cột `C` là `Số lượng` và cột `D` là `Đơn giá`, thì công thức tính `Thành tiền` tại ô `E4` là «=C4*D4».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-2', 'k7-p15', 2, 'Nhận biết', 'Trong bài thực hành dự án ''Trường học xanh'' (SGK trang 36–37), biết ô `C4` là `Số lượng cây` và ô `D4` là `Đơn giá (nghìn đồng)`, công thức nào cần nhập vào ô `E4` để tính `Thành tiền`?', '["`=C4+D4`", "`=C4*D4`", "`=C4/D4`", "`=C4-D4`"]'::jsonb, 1, '`Thành tiền` được tính bằng `Số lượng` nhân với `Đơn giá`, tức là `=C4*D4`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-3', 'k7-p15', 3, 'Nhận biết', 'Khi đang nhập công thức tại ô `E4`, sau khi gõ dấu `=`, cách làm nào giúp đưa địa chỉ ô `C4` vào công thức nhanh và không bao giờ nhầm địa chỉ?', '["Đóng tệp lại mở ra", "Dùng chuột nháy trực tiếp vào ô `C4` trên trang tính, sau đó gõ dấu `*` rồi nháy chuột vào ô `D4` và nhấn `Enter`", "Gõ chữ Số lượng nhân Đơn giá", "Nhấn phím `Delete`"]'::jsonb, 1, 'Nháy chuột chọn ô tham chiếu (`Point and Click`) khi lập công thức giúp Excel hiển thị khung màu trực quan quanh ô đó và tránh gõ sai địa chỉ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-4', 'k7-p15', 4, 'Thông hiểu', 'Sau khi sao chép công thức `=C4*D4` từ ô `E4` xuống đến ô `E12`, nếu em sửa đơn giá cây hoa cúc tại ô `D7` từ `10` thành `12` và nhấn `Enter`, điều gì sẽ xảy ra?', '["Không có ô nào thay đổi", "Giá trị `Thành tiền` tại ô `E7` tự động được tính lại theo đơn giá mới `12` ngay lập tức", "Công thức ở ô `E7` bị xóa mất", "Tất cả các ô khác đều biến thành `12`"]'::jsonb, 1, 'Vì ô `E7` chứa công thức `=C7*D7` nên khi `D7` thay đổi, kết quả tại `E7` tự động cập nhật tức thời.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-5', 'k7-p15', 5, 'Thông hiểu', 'Nếu tại ô `E8`, kết quả hiển thị chữ `#VALUE!` sau khi sao chép công thức `=C8*D8`, nguyên nhân nào sau đây là khả dĩ nhất?', '["Ô `C8` hoặc `D8` đang chứa dữ liệu kiểu Văn bản (ví dụ gõ nhầm chữ `''10 cây''` hoặc chữ `''O''` thay vì số `0`) khiến phép nhân số học không thực hiện được", "Máy tính chạy quá nhanh", "Phông chữ đang để Calibri", "Chưa lưu tệp"]'::jsonb, 0, 'Lỗi `#VALUE!` xuất hiện khi thực hiện phép toán số học (`+`, `-`, `*`, `/`) trên ô chứa dữ liệu kiểu Văn bản (`Text`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-6', 'k7-p15', 6, 'Vận dụng', 'Để thêm một trang tính (`Sheet`) mới vào sổ tính `THXanh.xlsx` đang mở, em nháy chuột vào biểu tượng nào ở góc dưới màn hình?', '["Biểu tượng dấu cộng `+` (`New sheet`) bên cạnh tên trang tính `Sheet1`", "Biểu tượng `Save` ở góc trên", "Biểu tượng `Close` (`X`)", "Nút `Wrap Text`"]'::jsonb, 0, 'Nút dấu cộng `+` trên thanh nhãn trang tính dùng để tạo thêm trang tính mới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-15-7', 'k7-p15', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C3.1), trước khi gửi bảng dự toán kinh phí `THXanh.xlsx` cho thầy cô hoặc đưa vào công cụ phân tích, bước kiểm tra nào giúp phát hiện sai sót nhanh nhất?', '["Kiểm tra ngẫu nhiên 1–2 dòng bằng cách tính nhẩm (`Số lượng x Đơn giá`) và nháy xem thanh công thức `Formula Bar` để chắc chắn mọi ô trong cột `Thành tiền` đều là công thức động chứ không phải số gõ tay", "Xóa hết tiêu đề cột", "Đổi tất cả số thành chữ", "Tắt màn hình"]'::jsonb, 0, 'Kiểm tra mẫu và xác nhận công thức trên `Formula Bar` đảm bảo tính toàn vẹn của bảng tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-1', 'k7-p16', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong phần mềm bảng tính, [___] (`Function`) là công thức được định nghĩa sẵn từ trước nhằm hỗ trợ tính toán nhanh chóng theo tên hàm và các tham số đầu vào."', '["hàm", "=AVERAGE(C4:C10)", "bỏ qua", "Hàm `=SUM(E4:E15)` & `=COUNT(E4:E15)`"]'::jsonb, 0, 'Theo SGK Tin học 7: Trong phần mềm bảng tính, «hàm» (`Function`) là công thức được định nghĩa sẵn từ trước nhằm hỗ trợ tính toán nhanh chóng theo tên hàm và các tham số đầu vào.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-2', 'k7-p16', 2, 'Nhận biết', 'Hàm nào trong phần mềm bảng tính Excel dùng để tính TRUNG BÌNH CỘNG của các giá trị số trong vùng dữ liệu?', '["`=SUM(...)`", "`=AVERAGE(...)`", "`=MAX(...)`", "`=COUNT(...)`"]'::jsonb, 1, 'Hàm `AVERAGE` dùng để tính trung bình cộng của các tham số hoặc vùng dữ liệu số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-3', 'k7-p16', 3, 'Nhận biết', 'Để tìm xem loại cây nào trong vùng số lượng `C4:C15` được trồng với số lượng NHIỀU NHẤT và ÍT NHẤT, em lần lượt sử dụng hai hàm nào?', '["`SUM` và `COUNT`", "`MAX` và `MIN`", "`AVERAGE` và `SUM`", "`MIN` và `COUNT`"]'::jsonb, 1, '`MAX` trả về giá trị lớn nhất (nhiều nhất) và `MIN` trả về giá trị nhỏ nhất (ít nhất).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-4', 'k7-p16', 4, 'Thông hiểu', 'Cho các ô `B1 = 8`, `B2 = 10`, `B3 = "Vắng"` (chữ), `B4 = 6`. Kết quả của công thức `=COUNT(B1:B4)` là bao nhiêu?', '["`4`", "`3` (vì hàm `COUNT` chỉ đếm các ô chứa dữ liệu kiểu Số là B1, B2, B4 và bỏ qua ô chữ B3)", "`24`", "`8`"]'::jsonb, 1, 'Hàm `COUNT` chỉ đếm số lượng các ô chứa giá trị kiểu Số, bỏ qua các ô chứa Văn bản hoặc ô trống.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-5', 'k7-p16', 5, 'Thông hiểu', 'Vẫn với các ô `B1 = 8`, `B2 = 10`, `B3` để trống, `B4 = 6`. Kết quả của công thức `=AVERAGE(B1:B4)` là bao nhiêu?', '["`6` (lấy 24 chia 4)", "`8` (lấy `(8 + 10 + 6) / 3 = 24 / 3 = 8` vì bỏ qua ô trống `B3`)", "`24`", "`10`"]'::jsonb, 1, 'Hàm `AVERAGE` chỉ tính trung bình cộng trên các ô thực sự có chứa giá trị số (3 ô: B1, B2, B4).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-6', 'k7-p16', 6, 'Vận dụng', 'Cách viết cú pháp hàm nào sau đây trong Excel là ĐÚNG?', '["`=SUM[C4:C10]`", "`=SUM(C4:C10)`", "`=SUM(C4-C10)`", "`SUM=(C4:C10)`"]'::jsonb, 1, 'Cú pháp hàm luôn bắt đầu bằng dấu `=`, tiếp theo là tên hàm và danh sách đối số đặt trong cặp dấu ngoặc tròn `( )`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-16-7', 'k7-p16', 7, 'Vận dụng', 'Tại ô `C11` có công thức hàm `=MAX(C4:C10)`. Khi sao chép công thức từ ô `C11` sang phải đến ô `D11`, công thức tại ô `D11` sẽ là gì?', '["`=MAX(C4:C10)`", "`=MAX(D4:D10)`", "`=MIN(D4:D10)`", "`=SUM(D4:D10)`"]'::jsonb, 1, 'Khi sao chép công thức chứa hàm sang cột bên cạnh, địa chỉ vùng dữ liệu tương đối `C4:C10` tự động chuyển thành `D4:D10`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-1', 'k7-p17', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi viết các hàm `AVERAGE`, `MAX`, `MIN` ở các dòng phía dưới dòng `Tổng cộng` (`C10`), ta phải hết sức chú ý chỉ chọn vùng dữ liệu gốc (`C4:C9`), tuyệt đối KHÔNG chọn bao gồm cả ô [___] (`C10`)."', '["Tổng cộng", "Số (Number)", "AutoSum", "`=SUM(E4:E9)`"]'::jsonb, 0, 'Theo SGK Tin học 7: Khi viết các hàm `AVERAGE`, `MAX`, `MIN` ở các dòng phía dưới dòng `Tổng cộng` (`C10`), ta phải hết sức chú ý chỉ chọn vùng dữ liệu gốc (`C4:C9`), tuyệt đối KHÔNG chọn bao gồm cả ô «Tổng cộng» (`C10`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-2', 'k7-p17', 2, 'Nhận biết', 'Trong bảng tính dự án ''Trường học xanh'', dữ liệu các loại cây nằm từ hàng 4 đến hàng 9, dòng 10 là dòng `Tổng cộng` (`=SUM(C4:C9)`). Công thức nào tại ô `C11` tính ĐÚNG số lượng cây trung bình của các loại cây?', '["`=AVERAGE(C4:C10)`", "`=AVERAGE(C4:C9)`", "`=SUM(C4:C9)`", "`=AVERAGE(C10)`"]'::jsonb, 1, 'Phải tính trung bình trên vùng dữ liệu gốc của các loại cây `C4:C9`, không được gộp cả dòng Tổng cộng `C10` vào.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-3', 'k7-p17', 3, 'Nhận biết', 'Cột `A` (`A4:A9`) lưu `STT` (1, 2, 3, 4, 5, 6), cột `B` (`B4:B9`) lưu `Tên cây` (Hoa hồng, Hoa cúc...). Để dùng hàm `COUNT` đếm số loại cây trong bảng, công thức nào sau đây cho kết quả bằng `6`?', '["`=COUNT(B4:B9)`", "`=COUNT(A4:A9)` (hoặc `=COUNT(C4:C9)` trên cột Số lượng)", "`=SUM(A4:A9)`", "`=MAX(B4:B9)`"]'::jsonb, 1, 'Hàm `COUNT` chỉ đếm các ô chứa số nên phải áp dụng trên cột `STT` (`A4:A9`) hoặc cột `Số lượng` (`C4:C9`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-4', 'k7-p17', 4, 'Thông hiểu', 'Biểu tượng chữ Hy Lạp `Σ` (`AutoSum`) nằm trong nhóm lệnh `Editing` của thẻ `Home` giúp thực hiện nhanh thao tác nào?', '["Xóa bảng tính", "Tự động chèn hàm `SUM` (hoặc chọn `Average`, `Count Numbers`, `Max`, `Min` trong mũi tên mở rộng) cho vùng số liệu liền kề", "Chèn hình ảnh", "Đổi màu nền"]'::jsonb, 1, 'Nút `AutoSum` (`Σ`) là công cụ chèn nhanh 5 hàm thống kê cơ bản.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-5', 'k7-p17', 5, 'Thông hiểu', 'Để tính tổng giá trị của hai vùng dữ liệu số rời nhau `C4:C8` và `E4:E8` trong cùng một hàm `SUM`, cách viết nào sau đây là ĐÚNG?', '["`=SUM(C4:C8, E4:E8)`", "`=SUM(C4:C8 : E4:E8)`", "`=SUM(C4:C8 - E4:E8)`", "`=AVERAGE(C4:C8, E4:E8)`"]'::jsonb, 0, 'Hàm `SUM` cho phép truyền nhiều vùng dữ liệu khác nhau ngăn cách bởi dấu phẩy `,` (hoặc `;`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-6', 'k7-p17', 6, 'Vận dụng', 'Khi sao chép vùng 4 công thức thống kê tại `C10:C13` sang `E10:E13` (cột `Thành tiền`), công thức `=MAX(C4:C9)` ở ô `C12` sẽ chuyển thành công thức gì ở ô `E12` và có ý nghĩa gì?', '["Thành `=MAX(E4:E9)`; cho biết khoản tiền lớn nhất chi cho một loại cây", "Thành `=MIN(E4:E9)`", "Thành `=MAX(C4:C9)`", "Thành `=SUM(E4:E9)`"]'::jsonb, 0, 'Địa chỉ tương đối `C4:C9` tự động đổi theo cột thành `E4:E9`, tìm giá trị `Thành tiền` cao nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-17-7', 'k7-p17', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C2.4), sau khi tính được `Tổng kinh phí = 2,450 (nghìn đồng)` vượt quá ngân sách quỹ lớp (`2,000 nghìn đồng`), hàm nào giúp nhóm xác định ngay loại cây đang tốn nhiều tiền nhất để cân nhắc điều chỉnh số lượng?', '["Hàm `MIN(E4:E9)`", "Hàm `MAX(E4:E9)` trên cột `Thành tiền`", "Hàm `COUNT(A4:A9)`", "Không hàm nào giúp được"]'::jsonb, 1, 'Hàm `MAX` trên cột `Thành tiền` chỉ ra ngay khoản chi lớn nhất để nhóm ưu tiên rà soát, điều chỉnh số lượng cho vừa ngân sách.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-1', 'k7-p18', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để giảm bớt số chữ số ở phần thập phân hiển thị (ví dụ làm gọn `16.66667` thành `16.7` hoặc `17`), ta chọn ô tính và nháy vào nút lệnh [___] (`Decrease Decimal`) trong nhóm `Number`."', '["giảm chữ số thập phân", "Merge & Center", "Borders (Kẻ viền)", "`Decrease Decimal` / `Increase Decimal`"]'::jsonb, 0, 'Theo SGK Tin học 7: Để giảm bớt số chữ số ở phần thập phân hiển thị (ví dụ làm gọn `16.66667` thành `16.7` hoặc `17`), ta chọn ô tính và nháy vào nút lệnh «giảm chữ số thập phân» (`Decrease Decimal`) trong nhóm `Number`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-2', 'k7-p18', 2, 'Nhận biết', 'Khi kết quả phép chia hoặc hàm `AVERAGE` có quá nhiều chữ số thập phân (ví dụ `12.345678`), để giảm bớt số chữ số thập phân hiển thị thành `12.35`, em dùng nút lệnh nào trong nhóm `Number` (thẻ `Home`)?', '["`Increase Decimal`", "`Decrease Decimal`", "`Merge & Center`", "`Wrap Text`"]'::jsonb, 1, 'Nút `Decrease Decimal` giảm số chữ số thập phân hiển thị và tự động làm tròn số hiển thị.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-3', 'k7-p18', 3, 'Nhận biết', 'Để hiển thị số `0.25` dưới dạng tỉ lệ phần trăm `25%`, em chọn ô tính đó và nháy vào nút lệnh nào trong nhóm `Number`?', '["Nút `%` (`Percent Style`)", "Nút `,` (`Comma Style`)", "Nút `$`", "Nút `Borders`"]'::jsonb, 0, 'Nút `%` (`Percent Style`) nhân giá trị hiển thị với 100 và gắn kí hiệu `%`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-4', 'k7-p18', 4, 'Thông hiểu', 'Để gộp các ô từ `A1` đến `F1` thành một ô tiêu đề chung nằm chính giữa phía trên bảng dữ liệu, em chọn vùng `A1:F1` rồi nháy nút lệnh nào?', '["`Wrap Text`", "`Merge & Center` (trong nhóm `Alignment`)", "`Fill Color`", "`AutoSum`"]'::jsonb, 1, '`Merge & Center` gộp các ô được chọn thành 1 ô duy nhất và căn giữa văn bản.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-5', 'k7-p18', 5, 'Thông hiểu', 'Muốn kẻ đường viền khung bảng đầy đủ cho vùng dữ liệu `A3:F12` để khi in ra giấy có các đường kẻ bảng rõ nét, em chọn vùng `A3:F12` rồi dùng công cụ nào trong nhóm `Font`?', '["Nút `Fill Color` (biểu tượng thùng sơn)", "Nút `Borders` -> chọn `All Borders`", "Nút `Font Color` (chữ A có gạch màu dưới)", "Nút `Bold` (`B`)"]'::jsonb, 1, 'Nút `Borders` -> `All Borders` kẻ đường viền bao quanh tất cả các ô trong vùng chọn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-6', 'k7-p18', 6, 'Vận dụng', 'Khi dùng nút `Decrease Decimal` chỉnh hiển thị của số `4.8` thành `5` (0 chữ số thập phân), nếu tại một ô khác ta lấy ô đó nhân với `2` thì kết quả tính ra sẽ là bao nhiêu?', '["`10`", "`9.6` (vì Excel luôn tính toán dựa trên giá trị gốc thực tế `4.8` được lưu trong ô chứ không phải số làm tròn hiển thị `5`)", "`8`", "`52`"]'::jsonb, 1, 'Định dạng hiển thị số (`Number Formatting`) chỉ thay đổi diện mạo hiển thị trên màn hình, không làm thay đổi giá trị thực lưu trong bộ nhớ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-18-7', 'k7-p18', 7, 'Vận dụng', 'Cách trình bày bảng tính nào sau đây đạt tính thẩm mỹ và khoa học cao nhất?', '["Tô mỗi ô một màu chói lọi khác nhau và để chữ màu vàng trên nền trắng", "Gộp ô căn giữa tiêu đề bảng, tô màu nền dịu (như xanh dương nhạt/xanh lá nhạt) và in đậm cho hàng tiêu đề cột, kẻ khung `All Borders` rõ ràng và định dạng số đồng nhất", "Gộp tất cả các ô số liệu trong bảng thành 1 ô duy nhất", "Dùng cỡ chữ 36pt cho toàn bộ các con số"]'::jsonb, 1, 'Bảng tính chuẩn mực cần phân biệt rõ cấp độ tiêu đề bảng, tiêu đề cột, dòng dữ liệu và dòng tổng cộng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-1', 'k7-p19', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi một ô đã được gộp từ nhiều ô bằng lệnh `Merge & Center`, nếu muốn tách ô đó trở lại thành các ô rời như ban đầu, ta chọn ô đó và nháy lại một lần nữa vào nút [___] (hoặc chọn `Unmerge Cells`)."', '["Merge & Center", "Sao chép định dạng", "% (Percent Style)", "Một khái niệm khác"]'::jsonb, 0, 'Theo SGK Tin học 7: Khi một ô đã được gộp từ nhiều ô bằng lệnh `Merge & Center`, nếu muốn tách ô đó trở lại thành các ô rời như ban đầu, ta chọn ô đó và nháy lại một lần nữa vào nút «Merge & Center» (hoặc chọn `Unmerge Cells`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-2', 'k7-p19', 2, 'Nhận biết', 'Trong bài thực hành định dạng bảng tính dự án ''Trường học xanh'' (SGK trang 46–47), để tách một ô tiêu đề đã lỡ gộp nhầm từ `A1:H1` trở về các ô riêng lẻ để gộp lại thành `A1:E1`, em làm thế nào?', '["Xóa toàn bộ trang tính", "Chọn ô đã gộp đó rồi nháy chuột lại vào nút `Merge & Center` (hoặc nháy mũi tên cạnh `Merge & Center` chọn `Unmerge Cells`)", "Nhấn phím `Delete`", "Vào thẻ `Data`"]'::jsonb, 1, 'Nút `Merge & Center` hoạt động như một công tắc bật/tắt: nháy lần 1 để gộp ô, nháy lần 2 (hoặc chọn `Unmerge Cells`) để hủy gộp ô.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-3', 'k7-p19', 3, 'Nhận biết', 'Công cụ nào trong nhóm `Clipboard` (thẻ `Home` - có biểu tượng hình cây chổi quét sơn) giúp sao chép nhanh màu nền, phông chữ và đường viền từ bảng thứ nhất sang bảng thứ hai?', '["`Format Painter`", "`Wrap Text`", "`AutoSum`", "`Find & Select`"]'::jsonb, 0, '`Format Painter` sao chép toàn bộ thuộc tính định dạng của ô/vùng mẫu và áp lên vùng đích.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-4', 'k7-p19', 4, 'Thông hiểu', 'Để định dạng các con số trong cột `Thành tiền` từ dạng `1250000` sang dạng có dấu phân cách hàng nghìn `1,250,000` (không lấy phần thập phân), em chọn vùng số liệu rồi thực hiện thao tác nào?', '["Nháy nút `%` (`Percent Style`)", "Nháy nút `,` (`Comma Style`) trong nhóm `Number`, sau đó nháy nút `Decrease Decimal` 2 lần để ẩn `.00`", "Gõ dấu phẩy bằng tay vào từng ô", "Nháy nút `Merge & Center`"]'::jsonb, 1, 'Nút `,` (`Comma Style`) bật dấu phân cách hàng nghìn kèm 2 số lẻ `.00`, kết hợp `Decrease Decimal` sẽ hiển thị số nguyên có dấu phân cách chuẩn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-5', 'k7-p19', 5, 'Thông hiểu', 'Khi tô màu nền (`Fill Color`) cho các ô dữ liệu trong bảng tính, nếu em lỡ chọn màu nền là màu Đen (`Black`) trong khi màu chữ cũng đang là màu Đen thì chuyện gì xảy ra?', '["Chữ hiển thị rõ gấp đôi", "Chữ bị trùng màu với nền nên không thể nhìn thấy chữ trên màn hình (muốn đọc được phải đổi màu chữ sang màu Trắng hoặc đổi màu nền nhạt đi)", "Dữ liệu trong ô bị xóa mất", "Công thức ngừng hoạt động"]'::jsonb, 1, 'Độ tương phản giữa màu chữ (`Font Color`) và màu nền (`Fill Color`) quyết định khả năng đọc hiển thị.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-6', 'k7-p19', 6, 'Vận dụng', 'Trong bảng tổng hợp kinh phí, ô `D4` là kinh phí khu vực 1 (`500`), ô `D7` là Tổng kinh phí toàn trường (`2000`). Sau khi nhập công thức `=D4/D7` ra kết quả `0.25`, nhấn nút `%` (`Percent Style`) sẽ hiển thị kết quả là gì?', '["`0.25%`", "`25%`", "`250%`", "`4%`"]'::jsonb, 1, '`0.25` tương đương với `25/100`, nên định dạng `Percent Style` hiển thị là `25%`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-19-7', 'k7-p19', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C2.5), một bảng tổng hợp dữ liệu được trình bày sạch đẹp, có tiêu đề rõ ràng, căn lề chuẩn và định dạng đơn vị số nhất quán mang lại lợi ích gì khi trích xuất sang báo cáo hoặc bài trình chiếu?', '["Giúp người xem nắm bắt thông tin cốt lõi ngay lập tức, tránh hiểu nhầm đơn vị tính và sẵn sàng sao chép trực tiếp sang trang chiếu PowerPoint ở các bài học tiếp theo", "Chỉ làm tốn mực in", "Không có tác dụng gì", "Làm sai lệch kết quả hàm SUM"]'::jsonb, 0, 'Trình bày bảng tính chuyên nghiệp vừa phục vụ đọc hiểu nhanh vừa sẵn sàng tích hợp sang văn bản Word hoặc bài trình chiếu PowerPoint.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-1', 'k7-p20', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Mỗi tệp bảng tính (được gọi là một Sổ tính - `Workbook`) có thể chứa một hoặc nhiều [___] (`Worksheet`), hiển thị tên ở thanh nhãn phía dưới cùng màn hình."', '["trang tính", "Rename", "Ctrl + P", "Kéo thả nhãn trang tính (`Move Sheet`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Mỗi tệp bảng tính (được gọi là một Sổ tính - `Workbook`) có thể chứa một hoặc nhiều «trang tính» (`Worksheet`), hiển thị tên ở thanh nhãn phía dưới cùng màn hình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-2', 'k7-p20', 2, 'Nhận biết', 'Để đổi tên trang tính từ `Sheet1` thành `Cây hoa` trong phần mềm Excel, em thực hiện thao tác nào sau đây?', '["Vào thẻ `File` -> `Save As`", "Nháy đúp chuột vào chữ `Sheet1` ở thanh nhãn trang tính phía dưới (hoặc nháy chuột phải vào `Sheet1` chọn `Rename`), gõ `Cây hoa` rồi nhấn `Enter`", "Nhấn phím `Delete`", "Vào thẻ `Insert` -> `Table`"]'::jsonb, 1, 'Nháy đúp vào nhãn trang tính hoặc nháy chuột phải chọn `Rename` là cách chuẩn để đổi tên trang tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-3', 'k7-p20', 3, 'Nhận biết', 'Muốn thay đổi thứ tự các trang tính để đưa trang tính `Tổng hợp` từ vị trí cuối cùng lên vị trí đầu tiên bên trái, em làm thế nào?', '["Xóa hết các trang tính phía trước", "Nhấn giữ nút trái chuột vào nhãn trang tính `Tổng hợp` rồi kéo dọc theo thanh nhãn trang tính về vị trí đầu tiên bên trái và thả chuột", "Nhấn tổ hợp phím `Ctrl + P`", "Đổi phông chữ tiêu đề"]'::jsonb, 1, 'Kéo thả chuột trực tiếp trên thanh nhãn trang tính giúp sắp xếp lại thứ tự các trang tính dễ dàng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-4', 'k7-p20', 4, 'Thông hiểu', 'Phát biểu nào sau đây là ĐÚNG và cần đặc biệt lưu ý khi thực hiện lệnh Xóa một trang tính (`Delete Sheet`)?', '["Xóa trang tính xong có thể nhấn `Ctrl + Z` để lấy lại bất cứ lúc nào", "Khi đã xác nhận xóa một trang tính (`Delete`), toàn bộ dữ liệu trên trang tính đó sẽ mất vĩnh viễn và KHÔNG THỂ khôi phục lại bằng lệnh `Undo` (`Ctrl + Z`)", "Trang tính bị xóa sẽ nằm trong `Recycle Bin` của Windows", "Không thể xóa được trang tính"]'::jsonb, 1, 'Excel không hỗ trợ `Undo` (`Ctrl + Z`) đối với thao tác xóa trang tính (`Delete Sheet`), nên luôn hiển thị hộp thoại cảnh báo xác nhận trước khi xóa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-5', 'k7-p20', 5, 'Thông hiểu', 'Tổ hợp phím tắt nào dùng để mở nhanh cửa sổ thiết lập in và Xem trước khi in (`Print`) trong Excel?', '["`Ctrl + S`", "`Ctrl + C`", "`Ctrl + P`", "`Ctrl + Z`"]'::jsonb, 2, '`Ctrl + P` (`Print`) là phím tắt chuẩn trong mọi phần mềm văn phòng để mở giao diện Xem trước và In ấn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-6', 'k7-p20', 6, 'Vận dụng', 'Khi bảng dữ liệu có chiều ngang gồm nhiều cột, để bảng in ra không bị cắt lẻ các cột sang trang giấy khác, trong cửa sổ `Print` em nên chọn hướng giấy và chế độ co giãn (`Scaling`) nào?', '["Hướng giấy Đứng (`Portrait`) và `No Scaling`", "Hướng giấy Ngang (`Landscape Orientation`) và chế độ `Fit All Columns on One Page` (hoặc `Fit Sheet on One Page`)", "Xóa bớt một nửa số cột đi", "Thu nhỏ cỡ chữ xuống 4pt"]'::jsonb, 1, 'Giấy ngang (`Landscape`) kết hợp `Fit All Columns on One Page` giúp toàn bộ các cột của bảng thu gọn vừa vặn trên bề ngang 1 trang giấy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-20-7', 'k7-p20', 7, 'Vận dụng', 'Trong cửa sổ `File -> Print`, tùy chọn `Print Active Sheets` và `Print Entire Workbook` khác nhau như thế nào?', '["`Print Active Sheets` chỉ in trang tính hiện đang mở, còn `Print Entire Workbook` in tất cả các trang tính có dữ liệu trong toàn bộ sổ tính", "Cả hai đều chỉ in trang đầu tiên", "`Print Entire Workbook` dùng để xóa tệp", "`Print Active Sheets` chỉ in màu đen trắng"]'::jsonb, 0, '`Active Sheets` là trang tính hiện hành đang chọn, còn `Entire Workbook` là toàn bộ các trang tính trong tệp Excel.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-1', 'k7-p21', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trang chiếu đầu tiên của bài trình chiếu cho biết chủ đề chính của buổi thuyết trình và tên người/nhóm trình bày được gọi là trang [___] (`Title Slide`)."', '["tiêu đề", "phân cấp", "Tab", "`Title Slide` (Bố cục Trang tiêu đề)"]'::jsonb, 0, 'Theo SGK Tin học 7: Trang chiếu đầu tiên của bài trình chiếu cho biết chủ đề chính của buổi thuyết trình và tên người/nhóm trình bày được gọi là trang «tiêu đề» (`Title Slide`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-2', 'k7-p21', 2, 'Nhận biết', 'Chức năng chính của phần mềm trình chiếu (như `Microsoft PowerPoint`) là gì?', '["Chỉ dùng để lập trình điều khiển robot", "Giúp tạo các trang chiếu (`Slides`) đa phương tiện và trình chiếu lên màn hình lớn phục vụ thuyết trình, báo cáo, giảng dạy", "Chỉ dùng để quét virus máy tính", "Chỉ dùng để nghe nhạc `.mp3`"]'::jsonb, 1, 'Phần mềm trình chiếu hỗ trợ biên tập các trang chiếu trực quan và trình chiếu (`Slide Show`) truyền tải thông tin trước đám đông.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-3', 'k7-p21', 3, 'Nhận biết', 'Trang chiếu đầu tiên của bài trình chiếu (có bố cục mặc định là `Title Slide`) có vai trò gì?', '["Trình bày bảng số liệu chi tiết 50 dòng", "Là Trang tiêu đề nhằm giới thiệu tên chủ đề của bài trình chiếu và tên người/nhóm thực hiện", "Là trang viết lời cảm ơn kết thúc", "Là trang nháp không hiển thị"]'::jsonb, 1, 'Trang tiêu đề (`Title Slide`) mở đầu bài thuyết trình, thu hút sự chú ý và giới thiệu tên đề tài cùng tác giả.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-4', 'k7-p21', 4, 'Thông hiểu', 'Tổ hợp phím tắt nào trong PowerPoint dùng để chèn thêm một trang chiếu mới (`New Slide`) vào bài trình chiếu hiện tại?', '["`Ctrl + N`", "`Ctrl + M`", "`Ctrl + S`", "`Ctrl + P`"]'::jsonb, 1, '`Ctrl + M` chèn thêm một trang chiếu mới (`New Slide`), trong khi `Ctrl + N` tạo một tệp bài trình chiếu mới hoàn toàn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-5', 'k7-p21', 5, 'Thông hiểu', 'Khi trình bày nội dung theo ''Cấu trúc phân cấp'' trên trang chiếu, các mục ở mức thấp hơn (mục con) được định dạng như thế nào so với mục ở mức cao hơn (mục cha)?', '["Viết sát lề trái hơn và cỡ chữ to hơn mục cha", "Thụt lề sâu hơn vào bên phải, dùng kí hiệu đầu dòng khác và có cỡ chữ nhỏ hơn mục cha", "Xóa hết chữ chỉ để lại dấu chấm", "Viết nối liền trên cùng 1 dòng với mục cha"]'::jsonb, 1, 'Trong cấu trúc phân cấp, cấp con lùi vào trong (`Indent`) và có cỡ chữ nhỏ hơn cấp cha để thể hiện rõ quan hệ bao hàm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-6', 'k7-p21', 6, 'Vận dụng', 'Để thay đổi bố cục khung chứa nội dung của trang chiếu hiện tại (ví dụ đổi từ 1 khung nội dung `Title and Content` sang 2 khung song song `Two Content`), em dùng nút lệnh nào trong nhóm `Slides` (thẻ `Home`)?', '["`New Slide`", "`Layout`", "`Reset`", "`Section`"]'::jsonb, 1, 'Nút `Layout` cho phép chọn lại mẫu bố cục khung văn bản/đối tượng cho trang chiếu đang chọn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-21-7', 'k7-p21', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.A3.2), tại sao việc lập dàn ý có cấu trúc phân cấp rõ ràng (Mục 1 -> 1.1, 1.2; Mục 2 -> 2.1, 2.2) lại rất hữu ích khi sử dụng các công cụ AI hỗ trợ tạo bài trình chiếu?', '["Vì AI chỉ hiểu được chữ viết tay", "Vì cấu trúc phân cấp giúp AI nhận diện chính xác đâu là tiêu đề trang chiếu (`Slide Title`), đâu là ý chính mức 1 và đâu là ý phụ mức 2 để phân bổ lên các trang chiếu tự động một cách mạch lạc", "Vì làm giảm số trang chiếu về 0", "Không có tác dụng gì"]'::jsonb, 1, 'Dàn ý phân cấp chuẩn (`Outline`) là đầu vào lí tưởng để các công cụ trình chiếu thông minh chuyển hóa thành từng slide.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-1', 'k7-p22', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong thẻ `Home` (nhóm `Paragraph`), nút lệnh `Increase List Level` (tương đương phím `Tab`) dùng để hạ cấp mục danh sách vào sâu một mức, còn nút [___] (tương đương `Shift + Tab`) dùng để nâng mục đó ra ngoài một mức."', '["Decrease List Level", "Design", "Esc", "Thẻ `Home` -> `New Slide` (`Ctrl + M`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Trong thẻ `Home` (nhóm `Paragraph`), nút lệnh `Increase List Level` (tương đương phím `Tab`) dùng để hạ cấp mục danh sách vào sâu một mức, còn nút «Decrease List Level» (tương đương `Shift + Tab`) dùng để nâng mục đó ra ngoài một mức.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-2', 'k7-p22', 2, 'Nhận biết', 'Trong bài thực hành tạo bài trình chiếu dự án ''Trường học xanh'' (SGK trang 56), để tạo các mục con lùi vào 1 cấp so với mục chính trên trang chiếu, em dùng nút lệnh nào trong nhóm `Paragraph` (thẻ `Home`)?', '["`Increase List Level` (hoặc nhấn phím `Tab` ở đầu dòng)", "`Decrease List Level`", "`Align Right`", "`Line Spacing`"]'::jsonb, 0, '`Increase List Level` tăng mức thụt lề danh sách, chuyển dòng hiện tại thành mục con cấp thấp hơn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-3', 'k7-p22', 3, 'Nhận biết', 'Để chọn một mẫu thiết kế giao diện có sẵn (`Themes`) giúp bài trình chiếu `TruongHocXanh.pptx` có màu sắc và phông chữ đẹp mắt, đồng bộ, em vào thẻ nào trên thanh Ribbon?', '["Thẻ `Insert`", "Thẻ `Design`", "Thẻ `Animations`", "Thẻ `Review`"]'::jsonb, 1, 'Nhóm lệnh `Themes` và `Variants` nằm trong thẻ `Design`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-4', 'k7-p22', 4, 'Thông hiểu', 'Khi muốn xóa một trang chiếu trống bị thừa ở ngăn danh sách trang chiếu bên trái, em nháy chuột phải vào trang chiếu đó và chọn lệnh nào?', '["`New Slide`", "`Duplicate Slide`", "`Delete Slide`", "`Hide Slide`"]'::jsonb, 2, 'Lệnh `Delete Slide` (hoặc nhấn phím `Delete`) xóa trang chiếu đang chọn khỏi bài trình chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-5', 'k7-p22', 5, 'Thông hiểu', 'Phím tắt nào trên bàn phím dùng để bắt đầu Trình chiếu toàn màn hình (`Slide Show`) từ trang chiếu đầu tiên?', '["Phím `F1`", "Phím `F2`", "Phím `F5`", "Phím `F12`"]'::jsonb, 2, 'Phím `F5` kích hoạt chế độ `Slide Show` bắt đầu từ Slide 1.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-6', 'k7-p22', 6, 'Vận dụng', 'Khi đang ở chế độ Trình chiếu toàn màn hình (`Slide Show`), nhấn phím nào giúp thoát ra ngay để quay về màn hình soạn thảo PowerPoint?', '["Phím `Tab`", "Phím `Esc`", "Phím `Shift`", "Phím `Caps Lock`"]'::jsonb, 1, 'Phím `Esc` (`Escape`) dùng để thoát khỏi chế độ trình chiếu toàn màn hình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-22-7', 'k7-p22', 7, 'Vận dụng', 'Phần mở rộng tên tệp mặc định khi lưu bài trình chiếu `TruongHocXanh` bằng phần mềm Microsoft PowerPoint là gì?', '["`.docx`", "`.xlsx`", "`.pptx`", "`.jpg`"]'::jsonb, 2, 'Tệp bài trình chiếu PowerPoint có phần mở rộng chuẩn là `.pptx`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-1', 'k7-p23', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để chèn một tệp hình ảnh có sẵn trong máy tính vào trang chiếu, ta vào thẻ `Insert` -> chọn `Pictures` -> chọn [___] (`This Device...`)."', '["Tệp từ máy tính", "Send to Back", "Ctrl + V", "`Bring to Front` & `Send to Back`"]'::jsonb, 0, 'Theo SGK Tin học 7: Để chèn một tệp hình ảnh có sẵn trong máy tính vào trang chiếu, ta vào thẻ `Insert` -> chọn `Pictures` -> chọn «Tệp từ máy tính» (`This Device...`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-2', 'k7-p23', 2, 'Nhận biết', 'Để chèn hình ảnh các loài cây hoa lưu trong thư mục dự án vào trang chiếu PowerPoint, em thực hiện thao tác nào?', '["Vào thẻ `Home` -> `New Slide`", "Vào thẻ `Insert` -> `Pictures` -> `This Device...` -> chọn tệp ảnh -> `Insert`", "Vào thẻ `Design` -> `Themes`", "Vào thẻ `Slide Show` -> `From Beginning`"]'::jsonb, 1, 'Lệnh `Insert` -> `Pictures` dùng để đưa tệp hình ảnh từ máy tính vào trang chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-3', 'k7-p23', 3, 'Nhận biết', 'Khi trên trang chiếu có một bức ảnh đang đè lên làm che khuất dòng chữ tiêu đề, thao tác nào giúp đưa dòng chữ nổi lên trên bức ảnh?', '["Nhấn phím `Delete` xóa dòng chữ", "Chọn bức ảnh -> vào thẻ `Picture Format` -> chọn `Send Backward` (`Send to Back`) để đẩy ảnh xuống lớp dưới (hoặc chọn khung chữ chọn `Bring to Front`)", "Đổi phông chữ thành Arial", "Nhấn phím `F5`"]'::jsonb, 1, 'Các đối tượng trên trang chiếu nằm trên các lớp (`Layers`) khác nhau; `Send to Back` đẩy ảnh xuống lớp dưới để chữ hiện lên trên.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-4', 'k7-p23', 4, 'Thông hiểu', 'Thao tác nào giúp thay đổi kích thước bức ảnh trên trang chiếu mà KHÔNG làm bức ảnh bị méo hay biến dạng tỉ lệ?', '["Kéo nút tròn ở chính giữa cạnh trên", "Kéo nút tròn ở chính giữa cạnh phải", "Kéo một trong 4 nút tròn ở 4 góc của khung viền bức ảnh", "Xoay ngược bức ảnh 180 độ"]'::jsonb, 2, 'Kéo ở 4 điểm góc bảo toàn tỉ lệ khung hình (`Aspect Ratio`) của bức ảnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-5', 'k7-p23', 5, 'Thông hiểu', 'Muốn đưa bảng ''Tổng hợp kinh phí dự án Trường học xanh'' đã làm bên Excel sang trang chiếu số 4 của bài trình chiếu PowerPoint, cách làm nào nhanh và chuẩn nhất?', '["Gõ lại từng con số bằng tay", "Mở tệp Excel, chọn vùng bảng cần lấy nhấn `Ctrl + C`, sau đó mở trang chiếu số 4 trong PowerPoint và nhấn `Ctrl + V`, rồi căn chỉnh kích thước bảng và cỡ chữ", "Không thể đưa bảng sang PowerPoint", "Đổi tên tệp Excel thành `.pptx`"]'::jsonb, 1, 'Các phần mềm trong bộ công cụ văn phòng (`Word`, `Excel`, `PowerPoint`) hỗ trợ sao chép và dán (`Ctrl+C / Ctrl+V`) bảng dữ liệu trực tiếp cho nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-6', 'k7-p23', 6, 'Vận dụng', 'Trong thẻ ngữ cảnh `Picture Format` (xuất hiện khi nháy chọn bức ảnh), công cụ `Crop` dùng để làm gì?', '["Tăng độ sáng màn hình", "Cắt bỏ những phần rìa thừa không cần thiết của bức ảnh để tập trung vào chủ thể chính", "Thêm âm thanh vào ảnh", "Sao chép ảnh sang trang khác"]'::jsonb, 1, 'Công cụ `Crop` giúp cắt gọn khung hình ảnh ngay trong PowerPoint.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-23-7', 'k7-p23', 7, 'Vận dụng', 'Khi chọn màu nền cho trang chiếu và màu chữ cho văn bản, nguyên tắc nào sau đây cần được tuân thủ?', '["Nền màu xanh đậm thì chữ cũng chọn màu xanh đậm", "Chọn màu chữ có độ tương phản cao với màu nền (nền sáng – chữ tối hoặc nền tối – chữ sáng) và giữ phông chữ thống nhất, dễ đọc", "Mỗi dòng chữ dùng một màu cầu vồng chói mắt", "Đặt bức ảnh nhiều màu sặc sỡ làm nền rồi viết chữ nhỏ đè lên"]'::jsonb, 1, 'Độ tương phản màu sắc cao và bố cục tách bạch giữa chữ và ảnh giúp khán giả theo dõi dễ dàng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-1', 'k7-p24', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Các hiệu ứng điều khiển cách thay đổi từ trang chiếu này sang trang chiếu kế tiếp nằm trong thẻ [___] (`Chuyển tiếp`)."', '["Transitions", "Animations", "None (Không có)", "Nguyên tắc sử dụng hiệu ứng sư phạm"]'::jsonb, 0, 'Theo SGK Tin học 7: Các hiệu ứng điều khiển cách thay đổi từ trang chiếu này sang trang chiếu kế tiếp nằm trong thẻ «Transitions» (`Chuyển tiếp`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-2', 'k7-p24', 2, 'Nhận biết', 'Để tạo hiệu ứng chuyển đổi nhẹ nhàng khi lật từ trang chiếu này sang trang chiếu tiếp theo trong bài trình chiếu, em vào thẻ nào trên thanh Ribbon?', '["Thẻ `Insert`", "Thẻ `Transitions`", "Thẻ `Animations`", "Thẻ `Review`"]'::jsonb, 1, 'Thẻ `Transitions` quản lí hiệu ứng chuyển tiếp giữa các trang chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-3', 'k7-p24', 3, 'Nhận biết', 'Để làm cho 3 bức ảnh các loài cây trên trang chiếu số 3 lần lượt xuất hiện từng ảnh một mỗi khi người thuyết trình nháy chuột giảng đến loài cây đó, em chọn từng bức ảnh và vào thẻ nào?', '["Thẻ `Transitions`", "Thẻ `Animations` (chọn hiệu ứng thuộc nhóm `Entrance` như `Fade` hoặc `Appear`)", "Thẻ `Design`", "Thẻ `File`"]'::jsonb, 1, 'Thẻ `Animations` dùng để gắn hiệu ứng chuyển động cho từng đối tượng cụ thể trên trang chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-4', 'k7-p24', 4, 'Thông hiểu', 'Một trang chiếu có thể được áp dụng tối đa bao nhiêu hiệu ứng chuyển trang (`Transition`) tại cùng một thời điểm?', '["Tối đa `1` hiệu ứng chuyển trang duy nhất cho mỗi trang chiếu", "10 hiệu ứng chuyển trang cùng lúc", "Không giới hạn", "Bắt buộc phải có 5 hiệu ứng"]'::jsonb, 0, 'Mỗi trang chiếu chỉ có 1 cách xuất hiện khi chuyển trang nên chỉ nhận 1 hiệu ứng `Transition`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-5', 'k7-p24', 5, 'Thông hiểu', 'Trong thẻ `Transitions`, nút lệnh `Apply To All` có tác dụng gì?', '["Xóa toàn bộ hiệu ứng của bài trình chiếu", "Áp dụng kiểu hiệu ứng chuyển trang đang chọn cho tất cả các trang chiếu trong bài trình chiếu để tạo sự đồng bộ, nhất quán", "Chuyển bài trình chiếu sang tệp Word", "Tắt âm thanh máy tính"]'::jsonb, 1, '`Apply To All` giúp đồng bộ một kiểu hiệu ứng chuyển trang thống nhất cho toàn bộ các slide.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-6', 'k7-p24', 6, 'Vận dụng', 'Muốn hủy bỏ hiệu ứng chuyển trang (`Transition`) hoặc hiệu ứng động (`Animation`) đã lỡ chọn cho một trang chiếu/đối tượng, em chọn trang chiếu/đối tượng đó rồi nháy vào ô nào trong danh sách hiệu ứng?', '["Ô `None` (nằm ở vị trí đầu tiên bên trái của bảng hiệu ứng)", "Ô `Random Bars`", "Ô `Bounce`", "Ô `Spin`"]'::jsonb, 0, 'Tùy chọn `None` gỡ bỏ hiệu ứng đã gắn và trả trang chiếu/đối tượng về trạng thái tĩnh bình thường.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-24-7', 'k7-p24', 7, 'Vận dụng', 'Cách sử dụng hiệu ứng nào sau đây trong bài báo cáo dự án ''Trường học xanh'' được đánh giá là HỢP LÍ và CHUYÊN NGHIỆP nhất?', '["Mỗi trang chiếu chọn một hiệu ứng nổ vỡ mảnh ghép kèm tiếng pháo tay thật to và cho từng chữ cái rơi xuống mất 20 giây", "Chọn 1 hiệu ứng chuyển trang nhẹ nhàng (như `Fade` hoặc `Push`) áp dụng thống nhất toàn bài, và dùng hiệu ứng xuất hiện (`Appear`/`Fade`) vừa phải để dẫn dắt từng ý chính theo lời thuyết trình", "Dùng toàn bộ hiệu ứng màu đỏ (`Exit`) làm các dòng chữ biến mất ngay khi vừa mở trang chiếu", "Cho tất cả các bức ảnh xoay tròn 360 độ liên tục"]'::jsonb, 1, 'Hiệu ứng tinh tế, nhanh gọn và nhất quán giúp tôn vinh nội dung và hỗ trợ nhịp điệu thuyết trình hiệu quả nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-1', 'k7-p25', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Thuật toán tìm kiếm [___] thực hiện tìm kiếm bằng cách so sánh lần lượt từ phần tử đầu tiên của danh sách cho đến khi tìm thấy giá trị cần tìm hoặc đến khi hết danh sách."', '["tuần tự", "mọi (bất kỳ)", "lặp", "Bước 1: Khởi tạo"]'::jsonb, 0, 'Theo SGK Tin học 7: Thuật toán tìm kiếm «tuần tự» thực hiện tìm kiếm bằng cách so sánh lần lượt từ phần tử đầu tiên của danh sách cho đến khi tìm thấy giá trị cần tìm hoặc đến khi hết danh sách.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-2', 'k7-p25', 2, 'Nhận biết', 'Ý tưởng chính của ''Thuật toán tìm kiếm tuần tự'' (`Sequential Search`) là gì?', '["Chia đôi danh sách ở vị trí chính giữa để tìm", "Xem xét và so sánh lần lượt từ phần tử đầu tiên của danh sách cho đến khi tìm thấy phần tử cần tìm hoặc đã xét hết danh sách", "Chỉ kiểm tra phần tử đầu tiên và phần tử cuối cùng", "Sắp xếp danh sách trước rồi mới nhìn phần tử ở giữa"]'::jsonb, 1, 'Tìm kiếm tuần tự duyệt từng phần tử một theo thứ tự từ đầu danh sách đến cuối danh sách.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-3', 'k7-p25', 3, 'Nhận biết', 'Thuật toán tìm kiếm tuần tự có yêu cầu danh sách đầu vào phải được sắp xếp theo thứ tự từ trước hay không?', '["Bắt buộc phải sắp xếp tăng dần", "Bắt buộc phải sắp xếp giảm dần", "Không yêu cầu; tìm kiếm tuần tự thực hiện được trên bất kỳ danh sách nào (đã sắp xếp hoặc chưa sắp xếp)", "Chỉ thực hiện được trên danh sách có 3 phần tử"]'::jsonb, 2, 'Vì xét lần lượt từng phần tử từ đầu đến cuối nên tìm kiếm tuần tự không đòi hỏi dữ liệu phải có thứ tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-4', 'k7-p25', 4, 'Thông hiểu', 'Cho danh sách tên 5 loài hoa: `(1) Cúc, (2) Hồng, (3) Đào, (4) Mai, (5) Lan`. Khi dùng thuật toán tìm kiếm tuần tự để tìm hoa `''Đào''`, thuật toán sẽ thực hiện bao nhiêu bước so sánh?', '["1 bước", "2 bước", "3 bước (so sánh lần lượt với Cúc -> Hồng -> Đào thì tìm thấy và dừng lại)", "5 bước"]'::jsonb, 2, 'Hoa `''Đào''` nằm ở vị trí thứ 3 nên thuật toán xét vị trí 1, vị trí 2 và đến vị trí 3 thì khớp và kết thúc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-5', 'k7-p25', 5, 'Thông hiểu', 'Cho dãy gồm 7 số: `14, 5, 21, 9, 33, 18, 7`. Nếu dùng thuật toán tìm kiếm tuần tự để tìm số `10`, thuật toán sẽ dừng lại khi nào và trả về kết quả gì?', '["Dừng ở vị trí 2 và báo Tìm thấy", "Sau khi đã so sánh hết cả 7 số (đến số `7` cuối cùng) và trả về thông báo `''Không tìm thấy''`", "Dừng ngay ở số `14` đầu tiên", "Không bao giờ dừng lại"]'::jsonb, 1, 'Vì số `10` không có trong dãy nên thuật toán phải duyệt hết cả 7 phần tử rồi báo `''Không tìm thấy''`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-6', 'k7-p25', 6, 'Vận dụng', 'Trong sơ đồ khối của thuật toán tìm kiếm tuần tự, hai cấu trúc điều khiển cơ bản nào được phối hợp với nhau?', '["Chỉ có cấu trúc tuần tự", "Cấu trúc lặp (lặp lại việc xét phần tử tiếp theo) và cấu trúc rẽ nhánh (kiểm tra đã tìm thấy chưa / đã hết danh sách chưa)", "Chỉ có cấu trúc vẽ hình", "Không dùng cấu trúc điều khiển nào"]'::jsonb, 1, 'Vòng lặp giúp duyệt qua các phần tử trong danh sách, còn rẽ nhánh kiểm tra điều kiện khớp giá trị và điều kiện kết thúc danh sách.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-25-7', 'k7-p25', 7, 'Vận dụng', 'Nếu một danh sách có `1000` phần tử, số lần so sánh TỐI ĐA mà thuật toán tìm kiếm tuần tự phải thực hiện trong trường hợp xấu nhất là bao nhiêu lần?', '["`10` lần", "`100` lần", "`500` lần", "`1000` lần"]'::jsonb, 3, 'Trong trường hợp phần tử cần tìm nằm ở vị trí thứ 1000 hoặc không có trong danh sách, tìm kiếm tuần tự phải thực hiện đủ 1000 lần so sánh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-1', 'k7-p26', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Điều kiện tiên quyết bắt buộc để có thể áp dụng thuật toán tìm kiếm nhị phân là danh sách dữ liệu phải được [___] theo thứ tự."', '["sắp xếp", "giữa", "phải (nửa sau)", "Giá trị cần tìm BẰNG phần tử ở giữa"]'::jsonb, 0, 'Theo SGK Tin học 7: Điều kiện tiên quyết bắt buộc để có thể áp dụng thuật toán tìm kiếm nhị phân là danh sách dữ liệu phải được «sắp xếp» theo thứ tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-2', 'k7-p26', 2, 'Nhận biết', 'Điều kiện BẮT BUỘC để có thể sử dụng được thuật toán tìm kiếm nhị phân (`Binary Search`) là gì?', '["Danh sách chỉ được chứa các số nhỏ hơn 10", "Danh sách dữ liệu đã được sắp xếp theo một thứ tự nhất định (tăng dần hoặc giảm dần)", "Danh sách phải có số lượng phần tử là số lẻ", "Danh sách không được lưu trong máy tính"]'::jsonb, 1, 'Tìm kiếm nhị phân dựa vào tính thứ tự của dữ liệu để loại bỏ một nửa vùng tìm kiếm sau mỗi lần so sánh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-3', 'k7-p26', 3, 'Nhận biết', 'Tại mỗi bước lặp của thuật toán tìm kiếm nhị phân, giá trị cần tìm được đem so sánh với phần tử nào của vùng tìm kiếm hiện hành?', '["Phần tử đầu tiên của vùng tìm kiếm", "Phần tử cuối cùng của vùng tìm kiếm", "Phần tử nằm ở vị trí chính giữa của vùng tìm kiếm", "Một phần tử bất kỳ ngẫu nhiên"]'::jsonb, 2, 'So sánh với phần tử ở giữa giúp chia đôi vùng tìm kiếm thành hai nửa bằng nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-4', 'k7-p26', 4, 'Thông hiểu', 'Cho dãy 9 số đã sắp xếp tăng dần: `(1) 3, (2) 6, (3) 10, (4) 15, (5) 21, (6) 28, (7) 36, (8) 45, (9) 55`. Để tìm số `36` bằng thuật toán tìm kiếm nhị phân, ở lần so sánh ĐẦU TIÊN thuật toán sẽ so sánh `36` với số nào?', '["Số `3` (vị trí 1)", "Số `21` (vị trí 5 - chính giữa của 9 phần tử)", "Số `55` (vị trí 9)", "Số `15` (vị trí 4)"]'::jsonb, 1, 'Dãy từ vị trí 1 đến 9 có vị trí chính giữa là `(1 + 9) / 2 = 5`, tương ứng với số `21`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-5', 'k7-p26', 5, 'Thông hiểu', 'Tiếp tục với câu trên: sau khi so sánh `36` với số `21` (ở vị trí 5) và thấy `36 > 21`, vùng tìm kiếm ở bước thứ hai sẽ thu hẹp về đoạn nào?', '["Từ vị trí 1 đến vị trí 4 (`3, 6, 10, 15`)", "Từ vị trí 6 đến vị trí 9 (`28, 36, 45, 55`)", "Giữ nguyên từ vị trí 1 đến 9", "Chỉ xét vị trí 5"]'::jsonb, 1, 'Vì dãy tăng dần và `36 > 21`, số `36` nếu có chắc chắn phải nằm ở nửa bên phải (từ vị trí 6 đến vị trí 9).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-6', 'k7-p26', 6, 'Vận dụng', 'Khi nào thì thuật toán tìm kiếm nhị phân kết thúc và thông báo `''Không tìm thấy''`?', '["Ngay sau lần so sánh đầu tiên", "Khi vùng tìm kiếm đã thu hẹp đến mức không còn phần tử nào (vị trí đầu vượt qua vị trí cuối) mà vẫn chưa tìm thấy giá trị cần tìm", "Khi tìm thấy phần tử ở giữa bằng giá trị cần tìm", "Sau đúng 100 bước"]'::jsonb, 1, 'Khi vùng tìm kiếm bị thu hẹp về rỗng mà chưa gặp phần tử khớp thì kết luận phần tử đó không tồn tại trong danh sách.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-26-7', 'k7-p26', 7, 'Vận dụng', 'Ưu điểm nổi bật nhất của thuật toán tìm kiếm nhị phân so với thuật toán tìm kiếm tuần tự trên một danh sách lớn đã sắp xếp là gì?', '["Không cần so sánh lần nào", "Số bước lặp (số lần so sánh) ít hơn rất nhiều nên tốc độ tìm kiếm nhanh vượt trội (với 1 triệu phần tử chỉ cần tối đa khoảng 20 lần so sánh)", "Thực hiện được trên danh sách lộn xộn", "Chỉ dùng phép cộng"]'::jsonb, 1, 'Nhờ giảm một nửa phạm vi sau mỗi bước, tìm kiếm nhị phân có tốc độ cực nhanh ($\log_2 N$ bước so với $N$ bước của tìm kiếm tuần tự).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-1', 'k7-p27', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Việc [___] dữ liệu theo một thứ tự nhất định (như thứ tự bảng chữ cái hoặc thứ tự số tăng dần) là điều kiện bắt buộc để có thể áp dụng thuật toán tìm kiếm nhị phân."', '["sắp xếp", "lớn", "Sort (Sắp xếp)", "Danh sách chưa được sắp xếp"]'::jsonb, 0, 'Theo SGK Tin học 7: Việc «sắp xếp» dữ liệu theo một thứ tự nhất định (như thứ tự bảng chữ cái hoặc thứ tự số tăng dần) là điều kiện bắt buộc để có thể áp dụng thuật toán tìm kiếm nhị phân.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-2', 'k7-p27', 2, 'Nhận biết', 'Mối liên hệ quan trọng nhất giữa ''Sắp xếp'' và ''Tìm kiếm'' trong tin học là gì?', '["Sắp xếp làm cho việc tìm kiếm trở nên chậm hơn", "Sắp xếp dữ liệu theo thứ tự là bước chuẩn bị cần thiết để có thể áp dụng thuật toán tìm kiếm nhị phân giúp tăng tốc độ tìm kiếm lên rất nhiều lần", "Sắp xếp và tìm kiếm hoàn toàn không liên quan gì đến nhau", "Đã sắp xếp rồi thì không được phép tìm kiếm nữa"]'::jsonb, 1, 'Dữ liệu được sắp xếp có thứ tự cho phép áp dụng thuật toán tìm kiếm nhị phân thay vì phải tìm tuần tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-3', 'k7-p27', 3, 'Nhận biết', 'Trong tình huống thực tế nào sau đây, con người đang vận dụng trực tiếp mối liên hệ giữa Sắp xếp và Tìm kiếm nhị phân?', '["Bỏ tất cả sách vở các môn lẫn lộn vào một chiếc thùng lớn", "Sắp xếp hồ sơ học sinh theo thứ tự bảng chữ cái A -> Z vào tủ hồ sơ để mỗi khi cần rút hồ sơ của học sinh nào có thể mở đúng ngăn chữ cái và tìm thấy ngay", "Đọc một cuốn truyện tiểu thuyết từ trang đầu đến trang cuối", "Ghi nhật ký cá nhân hàng ngày"]'::jsonb, 1, 'Xếp hồ sơ theo thứ tự A -> Z chính là bước sắp xếp để phục vụ việc tra cứu nhanh theo nguyên lí chia khoảng nhị phân.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-4', 'k7-p27', 4, 'Thông hiểu', 'Cho danh sách giá tiền (nghìn đồng) của 7 loại cây đã sắp xếp tăng dần: `(1) 10, (2) 15, (3) 20, (4) 25, (5) 30, (6) 40, (7) 50`. Nếu dùng tìm kiếm nhị phân để tìm loại cây có giá `15`, thuật toán sẽ duyệt qua các vị trí nào?', '["Vị trí 1 -> Vị trí 2", "Bước 1 xét vị trí 4 (giá `25`), vì `15 < 25` nên xét nửa đầu từ vị trí 1 đến 3; Bước 2 xét vị trí 2 (giá `15`) -> Tìm thấy!", "Vị trí 7 -> Vị trí 6 -> Vị trí 2", "Chỉ xét vị trí 1"]'::jsonb, 1, 'Vị trí giữa của `1..7` là `4` (`25`); do `15 < 25` nên thu hẹp về `1..3`, vị trí giữa của `1..3` là `2` (`15`) -> Khớp!'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-5', 'k7-p27', 5, 'Thông hiểu', 'Vẫn với danh sách giá tiền `(1) 10, (2) 15, (3) 20, (4) 25, (5) 30, (6) 40, (7) 50`, nếu dùng tìm kiếm nhị phân để tìm mức giá `35` (không có trong danh sách), thuật toán cần mấy lần so sánh để kết luận `''Không tìm thấy''`?', '["`7` lần so sánh", "`3` lần so sánh (xét vị trí 4: `25` -> xét vị trí 6: `40` -> xét vị trí 5: `30` -> vùng tìm kiếm rỗng và dừng)", "`1` lần so sánh", "`10` lần so sánh"]'::jsonb, 1, 'Với 7 phần tử ($2^3 - 1 = 7$), tìm kiếm nhị phân chỉ cần tối đa 3 lần so sánh là kết luận được có hay không.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-6', 'k7-p27', 6, 'Vận dụng', 'Khi làm việc với bảng dữ liệu dài hàng nghìn dòng trên phần mềm bảng tính Excel, công cụ nào giúp ta sắp xếp danh sách từ A -> Z trước khi tra cứu?', '["Công cụ `Sort` (trong thẻ `Data` hoặc thẻ `Home`)", "Công cụ `Merge & Center`", "Công cụ `Wrap Text`", "Công cụ `Borders`"]'::jsonb, 0, 'Công cụ `Sort` sắp xếp bảng dữ liệu theo thứ tự tăng dần hoặc giảm dần.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-27-7', 'k7-p27', 7, 'Vận dụng', 'Theo Khung năng lực AI (7.C2.7), tại sao các hệ thống cơ sở dữ liệu lớn và công cụ tìm kiếm AI luôn thực hiện ''Đánh chỉ mục và sắp xếp dữ liệu (`Indexing & Sorting`)'' trước khi phục vụ người dùng?', '["Để làm tốn bộ nhớ máy chủ", "Để khi hàng triệu người dùng gửi câu hỏi cùng lúc, hệ thống có thể tìm kiếm nhị phân trên chỉ mục đã sắp xếp và trả về kết quả chỉ trong vài phần nghìn giây", "Để xóa dữ liệu của người dùng", "Vì AI không biết đọc chữ"]'::jsonb, 1, 'Sắp xếp và đánh chỉ mục là bí quyết giúp các công cụ tìm kiếm và AI truy xuất tri thức tức thời.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-1', 'k7-p28', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Thuật toán sắp xếp [___] (`Bubble Sort`) thực hiện sắp xếp dãy số bằng cách lặp đi lặp lại việc xét từng cặp hai phần tử liền kề và đổi chỗ chúng nếu chúng đang đứng sai thứ tự."', '["nổi bọt", "đổi (hoán đổi)", "lớn", "Thao tác cơ sở trong Sắp xếp nổi bọt"]'::jsonb, 0, 'Theo SGK Tin học 7: Thuật toán sắp xếp «nổi bọt» (`Bubble Sort`) thực hiện sắp xếp dãy số bằng cách lặp đi lặp lại việc xét từng cặp hai phần tử liền kề và đổi chỗ chúng nếu chúng đang đứng sai thứ tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-2', 'k7-p28', 2, 'Nhận biết', 'Nguyên lí hoạt động đặc trưng của ''Thuật toán sắp xếp nổi bọt'' (`Bubble Sort`) là gì?', '["Chia đôi dãy số ở vị trí chính giữa", "Lặp lại việc xét từng cặp hai phần tử đứng liền kề nhau và đổi chỗ chúng nếu chúng đang đứng sai thứ tự", "Xóa bỏ tất cả các số lẻ trong dãy", "Cộng dồn tất cả các số vào phần tử đầu tiên"]'::jsonb, 1, 'So sánh và hoán đổi hai phần tử liền kề (`Adjacent elements`) khi ngược thứ tự là cơ chế cốt lõi của sắp xếp nổi bọt.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-3', 'k7-p28', 3, 'Nhận biết', 'Khi sử dụng thuật toán sắp xếp nổi bọt để sắp xếp dãy số theo thứ tự TĂNG DẦN (từ nhỏ đến lớn), khi xét hai phần tử liền kề `A` (đứng trước) và `B` (đứng sau), ta thực hiện đổi chỗ `A` và `B` khi nào?', '["Khi `A < B`", "Khi `A = B`", "Khi `A > B` (phần tử đứng trước lớn hơn phần tử đứng sau)", "Luôn luôn đổi chỗ mọi cặp"]'::jsonb, 2, 'Sắp xếp tăng dần yêu cầu số nhỏ đứng trước, số lớn đứng sau; nên nếu `A > B` (sai thứ tự) thì phải đổi chỗ `A` và `B`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-4', 'k7-p28', 4, 'Thông hiểu', 'Cho dãy 4 số: `8, 3, 6, 5`. Thực hiện thuật toán sắp xếp nổi bọt (duyệt từ trái sang phải để xếp tăng dần), ngay sau lần so sánh và đổi chỗ cặp ĐẦU TIÊN `(8, 3)`, dãy số trở thành gì?', '["`8, 3, 6, 5`", "`3, 8, 6, 5`", "`3, 6, 5, 8`", "`3, 5, 6, 8`"]'::jsonb, 1, 'Ở bước đầu tiên, so sánh hai phần tử kề nhau đầu dãy là `8` và `3`; vì `8 > 3` nên đổi chỗ thành `3, 8, 6, 5`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-5', 'k7-p28', 5, 'Thông hiểu', 'Vẫn với dãy `8, 3, 6, 5`, sau khi hoàn thành trọn vẹn LƯỢT DUYỆT THỨ NHẤT từ đầu đến cuối dãy, trạng thái của dãy số là gì?', '["`8, 3, 6, 5`", "`3, 6, 5, 8` (số `8` lần lượt đổi chỗ qua `3`, `6`, `5` để về đứng ở cuối dãy)", "`3, 5, 6, 8`", "`5, 6, 3, 8`"]'::jsonb, 1, 'Trong lượt 1: `(8,3) -> 3,8,6,5`; tiếp theo `(8,6) -> 3,6,8,5`; tiếp theo `(8,5) -> 3,6,5,8`. Số lớn nhất `8` đã về cuối dãy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-6', 'k7-p28', 6, 'Vận dụng', 'Trong quá trình chạy thuật toán sắp xếp nổi bọt, dấu hiệu nào cho phép thuật toán DỪNG SỚM ngay lập tức vì biết chắc chắn dãy số đã được sắp xếp xong?', '["Khi mới đổi chỗ được 1 cặp", "Khi thực hiện cả một lượt duyệt từ đầu đến cuối phần chưa sắp xếp mà KHÔNG xảy ra bất kỳ lần đổi chỗ nào", "Khi gặp một số chẵn", "Khi phần tử đầu tiên bằng 0"]'::jsonb, 1, 'Nếu duyệt qua mọi cặp liền kề mà không có cặp nào sai thứ tự (không cần đổi chỗ lần nào), nghĩa là toàn bộ dãy đã hoàn toàn đúng thứ tự.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-28-7', 'k7-p28', 7, 'Vận dụng', 'Nếu muốn dùng thuật toán sắp xếp nổi bọt để sắp xếp dãy số theo thứ tự GIẢM DẦN (từ lớn xuống nhỏ), điều kiện để đổi chỗ hai phần tử liền kề `A` (đứng trước) và `B` (đứng sau) sẽ là gì?', '["Đổi chỗ khi `A < B` (số đứng trước nhỏ hơn số đứng sau)", "Đổi chỗ khi `A > B`", "Đổi chỗ khi `A = B`", "Không bao giờ đổi chỗ"]'::jsonb, 0, 'Khi xếp giảm dần, số lớn phải đứng trước số nhỏ; do đó nếu số đứng trước nhỏ hơn số đứng sau (`A < B`) thì đổi chỗ chúng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-1', 'k7-p29', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Thuật toán sắp xếp [___] (`Selection Sort`) thực hiện sắp xếp tăng dần bằng cách: ở mỗi bước, chọn phần tử nhỏ nhất trong phần dãy chưa được sắp xếp và đổi chỗ nó về vị trí đầu tiên của phần dãy đó."', '["chọn", "N - 1", "lớn", "Lượt thứ hai (Xét từ vị trí 2 đến vị trí `N`)"]'::jsonb, 0, 'Theo SGK Tin học 7: Thuật toán sắp xếp «chọn» (`Selection Sort`) thực hiện sắp xếp tăng dần bằng cách: ở mỗi bước, chọn phần tử nhỏ nhất trong phần dãy chưa được sắp xếp và đổi chỗ nó về vị trí đầu tiên của phần dãy đó.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-2', 'k7-p29', 2, 'Nhận biết', 'Ý tưởng cốt lõi của ''Thuật toán sắp xếp chọn'' (`Selection Sort` - khi sắp xếp tăng dần) là gì?', '["Chỉ đổi chỗ phần tử đầu tiên với phần tử cuối cùng 1 lần duy nhất", "Ở lượt thứ nhất, tìm phần tử nhỏ nhất trong cả dãy đổi chỗ về vị trí 1; ở lượt thứ hai, tìm phần tử nhỏ nhất trong phần còn lại (từ vị trí 2 đến cuối) đổi chỗ về vị trí 2; tiếp tục cho đến khi dãy được sắp xếp xong", "Chia đôi dãy số để loại bỏ một nửa", "So sánh từng cặp liền kề và đổi chỗ liên tục"]'::jsonb, 1, 'Sắp xếp chọn (`Selection Sort`) lần lượt ''chọn'' phần tử nhỏ nhất trong vùng chưa sắp xếp để đưa về đúng vị trí đầu của vùng đó.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-3', 'k7-p29', 3, 'Nhận biết', 'Cho dãy 5 số: `25, 12, 30, 8, 19`. Khi thực hiện thuật toán sắp xếp chọn (`Selection Sort`) để xếp tăng dần, kết thúc LƯỢT THỨ NHẤT, hai số nào được đổi chỗ cho nhau và dãy số trở thành gì?', '["Đổi chỗ `25` và `12` -> `12, 25, 30, 8, 19`", "Tìm thấy số nhỏ nhất cả dãy là `8` (ở vị trí 4), đổi chỗ `8` với số đầu tiên `25` (ở vị trí 1) -> dãy thành `8, 12, 30, 25, 19`", "Đổi chỗ `30` và `8` -> `25, 12, 8, 30, 19`", "Đổi chỗ `25` và `19` -> `19, 12, 30, 8, 25`"]'::jsonb, 1, 'Trong lượt 1 của sắp xếp chọn, số nhỏ nhất toàn dãy là `8` được chọn và đổi chỗ trực tiếp với phần tử ở vị trí số 1 (`25`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-4', 'k7-p29', 4, 'Thông hiểu', 'Tiếp tục với dãy `8, 12, 30, 25, 19` sau lượt 1 ở câu trên: sang LƯỢT THỨ HAI (xét từ vị trí 2 đến vị trí 5: `12, 30, 25, 19`), thuật toán sắp xếp chọn sẽ làm gì?', '["Tìm thấy số nhỏ nhất trong phần còn lại là `12` đang đứng đúng ở vị trí số 2 nên giữ nguyên vị trí 2", "Đổi chỗ `8` với `12`", "Đổi chỗ `30` với `25`", "Xóa số `12` đi"]'::jsonb, 0, 'Trong vùng từ vị trí 2 đến 5 (`12, 30, 25, 19`), số nhỏ nhất chính là `12` đã nằm sẵn ở vị trí 2 nên không cần hoán đổi.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-5', 'k7-p29', 5, 'Thông hiểu', 'Tiếp tục sang LƯỢT THỨ BA (xét từ vị trí 3 đến vị trí 5 của dãy `8, 12, 30, 25, 19`, tức là xét `30, 25, 19`), hai số nào sẽ được đổi chỗ cho nhau?', '["Đổi chỗ `30` và `25`", "Số nhỏ nhất trong `(30, 25, 19)` là `19`, nên đổi chỗ `19` với phần tử ở vị trí 3 là `30` -> dãy thành `8, 12, 19, 25, 30`", "Đổi chỗ `12` và `19`", "Không đổi chỗ số nào"]'::jsonb, 1, 'Trong vùng `30, 25, 19`, phần tử nhỏ nhất là `19` được đưa về vị trí số 3 (đổi chỗ với `30`), tạo thành dãy `8, 12, 19, 25, 30`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-6', 'k7-p29', 6, 'Vận dụng', 'Để sắp xếp một dãy gồm `N` phần tử bằng thuật toán sắp xếp chọn, ta cần thực hiện tối đa bao nhiêu lượt chọn phần tử nhỏ nhất?', '["`N - 1` lượt (vì sau khi `N - 1` phần tử nhỏ hơn đã về đúng `N - 1` vị trí đầu, thì phần tử cuối cùng thứ `N` tự khắc là phần tử lớn nhất nằm ở vị trí cuối)", "`N + 5` lượt", "`1` lượt duy nhất", "`2 * N` lượt"]'::jsonb, 0, 'Sau `N - 1` lượt đặt đúng `N - 1` vị trí đầu tiên, phần tử còn lại duy nhất ở vị trí thứ `N` đương nhiên đã đứng đúng chỗ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-7-29-7', 'k7-p29', 7, 'Vận dụng', 'Theo SGK Tin học 7 (Bài 16 mục 3) và Khung năng lực AI (7.A2.5), việc giải bài toán sắp xếp dãy số thông qua việc lặp lại bài toán con ''Tìm số nhỏ nhất và đổi chỗ lên đầu'' thể hiện phương pháp tư duy khoa học nào?', '["Làm rối bài toán lên", "Chia một bài toán lớn phức tạp thành những bài toán nhỏ hơn, đơn giản hơn để dễ giải quyết (`Decomposition`)", "Bỏ qua không giải quyết vấn đề", "Đoán mò kết quả"]'::jsonb, 1, 'Phân rã bài toán lớn thành các bài toán con đơn giản là nguyên tắc vàng trong thiết kế thuật toán, lập trình và xây dựng dự án thực tế.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-1-1', 'k8-p01', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Năm 1642, nhà bác học Pháp Blaise Pascal đã chế tạo chiếc máy tính cơ học [___] giúp cha tính thuế."', '["Pascaline", "Charles Babbage", "John von Neumann", "Thế hệ thứ nhất (1945–1955)"]'::jsonb, 0, 'Theo SGK Tin học 8: Năm 1642, nhà bác học Pháp Blaise Pascal đã chế tạo chiếc máy tính cơ học «Pascaline» giúp cha tính thuế.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-1-2', 'k8-p01', 2, 'Nhận biết', 'Ai đã sáng chế ra máy tính cơ học Pascaline năm 1642?', '["Charles Babbage", "Blaise Pascal", "Gottfried Leibniz", "John von Neumann"]'::jsonb, 1, 'Năm 1642, Blaise Pascal (19 tuổi) chế tạo máy tính cơ học Pascaline giúp cha tính thuế.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-1-3', 'k8-p01', 3, 'Nhận biết', 'Máy tính cơ học thực hiện phép tính dựa trên cơ chế nào?', '["Bóng bán dẫn", "Các bánh răng truyền chuyển động ăn khớp", "Mạch tích hợp VLSI", "Đèn chân không"]'::jsonb, 1, 'Máy tính cơ học hoạt động thuần túy nhờ sự quay và ăn khớp của các bánh răng cơ khí.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-1-4', 'k8-p01', 4, 'Thông hiểu', 'Vì sao Charles Babbage được gọi là ''cha đẻ của công nghệ máy tính''?', '["Vì chế tạo điện thoại thông minh", "Vì phát minh bóng bán dẫn", "Vì đề xuất thiết kế máy tính đa năng tự động theo chương trình có cấu trúc như máy tính hiện đại", "Vì sáng lập mạng Internet"]'::jsonb, 2, 'Thiết kế Analytical Engine (1833) của Babbage đặt nền móng cho máy tính đa năng điều khiển bằng chương trình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
