  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-1', 'k8-p18', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "[___] (`Template`) là bài trình chiếu mẫu đã được thiết kế sẵn cả giao diện đồ họa lẫn bố cục gợi ý nội dung cho một chủ đề cụ thể."', '["Bản mẫu", "Link", "Place in This Document", "`File` -> `New` -> Chọn `Template`"]'::jsonb, 0, 'Theo SGK Tin học 8: «Bản mẫu» (`Template`) là bài trình chiếu mẫu đã được thiết kế sẵn cả giao diện đồ họa lẫn bố cục gợi ý nội dung cho một chủ đề cụ thể.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-2', 'k8-p18', 2, 'Nhận biết', 'Lợi ích chính của việc sử dụng Bản mẫu (`Template`) khi tạo bài trình chiếu là gì?', '["Tăng dung lượng ổ cứng", "Tiết kiệm thời gian thiết kế, đảm bảo tính thẩm mỹ chuyên nghiệp và có sẵn bố cục gợi ý theo chủ đề", "Tự động dịch sang tiếng Nhật", "Không cần người thuyết trình"]'::jsonb, 1, '`Template` cung cấp sẵn bộ khung đồ họa và bố cục nội dung chuẩn mực giúp tiết kiệm tối đa thời gian.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-3', 'k8-p18', 3, 'Nhận biết', 'Để tìm và mở một bản mẫu (`Template`) có sẵn trong PowerPoint, em vào đâu?', '["Vào `File` -> `New` -> chọn chủ đề (như `Education`) hoặc tìm tên bản mẫu", "Vào `Review` -> `Check Accessibility`", "Vào `View` -> `Notes Page`", "Nhấn `Ctrl + P`"]'::jsonb, 0, 'Màn hình `File` -> `New` hiển thị kho bản mẫu (`Templates`) theo từng lĩnh vực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-4', 'k8-p18', 4, 'Thông hiểu', 'Phím tắt chuẩn để mở hộp thoại chèn siêu liên kết (`Insert Hyperlink`) là gì?', '["`Ctrl + C`", "`Ctrl + K`", "`Ctrl + M`", "`Ctrl + D`"]'::jsonb, 1, '`Ctrl + K` là phím tắt mở hộp thoại `Insert Hyperlink` trong bộ công cụ Office.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-5', 'k8-p18', 5, 'Thông hiểu', 'Muốn tạo nút bấm trên Slide 2 để khi nháy chuột sẽ nhảy thẳng tới Slide 5 trong cùng bài trình chiếu, em chọn mục nào trong `Insert Hyperlink`?', '["`Existing File or Web Page`", "`Place in This Document` -> chọn `Slide 5`", "`Create New Document`", "`E-mail Address`"]'::jsonb, 1, '`Place in This Document` dùng để liên kết tới các trang chiếu nằm ngay trong tệp hiện hành.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-6', 'k8-p18', 6, 'Vận dụng', 'Muốn gắn liên kết để khi nháy chuột vào hình ảnh sẽ mở một tệp video `.mp4` lưu trên máy tính, em chọn mục nào trong `Insert Hyperlink`?', '["`Existing File or Web Page` -> chọn tệp video", "`Place in This Document`", "`E-mail Address`", "`Remove Link`"]'::jsonb, 0, '`Existing File or Web Page` cho phép trỏ đường dẫn tới tệp bất kỳ trên máy tính hoặc địa chỉ web.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-18-7', 'k8-p18', 7, 'Vận dụng', 'Phần mở rộng mặc định của tệp Bản mẫu PowerPoint (`PowerPoint Template`) là gì?', '["`.docx`", "`.xlsx`", "`.potx`", "`.pdf`"]'::jsonb, 2, 'Tệp bản mẫu PowerPoint có phần mở rộng chuẩn là `.potx`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-1', 'k8-p19', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để nhân bản một trang chiếu có sẵn trong bản mẫu (giữ nguyên toàn bộ bố cục đồ họa), ta nháy chuột phải vào trang đó và chọn [___]."', '["Duplicate Slide", "Edit Link", "cùng", "`Duplicate Slide`"]'::jsonb, 0, 'Theo SGK Tin học 8: Để nhân bản một trang chiếu có sẵn trong bản mẫu (giữ nguyên toàn bộ bố cục đồ họa), ta nháy chuột phải vào trang đó và chọn «Duplicate Slide».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-2', 'k8-p19', 2, 'Nhận biết', 'Thao tác nào giúp thay thế bức ảnh có sẵn trong bản mẫu (`Template`) bằng ảnh của em mà VẪN GIỮ NGUYÊN khung hình và hiệu ứng của bản mẫu?', '["Xóa ảnh mẫu rồi vẽ hình tròn", "Nháy chuột phải vào ảnh mẫu -> chọn `Change Picture` -> chọn ảnh mới", "Vào `Transitions`", "Nhấn `Ctrl + Z`"]'::jsonb, 1, '`Change Picture` chỉ thay nguồn ảnh bên trong và giữ nguyên 100% định dạng khung của bản mẫu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-3', 'k8-p19', 3, 'Nhận biết', 'Muốn gỡ bỏ siêu liên kết khỏi một dòng chữ (giữ nguyên chữ), em nháy chuột phải vào đó và chọn lệnh nào?', '["`Delete Slide`", "`Cut`", "`Remove Link` (hoặc `Remove Hyperlink`)", "`Duplicate`"]'::jsonb, 2, '`Remove Link` xóa đường dẫn liên kết nhưng giữ nguyên văn bản hoặc hình ảnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-4', 'k8-p19', 4, 'Thông hiểu', 'Vì sao khi chỉ chép mỗi tệp `.pptx` vào USB mang đến lớp mà quên chép tệp `Video.mp4` đi kèm thì siêu liên kết mở video lại báo lỗi?', '["Vì máy ở lớp hỏng màn hình", "Vì `Hyperlink` chỉ lưu đường dẫn trỏ tới tệp `Video.mp4` bên ngoài; không có tệp video đi kèm trong cùng thư mục thì không thể mở được", "Vì chưa đánh số trang", "Vì dùng phông chữ Calibri"]'::jsonb, 1, 'Siêu liên kết gọi tệp bên ngoài theo đường dẫn nên bắt buộc phải sao chép kèm tệp đích trong cùng thư mục.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-5', 'k8-p19', 5, 'Thông hiểu', 'Khi đang chiếu bài (`Slide Show`), con trỏ chuột biến thành hình gì khi trỏ vào nút bấm có gắn `Hyperlink`?', '["Hình mũi tên hai đầu", "Hình bàn tay", "Hình đồng hồ cát", "Hình dấu cộng"]'::jsonb, 1, 'Biểu tượng bàn tay cho biết đối tượng có thể nháy chuột để kích hoạt liên kết.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-6', 'k8-p19', 6, 'Vận dụng', 'Để tạo thêm một trang chiếu mới giống hệt bố cục đồ họa của trang chiếu số 3 trong bản mẫu, em chọn lệnh nào?', '["Nháy chuột phải vào Slide 3 -> chọn `Duplicate Slide`", "Nhấn `Ctrl + N`", "Vào `File` -> `Close`", "Chọn `Remove Header`"]'::jsonb, 0, '`Duplicate Slide` nhân bản toàn bộ thiết kế của trang chiếu đang chọn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-19-7', 'k8-p19', 7, 'Vận dụng', 'Khi lưu bài trình chiếu thành bản mẫu dùng chung, em chọn định dạng nào tại mục `Save as type`?', '["`.docx`", "`PowerPoint Template (*.potx)`", "`.xlsx`", "`.txt`"]'::jsonb, 1, 'Định dạng `.potx` là định dạng chuẩn của Bản mẫu PowerPoint.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-1', 'k8-p20', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "[___] là dãy hữu hạn các thao tác được sắp xếp theo trình tự xác định để giải quyết một bài toán."', '["Thuật toán", "Chương trình", "Bút vẽ", "Bước: ''Bắt đầu khi nháy chuột vào cờ xanh''"]'::jsonb, 0, 'Theo SGK Tin học 8: «Thuật toán» là dãy hữu hạn các thao tác được sắp xếp theo trình tự xác định để giải quyết một bài toán.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-2', 'k8-p20', 2, 'Nhận biết', 'Khái niệm ''Chương trình máy tính'' được hiểu đúng nhất là gì?', '["Các thiết bị phần cứng máy tính", "Dãy các câu lệnh mà máy tính có thể hiểu và thực hiện được để triển khai một thuật toán", "Bản vẽ tay trên giấy", "Trình duyệt xem video"]'::jsonb, 1, 'Chương trình là dãy các lệnh điều khiển máy tính thực hiện thuật toán.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-3', 'k8-p20', 3, 'Nhận biết', 'Trong Scratch, hai khối lệnh `di chuyển (100) bước` và `xoay phải (120) độ` thuộc nhóm lệnh nào?', '["Nhóm `Hiển thị` (`Looks`)", "Nhóm `Chuyển động` (`Motion`)", "Nhóm `Âm thanh` (`Sound`)", "Nhóm `Cảm biến` (`Sensing`)"]'::jsonb, 1, 'Các lệnh thay đổi vị trí và hướng của nhân vật thuộc nhóm `Chuyển động` (`Motion` - màu xanh dương).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-4', 'k8-p20', 4, 'Thông hiểu', 'Khi chuyển thuật toán vẽ hình vuông cạnh 100 bước sang chương trình Scratch dùng `lặp lại (4)`, hai lệnh bên trong vòng lặp là gì?', '["`di chuyển (100) bước` và `xoay phải (90) độ`", "`di chuyển (4) bước` và `xoay phải (100) độ`", "`di chuyển (90) bước` và `xoay phải (60) độ`", "`nhấc bút` và `xóa tất cả`"]'::jsonb, 0, 'Hình vuông có 4 cạnh bằng 100 bước và góc quay tại mỗi đỉnh là `360 / 4 = 90` độ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-5', 'k8-p20', 5, 'Thông hiểu', 'Khối lệnh nào trong nhóm `Bút vẽ` (`Pen`) dùng để xóa sạch các nét vẽ cũ trên sân khấu?', '["`đặt bút`", "`nhấc bút`", "`xóa tất cả` (`erase all`)", "`đặt màu bút`"]'::jsonb, 2, 'Lệnh `xóa tất cả` làm sạch toàn bộ nét mực vẽ trên sân khấu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-6', 'k8-p20', 6, 'Vận dụng', 'Các khối lệnh ghép nối tiếp nhau từ trên xuống dưới trong Scratch sẽ được thực hiện theo thứ tự nào?', '["Ngẫu nhiên", "Tuần tự từ khối lệnh trên xuống khối lệnh dưới", "Từ dưới ngược lên trên", "Chỉ thực hiện lệnh cuối cùng"]'::jsonb, 1, 'Máy tính thực thi các câu lệnh tuần tự từ trên xuống dưới theo đúng trình tự ghép nối.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-20-7', 'k8-p20', 7, 'Vận dụng', 'Để vẽ hình lục giác đều (6 cạnh bằng nhau), trong vòng lặp `lặp lại (6)` cần đặt góc xoay bằng bao nhiêu độ?', '["`45` độ", "`60` độ (`360 / 6`)", "`90` độ", "`120` độ"]'::jsonb, 1, 'Góc quay ngoài của đa giác đều 6 cạnh bằng `360 / 6 = 60` độ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-21-1', 'k8-p21', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để thêm nhóm lệnh `Bút vẽ` (`Pen`), ta nháy nút [___] (`Add Extension`) ở góc dưới bên trái giao diện Scratch."', '["Thêm phần mở rộng", "nhấc bút", "120", "`đặt bút` (`pen down`)"]'::jsonb, 0, 'Theo SGK Tin học 8: Để thêm nhóm lệnh `Bút vẽ` (`Pen`), ta nháy nút «Thêm phần mở rộng» (`Add Extension`) ở góc dưới bên trái giao diện Scratch.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-21-2', 'k8-p21', 2, 'Nhận biết', 'Vì sao nên đặt các lệnh `xóa tất cả`, `đi tới điểm x:0 y:0`, `đặt hướng bằng 90` ở ngay đầu chương trình vẽ hình?', '["Để xóa nhân vật", "Để thiết lập lại trạng thái xuất phát chuẩn giúp mỗi lần bấm cờ xanh chạy lại đều vẽ đúng vị trí", "Để tắt âm thanh", "Để đóng phần mềm"]'::jsonb, 1, 'Khởi tạo trạng thái ban đầu giúp xóa nét vẽ cũ và đưa nhân vật về đúng vị trí, hướng nhìn chuẩn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-21-3', 'k8-p21', 3, 'Nhận biết', 'Nếu nhân vật đang ở `(x: 120, y: 80)` và đang `đặt bút`, khi gọi lệnh `đi tới điểm x:0 y:0` mà quên `nhấc bút` thì điều gì xảy ra?', '["Nhân vật đứng yên", "Nhân vật về tâm `(0, 0)` và vẽ luôn một vạch thẳng nối từ `(120, 80)` về `(0, 0)`", "Sân khấu tự xóa sạch", "Chương trình dừng lại"]'::jsonb, 1, 'Khi bút đang hạ, mọi di chuyển của nhân vật đều tạo ra nét vẽ trên sân khấu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
