) VALUES (
  'rq-8-21-4', 'k8-p21', 4, 'Thông hiểu', 'Muốn nét mực vẽ trên sân khấu dày hơn, em dùng khối lệnh nào trong nhóm `Bút vẽ` (`Pen`)?', '["`đặt kích thước bút vẽ bằng (...)`", "`đặt kích thước bằng (...)%` trong nhóm `Hiển thị`", "`di chuyển (...) bước`", "`đợi (...) giây`"]'::jsonb, 0, 'Khối lệnh `đặt kích thước bút vẽ bằng (...)` điều chỉnh độ dày nét bút.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-21-5', 'k8-p21', 5, 'Thông hiểu', 'Nếu đặt khối `lặp lại (4) [di chuyển 80 bước, xoay phải 90 độ]` vào bên trong một vòng lặp `lặp lại (6)` kèm lệnh `xoay phải (60) độ` thì vẽ được hình gì?', '["1 đoạn thẳng", "Hoa văn gồm 6 hình vuông xoay đều quanh tâm (`6 x 60 = 360` độ)", "1 hình tam giác", "Không vẽ được gì"]'::jsonb, 1, 'Vòng lặp trong vẽ 1 hình vuông, vòng lặp ngoài xoay 6 lần mỗi lần 60 độ tạo thành hoa văn 6 hình vuông đối xứng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
