INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-21-7', 'k8-p21', 7, 'Vận dụng', 'Để đổi nhân vật chú Mèo sang nhân vật Bọ rùa (`Beetle`) trong thư viện Scratch, em nháy vào nút nào?', '["Nút `Chọn một Nhân vật` (`Choose a Sprite` ở góc dưới bên phải)", "Nút `Chọn một Phông nền`", "Nút `Thêm phần mở rộng`", "Nút `Cờ xanh`"]'::jsonb, 0, '`Choose a Sprite` mở thư viện nhân vật để thêm hoặc đổi nhân vật.'
