  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
