INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-23-4', 'k8-p23', 4, 'Thông hiểu', 'Biến `x` đang có giá trị là `10`. Sau khi chạy lệnh `thay đổi [x] một lượng (5)`, giá trị của `x` là bao nhiêu?', '["`5`", "`15`", "`50`", "`10`"]'::jsonb, 1, 'Lệnh `thay đổi [x] một lượng (5)` lấy giá trị hiện tại `10` cộng thêm `5` thành `15`.'
