) VALUES (
  'rq-8-23-6', 'k8-p23', 6, 'Vận dụng', 'Cách ghép khối lệnh nào trong lệnh `nói (...)` giúp thông báo cả lời dẫn và giá trị chu vi?', '["`nói (kết hợp (Chu vi của đa giác là: ) ((60) * (n)))`", "`nói ((Chu vi) + (n))`", "`nói ((60) > (n))`", "`nói (kí tự thứ 1 của n)`"]'::jsonb, 0, 'Khối `kết hợp` (`join`) nối xâu thông báo với giá trị biểu thức số `(60) * (n)`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
