  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-24-5', 'k8-p24', 5, 'Thông hiểu', 'Khe lắp điều kiện trong khối `nếu <...> thì` và `lặp lại cho đến khi <...>` có hình gì và nhận kiểu dữ liệu nào?', '["Hình tròn, kiểu Số", "Hình lục giác, nhận biểu thức kiểu Lôgic (`true`/`false`)", "Hình chữ nhật, kiểu Xâu", "Hình vuông"]'::jsonb, 1, 'Khe hình lục giác chỉ nhận các khối biểu thức kiểu Lôgic.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-24-6', 'k8-p24', 6, 'Vận dụng', 'Cho `S = 0, i = 1`. Lặp lại `4` lần: `[thay đổi S một lượng i; thay đổi i một lượng 1]`. Sau vòng lặp, `S` bằng bao nhiêu?', '["`4`", "`10` (vì `1 + 2 + 3 + 4 = 10`)", "`6`", "`1`"]'::jsonb, 1, 'Qua 4 vòng lặp, `S` được cộng lần lượt `1 + 2 + 3 + 4 = 10`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-24-7', 'k8-p24', 7, 'Vận dụng', 'Các khối lệnh rẽ nhánh và lặp nằm trong nhóm lệnh nào của Scratch?', '["Nhóm `Sự kiện` (`Events`)", "Nhóm `Điều khiển` (`Control`)", "Nhóm `Cảm biến` (`Sensing`)", "Nhóm `Hiển thị` (`Looks`)"]'::jsonb, 1, 'Nhóm `Điều khiển` (`Control`) chứa toàn bộ các khối lệnh rẽ nhánh và lặp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-1', 'k8-p25', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khối lệnh [___] (`pick random 1 to 100`) trong nhóm `Các phép toán` giúp máy tính chọn ngẫu nhiên một số nguyên từ 1 đến 100."', '["lấy ngẫu nhiên từ (1) đến (100)", "(x) = (n)", "dưới (bên ngoài)", "Biến `x`"]'::jsonb, 0, 'Theo SGK Tin học 8: Khối lệnh «lấy ngẫu nhiên từ (1) đến (100)» (`pick random 1 to 100`) trong nhóm `Các phép toán` giúp máy tính chọn ngẫu nhiên một số nguyên từ 1 đến 100.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-2', 'k8-p25', 2, 'Nhận biết', 'Khối lệnh `lấy ngẫu nhiên từ (1) đến (100)` nằm trong nhóm lệnh nào của Scratch?', '["Nhóm `Chuyển động`", "Nhóm `Cảm biến`", "Nhóm `Các phép toán` (`Operators`)", "Nhóm `Điều khiển`"]'::jsonb, 2, 'Hàm sinh số ngẫu nhiên `pick random` thuộc nhóm `Các phép toán` (`Operators`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-3', 'k8-p25', 3, 'Nhận biết', 'Nếu đặt lệnh `đặt [x] thành (lấy ngẫu nhiên từ 1 đến 100)` vào BÊN TRONG vòng lặp đoán số thì lỗi gì xảy ra?', '["Số `x` luôn bằng 1", "Số bí mật `x` bị đổi mới liên tục sau mỗi lần đoán làm gợi ý Lớn/Nhỏ mất tác dụng", "Người chơi thắng ngay", "Máy tính tắt nguồn"]'::jsonb, 1, 'Số bí mật phải cố định trong 1 ván chơi nên lệnh sinh `x` phải nằm ngoài vòng lặp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-4', 'k8-p25', 4, 'Thông hiểu', 'Khi kiểm thử chương trình Đoán số, tại sao nên tạm thời cho hiển thị biến `x` trên sân khấu?', '["Để trang trí", "Để người lập trình biết giá trị `x` và chủ động nhập thử cả 3 trường hợp (`n < x`, `n > x`, `n = x`) xem chương trình phản hồi đúng chưa", "Để xóa biến `n`", "Để tăng tốc độ mạng"]'::jsonb, 1, 'Hiển thị biến khi kiểm thử giúp xác minh tính đúng đắn của mọi nhánh điều kiện.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-5', 'k8-p25', 5, 'Thông hiểu', 'Giả sử số bí mật `x = 42`, người chơi nhập `n = 60`. Chương trình sẽ làm gì?', '["Báo đoán đúng và dừng", "Thực hiện nhánh `n > x`, thông báo `''Số bạn đoán lớn quá!''` và tiếp tục vòng lặp cho đoán lại", "Thực hiện nhánh `n < x`", "Xóa chương trình"]'::jsonb, 1, 'Vì `60 > 42` nên điều kiện `n = x` Sai (tiếp tục lặp) và nhánh `n > x` Đúng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-6', 'k8-p25', 6, 'Vận dụng', 'Khi đoán một số từ `1` đến `100` bằng chiến thuật chia đôi khoảng (lần 1 đoán 50...), cần tối đa bao nhiêu lần đoán để chắc chắn trúng?', '["100 lần", "50 lần", "7 lần (vì `2^7 = 128 > 100`)", "3 lần"]'::jsonb, 2, 'Chia đôi liên tiếp khoảng 100 phần tử chỉ cần tối đa 7 bước là thu hẹp về đúng 1 số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-25-7', 'k8-p25', 7, 'Vận dụng', 'Khi chương trình thoát khỏi khối `lặp lại cho đến khi <(x) = (n)>`, giá trị của `n` lúc đó như thế nào so với `x`?', '["`n < x`", "`n > x`", "`n = x`", "`n = 0`"]'::jsonb, 2, 'Vòng lặp chỉ dừng khi điều kiện `x = n` trở thành Đúng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-1', 'k8-p26', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Quá trình chạy thử chương trình với các bộ dữ liệu đầu vào để kiểm tra tính đúng đắn gọi là [___]."', '["kiểm thử", "gỡ lỗi", "lôgic", "Hiển thị biến trên sân khấu"]'::jsonb, 0, 'Theo SGK Tin học 8: Quá trình chạy thử chương trình với các bộ dữ liệu đầu vào để kiểm tra tính đúng đắn gọi là «kiểm thử».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-2', 'k8-p26', 2, 'Nhận biết', 'Hoạt động tìm kiếm nguyên nhân và sửa các sai sót khi chương trình chạy không đúng kịch bản mong muốn gọi là gì?', '["Nén dữ liệu", "Gỡ lỗi (`Debugging`)", "Định dạng trang", "Sao lưu tệp"]'::jsonb, 1, 'Gỡ lỗi (`Debugging`) là quá trình phát hiện và khắc phục lỗi trong chương trình máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-3', 'k8-p26', 3, 'Nhận biết', 'Khi chương trình VẪN CHẠY ĐƯỢC nhưng cho kết quả tính toán SAI với yêu cầu đề bài, chương trình đó mắc loại lỗi nào?', '["Lỗi phần cứng", "Lỗi lôgic (`Logic Error`)", "Lỗi mất mạng", "Lỗi màn hình"]'::jsonb, 1, 'Lỗi lôgic xảy ra khi thuật toán, công thức hoặc điều kiện điều khiển bị viết sai.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-4', 'k8-p26', 4, 'Thông hiểu', 'Trong chương trình tính tổng từ 1 đến 5: Đặt `i = 1, S = 0`, lặp 5 lần `[thay đổi S một lượng i]`. Kết quả `S` ra `5` thay vì `15` là do thiếu lệnh gì?', '["Thiếu lệnh `xóa tất cả`", "Thiếu lệnh `thay đổi [i] một lượng (1)` bên trong vòng lặp", "Thiếu lệnh `đặt bút`", "Thiếu lệnh `nói`"]'::jsonb, 1, 'Không tăng `i` trong vòng lặp khiến `i` luôn bằng 1 suốt 5 lần cộng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-5', 'k8-p26', 5, 'Thông hiểu', 'Kỹ thuật nào giúp người lập trình Scratch dễ dàng theo dõi giá trị của các biến thay đổi như thế nào trong khi vòng lặp đang chạy?', '["Tắt màn hình", "Tích chọn hiển thị các biến trên sân khấu và thêm tạm lệnh `đợi (1) giây` trong vòng lặp", "Xóa hết các biến", "Đổi tên tệp"]'::jsonb, 1, 'Hiển thị biến kết hợp làm chậm vòng lặp giúp quan sát vết giá trị biến ở từng bước lặp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-6', 'k8-p26', 6, 'Vận dụng', 'Nhờ đặc điểm nào mà ngôn ngữ lập trình kéo thả khối lệnh như Scratch giúp người học tránh được lỗi cú pháp?', '["Nhờ hình dáng các khối lệnh và khe cắm chỉ cho phép ghép nối khi đúng cú pháp và tương thích kiểu dữ liệu", "Nhờ không có phép toán", "Nhờ chỉ vẽ được hình vuông", "Nhờ không cần bàn phím"]'::jsonb, 0, 'Cơ chế khớp nối hình học (tròn, lục giác, chữ nhật) ngăn chặn việc ghép sai quy tắc cú pháp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-26-7', 'k8-p26', 7, 'Vận dụng', 'Để kiểm thử chương trình xét tuyển (Đỗ khi `Điểm >= 5.0`, Trượt khi `Điểm < 5.0`), bộ dữ liệu kiểm thử nào tốt nhất?', '["Chỉ thử điểm `9.0`", "Thử đủ cả 3 mức: lớn hơn 5 (`7.5`), nhỏ hơn 5 (`4.0`) và ngay tại biên (`5.0`)", "Chỉ thử điểm `10`", "Không cần thử"]'::jsonb, 1, 'Kiểm thử cả nhánh Đỗ, nhánh Trượt và điểm biên `5.0` giúp phát hiện lỗi dùng nhầm `>` thay vì `>=`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-1', 'k8-p27', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Vòng lặp đoán số giới hạn 7 lượt sẽ dừng lại khi người chơi đoán đúng (`x = n`) [___] đã đoán đủ 7 lượt (`count = 7`)."', '["hoặc", "7", "(x) = (n)", "Một khái niệm khác"]'::jsonb, 0, 'Theo SGK Tin học 8: Vòng lặp đoán số giới hạn 7 lượt sẽ dừng lại khi người chơi đoán đúng (`x = n`) «hoặc» đã đoán đủ 7 lượt (`count = 7`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-2', 'k8-p27', 2, 'Nhận biết', 'Trong trò chơi Đoán số giới hạn 7 lượt, vòng lặp cho người chơi nhập số đoán dừng lại khi nào?', '["Khi `(x = n) và (count = 7)`", "Khi `(x = n) hoặc (count = 7)` (khi khởi tạo `count = 0` và tăng sau mỗi lần nhập)", "Khi `count = 100`", "Không bao giờ dừng"]'::jsonb, 1, 'Vòng lặp dừng ngay khi 1 trong 2 điều kiện xảy ra: đoán trúng (`x = n`) hoặc đã dùng hết 7 lượt (`count = 7`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-3', 'k8-p27', 3, 'Nhận biết', 'Đặt `count = 0` ở đầu chương trình, trong vòng lặp mỗi lần nhập số đoán thì tăng `count` thêm 1. Nếu điều kiện dừng là `<(x = n) hoặc (count = 7)>`, người chơi đoán sai liên tiếp được nhập tối đa mấy lần?', '["6 lần", "7 lần", "8 lần", "9 lần"]'::jsonb, 1, 'Biến `count` tăng từ 0 lên 1, 2, 3, 4, 5, 6, 7 qua đúng 7 lần nhập rồi dừng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-4', 'k8-p27', 4, 'Thông hiểu', 'Nếu sau vòng lặp ta viết `nếu <count = 7> thì [nói (Bạn đã thua!)] nếu không [nói (Thành công!)]`, lỗi gì xảy ra khi người chơi đoán TRÚNG ở đúng lượt thứ 7?', '["Khi đoán trúng ở lượt thứ 7, vừa có `x = n` vừa có `count = 7`, nên máy kiểm tra `count = 7` thấy Đúng và báo `''Bạn đã thua!''` (xử thua oan)", "Máy báo Thành công", "Máy tự tắt", "Không có lỗi gì"]'::jsonb, 0, 'Kiểm tra theo `count = 7` không phân biệt được lượt thứ 7 đó người chơi đoán đúng hay đoán sai.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-5', 'k8-p27', 5, 'Thông hiểu', 'Khối lệnh kiểm tra kết quả cuối cùng (đặt ngay sau vòng lặp) nào là ĐÚNG và gọn nhất?', '["`nếu <(x) = (n)> thì [nói (Thành công!)] nếu không [nói (Bạn đã thua!)]`", "`nếu <(count) = (1)> thì [nói (Thành công!)]`", "`nếu <(n) > (100)> thì [nói (Thua!)]`", "Không cần kiểm tra"]'::jsonb, 0, 'So sánh trực tiếp `x = n` xác định chính xác người chơi đã đoán trúng số bí mật hay chưa.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-6', 'k8-p27', 6, 'Vận dụng', 'Nếu sơ ý đặt lệnh `thay đổi [count] một lượng (1)` ở BÊN NGOÀI vòng lặp thì điều gì xảy ra?', '["Biến `count` không tăng trong khi lặp nên người chơi đoán sai bao nhiêu lần cũng không bị dừng ở lượt thứ 7", "Chỉ đoán được 1 lần", "Chương trình chạy đúng", "Số bí mật bằng 7"]'::jsonb, 0, 'Lệnh đếm số lượt phải nằm bên trong vòng lặp thì mỗi lượt đoán `count` mới tăng thêm 1.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-27-7', 'k8-p27', 7, 'Vận dụng', 'Trường hợp kiểm thử `''Người chơi đoán đúng ngay ở lượt thứ 7 cuối cùng''` được gọi là kiểm thử gì trong kỹ thuật phần mềm?', '["Kiểm thử âm thanh", "Kiểm thử giá trị biên (`Boundary Testing`)", "Kiểm thử phông chữ", "Kiểm thử phần cứng"]'::jsonb, 1, 'Lượt thứ 7 là ranh giới tối đa của số lần đoán nên thuộc kịch bản kiểm thử biên.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-1', 'k8-p28', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Sử dụng máy tính và thiết bị số giúp tự động hóa quy trình, tiết kiệm thời gian và nâng cao [___] công việc."', '["hiệu quả", "tin học", "trí tuệ", "Phát triển phần mềm & Lập trình"]'::jsonb, 0, 'Theo SGK Tin học 8: Sử dụng máy tính và thiết bị số giúp tự động hóa quy trình, tiết kiệm thời gian và nâng cao «hiệu quả» công việc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-2', 'k8-p28', 2, 'Nhận biết', 'Nghề nào sau đây thuộc trực tiếp vào nhóm ''Các nghề thuộc lĩnh vực tin học''?', '["Bác sĩ siêu âm", "Giáo viên Lịch sử chiếu slide", "Kỹ sư phát triển phần mềm và Chuyên gia an ninh mạng", "Nông dân dùng máy gặt"]'::jsonb, 2, 'Kỹ sư phần mềm và Chuyên gia an ninh mạng trực tiếp tạo ra và bảo vệ hệ thống CNTT.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-3', 'k8-p28', 3, 'Nhận biết', 'Việc ứng dụng tin học trong ngành ngân hàng đem lại lợi ích rõ rệt nào?', '["Phải xếp hàng cả ngày", "Giao dịch chuyển khoản trực tuyến 24/7, thanh toán số nhanh chóng và chính xác", "Không cần bảo mật", "Chỉ tính toán bằng bàn tính gỗ"]'::jsonb, 1, 'Hệ thống ngân hàng số giúp tự động hóa giao dịch tài chính an toàn, tức thời.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-4', 'k8-p28', 4, 'Thông hiểu', 'Nhiệm vụ chính của ''Chuyên viên quản trị cơ sở dữ liệu'' là gì?', '["Sửa ống nước", "Thiết kế, tổ chức lưu trữ, sao lưu và đảm bảo an toàn, bảo mật cho kho dữ liệu của tổ chức", "Lái máy bay", "May quần áo"]'::jsonb, 1, 'Quản trị viên cơ sở dữ liệu quản lí và bảo vệ nguồn tài nguyên dữ liệu số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-5', 'k8-p28', 5, 'Thông hiểu', 'Vì sao Kiến trúc sư ngày nay cần thành thạo các phần mềm thiết kế trên máy tính?', '["Để không cần học kiến trúc", "Giúp dựng mô hình 3D trực quan, tính toán kích thước chính xác và chỉnh sửa bản vẽ nhanh chóng", "Vì cấm vẽ trên giấy", "Để sửa phần cứng máy tính"]'::jsonb, 1, 'Phần mềm thiết kế chuyên dụng giúp nâng cao vượt trội năng suất và độ chính xác của bản vẽ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-6', 'k8-p28', 6, 'Vận dụng', 'Nhận định nào ĐÚNG về tầm quan trọng của môn Tin học đối với học sinh?', '["Chỉ ai làm lập trình viên mới cần học Tin học", "Tin học trang bị năng lực số cốt lõi và tư duy máy tính cần thiết cho mọi ngành nghề trong xã hội hiện đại", "Học Tin học chỉ để chơi game", "Không liên quan đến các môn khác"]'::jsonb, 1, 'Mọi ngành nghề hiện đại đều thực hiện chuyển đổi số nên năng lực tin học là thiết yếu cho tất cả học sinh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-28-7', 'k8-p28', 7, 'Vận dụng', 'Trước sự phát triển của AI, thái độ đúng đắn của người lao động tương lai là gì?', '["Sợ hãi trốn tránh công nghệ", "Ỷ lại hoàn toàn vào AI", "Chủ động học tập, rèn tư duy sáng tạo và làm chủ công cụ số/AI để nâng cao hiệu quả công việc", "Ngừng học tập"]'::jsonb, 2, 'Làm chủ công nghệ và AI kết hợp tư duy sáng tạo giúp con người phát triển bền vững trong kỷ nguyên số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-1', 'k8-p29', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Nhà toán học nữ người Anh [___] (1815–1852) được tôn vinh là lập trình viên máy tính đầu tiên trong lịch sử nhân loại."', '["Ada Lovelace", "Grace Hopper", "bình đẳng", "Ada Lovelace (1815–1852)"]'::jsonb, 0, 'Theo SGK Tin học 8: Nhà toán học nữ người Anh «Ada Lovelace» (1815–1852) được tôn vinh là lập trình viên máy tính đầu tiên trong lịch sử nhân loại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-2', 'k8-p29', 2, 'Nhận biết', 'Ai được thế giới công nhận là ''Lập trình viên đầu tiên'' trong lịch sử máy tính?', '["Blaise Pascal", "Charles Babbage", "Nữ bá tước Ada Lovelace", "John von Neumann"]'::jsonb, 2, 'Bà Ada Lovelace (1815–1852) đã viết thuật toán đầu tiên cho máy tính của Babbage và trở thành lập trình viên đầu tiên trong lịch sử.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-3', 'k8-p29', 3, 'Nhận biết', 'Nhà khoa học nữ Grace Hopper nổi tiếng với thành tựu nào trong lịch sử Tin học?', '["Chế tạo bàn tính", "Phát triển chương trình dịch (Compiler) đầu tiên, đặt nền móng cho ngôn ngữ COBOL và thuật ngữ ''Debug''", "Phát minh đèn chân không", "Tạo ra chuột máy tính"]'::jsonb, 1, 'Đô đốc Grace Hopper là người tiên phong về trình biên dịch và ngôn ngữ lập trình bậc cao COBOL.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-4', 'k8-p29', 4, 'Thông hiểu', 'Nhận định nào thể hiện ĐÚNG tinh thần bình đẳng giới trong lĩnh vực tin học?', '["Con trai luôn giỏi máy tính hơn con gái", "Con gái chỉ nên gõ văn bản, không nên học lập trình", "Cả nam và nữ đều có năng lực tư duy và cơ hội thành công bình đẳng trong mọi ngành nghề tin học", "Chỉ tuyển nam vào ngành CNTT"]'::jsonb, 2, 'Năng lực tin học phụ thuộc vào sự rèn luyện và đam mê cá nhân, hoàn toàn không phụ thuộc vào giới tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-5', 'k8-p29', 5, 'Thông hiểu', 'Đặc điểm nào của ngành Công nghệ thông tin giúp xóa bỏ rào cản về thể lực giữa nam và nữ?', '["Phải khuân vác nặng", "Là ngành lao động trí óc dựa trên tri thức, sáng tạo và môi trường làm việc hiện đại, linh hoạt", "Làm việc ngoài biển khơi", "Không dùng máy tính"]'::jsonb, 1, 'Lao động trí óc trong môi trường số tạo cơ hội phát triển công bằng cho cả hai giới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-6', 'k8-p29', 6, 'Vận dụng', 'Khi phân công nhiệm vụ trong nhóm thực hành Tin học (Lập trình, Thiết kế slide, Báo cáo), cách làm nào văn minh nhất?', '["Cấm các bạn nữ lập trình", "Tạo cơ hội bình đẳng để cả bạn nam và bạn nữ đều được tham gia lập trình, thiết kế và thuyết trình theo năng lực", "Chỉ cho bạn nam dùng máy tính", "Tách riêng không hợp tác"]'::jsonb, 1, 'Hợp tác bình đẳng giúp mọi học sinh cùng phát triển toàn diện các kỹ năng số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-8-29-7', 'k8-p29', 7, 'Vận dụng', 'Theo Khung năng lực AI (8.B3.1), nếu một AI tạo ảnh luôn mặc định vẽ nam giới khi được yêu cầu vẽ ''Giám đốc công nghệ'', hiện tượng đó gọi là gì?', '["Tăng tốc độ xử lí", "Thiên kiến giới tính (`Gender Bias`) trong dữ liệu huấn luyện AI cần được nhận diện và khắc phục", "Lỗi bàn phím", "Hết bộ nhớ RAM"]'::jsonb, 1, 'Nhận diện định kiến giới trong AI giúp người dùng và nhà phát triển hướng tới các hệ thống AI công bằng, bình đẳng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-1', 'k9-p01', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Các thiết bị thông minh trong gia đình, y tế, giao thông, thương mại hoạt động tự động được là nhờ bên trong có gắn [___] thông tin."', '["bộ xử lí", "lưu trữ", "Internet", "Tính toán nhanh và chính xác"]'::jsonb, 0, 'Theo SGK Tin học 9: Các thiết bị thông minh trong gia đình, y tế, giao thông, thương mại hoạt động tự động được là nhờ bên trong có gắn «bộ xử lí» thông tin.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-2', 'k9-p01', 2, 'Nhận biết', 'Bộ phận cốt lõi nào bên trong máy giặt thông minh, điều hòa инverter và robot hút bụi giúp chúng tự động điều chỉnh chế độ hoạt động?', '["Bánh răng bằng gỗ", "Bộ xử lí thông tin (vi xử lí)", "Dây cót đồng hồ", "Ống thủy tinh chân không"]'::jsonb, 1, 'Các thiết bị điện tử thông minh đều được tích hợp bộ xử lí thông tin nhận tín hiệu từ cảm biến để điều khiển tự động.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-3', 'k9-p01', 3, 'Nhận biết', 'Đâu KHÔNG phải là khả năng ưu việt của máy tính điện tử?', '["Tính toán cực nhanh và chính xác", "Lưu trữ lượng dữ liệu khổng lồ và tìm kiếm tức thời", "Tự nảy sinh tình cảm, cảm xúc sinh học giống hệt con người", "Làm việc tự động, liên tục theo chương trình không biết mệt mỏi"]'::jsonb, 2, 'Máy tính mạnh về tính toán, lưu trữ, kết nối và tự động hóa, nhưng không có cảm xúc sinh học tự nhiên của con người.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-4', 'k9-p01', 4, 'Thông hiểu', 'Trong lĩnh vực khoa học vũ trụ và dự báo thời tiết, khả năng nào của siêu máy tính đóng vai trò quyết định?', '["Khả năng phát nhạc giải trí", "Khả năng thực hiện hàng triệu tỉ phép tính phức tạp mỗi giây với độ chính xác cực cao", "Khả năng in văn bản trên giấy A4", "Khả năng thu nhỏ thành đồng hồ đeo tay"]'::jsonb, 1, 'Dự báo thời tiết và tính toán quỹ đạo tàu vũ trụ đòi hỏi xử lí mô hình toán học khổng lồ trong thời gian thực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-5', 'k9-p01', 5, 'Thông hiểu', 'Thiết bị nào sau đây tại siêu thị hoặc cửa hàng tiện lợi là thiết bị có gắn bộ xử lí thông tin?', '["Giỏ nhựa xách tay", "Máy quét mã vạch và máy thanh toán POS kết nối phần mềm bán hàng", "Kệ sắt trưng bày hàng hóa", "Tờ giấy ghi bảng giá"]'::jsonb, 1, 'Máy POS và đầu đọc mã vạch có bộ xử lí để giải mã thông tin sản phẩm, tính tổng tiền và cập nhật kho tự động.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-6', 'k9-p01', 6, 'Vận dụng', 'Khái niệm ''Internet vạn vật'' (IoT - Internet of Things) dùng để chỉ điều gì?', '["Chỉ gồm các máy tính để bàn nối dây mạng LAN", "Mạng lưới các thiết bị, phương tiện, cảm biến có gắn bộ xử lí được kết nối Internet để thu thập và trao đổi dữ liệu tự động", "Một phần mềm soạn thảo văn bản", "Một trò chơi điện tử ngoại tuyến"]'::jsonb, 1, 'IoT kết nối các thiết bị gắn bộ xử lí (nhà thông minh, nông nghiệp thông minh, giao thông thông minh) qua Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-1-7', 'k9-p01', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.A2.1), minh chứng rõ nhất cho thấy AI kết hợp với thiết bị số đang tạo tác động lớn đến xã hội là gì?', '["Các thiết bị chỉ bật/tắt bằng cầu dao tay", "Hệ thống camera AI giao thông, trợ lí ảo giọng nói, dịch thuật tức thời và chẩn đoán y khoa thông minh hỗ trợ hàng triệu người mỗi ngày", "Con người quay lại viết thư tay hoàn toàn", "Máy tính ngày càng nặng hàng chục tấn"]'::jsonb, 1, 'AI giúp các thiết bị số xử lí dữ liệu phi cấu trúc (hình ảnh, giọng nói, ngôn ngữ) và hỗ trợ ra quyết định thông minh trong mọi lĩnh vực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-1', 'k9-p02', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong giáo dục, công nghệ thông tin giúp chuyển từ cách học thụ động sang học tập chủ động, [___] hóa theo nhịp độ của từng người học."', '["cá nhân", "Xã hội", "tinh thần", "Tác động lên Giáo dục"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong giáo dục, công nghệ thông tin giúp chuyển từ cách học thụ động sang học tập chủ động, «cá nhân» hóa theo nhịp độ của từng người học.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-2', 'k9-p02', 2, 'Nhận biết', 'Ví dụ nào sau đây thể hiện tác động tích cực của CNTT đối với lĩnh vực giáo dục?', '["Học sinh chỉ có thể học khi đến lớp giờ hành chính", "Học sinh có thể tự học mọi lúc, mọi nơi qua kho học liệu số, phòng thí nghiệm ảo và lớp học trực tuyến", "Học sinh sao chép bài văn trên mạng nộp cho cô giáo", "Bỏ hoàn toàn sách giáo khoa và việc ghi chép"]'::jsonb, 1, 'CNTT xóa bỏ rào cản không gian và thời gian, cung cấp học liệu đa phương tiện hỗ trợ tự học suốt đời.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-3', 'k9-p02', 3, 'Nhận biết', 'Trong lĩnh vực hành chính và đời sống xã hội, dịch vụ nào sau đây là thành tựu của chuyển đổi số?', '["Phải đi lại nhiều lần nộp hồ sơ giấy trực tiếp", "Cổng Dịch vụ công trực tuyến, căn cước điện tử VNeID và thanh toán không dùng tiền mặt", "Gửi công văn bằng ngựa trạm", "Xếp hàng mua tem phiếu"]'::jsonb, 1, 'Chính phủ số và công dân số giúp thực hiện thủ tục hành chính và thanh toán trực tuyến minh bạch, thuận tiện.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-4', 'k9-p02', 4, 'Thông hiểu', 'Nguy cơ nào đối với sức khỏe THỂ CHẤT thường xảy ra khi học sinh ngồi dùng máy tính, điện thoại liên tục nhiều giờ liền trong bóng tối?', '["Tăng chiều cao nhanh", "Suy giảm thị lực (cận thị, khô mắt), đau mỏi cổ vai gáy, cong vẹo cột sống và mất ngủ", "Tăng cường thể lực", "Cải thiện hệ hô hấp"]'::jsonb, 1, 'Ánh sáng xanh từ màn hình và tư thế ngồi bất động lâu gây hại trực tiếp cho mắt, cột sống và giấc ngủ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-5', 'k9-p02', 5, 'Thông hiểu', 'Biểu hiện nào cho thấy một người đang bị ảnh hưởng tiêu cực về sức khỏe TINH THẦN do lạm dụng mạng xã hội và trò chơi trực tuyến?', '["Luôn vui vẻ trò chuyện với gia đình và tập thể thao đều đặn", "Lo âu, cáu gắt khi không có mạng, sao nhãng học tập, thu mình và né tránh giao tiếp trực tiếp", "Quản lí thời gian học tập khoa học", "Đọc sách giấy mỗi tối"]'::jsonb, 1, 'Nghiện Internet gây lệ thuộc tâm lí, rối loạn cảm xúc và làm suy giảm mối quan hệ xã hội thực tế.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-6', 'k9-p02', 6, 'Vận dụng', 'Thói quen nào sau đây giúp cân bằng cuộc sống số và bảo vệ sức khỏe theo Khung năng lực số (4.3.TC2)?', '["Vừa ăn cơm vừa lướt điện thoại và mang điện thoại lên giường xem tới khuya", "Thiết lập giới hạn thời gian sử dụng màn hình, ngồi đúng tư thế, nghỉ giải lao sau mỗi 30–45 phút và tích cực vận động thể chất", "Chỉ dùng máy tính vào ban đêm", "Tắt hết đèn phòng khi dùng máy tính"]'::jsonb, 1, 'Chủ động kiểm soát thời gian màn hình và nghỉ ngơi hợp lí giúp bảo vệ cả thể chất lẫn tinh thần.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-2-7', 'k9-p02', 7, 'Vận dụng', 'Quan điểm phản biện nào là ĐÚNG ĐẮN trước sự bùng nổ của Trí tuệ nhân tạo (AI) trong giáo dục?', '["Cấm tuyệt đối học sinh chạm vào máy tính", "AI có thể học thay con người nên không cần đến trường nữa", "AI là trợ lí cá nhân hóa học tập rất mạnh mẽ, nhưng người học phải giữ vai trò chủ động tư duy, kiểm chứng thông tin và rèn luyện kỹ năng thực hành", "Tin tưởng 100% mọi câu trả lời của AI"]'::jsonb, 2, 'Sử dụng công nghệ và AI như công cụ hỗ trợ tư duy thay vì phụ thuộc thụ động là chìa khóa thành công trong kỷ nguyên số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-1', 'k9-p03', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong quá trình giải quyết vấn đề, con người luôn cần tìm kiếm, tiếp nhận và trao đổi [___] để làm căn cứ ra quyết định."', '["thông tin", "chất lượng", "sai lầm", "Tìm kiếm thông tin"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong quá trình giải quyết vấn đề, con người luôn cần tìm kiếm, tiếp nhận và trao đổi «thông tin» để làm căn cứ ra quyết định.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-2', 'k9-p03', 2, 'Nhận biết', 'Yếu tố nào đóng vai trò là cơ sở trực tiếp giúp con người đưa ra các quyết định đúng đắn khi giải quyết vấn đề?', '["Sự phỏng đoán ngẫu nhiên", "Thông tin có chất lượng tốt được thu thập và thẩm định kỹ lưỡng", "Tin đồn trên mạng", "Cảm xúc nhất thời"]'::jsonb, 1, 'Chất lượng của quyết định phụ thuộc trực tiếp vào chất lượng của thông tin đầu vào.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-3', 'k9-p03', 3, 'Nhận biết', 'Điều gì sẽ xảy ra nếu chúng ta giải quyết vấn đề dựa trên nguồn thông tin sai sự thật hoặc đã quá lỗi thời?', '["Vấn đề tự động được giải quyết nhanh hơn", "Dẫn đến quyết định sai lầm, gây lãng phí thời gian, tiền bạc hoặc nguy hại cho sức khỏe, an toàn", "Không ảnh hưởng gì", "Máy tính chạy nhanh hơn"]'::jsonb, 1, 'Thông tin rác/sai lệch dẫn tới quyết định sai lầm (nguyên lí Garbage In, Garbage Out).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-4', 'k9-p03', 4, 'Thông hiểu', 'Khi tìm hiểu thông tin về quy chế thi tuyển sinh vào lớp 10 THPT của tỉnh Bắc Ninh, nguồn thông tin nào có chất lượng đáng tin cậy nhất?', '["Một bài đăng không rõ tác giả trên diễn đàn tự do", "Văn bản hướng dẫn tuyển sinh chính thức năm học hiện tại trên cổng thông tin Sở Giáo dục và Đào tạo Bắc Ninh", "Lời kể truyền miệng từ vài năm trước", "Đoạn quảng cáo của trung tâm gia sư tự phát"]'::jsonb, 1, 'Cổng thông tin của Sở GD&ĐT là nguồn chính thống, có thẩm quyền pháp lí và cập nhật chính xác nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-5', 'k9-p03', 5, 'Thông hiểu', 'Trong hoạt động trao đổi thông tin khi làm dự án nhóm, yêu cầu nào về chất lượng thông tin là quan trọng?', '["Gửi càng nhiều tin nhắn rác càng tốt", "Cung cấp thông tin chính xác, kịp thời, rõ ràng và dễ hiểu cho các thành viên trong nhóm", "Giấu bớt thông tin quan trọng", "Gửi thông tin đã hết hạn sử dụng"]'::jsonb, 1, 'Trao đổi thông tin có chất lượng giúp cả nhóm phối hợp thống nhất và hoàn thành nhiệm vụ đúng tiến độ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-6', 'k9-p03', 6, 'Vận dụng', 'Vì sao trong môi trường số hiện nay, việc quan tâm đến chất lượng thông tin lại càng trở nên cấp thiết hơn bao giờ hết?', '["Vì trên Internet có quá ít thông tin", "Vì thông tin trên Internet vô cùng khổng lồ, đa dạng nhưng thượng vàng hạ cám, lẫn lộn nhiều tin giả, tin rác và thông tin chưa kiểm chứng", "Vì máy tìm kiếm bị hỏng", "Vì không ai dùng Internet nữa"]'::jsonb, 1, 'Sự bùng nổ thông tin số và nội dung tự phát đòi hỏi bộ lọc tư duy phản biện để gạn đục khơi trong.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-3-7', 'k9-p03', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.A3.1), khi nhận được một bản tổng hợp thông tin từ công cụ AI tạo sinh, người dùng thông thái cần làm gì?', '["Sao chép sử dụng ngay không cần đọc lại", "Phân tích, đối chiếu các số liệu và sự kiện trọng yếu với nguồn tài liệu gốc chính thống trước khi đưa ra quyết định", "Xóa trình duyệt web", "Tin rằng AI không bao giờ nhầm lẫn"]'::jsonb, 1, 'Tư duy phản biện đòi hỏi luôn kiểm chứng thông tin từ AI với các nguồn dữ liệu gốc đáng tin cậy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-1', 'k9-p04', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Bốn tiêu chí cơ bản để đánh giá chất lượng thông tin gồm: Tính mới, Tính chính xác, Tính [___] và Tính sử dụng được."', '["đầy đủ", "chính xác", "sử dụng được", "Tính mới (Tính cập nhật)"]'::jsonb, 0, 'Theo SGK Tin học 9: Bốn tiêu chí cơ bản để đánh giá chất lượng thông tin gồm: Tính mới, Tính chính xác, Tính «đầy đủ» và Tính sử dụng được.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-2', 'k9-p04', 2, 'Nhận biết', 'Bốn tiêu chí chuẩn để đánh giá chất lượng thông tin trong giải quyết vấn đề (theo SGK Tin học 9 Bài 2) là gì?', '["Tính dài, tính đẹp, tính nhiều màu sắc và tính miễn phí", "Tính mới, tính chính xác, tính đầy đủ và tính sử dụng được", "Tính bí mật, tính phức tạp, tính ngẫu nhiên và tính giải trí", "Tính nhanh, tính rẻ, tính phổ biến và tính hài hước"]'::jsonb, 1, 'SGK Tin học 9 quy định 4 tiêu chí đánh giá chất lượng thông tin: Tính mới, Tính chính xác, Tính đầy đủ và Tính sử dụng được.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-3', 'k9-p04', 3, 'Nhận biết', 'Bạn Nam dùng bảng giá vé tàu hỏa năm 2015 để dự trù kinh phí cho chuyến đi của lớp vào năm 2026. Thông tin Nam dùng vi phạm tiêu chí nào?', '["Tính sử dụng được", "Tính mới (tính cập nhật)", "Tính thẩm mỹ", "Tính đa phương tiện"]'::jsonb, 1, 'Giá vé từ năm 2015 đã lỗi thời so với năm 2026 nên không đảm bảo tính mới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-4', 'k9-p04', 4, 'Thông hiểu', 'Một bài báo y khoa viết bằng tiếng Đức chuyên sâu rất chuẩn xác nhưng học sinh lớp 9 chỉ biết tiếng Việt và tiếng Anh nên không thể đọc hiểu để áp dụng. Thông tin đó thiếu tiêu chí nào đối với học sinh đó?', '["Tính mới", "Tính chính xác", "Tính sử dụng được", "Tính bản quyền"]'::jsonb, 2, 'Tính sử dụng được phụ thuộc vào khả năng tiếp nhận (ngôn ngữ, trình độ) và mục đích cụ thể của người dùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-5', 'k9-p04', 5, 'Thông hiểu', 'Khi tìm hiểu về một trường THPT, bạn An chỉ xem duy nhất thông tin về ''Sân bóng của trường rất rộng'' rồi quyết định nộp hồ sơ mà không tìm hiểu chất lượng giảng dạy, học phí, khoảng cách đi lại. Thông tin của An thiếu tiêu chí nào?', '["Tính đầy đủ", "Tính mới", "Tính chính xác", "Tính bảo mật"]'::jsonb, 0, 'Để giải quyết bài toán chọn trường, cần thông tin toàn diện trên nhiều khía cạnh (học tập, điểm chuẩn, khoảng cách, học phí), nên chỉ biết về sân bóng là thiếu tính đầy đủ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-6', 'k9-p04', 6, 'Vận dụng', 'Để kiểm tra ''Tính chính xác'' của một số liệu thống kê tìm được trên mạng, cách làm nào đúng đắn nhất?', '["Xem bài đăng có nhiều bình luận khen không", "Kiểm tra nguồn phát hành (Tổng cục Thống kê, bộ ngành chính thống) và đối chiếu chéo với các tài liệu uy tín khác", "Xem phông chữ có đẹp không", "Đoán mò theo cảm tính"]'::jsonb, 1, 'Tính chính xác được thẩm định qua uy tín, thẩm quyền của nguồn tin và sự nhất quán khi đối chiếu chéo.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-4-7', 'k9-p04', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.B3.1), hiện tượng AI chỉ đưa ra thông tin nghiêng về một góc nhìn phiến diện do dữ liệu huấn luyện không cân bằng liên quan đến tiêu chí nào?', '["Làm suy giảm tính chính xác và tính đầy đủ của thông tin do sự thiên vị/thành kiến (AI Bias)", "Tăng tính sử dụng được", "Tăng tốc độ mạng", "Giảm dung lượng tệp"]'::jsonb, 0, 'Thiên vị AI (AI Bias) làm thông tin thiếu khách quan, thiếu đầy đủ các góc nhìn đa chiều.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-1', 'k9-p05', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Ở Nhiệm vụ 1 (Tìm kiếm theo mục đích), trước khi gõ từ khóa tìm kiếm, ta cần xác định rõ [___] giải quyết vấn đề và danh mục các thông tin cần thu thập."', '["mục tiêu / mục đích", "bốn (4)", "quyết định", "Bước 1: Xác định vấn đề & nhu cầu thông tin"]'::jsonb, 0, 'Theo SGK Tin học 9: Ở Nhiệm vụ 1 (Tìm kiếm theo mục đích), trước khi gõ từ khóa tìm kiếm, ta cần xác định rõ «mục tiêu / mục đích» giải quyết vấn đề và danh mục các thông tin cần thu thập.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-2', 'k9-p05', 2, 'Nhận biết', 'Trong bài thực hành tìm kiếm thông tin để chọn trường THPT sau khi tốt nghiệp lớp 9, bước đầu tiên em cần thực hiện là gì?', '["Mở mạng xã hội xem tin giải trí", "Xác định rõ mục đích tìm kiếm và liệt kê các nội dung thông tin cụ thể cần thu thập về các trường THPT", "Chọn đại một trường không cần tìm hiểu", "Tắt máy tính"]'::jsonb, 1, 'Tìm kiếm có mục đích đòi hỏi phải xác định trước danh mục các câu hỏi và dữ liệu cần tìm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-3', 'k9-p05', 3, 'Nhận biết', 'Từ khóa nào sau đây giúp tìm kiếm thông tin chính xác nhất về kế hoạch tuyển sinh lớp 10 năm học 2026–2027 tại tỉnh Bắc Ninh?', '["Trường học", "\"Kế hoạch tuyển sinh lớp 10\" Bắc Ninh 2026-2027 site:bacninh.edu.vn", "Thi cấp 3", "Học sinh lớp 9"]'::jsonb, 1, 'Sử dụng cụm từ khóa trong dấu ngoặc kép kèm năm học và tên miền ngành giáo dục địa phương giúp lọc đúng văn bản chính thống.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-4', 'k9-p05', 4, 'Thông hiểu', 'Khi thu thập thông tin về điểm chuẩn vào lớp 10 của một trường THPT, vì sao nên xem số liệu của 2–3 năm liên tiếp gần nhất thay vì chỉ xem 1 năm cách đây 8 năm?', '["Để đảm bảo tính mới (cập nhật xu hướng hiện tại) và tính đầy đủ giúp đánh giá mức độ cạnh tranh sát thực tế", "Vì số năm cũ khó đọc", "Để cộng tổng điểm lại", "Vì máy tính yêu cầu"]'::jsonb, 0, 'Số liệu 2–3 năm gần nhất phản ánh sát mặt bằng điểm chuẩn và chỉ tiêu hiện hành.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-5', 'k9-p05', 5, 'Thông hiểu', 'Một trang web giới thiệu rất đúng và mới về các trường THPT tại Thành phố Hồ Chí Minh, nhưng em đang sinh sống và dự thi tại Bắc Ninh. Đối với bài toán chọn trường của em, thông tin đó không đáp ứng tiêu chí nào?', '["Tính chính xác", "Tính mới", "Tính sử dụng được (không phù hợp với mục tiêu và địa bàn dự thi của người dùng)", "Tính pháp lí"]'::jsonb, 2, 'Dù thông tin đúng và mới nhưng không đúng đối tượng/mục tiêu giải quyết vấn đề của người dùng thì không có tính sử dụng được.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-6', 'k9-p05', 6, 'Vận dụng', 'Trong phiếu đánh giá chất lượng thông tin của nhóm, cột ''Nguồn thông tin (URL, cơ quan ban hành, ngày đăng)'' giúp kiểm tra trực tiếp hai tiêu chí nào?', '["Tính mới và Tính chính xác", "Tính giải trí và Tính nghệ thuật", "Dung lượng tệp và Tốc độ tải", "Màu sắc và Phông chữ"]'::jsonb, 0, 'Cơ quan ban hành bảo chứng cho Tính chính xác, còn ngày đăng bảo chứng cho Tính mới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-5-7', 'k9-p05', 7, 'Vận dụng', 'Khi sử dụng AI để hỗ trợ lập bảng so sánh các tổ hợp môn học lớp 10 (như tổ hợp có môn Tin học, Công nghệ, KHTN hay KHXH), học sinh cần làm gì?', '["Để AI tự quyết định trường học thay mình", "Cung cấp dữ liệu các tổ hợp môn thực tế từ thông báo chính thức của trường THPT dự kiến thi vào cho AI, rồi dùng AI phân tích sự phù hợp với năng lực bản thân", "Không cần xem thông báo của trường", "Chỉ hỏi AI về các trường ở nước ngoài"]'::jsonb, 1, 'Cung cấp dữ liệu gốc chính thống cho AI (Grounding) giúp kết quả phân tích vừa chính xác vừa sát với thực tế trường THPT tại địa phương.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-1', 'k9-p06', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Công nghệ kĩ thuật số bên cạnh những lợi ích to lớn cũng tiềm ẩn nhiều tác động [___] đối với con người, xã hội và môi trường nếu bị lạm dụng hoặc lợi dụng."', '["tiêu cực", "giản đơn / thủ công", "rác thải", "Rủi ro an toàn thông tin & lừa đảo mạng"]'::jsonb, 0, 'Theo SGK Tin học 9: Công nghệ kĩ thuật số bên cạnh những lợi ích to lớn cũng tiềm ẩn nhiều tác động «tiêu cực» đối với con người, xã hội và môi trường nếu bị lạm dụng hoặc lợi dụng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-2', 'k9-p06', 2, 'Nhận biết', 'Đâu là một trong những tác động tiêu cực của công nghệ kĩ thuật số đối với thị trường lao động?', '["Tạo ra nhiều ngành nghề công nghệ mới", "Làm một số công việc thủ công, giản đơn có tính lặp đi lặp lại bị máy móc tự động hóa thay thế, gây nguy cơ thất nghiệp nếu người lao động không nâng cao kỹ năng", "Giúp tính lương nhanh hơn", "Giúp tìm việc làm trực tuyến"]'::jsonb, 1, 'Tự động hóa thay thế các công việc giản đơn lặp lại, đòi hỏi người lao động phải chuyển đổi và nâng cao kỹ năng số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-3', 'k9-p06', 3, 'Nhận biết', 'Hành vi kẻ xấu gửi đường dẫn giả mạo trang web ngân hàng hoặc phần thưởng ảo để dụ người dùng nhập mật khẩu và mã OTP gọi là gì?', '["Tấn công lừa đảo trực tuyến (`Phishing`) đánh cắp dữ liệu cá nhân và tài khoản", "Bảo trì phần mềm", "Nâng cấp đường truyền Internet", "Sao lưu đám mây"]'::jsonb, 0, 'Lừa đảo trực tuyến (`Phishing`) là mối đe dọa phổ biến nhằm chiếm đoạt thông tin định danh và tài chính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-4', 'k9-p06', 4, 'Thông hiểu', 'Tác động tiêu cực nào đối với MÔI TRƯỜNG phát sinh từ việc vòng đời các thiết bị kĩ thuật số ngày càng ngắn?', '["Tăng diện tích rừng tự nhiên", "Phát sinh lượng lớn rác thải điện tử (pin, bo mạch chứa chì, thủy ngân...) gây ô nhiễm nghiêm trọng nếu không được tái chế đúng cách", "Làm giảm nhiệt độ Trái Đất", "Làm sạch nguồn nước"]'::jsonb, 1, 'Rác thải điện tử (E-waste) là thách thức môi trường toàn cầu trong kỷ nguyên kĩ thuật số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-5', 'k9-p06', 5, 'Thông hiểu', 'Lệ thuộc quá mức vào dịch vụ số và mạng xã hội dẫn đến hệ lụy nào trong quan hệ gia đình và cộng đồng?', '["Mọi người gắn kết trực tiếp nhiều hơn", "Con người trở nên xa cách trong đời thực, giảm kỹ năng giao tiếp trực tiếp và dễ bị tổn thương bởi bạo lực mạng", "Tăng thời gian tập thể dục", "Giúp mắt sáng hơn"]'::jsonb, 1, 'Lạm dụng không gian ảo làm suy giảm chất lượng tương tác trực tiếp giữa người với người.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-6', 'k9-p06', 6, 'Vận dụng', 'Theo Khung năng lực số (4.2.TC2), thông tin nào sau đây cần được BẢO MẬT TUYỆT ĐỐI, không đăng công khai lên mạng xã hội?', '["Tên trường học của em", "Số định danh cá nhân (CCCD), mật khẩu tài khoản, mã OTP ngân hàng và địa chỉ nhà riêng chi tiết kèm lịch trình vắng nhà", "Sở thích đọc sách khoa học", "Danh sách các môn học ở trường"]'::jsonb, 1, 'Lộ thông tin định danh, mật khẩu, mã OTP và lịch trình cá nhân tạo điều kiện cho tội phạm mạng và kẻ xấu lợi dụng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-6-7', 'k9-p06', 7, 'Vận dụng', 'Khi nhận được cuộc gọi video từ tài khoản mạng xã hội của người quen hỏi vay tiền gấp với hình ảnh hơi nhòe và âm thanh ngắt quãng (nghi ngờ Deepfake AI), cách xử lí nào AN TOÀN NHẤT?', '["Chuyển tiền ngay lập tức vì nhìn thấy mặt người quen", "Ngắt cuộc gọi mạng, gọi điện trực tiếp vào số thuê bao di động của người đó để xác minh và tuyệt đối không chuyển tiền khi chưa kiểm chứng trực tiếp", "Cung cấp mã OTP ngân hàng cho người gọi", "Chia sẻ mật khẩu tài khoản"]'::jsonb, 1, 'Xác minh qua kênh liên lạc độc lập (số điện thoại truyền thống hoặc gặp trực tiếp) là nguyên tắc vàng chống lừa đảo Deepfake.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-1', 'k9-p07', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Các văn bản pháp luật trụ cột điều chỉnh hoạt động trên môi trường số tại Việt Nam gồm: Luật Công nghệ thông tin (2006), Luật [___] (2018), Luật Sở hữu trí tuệ và các Nghị định về dịch vụ Internet."', '["An ninh mạng", "nghiêm cấm", "trách nhiệm", "Luật Công nghệ thông tin & Nghị định Internet"]'::jsonb, 0, 'Theo SGK Tin học 9: Các văn bản pháp luật trụ cột điều chỉnh hoạt động trên môi trường số tại Việt Nam gồm: Luật Công nghệ thông tin (2006), Luật «An ninh mạng» (2018), Luật Sở hữu trí tuệ và các Nghị định về dịch vụ Internet.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-2', 'k9-p07', 2, 'Nhận biết', 'Văn bản pháp luật nào của Việt Nam (ban hành năm 2018) quy định cụ thể về việc bảo vệ an ninh quốc gia, trật tự an toàn xã hội và phòng chống các hành vi vi phạm pháp luật trên không gian mạng?', '["Luật Giao thông đường bộ", "Luật An ninh mạng", "Luật Đất đai", "Luật Khám bệnh, chữa bệnh"]'::jsonb, 1, 'Luật An ninh mạng (2018) quy định toàn diện về bảo vệ an ninh mạng và các hành vi bị nghiêm cấm trên không gian mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-3', 'k9-p07', 3, 'Nhận biết', 'Hành vi nào sau đây VI PHẠM Luật Công nghệ thông tin và Luật An ninh mạng?', '["Tra cứu tài liệu học tập trên cổng thông tin điện tử của trường", "Tạo lập hoặc chia sẻ bài viết bịa đặt, sai sự thật gây hoang mang trong nhân dân và xúc phạm danh dự cá nhân, tổ chức", "Gửi thư điện tử nộp bài tập cho giáo viên", "Tham gia cuộc thi trực tuyến do Bộ GD&ĐT tổ chức"]'::jsonb, 1, 'Tung tin giả, vu khống, xúc phạm uy tín, danh dự của tổ chức/cá nhân là hành vi bị nghiêm cấm trong Luật CNTT và Luật An ninh mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-4', 'k9-p07', 4, 'Thông hiểu', 'Một học sinh tìm được mật khẩu email của bạn cùng lớp rồi tự ý đăng nhập, đọc trộm tin nhắn và xóa các tệp tài liệu của bạn. Hành vi này là gì?', '["Một trò đùa vô hại", "Hành vi vi phạm pháp luật: xâm nhập trái phép, xâm phạm bí mật thư tín và hủy hoại dữ liệu của người khác", "Thực hành kỹ năng tin học tốt", "Giúp bạn kiểm tra bảo mật"]'::jsonb, 1, 'Truy cập trái phép vào tài khoản, chiếm đoạt hoặc xóa dữ liệu của người khác là hành vi vi phạm pháp luật.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-5', 'k9-p07', 5, 'Thông hiểu', 'Về khía cạnh pháp lí của việc sở hữu và sử dụng thông tin, hành động nào sau đây là ĐÚNG?', '["Mọi hình ảnh, phần mềm tìm thấy trên Internet đều là vô chủ nên ai lấy bán cũng được", "Chỉ sử dụng phần mềm có bản quyền/mã nguồn mở hợp pháp, xin phép chủ sở hữu khi khai thác thương mại và ghi rõ nguồn trích dẫn", "Xóa tên tác giả trên bức tranh số rồi đăng ký bản quyền tên mình", "Tải sách lậu về in bán lấy tiền"]'::jsonb, 1, 'Tác phẩm số và phần mềm máy tính được bảo hộ quyền tác giả theo Luật Sở hữu trí tuệ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-6', 'k9-p07', 6, 'Vận dụng', 'Khi phát hiện một trang web hoặc tài khoản mạng xã hội có hành vi lừa đảo hoặc xâm hại trẻ em trên mạng, công dân nên làm gì?', '["Bấm thích và chia sẻ rộng rãi", "Báo cáo (Report) vi phạm trên nền tảng và thông báo cho thầy cô, cha mẹ hoặc cơ quan chức năng có thẩm quyền", "Tham gia bình luận cổ vũ", "Cung cấp thông tin cá nhân cho trang đó"]'::jsonb, 1, 'Kịp thời báo cáo và thông tin cho người lớn/cơ quan chức năng giúp ngăn chặn hành vi phạm pháp và bảo vệ cộng đồng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-7-7', 'k9-p07', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.B2.1), nếu một người dùng công cụ AI để viết bài vu khống người khác hoặc tạo ảnh giả mạo gây thiệt hại rồi đăng lên mạng, ai sẽ phải chịu trách nhiệm trước pháp luật?', '["Không ai phải chịu trách nhiệm vì do máy tính làm", "Chính người dùng đã ra lệnh và phát tán nội dung vi phạm đó phải chịu hoàn toàn trách nhiệm trước pháp luật", "Chiếc màn hình máy tính chịu trách nhiệm", "Nhà cung cấp dịch vụ điện lực chịu trách nhiệm"]'::jsonb, 1, 'AI chỉ là công cụ; con người là chủ thể điều khiển, kiểm duyệt và phát tán thông tin nên phải chịu trách nhiệm pháp lí và đạo đức đối với sản phẩm đăng tải.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-1', 'k9-p08', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Phần mềm [___] là phần mềm tái tạo, bắt chước hoạt động của một hệ thống, hiện tượng hoặc quá trình trong thế giới thực trên màn hình máy tính."', '["mô phỏng", "khám phá", "PhET", "Một khái niệm khác"]'::jsonb, 0, 'Theo SGK Tin học 9: Phần mềm «mô phỏng» là phần mềm tái tạo, bắt chước hoạt động của một hệ thống, hiện tượng hoặc quá trình trong thế giới thực trên màn hình máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-2', 'k9-p08', 2, 'Nhận biết', 'Khái niệm ''Phần mềm mô phỏng'' được hiểu đúng nhất là gì?', '["Phần mềm chỉ dùng để gõ văn bản hành chính", "Phần mềm mô형 hóa và tái hiện hoạt động của các đối tượng, hiện tượng hay hệ thống thực tế trên máy tính để con người tương tác, quan sát và nghiên cứu", "Phần mềm diệt virus máy tính", "Phần mềm nén tệp tin"]'::jsonb, 1, 'Phần mềm mô phỏng xây dựng mô hình số của thế giới thực giúp người dùng thử nghiệm, tương tác và khám phá quy luật.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-3', 'k9-p08', 3, 'Nhận biết', 'Đâu KHÔNG phải là lợi ích của phần mềm mô phỏng trong học tập môn Khoa học tự nhiên?', '["Giúp làm thí nghiệm an toàn, không sợ nổ hóa chất hay chập cháy điện", "Tiết kiệm chi phí mua sắm vật tư tiêu hao và có thể làm đi làm lại nhiều lần", "Cho phép điều chỉnh nhanh các thông số (như trọng lực, ma sát, điện trở) để quan sát sự thay đổi tức thời", "Làm cho học sinh không cần phải hiểu kiến thức môn học nữa"]'::jsonb, 3, 'Phần mềm mô phỏng là công cụ trực quan giúp học sinh chủ động khám phá và hiểu sâu bản chất kiến thức hơn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-4', 'k9-p08', 4, 'Thông hiểu', 'Hệ thống mô phỏng buồng lái máy bay (`Flight Simulator`) mang lại giá trị cốt lõi nào trong việc đào tạo phi công?', '["Để phi công xem phim giải trí", "Giúp học viên phi công luyện tập thành thạo kỹ năng điều khiển và xử lí các tình huống thời tiết nguy hiểm, sự cố động cơ một cách an toàn tuyệt đối trên mặt đất trước khi bay thật", "Thay thế hoàn toàn máy bay thương mại", "Giảm tốc độ của máy bay"]'::jsonb, 1, 'Mô phỏng buồng lái giúp rèn kỹ năng xử lí sự cố hiểm nghèo mà không gây bất kỳ rủi ro nào về tính mạng và phương tiện.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-5', 'k9-p08', 5, 'Thông hiểu', 'Để mô phỏng việc pha trộn các màu sắc khác nhau (ví dụ hệ màu RGB và RYB) xem tạo ra màu gì trước khi pha sơn thực tế, SGK Tin học 9 giới thiệu công cụ trực tuyến nào?', '["Phần mềm gõ tiếng Việt Unikey", "Trang web mô phỏng pha màu (như `trycolors.com`) hoặc công cụ mô phỏng ánh sáng màu trong `PhET`", "Phần mềm quản lí tệp File Explorer", "Phần mềm Calculator"]'::jsonb, 1, 'SGK Tin học 9 Bài 5 giới thiệu mô phỏng pha màu (`trycolors.com`) và mô phỏng nhìn màu sắc (`Color Vision` trên `PhET`) giúp khám phá quy tắc hợp màu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-6', 'k9-p08', 6, 'Vận dụng', 'Trong môn Toán học lớp 9, phần mềm nào sau đây là công cụ mô phỏng hình học động và đồ thị hàm số phổ biến nhất?', '["`GeoGebra`", "`WinRAR`", "`Windows Media Player`", "`Notepad`"]'::jsonb, 0, '`GeoGebra` kết hợp hình học động, đại số và bảng tính giúp dựng hình, kéo thả điểm và khám phá các tính chất toán học.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-8-7', 'k9-p08', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.D1.1), vai trò của con người khi làm việc với các phần mềm mô phỏng và mô hình dự báo AI là gì?', '["Con người không cần làm gì cả", "Con người là người xác định bài toán, thiết lập các tham số đầu vào, quan sát phân tích dữ liệu đầu ra và đưa ra kết luận khoa học", "Máy tính tự đặt mục tiêu nghiên cứu thay con người", "Chỉ nhìn hình ảnh cho vui"]'::jsonb, 1, 'Con người luôn giữ vai trò chủ thể dẫn dắt: đặt giả thuyết, thiết lập tham số thí nghiệm trên phần mềm mô phỏng và rút ra tri thức.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-1', 'k9-p09', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong mô phỏng `Các dạng năng lượng và sự chuyển hóa` trên PhET, có 5 dạng năng lượng được kí hiệu bằng 5 màu sắc gồm: Cơ năng, Điện năng, [___] năng, Quang năng và Hóa năng."', '["Nhiệt", "Điện", "Ampe kế", "Một khái niệm khác"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong mô phỏng `Các dạng năng lượng và sự chuyển hóa` trên PhET, có 5 dạng năng lượng được kí hiệu bằng 5 màu sắc gồm: Cơ năng, Điện năng, «Nhiệt» năng, Quang năng và Hóa năng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-2', 'k9-p09', 2, 'Nhận biết', 'Trong mô phỏng ''Các dạng năng lượng và sự chuyển hóa'' trên PhET (`Nhiệm vụ 1` - SGK Tin học 9), để nhìn thấy trực quan các dạng năng lượng di chuyển qua các bộ phận, em cần đánh dấu chọn vào ô nào?', '["Ô `Biểu tượng năng lượng` (`Energy Symbols`)", "Ô `Tắt âm thanh`", "Ô `Xóa tất cả`", "Ô `Đổi ngôn ngữ`"]'::jsonb, 0, 'Tích chọn `Energy Symbols` giúp hiển thị các ô vuông màu (E) đại diện cho Cơ năng, Điện năng, Nhiệt năng, Quang năng, Hóa năng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-3', 'k9-p09', 3, 'Nhận biết', 'Trong thí nghiệm ảo với hệ thống gồm: [Vòi nước chảy] -> [Tua-bin máy phát điện] -> [Bình nước có dây may-so đun nóng], sự chuyển hóa năng lượng diễn ra theo thứ tự nào?', '["Quang năng -> Điện năng -> Cơ năng", "Cơ năng (của dòng nước và tua-bin) -> Điện năng (trong dây dẫn) -> Nhiệt năng (đun sôi nước)", "Hóa năng -> Quang năng -> Nhiệt năng", "Nhiệt năng -> Hóa năng -> Điện năng"]'::jsonb, 1, 'Dòng nước chảy có cơ năng làm quay tua-bin máy phát tạo ra điện năng, điện năng qua dây điện trở biến thành nhiệt năng đun nóng nước.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-4', 'k9-p09', 4, 'Thông hiểu', 'Nếu thay ''Tua-bin máy phát điện'' ở giữa bằng ''Tấm pin Mặt Trời'', nguồn năng lượng đầu vào nào sau đây sẽ tạo ra được dòng điện?', '["Vòi nước chảy", "Người đạp xe", "Ánh sáng Mặt Trời (khi kéo thanh trượt Mây về `Không có` - `None`)", "Ấm nước đun sôi"]'::jsonb, 2, 'Tấm pin quang điện chỉ chuyển hóa Quang năng từ ánh sáng Mặt Trời thành Điện năng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-5', 'k9-p09', 5, 'Thông hiểu', 'Khi quan sát mô phỏng thắp sáng bóng đèn sợi đốt so với bóng đèn компакт/LED trên PhET, em nhận thấy điều gì về hiệu quả sử dụng năng lượng?', '["Bóng đèn sợi đốt không tỏa ra chút nhiệt năng nào", "Bóng đèn sợi đốt chuyển hóa phần lớn điện năng thành Nhiệt năng (hao phí) và chỉ một phần nhỏ thành Quang năng, trong khi đèn huỳnh quang/LED chuyển hóa thành Quang năng nhiều hơn hẳn", "Cả hai bóng đèn đều chỉ tạo ra Hóa năng", "Bóng đèn sợi đốt tạo ra Cơ năng"]'::jsonb, 1, 'Mô phỏng hiển thị rất rõ các hạt Nhiệt năng (màu đỏ) thoát ra dày đặc ở bóng đèn sợi đốt, giúp học sinh hiểu vì sao đèn LED tiết kiệm điện hơn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-6', 'k9-p09', 6, 'Vận dụng', 'Trong mô phỏng lắp ráp mạch điện trên PhET (`Nhiệm vụ 2`), lợi ích lớn nhất khi học sinh vô tình nối trực tiếp hai cực của viên pin bằng một dây dẫn (gây hiện tượng đoản mạch) trên phần mềm là gì?', '["Làm hỏng màn hình máy tính thật", "Phần mềm hiển thị hình ảnh ngọn lửa cảnh báo hiện tượng đoản mạch trực quan giúp học sinh rút kinh nghiệm sâu sắc mà hoàn toàn không gây cháy nổ hay hỏng thiết bị thật", "Làm mất điện cả trường học", "Không có hiện tượng gì xảy ra"]'::jsonb, 1, 'Mô phỏng tái hiện trực quan sự cố đoản mạch (chập điện) giúp học sinh học quy tắc an toàn điện mà không gặp nguy hiểm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-9-7', 'k9-p09', 7, 'Vận dụng', 'Từ việc thực hành Nhiệm vụ 1 và Nhiệm vụ 2 trên phần mềm mô phỏng PhET, kết luận nào sau đây là ĐÚNG về vai trò của phần mềm mô phỏng?', '["Phần mềm mô phỏng giúp kiểm chứng các định luật vật lí, thu thập số liệu đo đạc chính xác và khám phá mối quan hệ nhân quả giữa các đại lượng khoa học", "Phần mềm mô phỏng chỉ dùng để vẽ tranh", "Phần mềm mô phỏng thay thế hoàn toàn môn Toán", "Phần mềm mô phỏng không có tính chính xác"]'::jsonb, 0, 'Thông qua việc thay đổi các biến số và đo đạc trên mô phỏng, học sinh tự phát hiện và kiểm chứng tri thức khoa học.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-1', 'k9-p10', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong phần mềm `GeoGebra`, để vẽ nhanh một hình ngũ giác đều có 5 cạnh và 5 góc bằng nhau, ta chọn công cụ [___] (`Regular Polygon`) và nhập số đỉnh là `5`."', '["Đa giác đều", "ngũ giác", "1,618", "Công cụ `Đa giác đều` (`Regular Polygon`)"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong phần mềm `GeoGebra`, để vẽ nhanh một hình ngũ giác đều có 5 cạnh và 5 góc bằng nhau, ta chọn công cụ «Đa giác đều» (`Regular Polygon`) và nhập số đỉnh là `5`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-2', 'k9-p10', 2, 'Nhận biết', 'Để bắt đầu dựng hình ngôi sao 5 cánh đều chính xác trong phần mềm `GeoGebra` (`Nhiệm vụ 3` - SGK Tin học 9), bước đầu tiên em sử dụng công cụ nào?', '["Vẽ tay tự do bằng bút (`Freehand Shape`)", "Chọn công cụ `Đa giác đều` (`Regular Polygon`), lấy 2 điểm A, B rồi nhập số đỉnh `Vertices: 5` để tạo hình ngũ giác đều ABCDE", "Chọn công cụ `Hình tròn`", "Chọn công cụ `Hộp văn bản`"]'::jsonb, 1, 'Ngôi sao 5 cánh đều nội tiếp trong ngũ giác đều, nên dựng ngũ giác đều 5 đỉnh bằng `Regular Polygon` đảm bảo tính đối xứng chính xác tuyệt đối.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-3', 'k9-p10', 3, 'Nhận biết', 'Sau khi đã có hình ngũ giác đều `ABCDE`, làm thế nào để tạo ra hình ngôi sao 5 cánh đều?', '["Nối các đỉnh kề nhau AB, BC, CD", "Dùng công cụ `Đoạn thẳng` (`Segment`) nối các cặp đỉnh không kề nhau (các đường chéo `AC, CE, EB, BD, DA`)", "Xóa hết các đỉnh đi", "Tô màu toàn bộ màn hình"]'::jsonb, 1, 'Năm đường chéo của ngũ giác đều cắt nhau tạo thành hình ngôi sao năm cánh đều hoàn chỉnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-4', 'k9-p10', 4, 'Thông hiểu', 'Để xác định điểm cắt nhau `F` giữa hai đoạn thẳng `AD` và `CE` trong `GeoGebra`, em chọn công cụ nào?', '["Công cụ `Giao điểm` (`Intersect` - trong nhóm công cụ Điểm)", "Công cụ `Đa giác đều`", "Công cụ `Góc` (`Angle`)", "Công cụ `Di chuyển` (`Move`)"]'::jsonb, 0, 'Công cụ `Giao điểm` (`Intersect`) tạo điểm chính xác tại vị trí hai đường thẳng/đoạn thẳng giao nhau.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-5', 'k9-p10', 5, 'Thông hiểu', 'Công cụ nào trong `GeoGebra` dùng để hiển thị số đo độ dài của đoạn thẳng `AD`, `AG`, `AF` lên màn hình?', '["Công cụ `Khoảng cách hoặc Độ dài` (`Distance or Length` - biểu tượng `cm`)", "Công cụ `Đối xứng trục`", "Công cụ `Song song`", "Công cụ `Tiếp tuyến`"]'::jsonb, 0, 'Công cụ `Khoảng cách hoặc Độ dài` đo và hiển thị độ dài chính xác của đoạn thẳng giữa hai điểm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-6', 'k9-p10', 6, 'Vận dụng', 'Khi tính tỉ số giữa độ dài đường chéo và độ dài cạnh của hình ngũ giác đều (hoặc tỉ số độ dài đoạn lớn chia đoạn nhỏ liên tiếp trên cánh sao năm cánh đều), kết quả thu được luôn xấp xỉ hằng số nào?', '["Xấp xỉ `3,14` (số Pi)", "Xấp xỉ `1,618` (Tỉ lệ vàng - Golden Ratio)", "Xấp xỉ `2,000`", "Xấp xỉ `0,500`"]'::jsonb, 1, 'Trong ngũ giác đều và ngôi sao 5 cánh đều, tỉ số giữa các đoạn thẳng tương ứng luôn bằng Tỉ lệ vàng `(1 + √5)/2 ≈ 1,618`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-10-7', 'k9-p10', 7, 'Vận dụng', 'Thao tác nào trên `GeoGebra` giúp chứng minh thuyết phục nhất rằng Tỉ lệ vàng `≈ 1,618` là tính chất bất biến của mọi ngôi sao năm cánh đều không phụ thuộc vào kích thước?', '["Tắt màn hình máy tính", "Dùng công cụ `Di chuyển` (`Move`) kéo điểm `A` hoặc `B` để phóng to, thu nhỏ ngôi sao với nhiều kích thước khác nhau và quan sát thấy độ dài các đoạn thay đổi nhưng tỉ số của chúng luôn bằng `1,62` (`1,618`)", "Đổi màu ngôi sao sang màu xanh", "Ẩn các tên điểm"]'::jsonb, 1, 'Tính năng hình học động của `GeoGebra` cho phép biến thiên kích thước liên tục mà vẫn bảo toàn quan hệ hình học để kiểm chứng tính bất biến của tỉ số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-1', 'k9-p11', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Hai công cụ trực quan hiệu quả nhất thường được sử dụng để trình bày thông tin trong trao đổi và hợp tác nhóm là [___] và bài trình chiếu."', '["sơ đồ tư duy", "đính kèm", "đám mây", "Sơ đồ tư duy số (`Mind Map`)"]'::jsonb, 0, 'Theo SGK Tin học 9: Hai công cụ trực quan hiệu quả nhất thường được sử dụng để trình bày thông tin trong trao đổi và hợp tác nhóm là «sơ đồ tư duy» và bài trình chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-2', 'k9-p11', 2, 'Nhận biết', 'Khả năng nổi bật của phần mềm sơ đồ tư duy trên máy tính so với sơ đồ tư duy vẽ trên giấy là gì?', '["Không thể đổi màu nhánh", "Cho phép đính kèm các tệp văn bản, hình ảnh, video, bảng tính và liên kết trang web vào từng nhánh của sơ đồ", "Chỉ viết được tối đa 3 nhánh", "Không lưu lại được"]'::jsonb, 1, 'Sơ đồ tư duy số cho phép đính kèm đa phương tiện (`Attachment`/`Hyperlink`), dễ chỉnh sửa và chia sẻ hợp tác qua mạng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-3', 'k9-p11', 3, 'Nhận biết', 'Trong buổi họp nhóm đầu tiên để ''Động não (Brainstorming) tìm ý tưởng và phân chia các mảng công việc của dự án'', công cụ trực quan nào phù hợp nhất?', '["Sơ đồ tư duy (`Mind Map`)", "Máy tính bỏ túi", "Phần mềm nghe nhạc", "Trình duyệt xem phim"]'::jsonb, 0, 'Sơ đồ tư duy giúp phát triển ý tưởng tỏa nhánh từ chủ đề trung tâm và thấy ngay mối quan hệ giữa các mảng công việc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-4', 'k9-p11', 4, 'Thông hiểu', 'Khi đính kèm một tệp bảng tính kinh phí (`KinhPhi.xlsx`) vào nhánh ''Tài chính'' của sơ đồ tư duy, lợi ích đạt được là gì?', '["Làm mất tệp bảng tính", "Giữ cho sơ đồ tư duy ngắn gọn, trực quan nhưng khi cần kiểm tra số liệu chi tiết chỉ cần nháy chuột vào biểu tượng đính kèm để mở ngay trang tính", "Biến sơ đồ tư duy thành tệp âm thanh", "Xóa nhánh Tài chính"]'::jsonb, 1, 'Đính kèm tệp giúp kết hợp tính khái quát của sơ đồ tư duy với tính chi tiết của tệp dữ liệu chuyên dụng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-5', 'k9-p11', 5, 'Thông hiểu', 'Khi đưa biểu đồ từ phần mềm bảng tính Excel sang trang chiếu PowerPoint theo chế độ ''Liên kết dữ liệu'' (`Paste Link` / `Use Destination Theme & Link Data`), điều gì xảy ra khi số liệu bên tệp Excel thay đổi?', '["Biểu đồ bên PowerPoint tự động xóa", "Biểu đồ trên trang chiếu PowerPoint có thể cập nhật theo số liệu mới của tệp bảng tính Excel", "Tệp Excel bị khóa", "Không có gì thay đổi"]'::jsonb, 1, 'Liên kết dữ liệu giữa bảng tính và bài trình chiếu giúp biểu đồ luôn đồng bộ với số liệu nguồn mới nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-6', 'k9-p11', 6, 'Vận dụng', 'Để sử dụng hình ảnh, biểu đồ và video một cách HỢP LÍ trong bài trình chiếu phục vụ trao đổi, hợp tác, cần tuân thủ nguyên tắc nào?', '["Chèn càng nhiều video dài hàng tiếng đồng hồ càng tốt", "Chọn lọc hình ảnh, biểu đồ, video ngắn gọn, sát nội dung minh họa, chất lượng rõ nét và tôn trọng bản quyền tác giả", "Dùng hình ảnh không liên quan đến chủ đề", "Đặt biểu đồ cỡ siêu nhỏ không ai đọc được số"]'::jsonb, 1, 'Đa phương tiện phải phục vụ trực tiếp cho việc làm rõ thông điệp và đảm bảo tính thẩm mỹ, bản quyền.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-11-7', 'k9-p11', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.A3.1), công cụ AI có thể hỗ trợ nhóm học sinh ở khâu nào khi xây dựng sơ đồ tư duy cho dự án học tập?', '["Làm thay toàn bộ việc thuyết trình trên lớp", "Gợi ý các nhánh ý tưởng ban đầu để nhóm thảo luận, chọn lọc và mở rộng thêm các nhánh con thực tế", "Tự động chấm điểm cho giáo viên", "Xóa tệp của các thành viên khác"]'::jsonb, 1, 'AI là công cụ hỗ trợ kích hoạt ý tưởng (Brainstorming partner), còn nhóm học sinh đánh giá, lựa chọn và hoàn thiện sơ đồ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-1', 'k9-p12', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong phần mềm sơ đồ tư duy (như `MindMaple Lite`), để gắn đường dẫn mở một tệp văn bản, trang tính hoặc video vào nhánh đang chọn, ta vào thẻ `Insert` và chọn [___] (hoặc `Attachment`)."', '["Hyperlink", "liên kết", "Refresh Data", "`Insert` -> `Picture` (trên Sơ đồ tư duy)"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong phần mềm sơ đồ tư duy (như `MindMaple Lite`), để gắn đường dẫn mở một tệp văn bản, trang tính hoặc video vào nhánh đang chọn, ta vào thẻ `Insert` và chọn «Hyperlink» (hoặc `Attachment`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-2', 'k9-p12', 2, 'Nhận biết', 'Trong `Nhiệm vụ 1` (Bài 8 - SGK Tin học 9), để đính kèm tệp bảng tính hoặc tệp video vào một nhánh của sơ đồ tư duy trên phần mềm `MindMaple Lite`, em chọn nhánh đó rồi thực hiện lệnh nào?', '["Vào thẻ `File` -> `Print`", "Vào thẻ `Insert` -> chọn `Hyperlink` (hoặc `Attachment`) -> chọn tệp cần đính kèm", "Vào thẻ `View` -> `Zoom Out`", "Nhấn phím `Delete`"]'::jsonb, 1, 'Nhóm lệnh `Links` (`Hyperlink` / `Attachment`) trong thẻ `Insert` dùng để đính kèm tệp ngoài hoặc trang web vào nhánh sơ đồ tư duy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-3', 'k9-p12', 3, 'Nhận biết', 'Khi muốn chèn một bức ảnh trực tiếp vào nhánh của sơ đồ tư duy để minh họa trực quan ngay trên sơ đồ, em dùng lệnh nào?', '["`Insert` -> `Picture` -> chọn tệp ảnh", "`File` -> `Exit`", "`Format` -> `Font`", "`Review` -> `Spelling`"]'::jsonb, 0, 'Lệnh `Insert` -> `Picture` hiển thị trực tiếp hình ảnh bên trong nhánh được chọn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-4', 'k9-p12', 4, 'Thông hiểu', 'Ở `Nhiệm vụ 2` (Liên kết dữ liệu trong bài trình chiếu), sau khi `Copy` biểu đồ từ Excel, tùy chọn dán (`Paste Options`) nào trong PowerPoint giúp biểu đồ GIỮ LIÊN KẾT động với tệp bảng tính gốc?', '["`Picture (U)` (Dán dưới dạng ảnh tĩnh)", "`Use Destination Theme & Link Data (L)` hoặc `Keep Source Formatting & Link Data (F)`", "`Keep Text Only (T)`", "Gõ lại bằng tay"]'::jsonb, 1, 'Hai tùy chọn có chữ `Link Data` giúp duy trì đường dẫn liên kết giữa biểu đồ trên slide và bảng số liệu trong Excel.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-5', 'k9-p12', 5, 'Thông hiểu', 'Giả sử biểu đồ trên trang chiếu PowerPoint đã được dán theo chế độ `Link Data` với tệp Excel. Khi em sửa số liệu bên tệp Excel và lưu lại, muốn biểu đồ bên PowerPoint cập nhật ngay số liệu mới, em chọn biểu đồ rồi nháy nút nào trong thẻ `Chart Design`?', '["`Refresh Data`", "`Delete Chart`", "`Switch Row/Column`", "`Add Chart Element`"]'::jsonb, 0, 'Nút `Refresh Data` trong thẻ `Chart Design` đọc lại dữ liệu mới nhất từ tệp Excel nguồn và vẽ lại biểu đồ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-6', 'k9-p12', 6, 'Vận dụng', 'Lợi ích lớn nhất của việc trình bày sơ đồ tư duy đính kèm đa phương tiện trong buổi họp nhóm là gì?', '["Không ai phải phát biểu ý kiến", "Giúp cả nhóm vừa bao quát được toàn bộ cấu trúc kế hoạch trên 1 màn hình duy nhất, vừa mở xem được ngay bất kỳ tài liệu, video, bảng tính chi tiết nào khi thảo luận đến nhánh đó", "Làm cho cuộc họp kéo dài gấp 3 lần", "Thay thế hoàn toàn việc thực hiện dự án"]'::jsonb, 1, 'Sơ đồ tư duy đính kèm tệp đóng vai trò như một ''Bảng điều khiển trung tâm (Dashboard)'' kết nối mọi tài nguyên của dự án.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-12-7', 'k9-p12', 7, 'Vận dụng', 'Nguyên tắc quản lí tệp nào bắt buộc phải tuân thủ khi tạo sơ đồ tư duy có đính kèm tệp và bài trình chiếu có liên kết dữ liệu?', '["Lưu mỗi tệp ở một ổ đĩa khác nhau ngẫu nhiên", "Tạo một thư mục chung cho dự án và lưu tất cả các tệp (sơ đồ tư duy, bài trình chiếu, văn bản, bảng tính, ảnh, video) vào trong thư mục đó trước khi tạo liên kết", "Xóa các tệp gốc ngay sau khi tạo liên kết", "Đổi tên các tệp gốc liên tục sau khi đã gắn liên kết"]'::jsonb, 1, 'Lưu chung trong một thư mục và không tự ý xóa/đổi tên tệp gốc đảm bảo các đường dẫn liên kết không bị gãy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-1', 'k9-p13', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong bài trình chiếu báo cáo dự án, việc kết hợp hài hòa văn bản ngắn gọn với hình ảnh, sơ đồ, biểu đồ và [___] giúp thông tin sinh động, thuyết phục hơn."', '["video", "Video on My PC", "nguồn trích dẫn", "Hình ảnh minh họa (`Pictures`)"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong bài trình chiếu báo cáo dự án, việc kết hợp hài hòa văn bản ngắn gọn với hình ảnh, sơ đồ, biểu đồ và «video» giúp thông tin sinh động, thuyết phục hơn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-2', 'k9-p13', 2, 'Nhận biết', 'Khi thiết kế bài trình chiếu báo cáo dự án (`Nhiệm vụ 3` - Bài 8 SGK Tin học 9), cách sử dụng hình ảnh nào sau đây là HỢP LÍ NHẤT?', '["Chèn 12 bức ảnh khác nhau đè kín lên toàn bộ chữ của trang chiếu", "Chọn 1–2 hình ảnh sắc nét, sát nội dung trọng tâm, bố trí hài hòa với các ý chính ngắn gọn và ghi nguồn ảnh", "Kéo dãn bức ảnh theo 1 chiều ngang cho biến dạng", "Chỉ chọn những bức ảnh bị mờ vỡ hạt"]'::jsonb, 1, 'Hình ảnh trên trang chiếu cần chọn lọc chất lượng cao, đúng trọng tâm và giữ đúng tỉ lệ khung hình.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-3', 'k9-p13', 3, 'Nhận biết', 'Để nhúng trực tiếp một tệp video quay cảnh chạy phần mềm mô phỏng lưu trên máy tính vào trang chiếu PowerPoint, em chọn lệnh nào?', '["Vào thẻ `Insert` -> `Video` -> `This Device...` (hoặc `Video on My PC...`)", "Vào thẻ `Design` -> `Themes`", "Vào thẻ `Transitions` -> `Sound`", "Vào thẻ `Review` -> `Comment`"]'::jsonb, 0, 'Nhóm lệnh `Media` trong thẻ `Insert` cho phép chèn tệp `Video` và `Audio` trực tiếp từ máy tính vào trang chiếu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-4', 'k9-p13', 4, 'Thông hiểu', 'Khi muốn trình bày ''Cấu trúc 4 giai đoạn thực hiện dự án'', công cụ trực quan nào trên trang chiếu giúp người xem dễ theo dõi nhất?', '["Một đoạn văn bản dài 20 dòng", "Một sơ đồ quy trình (`SmartArt` dạng `Process`) gồm 4 bước nối tiếp nhau", "Một biểu đồ hình quạt tròn", "Một tệp âm thanh"]'::jsonb, 1, 'Sơ đồ quy trình (`SmartArt Process`) thể hiện trực quan trình tự các giai đoạn thực hiện công việc.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-5', 'k9-p13', 5, 'Thông hiểu', 'Nếu muốn biểu diễn cơ cấu tỉ lệ phần trăm (%) thời lượng dành cho các hoạt động trong buổi Triển lãm Tin học, công cụ trực quan nào phù hợp nhất?', '["Biểu đồ hình quạt tròn (`Pie Chart`)", "Danh sách gạch đầu dòng 15 dòng", "Bảng số liệu thô không định dạng", "Chân trang (`Footer`)"]'::jsonb, 0, 'Biểu đồ hình quạt tròn giúp người xem nhận biết ngay tỉ trọng % của từng phần trong tổng thể.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-6', 'k9-p13', 6, 'Vận dụng', 'Về mặt pháp lí và đạo đức số (NLC 3.3.TC2), khi sử dụng video hoặc hình ảnh của tác giả khác trên Internet để minh họa trong bài trình chiếu, em phải làm gì?', '["Xóa logo tác giả và nhận là do mình tự quay", "Chọn tư liệu từ nguồn cho phép sử dụng trong học tập và ghi rõ tên tác giả, nguồn trích dẫn trên trang chiếu hoặc trang Tài liệu tham khảo cuối bài", "Không cần ghi nguồn vì chỉ chiếu trong lớp", "Sửa đổi nội dung gây hiểu lầm về tác giả"]'::jsonb, 1, 'Ghi rõ nguồn trích dẫn và tôn trọng bản quyền là nguyên tắc bắt buộc khi tạo sản phẩm số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-13-7', 'k9-p13', 7, 'Vận dụng', 'Tính năng `Trim Video` trong thẻ `Playback` (khi chọn video trên PowerPoint) giúp ích gì cho người thuyết trình?', '["Đổi màu nền trang chiếu", "Cắt gọn phần đầu và phần cuối không cần thiết của video, chỉ giữ lại đoạn trọng tâm nhất để tiết kiệm thời gian thuyết trình", "Chuyển video thành bảng tính Excel", "Kiểm tra lỗi chính tả"]'::jsonb, 1, '`Trim Video` giúp trích xuất đúng đoạn video đắt giá nhất mà không cần dùng phần mềm dựng phim bên ngoài.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-1', 'k9-p14', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Công cụ [___] (`Data Validation`) trong thẻ `Data` của Excel dùng để quy định điều kiện hợp lệ cho dữ liệu được phép nhập vào một ô hoặc một vùng ô tính."', '["xác thực dữ liệu", "Error Alert", "List", "`Allow: List`"]'::jsonb, 0, 'Theo SGK Tin học 9: Công cụ «xác thực dữ liệu» (`Data Validation`) trong thẻ `Data` của Excel dùng để quy định điều kiện hợp lệ cho dữ liệu được phép nhập vào một ô hoặc một vùng ô tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-2', 'k9-p14', 2, 'Nhận biết', 'Chức năng chính của công cụ Xác thực dữ liệu (`Data Validation`) trong phần mềm bảng tính Excel là gì?', '["Tự động dịch bảng tính sang tiếng Anh", "Kiểm soát và giới hạn kiểu dữ liệu hoặc giá trị dữ liệu được phép nhập vào ô tính, giúp ngăn chặn lỗi nhập sai và đảm bảo tính nhất quán của dữ liệu", "Vẽ biểu đồ 3D tự động", "Đổi màu nền trang tính"]'::jsonb, 1, '`Data Validation` quy định điều kiện hợp lệ cho ô tính, giúp nhập dữ liệu nhanh, chuẩn xác và đồng nhất.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-3', 'k9-p14', 3, 'Nhận biết', 'Nút lệnh `Data Validation` nằm ở vị trí nào trên giao diện phần mềm Excel?', '["Thẻ `Home` -> nhóm `Font`", "Thẻ `Data` -> nhóm `Data Tools`", "Thẻ `Insert` -> nhóm `Charts`", "Thẻ `Page Layout` -> nhóm `Themes`"]'::jsonb, 1, 'Công cụ `Data Validation` nằm trong nhóm `Data Tools` thuộc thẻ `Data`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-4', 'k9-p14', 4, 'Thông hiểu', 'Trong bài toán Quản lí tài chính gia đình, để người dùng chỉ được chọn tên `Khoản chi` từ một danh sách có sẵn (như: Ăn uống, Điện nước, Học tập, Y tế...) mà không phải gõ tay, ta chọn tùy chọn nào tại ô `Allow` trong hộp thoại `Data Validation`?', '["`Any value`", "`List`", "`Text length`", "`Time`"]'::jsonb, 1, 'Tùy chọn `Allow: List` tạo mũi tên danh sách thả xuống (`Drop-down list`) tại ô tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-5', 'k9-p14', 5, 'Thông hiểu', 'Để quy định cột `Số tiền` chỉ cho phép nhập các số nguyên lớn hơn `0`, trong thẻ `Settings` của `Data Validation` ta thiết lập như thế nào?', '["`Allow: Whole number` -> `Data: greater than` -> `Minimum: 0`", "`Allow: List`", "`Allow: Date`", "`Allow: Any value`"]'::jsonb, 0, '`Whole number` giới hạn kiểu số nguyên, và `greater than: 0` bắt buộc giá trị nhập vào phải lớn hơn 0.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-6', 'k9-p14', 6, 'Vận dụng', 'Ba thẻ (tab) bên trong hộp thoại `Data Validation` của Excel lần lượt là gì?', '["`Home`, `Insert`, `Data`", "`Settings` (Thiết lập điều kiện), `Input Message` (Thông điệp hướng dẫn nhập), `Error Alert` (Cảnh báo lỗi khi nhập sai)", "`Font`, `Alignment`, `Number`", "`Sort`, `Filter`, `Clear`"]'::jsonb, 1, 'Hộp thoại `Data Validation` gồm đúng 3 thẻ: `Settings`, `Input Message` và `Error Alert`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-14-7', 'k9-p14', 7, 'Vận dụng', 'Khi thiết lập `Allow: List`, tại ô `Source` (Nguồn dữ liệu của danh sách), ta chỉ định thông tin gì?', '["Địa chỉ vùng các ô tính chứa danh sách các mục chuẩn (ví dụ: `=$F$3:$F$10`) hoặc các mục viết cách nhau bởi dấu phân cách", "Tên tệp Word", "Địa chỉ trang web", "Màu sắc của chữ"]'::jsonb, 0, 'Ô `Source` chứa vùng tham chiếu cố định tới danh sách các mục dùng để hiển thị trong danh sách thả xuống.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-1', 'k9-p15', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trước khi mở hộp thoại `Data Validation`, bước đầu tiên bắt buộc phải thực hiện là [___] vùng các ô tính cần áp dụng quy tắc xác thực."', '["chọn (bôi đen)", "mũi tên", "Clear All", "`Input Message`"]'::jsonb, 0, 'Theo SGK Tin học 9: Trước khi mở hộp thoại `Data Validation`, bước đầu tiên bắt buộc phải thực hiện là «chọn (bôi đen)» vùng các ô tính cần áp dụng quy tắc xác thực.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-2', 'k9-p15', 2, 'Nhận biết', 'Để áp dụng quy tắc xác thực dữ liệu (`Data Validation`) cho toàn bộ các ô từ `B3` đến `B25` cùng một lúc, em nên làm như thế nào?', '["Phải làm thủ công từng ô một mất 23 lần", "Kéo chuột bôi đen toàn bộ vùng `B3:B25` trước, sau đó vào `Data` -> `Data Validation` và thiết lập quy tắc 1 lần duy nhất", "Không thể áp dụng cho nhiều ô", "Vào thẻ `View` -> `Freeze Panes`"]'::jsonb, 1, 'Chọn trước cả vùng ô tính cần kiểm soát giúp thiết lập `Data Validation` đồng loạt cho tất cả các ô trong vùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-3', 'k9-p15', 3, 'Nhận biết', 'Trong bài thực hành quản lí tài chính gia đình (SGK trang 40), danh sách các khoản chi chuẩn (`Ở, Ăn, Học tập, Y tế, Đi lại, Khác`) được đặt ở vùng `F3:F8`. Để tạo danh sách thả xuống cho cột `Khoản chi` (`B3:B15`), tại ô `Source` của `Allow: List` ta nhập gì?', '["`=$F$3:$F$8`", "`=SUM(F3:F8)`", "`=B3:B15`", "`=F3*F8`"]'::jsonb, 0, 'Ô `Source` cần chứa địa chỉ tuyệt đối của vùng lưu danh sách các khoản mục chuẩn `=$F$3:$F$8`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-4', 'k9-p15', 4, 'Thông hiểu', 'Khi nháy chuột chọn vào ô `B3` đã được thiết lập `Data Validation`, một hộp chú thích nhỏ hiện lên ngay cạnh ô với dòng chữ `''Hãy chọn khoản chi từ danh sách''`. Nội dung này được thiết lập ở thẻ nào?', '["Thẻ `Settings`", "Thẻ `Input Message`", "Thẻ `Error Alert`", "Thẻ `Home`"]'::jsonb, 1, 'Thẻ `Input Message` quy định thông điệp hướng dẫn hiển thị ngay khi con trỏ chuột chọn vào ô tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-5', 'k9-p15', 5, 'Thông hiểu', 'Khi người dùng cố tình gõ số `-500` vào cột `Số tiền` (đã cài đặt `Whole number > 0`) và nhấn `Enter`, một hộp thoại báo lỗi hiện ra chặn lại không cho nhập. Hộp thoại này được cấu hình ở thẻ nào?', '["Thẻ `Error Alert` (với `Style: Stop`)", "Thẻ `Input Message`", "Thẻ `Page Setup`", "Thẻ `Insert`"]'::jsonb, 0, 'Thẻ `Error Alert` xử lí thông báo lỗi và ngăn chặn khi dữ liệu nhập vào vi phạm điều kiện ở thẻ `Settings`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-6', 'k9-p15', 6, 'Vận dụng', 'Nếu trong thẻ `Settings` của `Allow: List`, người dùng BỎ TÍCH ô `In-cell dropdown` thì điều gì sẽ xảy ra?', '["Ô tính bị xóa mất", "Khi nháy vào ô tính sẽ KHÔNG hiện nút mũi tên danh sách thả xuống, khiến người dùng khó chọn mục từ danh sách", "Bảng tính tự động tô màu đỏ", "Mọi dữ liệu đều bị biến thành số 0"]'::jsonb, 1, 'Ô `In-cell dropdown` phải được tích chọn thì mũi tên danh sách thả xuống mới hiển thị ở cạnh phải ô tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-15-7', 'k9-p15', 7, 'Vận dụng', 'Sau khi thiết lập xong `Data Validation` cho trang tính `Chi` và trang tính `Thu`, bước kiểm thử nào giúp đảm bảo sản phẩm bảng tính hoạt động hoàn hảo?', '["Đóng tệp ngay không cần thử", "Thử chọn các mục từ danh sách thả xuống và cố tình nhập thử 1 giá trị sai quy định để kiểm tra xem hộp thoại `Error Alert` có chặn lại đúng như thiết kế hay không", "Xóa cột danh sách nguồn `F3:F8` đi", "Đổi đuôi tệp sang `.docx`"]'::jsonb, 1, 'Kiểm thử cả dữ liệu hợp lệ và dữ liệu không hợp lệ (Negative test) giúp xác nhận quy tắc `Data Validation` đã hoạt động đúng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-1', 'k9-p16', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Hàm [___] trong phần mềm bảng tính dùng để đếm số ô tính trong một vùng dữ liệu (`range`) thỏa mãn một điều kiện (`criteria`) cho trước."', '["COUNTIF", "criteria", "tuyệt đối", "Tham số `range` (ví dụ: `$B$3:$B$15`)"]'::jsonb, 0, 'Theo SGK Tin học 9: Hàm «COUNTIF» trong phần mềm bảng tính dùng để đếm số ô tính trong một vùng dữ liệu (`range`) thỏa mãn một điều kiện (`criteria`) cho trước.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-2', 'k9-p16', 2, 'Nhận biết', 'Hàm `COUNTIF` trong phần mềm bảng tính Excel có chức năng gì?', '["Tính tổng các ô trong vùng dữ liệu", "Đếm số ô tính trong một vùng dữ liệu thỏa mãn một điều kiện cho trước", "Tìm giá trị lớn nhất trong vùng", "Tính trung bình cộng các ô số"]'::jsonb, 1, '`COUNT` là đếm, `IF` là nếu (điều kiện); `COUNTIF` dùng để đếm số ô thỏa mãn điều kiện xác định.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-3', 'k9-p16', 3, 'Nhận biết', 'Cú pháp đúng của hàm `COUNTIF` là gì?', '["`=COUNTIF(criteria, range)`", "`=COUNTIF(range, criteria)`", "`=COUNTIF(range, criteria, sum_range)`", "`=COUNTIF(logical_test, value_if_true)`"]'::jsonb, 1, 'Hàm `COUNTIF` có đúng 2 tham số theo thứ tự: `range` (vùng cần đếm) và `criteria` (điều kiện đếm).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-4', 'k9-p16', 4, 'Thông hiểu', 'Giả sử vùng `B3:B15` chứa tên các khoản thu của gia đình, ô `F3` chứa chữ `''Lương''`. Công thức nào tại ô `G3` đếm đúng số lần nhận `''Lương''` và cho phép sao chép xuống các dòng `G4:G6` mà không bị lệch vùng dữ liệu?', '["`=COUNTIF(B3:B15, F3)`", "`=COUNTIF($B$3:$B$15, F3)`", "`=COUNTIF(B3:B15, $F$3)`", "`=COUNT($B$3:$B$15, F3)`"]'::jsonb, 1, 'Phải cố định vùng dữ liệu nguồn thành `$B$3:$B$15` và để tương đối ô điều kiện `F3`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-5', 'k9-p16', 5, 'Thông hiểu', 'Nếu tại ô `G3` người dùng quên dấu `$` mà nhập `=COUNTIF(B3:B15, F3)`, khi sao chép công thức đó xuống ô `G5` (cách 2 dòng) thì công thức tại `G5` sẽ bị biến đổi thành gì?', '["`=COUNTIF($B$3:$B$15, F5)`", "`=COUNTIF(B5:B17, F5)` (làm bỏ sót mất dữ liệu ở hai ô đầu `B3` và `B4`)", "`=COUNTIF(B3:B15, F3)`", "`=COUNTIF(B1:B13, F5)`"]'::jsonb, 1, 'Khi không có dấu `$`, vùng `B3:B15` là địa chỉ tương đối nên bị trôi xuống 2 dòng thành `B5:B17`, gây sai lệch kết quả đếm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-6', 'k9-p16', 6, 'Vận dụng', 'Công thức nào sau đây đếm số ô trong vùng `D3:D20` có giá trị lớn hơn hoặc bằng `1000`?', '["`=COUNTIF(D3:D20, >=1000)`", "`=COUNTIF(D3:D20, \">=1000\")`", "`=COUNT(D3:D20, \">=1000\")`", "`=SUMIF(D3:D20, \">=1000\")`"]'::jsonb, 1, 'Khi điều kiện `criteria` chứa toán tử so sánh (`>`, `<`, `>=`, `<=`, `<>`), biểu thức điều kiện bắt buộc phải đặt trong cặp dấu ngoặc kép `">=1000"`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-16-7', 'k9-p16', 7, 'Vận dụng', 'Cho vùng `A1:A5` lần lượt chứa các giá trị: `"Ăn"`, `"Ở"`, `"Ăn"`, `"Đi lại"`, `"Ăn"`. Kết quả của công thức `=COUNTIF(A1:A5, "Ăn")` là bao nhiêu?', '["`1`", "`2`", "`3`", "`5`"]'::jsonb, 2, 'Trong vùng `A1:A5` có 3 ô chứa chuỗi `"Ăn"` (tại A1, A3, A5), nên hàm `COUNTIF` trả về kết quả là `3`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-1', 'k9-p17', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Hàm [___] trong Excel dùng để tính tổng giá trị của những ô thỏa mãn một điều kiện cho trước."', '["SUMIF", "sum_range", "tuyệt đối", "Tham số thứ nhất: `range` (`$B$3:$B$15`)"]'::jsonb, 0, 'Theo SGK Tin học 9: Hàm «SUMIF» trong Excel dùng để tính tổng giá trị của những ô thỏa mãn một điều kiện cho trước.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-2', 'k9-p17', 2, 'Nhận biết', 'Chức năng của hàm `SUMIF` trong phần mềm bảng tính là gì?', '["Đếm số ô thỏa mãn điều kiện", "Tính tổng giá trị của các ô thỏa mãn một điều kiện cho trước", "Tìm giá trị nhỏ nhất theo điều kiện", "Kiểm tra điều kiện đúng hay sai"]'::jsonb, 1, '`SUM` là tính tổng, `IF` là điều kiện; `SUMIF` tính tổng các ô số liệu tương ứng với các dòng thỏa mãn điều kiện.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-3', 'k9-p17', 3, 'Nhận biết', 'Trong cú pháp `=SUMIF(range, criteria, [sum_range])`, ý nghĩa của 3 tham số lần lượt là gì?', '["Vùng tính tổng, Vùng điều kiện, Điều kiện", "Vùng kiểm tra điều kiện (`range`), Điều kiện (`criteria`), Vùng chứa giá trị cần tính tổng (`sum_range`)", "Điều kiện, Vùng kiểm tra, Vùng tính tổng", "Giá trị đúng, Giá trị sai, Điều kiện"]'::jsonb, 1, 'Thứ tự chuẩn của `SUMIF` là: (1) `range` - vùng xét điều kiện, (2) `criteria` - điều kiện, (3) `sum_range` - vùng tính tổng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-4', 'k9-p17', 4, 'Thông hiểu', 'Trong bảng chi tiêu gia đình: cột `B` (`B3:B20`) lưu tên `Khoản chi`, cột `D` (`D3:D20`) lưu `Số tiền`, cột `F` (`F3:F8`) lưu danh sách 6 tên khoản chi chuẩn. Công thức tại ô `H3` để tính tổng tiền của khoản chi ở `F3` và sao chép xuống `H8` là gì?', '["`=SUMIF(B3:B20, F3, D3:D20)`", "`=SUMIF($B$3:$B$20, F3, $D$3:$D$20)`", "`=SUMIF($D$3:$D$20, F3, $B$3:$B$20)`", "`=COUNTIF($B$3:$B$20, F3)`"]'::jsonb, 1, 'Cả hai vùng `$B$3:$B$20` (`range`) và `$D$3:$D$20` (`sum_range`) đều phải cố định tuyệt đối bằng dấu `$`, còn ô điều kiện `F3` để tương đối.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-5', 'k9-p17', 5, 'Thông hiểu', 'Nếu người dùng viết nhầm thứ tự tham số thành `=SUMIF($D$3:$D$20, F3, $B$3:$B$20)` (đặt cột Số tiền làm `range` và cột Tên khoản chi làm `sum_range`), kết quả trả về sẽ là gì?', '["Tính ra tổng tiền hoàn toàn đúng", "Trả về kết quả bằng `0` (vì cột Số tiền `D3:D20` không có ô nào khớp với chữ tên khoản chi ở `F3` và cột chữ `B3:B20` không cộng tổng số học được)", "Máy tính tự đổi lại cho đúng", "Xóa bảng tính"]'::jsonb, 1, 'Đặt nhầm `range` và `sum_range` làm hàm tìm chữ trong cột số và cộng số trên cột chữ nên kết quả bằng `0`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-6', 'k9-p17', 6, 'Vận dụng', 'Cho bảng gồm 4 dòng: Dòng 1 (`Ăn`, `100`), Dòng 2 (`Ở`, `250`), Dòng 3 (`Ăn`, `150`), Dòng 4 (`Đi lại`, `80`). Công thức `=SUMIF(A1:A4, "Ăn", B1:B4)` cho kết quả bằng bao nhiêu?', '["`2`", "`250` (vì `100 + 150 = 250`)", "`580`", "`100`"]'::jsonb, 1, 'Hàm `SUMIF` lọc ra Dòng 1 và Dòng 3 có cột A là `"Ăn"` rồi cộng giá trị tương ứng ở cột B: `100 + 150 = 250`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-17-7', 'k9-p17', 7, 'Vận dụng', 'Công thức `=SUMIF(D3:D15, ">1000")` (chỉ có 2 tham số) thực hiện công việc gì?', '["Đếm số ô lớn hơn 1000", "Tính tổng tất cả các giá trị lớn hơn `1000` nằm ngay trong vùng `D3:D15`", "Báo lỗi thiếu tham số", "Tính trung bình cộng"]'::jsonb, 1, 'Khi lược bỏ `sum_range`, Excel tự động lấy chính vùng `range` (`D3:D15`) làm vùng tính tổng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-1', 'k9-p18', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Hàm [___] trong Excel dùng để kiểm tra một điều kiện (`logical_test`): nếu điều kiện đúng thì trả về một giá trị, nếu điều kiện sai thì trả về một giá trị khác."', '["IF", "value_if_false", "ngoặc kép", "Tham số 1: `logical_test`"]'::jsonb, 0, 'Theo SGK Tin học 9: Hàm «IF» trong Excel dùng để kiểm tra một điều kiện (`logical_test`): nếu điều kiện đúng thì trả về một giá trị, nếu điều kiện sai thì trả về một giá trị khác.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-2', 'k9-p18', 2, 'Nhận biết', 'Chức năng của hàm `IF` trong phần mềm bảng tính là gì?', '["Đếm số ô thỏa mãn điều kiện", "Tính tổng các ô thỏa mãn điều kiện", "Kiểm tra một điều kiện lôgic và trả về một giá trị nếu điều kiện Đúng, trả về giá trị khác nếu điều kiện Sai", "Sắp xếp bảng dữ liệu"]'::jsonb, 2, 'Hàm `IF` thực hiện cấu trúc rẽ nhánh có điều kiện trên trang tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-3', 'k9-p18', 3, 'Nhận biết', 'Cú pháp đúng của hàm `IF` trong Excel là gì?', '["`=IF(value_if_true, logical_test, value_if_false)`", "`=IF(logical_test, [value_if_true], [value_if_false])`", "`=IF(range, criteria)`", "`=IF(sum_range, range, criteria)`"]'::jsonb, 1, 'Thứ tự 3 tham số của `IF` là: Điều kiện kiểm tra (`logical_test`), Giá trị khi Đúng (`value_if_true`), Giá trị khi Sai (`value_if_false`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-4', 'k9-p18', 4, 'Thông hiểu', 'Cho ô `A1 = 65%`. Công thức `=IF(A1>50%, "Vượt mức", "Đạt chuẩn")` sẽ trả về kết quả nào?', '["`\"Đạt chuẩn\"`", "`\"Vượt mức\"`", "`65%`", "`#NAME?`"]'::jsonb, 1, 'Vì `65% > 50%` là Đúng (`TRUE`), hàm `IF` trả về tham số thứ hai là `"Vượt mức"`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-5', 'k9-p18', 5, 'Thông hiểu', 'Nếu người dùng nhập công thức `=IF(N3>50%, Nhiều quá, Hợp lí)` (không có dấu ngoặc kép quanh chữ), Excel sẽ báo lỗi gì?', '["Lỗi `#NAME?` (vì chuỗi văn bản trong công thức không đặt trong dấu ngoặc kép nên Excel tưởng là tên hàm/tên vùng không tồn tại)", "Lỗi `######`", "Lỗi `#DIV/0!`", "Chạy bình thường"]'::jsonb, 0, 'Mọi hằng xâu kí tự bên trong công thức Excel đều bắt buộc phải đặt trong cặp dấu ngoặc kép `" "`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-6', 'k9-p18', 6, 'Vận dụng', 'Theo quy tắc quản lí tài chính 50-30-20 được giới thiệu trong SGK Tin học 9, ba con số `50% - 30% - 20%` lần lượt tương ứng với 3 nhóm nào?', '["50% Giải trí - 30% Tiết kiệm - 20% Thiết yếu", "50% Nhu cầu thiết yếu - 30% Mong muốn cá nhân - 20% Tiết kiệm", "50% Đi vay - 30% Mua xe - 20% Ăn uống", "50% Học tập - 30% Y tế - 20% Điện nước"]'::jsonb, 1, 'Quy tắc 50-30-20 chia thu nhập thành: 50% Nhu cầu thiết yếu, 30% Mong muốn và 20% Tiết kiệm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-18-7', 'k9-p18', 7, 'Vận dụng', 'Cho công thức hàm `IF` lồng nhau: `=IF(DTB>=8, "Giỏi", IF(DTB>=6.5, "Khá", "Đạt"))`. Nếu `DTB = 7.2` thì công thức trả về kết quả gì?', '["`\"Giỏi\"`", "`\"Khá\"`", "`\"Đạt\"`", "`7.2`"]'::jsonb, 1, 'Với `DTB = 7.2`, điều kiện đầu `7.2 >= 8` là Sai nên xét sang hàm `IF` thứ hai; tại đây `7.2 >= 6.5` là Đúng nên trả về `"Khá"`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-1', 'k9-p19', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Khi lưu ngưỡng tỉ lệ quy định (`50%`, `30%`) vào cột `M` (`M3`, `M4`) và tỉ lệ thực tế vào cột `N` (`N3`, `N4`), việc viết điều kiện `N3>M3` trong hàm `IF` giúp dễ dàng [___] công thức từ dòng 3 xuống dòng 4."', '["sao chép", "hai (2)", "<>", "`=IF(N3>M3, \"Nhiều quá\", \"Hợp lí\")`"]'::jsonb, 0, 'Theo SGK Tin học 9: Khi lưu ngưỡng tỉ lệ quy định (`50%`, `30%`) vào cột `M` (`M3`, `M4`) và tỉ lệ thực tế vào cột `N` (`N3`, `N4`), việc viết điều kiện `N3>M3` trong hàm `IF` giúp dễ dàng «sao chép» công thức từ dòng 3 xuống dòng 4.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-2', 'k9-p19', 2, 'Nhận biết', 'Trong bảng phân tích chi tiêu theo quy tắc 50-30-20 (SGK trang 50), cột `M` lưu tỉ lệ quy định (`M3 = 50%`, `M4 = 30%`), cột `N` lưu tỉ lệ chi thực tế (`N3`, `N4`). Công thức nào tại ô `O3` cho phép sao chép trực tiếp xuống `O4` để đánh giá đúng cả 2 nhóm?', '["`=IF(N3>50%, \"Nhiều quá\", \"Hợp lí\")`", "`=IF(N3>M3, \"Nhiều quá\", \"Hợp lí\")`", "`=IF($N$3>$M$3, \"Nhiều quá\", \"Hợp lí\")`", "`=SUMIF(N3, M3)`"]'::jsonb, 1, 'Dùng địa chỉ tương đối `N3>M3` giúp khi sao chép từ `O3` xuống `O4` công thức tự động đổi thành `=IF(N4>M4, "Nhiều quá", "Hợp lí")`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-3', 'k9-p19', 3, 'Nhận biết', 'Công thức hàm `IF` lồng nhau nào sau đây là ĐÚNG cú pháp để phân loại tỉ lệ thực tế `N3` so với mức quy định `M3` thành 3 mức (`"Nhiều quá"`, `"Ít quá"`, `"Hợp lí"`)?', '["`=IF(N3>M3, \"Nhiều quá\", IF(N3<M3, \"Ít quá\", \"Hợp lí\"))`", "`=IF(N3>M3, \"Nhiều quá\", \"Hợp lí\", IF(N3<M3, \"Ít quá\"))`", "`=IF(N3>M3 AND N3<M3, \"Hợp lí\")`", "`=IF(N3>M3, \"Nhiều quá\", (N3<M3, \"Ít quá\", \"Hợp lí\"))`"]'::jsonb, 0, 'Hàm `IF` thứ hai được đặt vào vị trí tham số thứ ba (`value_if_false`) của hàm `IF` thứ nhất và đóng đủ 2 dấu ngoặc đơn ở cuối.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-4', 'k9-p19', 4, 'Thông hiểu', 'Trong Excel, phép toán so sánh ''Lớn hơn hoặc bằng'' và ''Khác nhau'' được viết như thế nào trong biểu thức `logical_test` của hàm `IF`?', '["`≥` và `≠`", "`>=` và `<>`", "`=>` và `!=`", "`>>` và `><`"]'::jsonb, 1, 'Trong công thức Excel, ''lớn hơn hoặc bằng'' viết là `>=`, ''nhỏ hơn hoặc bằng'' viết là `<=`, và ''khác'' viết là `<>`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-5', 'k9-p19', 5, 'Thông hiểu', 'Giả sử `M3 = 50%`, `N3 = 50%`. Kết quả của công thức `=IF(N3>M3, "Nhiều quá", IF(N3<M3, "Ít quá", "Hợp lí"))` là gì?', '["`\"Nhiều quá\"`", "`\"Ít quá\"`", "`\"Hợp lí\"`", "`0`"]'::jsonb, 2, 'Vì `50% > 50%` là Sai và `50% < 50%` cũng là Sai, nên hàm trả về giá trị cuối cùng là `"Hợp lí"`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-6', 'k9-p19', 6, 'Vận dụng', 'Lỗi gì sẽ xảy ra nếu khi gõ hàm `IF` lồng nhau, người dùng thiếu dấu phẩy `,` (hoặc dấu chấm phẩy `;`) ngăn cách giữa các tham số?', '["Excel bật hộp thoại cảnh báo lỗi cú pháp công thức (`There''s a problem with this formula`) và không thực hiện được phép tính", "Excel tự động xóa trang tính", "Máy tính tự tắt màn hình", "Kết quả luôn bằng 100"]'::jsonb, 0, 'Các tham số trong hàm bắt buộc phải được phân tách đúng bằng dấu ngăn cách đối số theo cấu hình máy (`,` hoặc `;`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-19-7', 'k9-p19', 7, 'Vận dụng', 'Sau khi dùng hàm `IF` xuất ra chữ `"Nhiều quá"` ở cột `Đánh giá`, tính năng nào trong thẻ `Home` giúp tự động tô nền màu đỏ cảnh báo cho những ô có chữ `"Nhiều quá"`?', '["`Conditional Formatting` (`Highlight Cells Rules` -> `Text that Contains...`)", "`Merge & Center`", "`Wrap Text`", "`Format Painter`"]'::jsonb, 0, '`Conditional Formatting` giúp định dạng màu sắc tự động dựa trên giá trị kết quả của ô tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-1', 'k9-p20', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để tham chiếu đến một ô tính nằm ở trang tính khác trong cùng sổ tính Excel, ta viết theo cú pháp: `=Tên_trang_tính[___]Địa_chỉ_ô` (dấu chấm than ở giữa)."', '["!", "nháy đơn ('' '')", "=B4-B5", "`=Thu!H7`"]'::jsonb, 0, 'Theo SGK Tin học 9: Để tham chiếu đến một ô tính nằm ở trang tính khác trong cùng sổ tính Excel, ta viết theo cú pháp: `=Tên_trang_tính«!»Địa_chỉ_ô` (dấu chấm than ở giữa).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-2', 'k9-p20', 2, 'Nhận biết', 'Kí hiệu nào được sử dụng trong công thức Excel để ngăn cách giữa `Tên trang tính` và `Địa chỉ ô` khi tham chiếu liên trang tính?', '["Dấu chấm `.`", "Dấu chấm than `!`", "Dấu hai chấm `:`", "Dấu đô la `$`"]'::jsonb, 1, 'Cú pháp chuẩn để tham chiếu đến ô ở trang tính khác là `Tên_trang_tính!Địa_chỉ_ô` (dùng dấu chấm than `!`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-3', 'k9-p20', 3, 'Nhận biết', 'Tại ô `B4` của trang tính `Tổng hợp`, muốn lấy giá trị của ô `H7` nằm bên trang tính `Thu`, công thức nào sau đây là ĐÚNG?', '["`=Thu:H7`", "`=Thu!H7`", "`=Thu.H7`", "`=H7!Thu`"]'::jsonb, 1, '`=Thu!H7` tham chiếu chính xác đến ô `H7` của trang tính `Thu`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-4', 'k9-p20', 4, 'Thông hiểu', 'Nếu trang tính chứa dữ liệu có tên là `Chi tiêu tháng 10` (có chứa dấu cách), công thức tham chiếu đến ô `D15` của trang tính đó được viết như thế nào?', '["`=Chi tiêu tháng 10!D15`", "`=''Chi tiêu tháng 10''!D15`", "`=\"Chi tiêu tháng 10\"!D15`", "`=(Chi tiêu tháng 10)!D15`"]'::jsonb, 1, 'Khi tên trang tính có khoảng trắng, Excel đặt tên trang tính trong cặp dấu nháy đơn `'' ''` trước dấu `!`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-5', 'k9-p20', 5, 'Thông hiểu', 'Trên trang tính `Chi` (SGK trang 53), để tính tỉ lệ chi tiêu của nhóm ''Nhu cầu thiết yếu'' (có tổng tiền ở ô `M3` của trang `Chi`) so với `Tổng thu nhập` (nằm ở ô `H7` của trang tính `Thu`), công thức đúng tại ô `N3` của trang `Chi` là gì?', '["`=M3/H7`", "`=M3/Thu!$H$7`", "`=Chi!M3*Thu!H7`", "`=SUM(M3, Thu!H7)`"]'::jsonb, 1, 'Lấy số tiền chi ở ô `M3` chia cho Tổng thu nhập ở ô `Thu!$H$7` (cố định `$H$7` để sao chép xuống `N4`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-6', 'k9-p20', 6, 'Vận dụng', 'Ưu điểm lớn nhất của việc sử dụng công thức tham chiếu liên trang tính (`=Thu!H7`, `=Chi!H9`) trên trang tính `Tổng hợp` là gì?', '["Làm giảm số lượng trang tính", "Đảm bảo tính nhất quán và cập nhật tự động: mọi thay đổi ở trang `Thu` và `Chi` đều được phản ánh tức thời trên trang `Tổng hợp` mà không cần sửa lại bằng tay", "Không cần dùng công thức", "Biến số liệu thành văn bản"]'::jsonb, 1, 'Tham chiếu liên trang tính tạo kết nối động xuyên suốt toàn bộ sổ tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-20-7', 'k9-p20', 7, 'Vận dụng', 'Để thêm một trang tính mới đặt tên là `Tổng hợp` và đưa nó lên vị trí đầu tiên bên trái của thanh nhãn trang tính (Sheet tabs), em thực hiện thế nào?', '["Nháy nút dấu `+` (`New sheet`), nháy đúp vào tên trang tính mới để đổi tên thành `Tổng hợp`, rồi kéo thả nhãn trang tính đó sang vị trí đầu tiên bên trái", "Vào thẻ `Data` -> `Sort`", "Nhấn phím `F4`", "Đóng phần mềm Excel"]'::jsonb, 0, 'Nháy đúp vào Sheet tab để đổi tên (`Rename`) và kéo thả chuột để sắp xếp vị trí các trang tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-1', 'k9-p21', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Để các con số tiền tệ lớn (như `15000000`) dễ đọc hơn thành `15,000,000`, ta chọn vùng số liệu và sử dụng nút lệnh định dạng phân cách hàng nghìn [___] (`Comma Style`) trong nhóm `Number` (thẻ `Home`)."', '[",", "Ctrl", "Mong muốn", "Trang tính `Thu`"]'::jsonb, 0, 'Theo SGK Tin học 9: Để các con số tiền tệ lớn (như `15000000`) dễ đọc hơn thành `15,000,000`, ta chọn vùng số liệu và sử dụng nút lệnh định dạng phân cách hàng nghìn «,» (`Comma Style`) trong nhóm `Number` (thẻ `Home`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-2', 'k9-p21', 2, 'Nhận biết', 'Để hoàn thiện bảng tính `TaiChinhGiaDinh.xlsx` (SGK trang 53–54), các trang tính cần có trong sổ tính này là gì?', '["Chỉ cần 1 trang tính `Nháp`", "Gồm 3 trang tính được kết nối dữ liệu với nhau: `Tổng hợp`, `Thu` và `Chi`", "Gồm 10 trang văn bản Word", "Chỉ gồm biểu đồ không có bảng số"]'::jsonb, 1, 'Sổ tính quản lí tài chính gia đình hoàn chỉnh gồm 3 trang tính `Tổng hợp`, `Thu` và `Chi`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-3', 'k9-p21', 3, 'Nhận biết', 'Trên trang tính `Tổng hợp`, để so sánh trực quan độ lớn giữa `Tổng thu` và `Tổng chi` trong tháng, dạng biểu đồ nào phù hợp nhất?', '["Biểu đồ cột (`Column Chart`)", "Biểu đồ phân tán (`Scatter`)", "Biểu đồ radar", "Không thể vẽ biểu đồ"]'::jsonb, 0, 'Biểu đồ cột giúp so sánh trực tiếp độ cao (số tiền) giữa Tổng thu và Tổng chi.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-4', 'k9-p21', 4, 'Thông hiểu', 'Trên trang tính `Chi`, để thể hiện tỉ trọng phần trăm (%) của từng khoản chi (`Ở, Ăn, Học tập, Y tế, Đi lại, Giải trí`) trong tổng chi tiêu, dạng biểu đồ nào thích hợp nhất?', '["Biểu đồ đoạn thẳng (`Line Chart`)", "Biểu đồ hình quạt tròn (`Pie Chart`)", "Biểu đồ miền", "Biểu đồ hộp"]'::jsonb, 1, 'Biểu đồ hình quạt tròn thể hiện rõ nhất cơ cấu tỉ lệ % của từng khoản chi trong tổng chi tiêu 100%.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-5', 'k9-p21', 5, 'Thông hiểu', 'Khi định dạng cột `Số tiền`, thao tác nào giúp các con số hiển thị dấu phân cách hàng nghìn (ví dụ `5,250,000`) giúp dễ đọc và tránh nhầm số chữ số 0?', '["Vào thẻ `Home` -> nhóm `Number` -> nháy nút `,` (`Comma Style`) và giảm chữ số thập phân (`Decrease Decimal`)", "Vào thẻ `Insert` -> `Shapes`", "Vào thẻ `Data` -> `Filter`", "Gõ chữ triệu vào sau con số"]'::jsonb, 0, 'Định dạng `Comma Style` trong nhóm `Number` hiển thị dấu phân cách hàng nghìn trong khi vẫn giữ nguyên kiểu dữ liệu Số để tính toán.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-6', 'k9-p21', 6, 'Vận dụng', 'Nếu người dùng gõ trực tiếp chữ `''500 nghìn''` (vừa số vừa chữ) vào ô `Số tiền` thay vì nhập số `500`, điều gì sẽ xảy ra?', '["Hàm `SUMIF` tính nhanh hơn", "Ô đó bị coi là dữ liệu kiểu Văn bản (`Text`), bị `Data Validation` chặn lại hoặc làm hàm `SUMIF`/`SUM` bỏ qua không cộng được", "Tự động đổi thành đô la", "Biểu đồ đẹp hơn"]'::jsonb, 1, 'Cột `Số tiền` bắt buộc chỉ chứa giá trị kiểu Số thuần túy; đơn vị tính (nghìn đồng / VNĐ) được ghi ở tiêu đề cột hoặc định dạng `Number Format`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-21-7', 'k9-p21', 7, 'Vận dụng', 'Sau khi hoàn thiện toàn bộ công thức trên cả 3 trang tính, nếu em thêm một khoản chi mới `''Đi du lịch: 3,000 (nghìn đồng)''` vào bảng nhật ký trang `Chi`, những thành phần nào sẽ TỰ ĐỘNG CẬP NHẬT?', '["Không thành phần nào tự cập nhật", "Tất cả đều tự động cập nhật: `COUNTIF`, `SUMIF`, tỉ lệ 50-30-20, nhận xét hàm `IF`, số liệu `Tổng chi`/`Tiết kiệm` bên trang `Tổng hợp` và các biểu đồ", "Chỉ có trang `Thu` thay đổi", "Phải vẽ lại biểu đồ từ đầu"]'::jsonb, 1, 'Đó chính là sức mạnh của mô hình bảng tính tự động hóa từ khâu nhập liệu đến trang tổng hợp và biểu đồ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-1', 'k9-p22', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Quá trình giải quyết một vấn đề trong học tập và đời sống thường gồm [___] bước cơ bản theo trình tự logic."', '["năm (5)", "Phân tích", "Đánh giá", "Bước 1 & Bước 2 (Tìm hiểu & Phân tích)"]'::jsonb, 0, 'Theo SGK Tin học 9: Quá trình giải quyết một vấn đề trong học tập và đời sống thường gồm «năm (5)» bước cơ bản theo trình tự logic.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-2', 'k9-p22', 2, 'Nhận biết', 'Quy trình giải quyết vấn đề được trình bày trong SGK Tin học 9 (Bài 14) gồm bao nhiêu bước và theo thứ tự nào?', '["3 bước: Nhập -> Xử lí -> Xuất", "5 bước: (1) Tìm hiểu vấn đề -> (2) Phân tích vấn đề -> (3) Lựa chọn giải pháp -> (4) Thực hiện giải pháp -> (5) Đánh giá kết quả", "2 bước: Làm thử -> Bỏ cuộc", "4 bước: Sao chép -> Dán -> In -> Nộp"]'::jsonb, 1, 'Quy trình giải quyết vấn đề chuẩn gồm 5 bước: Tìm hiểu -> Phân tích -> Lựa chọn giải pháp -> Thực hiện -> Đánh giá.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-3', 'k9-p22', 3, 'Nhận biết', 'Hoạt động ''Chia một nhiệm vụ dự án lớn thành các công việc nhỏ hơn và tìm mối liên hệ giữa dữ kiện đã cho với mục tiêu cần đạt'' thuộc bước nào?', '["Bước 1: Tìm hiểu vấn đề", "Bước 2: Phân tích vấn đề", "Bước 4: Thực hiện giải pháp", "Bước 5: Đánh giá kết quả"]'::jsonb, 1, 'Phân tích vấn đề (Bước 2) giúp bóc tách cấu trúc bên trong và chia bài toán lớn thành các bài toán con.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-4', 'k9-p22', 4, 'Thông hiểu', 'Khi nhóm học sinh thảo luận 3 cách khác nhau để gây quỹ từ thiện cho lớp, sau đó so sánh tính khả thi và quyết định chọn phương án ''Thu gom giấy vụn và làm đồ tái chế'', nhóm đang thực hiện bước nào?', '["Bước 1: Tìm hiểu vấn đề", "Bước 3: Lựa chọn giải pháp", "Bước 4: Thực hiện giải pháp", "Bước 5: Đánh giá kết quả"]'::jsonb, 1, 'Đề xuất các phương án và cân nhắc chọn ra phương án tối ưu thuộc Bước 3: Lựa chọn giải pháp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-5', 'k9-p22', 5, 'Thông hiểu', 'Tại sao Bước 5 (Đánh giá kết quả) lại không thể thiếu sau khi đã thực hiện xong giải pháp?', '["Để làm tốn thêm thời gian", "Để kiểm tra xem vấn đề đã được giải quyết đúng mục tiêu chưa, phát hiện sai sót để khắc phục và rút ra bài học kinh nghiệm cho các lần sau", "Để xóa bỏ kết quả vừa làm", "Chỉ để trang trí báo cáo"]'::jsonb, 1, 'Đánh giá kết quả giúp xác nhận chất lượng đầu ra và cải tiến liên tục.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-6', 'k9-p22', 6, 'Vận dụng', 'Trong bài toán ''Tổ chức buổi dã ngoại cuối cấp cho lớp 9A'', việc xác định rõ ''Số lượng học sinh tham gia, ngân sách tối đa mỗi bạn và thời gian cho phép (1 ngày Chủ nhật)'' thuộc bước nào?', '["Bước 1: Tìm hiểu vấn đề (xác định các điều kiện đã cho và yêu cầu cần đạt)", "Bước 4: Thực hiện giải pháp", "Bước 5: Đánh giá kết quả", "Không thuộc bước nào"]'::jsonb, 0, 'Xác định rõ đầu vào, ràng buộc và mục tiêu là nội dung cốt lõi của Bước 1: Tìm hiểu vấn đề.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-22-7', 'k9-p22', 7, 'Vận dụng', 'Khi áp dụng quy trình 5 bước để giải quyết vấn đề có sự hỗ trợ của công cụ AI, con người giữ vai trò quyết định ở những bước nào?', '["Con người giao phó cả 5 bước cho AI tự làm hết", "Con người chủ trì toàn bộ quy trình, đặc biệt là Tìm hiểu, Phân tích, Lựa chọn giải pháp và Đánh giá thẩm định kết quả; AI chỉ là công cụ hỗ trợ gợi ý và thực thi nhanh ở một số công đoạn", "Con người chỉ làm Bước 4", "Không cần bước Đánh giá"]'::jsonb, 1, 'Con người là chủ thể định hướng mục tiêu và chịu trách nhiệm thẩm định kết quả cuối cùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-1', 'k9-p23', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Một giải pháp được mô tả thành dãy hữu hạn các bước sắp xếp theo trình tự xác định sao cho sau khi thực hiện hết các bước đó thì đạt được mục tiêu gọi là một [___]."', '["thuật toán", "sơ đồ khối", "thoi", "Hình Ô van & Hình Bình hành"]'::jsonb, 0, 'Theo SGK Tin học 9: Một giải pháp được mô tả thành dãy hữu hạn các bước sắp xếp theo trình tự xác định sao cho sau khi thực hiện hết các bước đó thì đạt được mục tiêu gọi là một «thuật toán».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-2', 'k9-p23', 2, 'Nhận biết', 'Trong sơ đồ khối mô tả thuật toán, HÌNH BÌNH HÀNH được quy ước dùng để biểu diễn thao tác nào?', '["Bắt đầu và Kết thúc thuật toán", "Nhập dữ liệu đầu vào (Input) hoặc Xuất dữ liệu đầu ra (Output)", "Kiểm tra điều kiện Đúng/Sai", "Thực hiện phép gán số học"]'::jsonb, 1, 'Theo quy ước sơ đồ khối trong SGK Tin học 9 (trang 61), hình bình hành biểu diễn thao tác Nhập/Xuất dữ liệu.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-3', 'k9-p23', 3, 'Nhận biết', 'Trong sơ đồ khối, HÌNH CHỮ NHẬT và HÌNH THOI lần lượt biểu diễn những thao tác nào?', '["Hình chữ nhật: Nhập dữ liệu; Hình thoi: Kết thúc", "Hình chữ nhật: Các phép tính toán/xử lí; Hình thoi: Kiểm tra điều kiện (Đúng/Sai)", "Hình chữ nhật: Kiểm tra điều kiện; Hình thoi: Tính toán", "Cả hai đều dùng để bắt đầu"]'::jsonb, 1, 'Hình chữ nhật dùng cho bước xử lí/tính toán, còn hình thoi dùng cho bước kiểm tra điều kiện rẽ nhánh hoặc lặp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-4', 'k9-p23', 4, 'Thông hiểu', 'Hai phương pháp phổ biến nhất để mô tả một thuật toán là gì?', '["Vẽ tranh sơn dầu và chụp ảnh", "Liệt kê các bước (bằng ngôn ngữ tự nhiên) và vẽ sơ đồ khối", "Ghi âm giọng nói và quay video", "Lọc dữ liệu và tạo biểu đồ"]'::jsonb, 1, 'Thuật toán thường được mô tả bằng cách liệt kê tuần tự các bước hoặc biểu diễn trực quan bằng sơ đồ khối.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-5', 'k9-p23', 5, 'Thông hiểu', 'Cho thuật toán sau: Bước 1: Nhập số giờ làm việc `t` và thù lao 1 giờ `a`. Bước 2: Nếu `t <= 40` thì `Lương ← t * a`, ngược lại thì `Lương ← (40 + (t - 40) * 1.5) * a`. Bước 3: Thông báo `Lương`. Bước 2 sử dụng cấu trúc điều khiển nào?', '["Cấu trúc tuần tự thuần túy", "Cấu trúc rẽ nhánh dạng đủ (`Nếu ... thì ... ngược lại ...`)", "Cấu trúc lặp vô hạn", "Không có cấu trúc điều khiển"]'::jsonb, 1, 'Bước 2 kiểm tra điều kiện `t <= 40` để tính theo 1 trong 2 công thức khác nhau nên là cấu trúc rẽ nhánh dạng đủ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-6', 'k9-p23', 6, 'Vận dụng', 'Ưu điểm nổi bật của việc biểu diễn giải pháp dưới dạng sơ đồ khối là gì?', '["Không cần xác định điều kiện dừng", "Thể hiện trực quan, rõ ràng trình tự thực hiện và các nhánh rẽ, vòng lặp của thuật toán thông qua các khối hình chuẩn và mũi tên", "Làm cho thuật toán dài gấp 10 lần", "Tự động biến thành tệp âm thanh"]'::jsonb, 1, 'Sơ đồ khối giúp người đọc nắm bắt ngay luồng điều khiển (control flow) của giải pháp.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-23-7', 'k9-p23', 7, 'Vận dụng', 'Vì sao việc mô tả được giải pháp dưới dạng thuật toán lại là cầu nối quan trọng để chuyển giao công việc cho máy tính thực hiện?', '["Vì máy tính chỉ làm việc theo cảm hứng", "Vì máy tính hoạt động theo chương trình, mà chương trình chính là bản dịch trực tiếp từ các bước của thuật toán sang ngôn ngữ lập trình", "Vì máy tính không biết tính toán", "Vì thuật toán chỉ dùng để in ra giấy"]'::jsonb, 1, 'Khi giải pháp đã được tường minh hóa thành thuật toán, người lập trình có thể chuyển hóa ngay thành chương trình máy tính.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-1', 'k9-p24', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong tin học, [___] là một công việc hay một nhiệm vụ cần giải quyết mà con người có thể giao cho máy tính thực hiện."', '["bài toán", "Đầu vào", "thuật toán", "Bài toán: Tính tiền lương làm việc theo giờ"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong tin học, «bài toán» là một công việc hay một nhiệm vụ cần giải quyết mà con người có thể giao cho máy tính thực hiện.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-2', 'k9-p24', 2, 'Nhận biết', 'Trong lĩnh vực Tin học, khái niệm ''Bài toán'' được hiểu là gì?', '["Chỉ là các bài tập tính cộng trừ nhân chia trong sách giáo khoa Toán", "Là một nhiệm vụ hay công việc bất kỳ (tính toán, tìm kiếm, sắp xếp, quản lí, điều khiển...) có thể giao cho máy tính thực hiện thông qua thuật toán và chương trình", "Là một lỗi phần cứng của máy tính", "Là một thiết bị ngoại vi"]'::jsonb, 1, 'Theo SGK Tin học 9 (Bài 15), bài toán tin học là một nhiệm vụ có thể giao cho máy tính thực hiện.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-3', 'k9-p24', 3, 'Nhận biết', 'Khi phát biểu một bài toán tin học để chuẩn bị giao cho máy tính giải quyết, hai thành phần bắt buộc phải xác định rõ là gì?', '["Màu sắc màn hình và Tốc độ chuột", "Đầu vào (`Input`) và Đầu ra (`Output`)", "Tên người dùng và Mật khẩu", "Đầu trang và Chân trang"]'::jsonb, 1, 'Mọi bài toán tin học đều được đặc tả bởi cặp thông tin: Đầu vào (`Input`) và Đầu ra (`Output`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-4', 'k9-p24', 4, 'Thông hiểu', 'Cho bài toán: ''Tính chỉ số khối cơ thể BMI của một người, biết công thức `BMI = Cân_nặng / (Chiều_cao * Chiều_cao)`''. Đầu vào (`Input`) và Đầu ra (`Output`) của bài toán này là gì?', '["`Input`: Chỉ số BMI; `Output`: Cân nặng và Chiều cao", "`Input`: Cân nặng (kg) và Chiều cao (m) của người đó; `Output`: Giá trị chỉ số BMI tính được", "`Input`: Tên người đó; `Output`: Tuổi của người đó", "Không có Input và Output"]'::jsonb, 1, 'Dữ liệu cần cung cấp cho máy tính là Cân nặng và Chiều cao (`Input`), kết quả máy tính trả về là chỉ số BMI (`Output`).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-5', 'k9-p24', 5, 'Thông hiểu', 'Trong bài toán ''Tìm kiếm xem bạn Nguyễn Văn An có tên trong danh sách trúng tuyển vào lớp 10 hay không'', Đầu vào (`Input`) là gì?', '["Câu trả lời Có hoặc Không", "Danh sách họ tên các thí sinh trúng tuyển và tên cần tìm `''Nguyễn Văn An''`", "Chỉ có chữ `''An''`", "Số lượng phòng học của trường"]'::jsonb, 1, 'Để tìm kiếm, máy tính phải được cung cấp cả Danh sách dữ liệu cần tra cứu lẫn Từ khóa cần tìm làm `Input`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-6', 'k9-p24', 6, 'Vận dụng', 'Điều kiện tiên quyết để một nhiệm vụ thực tế có thể chuyển giao cho máy tính tự động thực hiện là gì?', '["Nhiệm vụ đó phải làm bằng tay trong 1 giây", "Con người phải xác định được rõ `Input`, `Output` và xây dựng được thuật toán (quy trình hữu hạn các bước rõ ràng) để giải quyết nhiệm vụ đó", "Máy tính phải được sơn màu đen", "Không cần viết chương trình"]'::jsonb, 1, 'Máy tính chỉ giải quyết được bài toán khi con người chỉ ra được thuật toán biến đổi từ `Input` sang `Output`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-24-7', 'k9-p24', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.D1.1), trong một ứng dụng AI dịch văn bản từ tiếng Anh sang tiếng Việt, `Input` và `Output` là gì và ai là người xác định yêu cầu bài toán?', '["`Input`: Đoạn văn bản tiếng Anh cần dịch; `Output`: Đoạn văn bản tiếng Việt tương ứng; Con người là người xác định bài toán và đánh giá chất lượng bản dịch", "`Input`: Tiếng Việt; `Output`: Tiếng Pháp", "Không có `Input`", "AI tự sinh ra nhu cầu dịch mà không cần người dùng"]'::jsonb, 0, 'Trong mọi hệ thống tính toán và AI, việc xác định đúng dữ liệu đầu vào và mục tiêu đầu ra luôn do con người đảm nhiệm.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-1', 'k9-p25', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Quy trình con người giao bài toán cho máy tính giải quyết gồm [___] bước: Xác định bài toán -> Tìm thuật toán -> Viết chương trình -> Kiểm thử và gỡ lỗi."', '["bốn (4)", "chương trình", "Kiểm thử", "Bước 2: Tìm thuật toán"]'::jsonb, 0, 'Theo SGK Tin học 9: Quy trình con người giao bài toán cho máy tính giải quyết gồm «bốn (4)» bước: Xác định bài toán -> Tìm thuật toán -> Viết chương trình -> Kiểm thử và gỡ lỗi.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-2', 'k9-p25', 2, 'Nhận biết', 'Thứ tự đúng của 4 bước trong quy trình giao bài toán cho máy tính giải quyết (SGK Tin học 9 Bài 15) là gì?', '["Viết chương trình -> Xác định bài toán -> Tìm thuật toán -> Kiểm thử", "(1) Xác định bài toán -> (2) Tìm thuật toán -> (3) Viết chương trình -> (4) Kiểm thử và gỡ lỗi", "Kiểm thử -> Viết chương trình -> Tìm thuật toán -> Xác định bài toán", "Chỉ gồm 1 bước duy nhất là Viết chương trình"]'::jsonb, 1, 'Quy trình chuẩn gồm 4 bước tuần tự: Xác định bài toán (Input/Output) -> Tìm thuật toán -> Viết chương trình -> Kiểm thử và gỡ lỗi.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-3', 'k9-p25', 3, 'Nhận biết', 'Công việc ''Mô tả giải pháp giải bài toán bằng sơ đồ khối hoặc liệt kê từng bước xử lí'' thuộc bước nào trong quy trình giải bài toán tin học?', '["Bước 1: Xác định bài toán", "Bước 2: Tìm (Xây dựng) thuật toán", "Bước 3: Viết chương trình", "Bước 4: Kiểm thử và gỡ lỗi"]'::jsonb, 1, 'Biểu diễn các bước giải bằng sơ đồ khối hoặc liệt kê là nội dung của Bước 2: Tìm thuật toán.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-4', 'k9-p25', 4, 'Thông hiểu', 'Trong quy trình 5 bước giải quyết vấn đề (Bài 14) và 4 bước giải bài toán tin học (Bài 15), bước ''Kiểm thử và gỡ lỗi chương trình'' tương ứng với bước nào của quá trình giải quyết vấn đề?', '["Bước 1: Tìm hiểu vấn đề", "Bước 3: Lựa chọn giải pháp", "Bước 5: Đánh giá kết quả", "Bước 2: Phân tích vấn đề"]'::jsonb, 2, 'Kiểm thử và gỡ lỗi chính là hoạt động đánh giá xem chương trình đã tạo ra kết quả đúng mục tiêu hay chưa (tương ứng Bước 5: Đánh giá kết quả).'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-5', 'k9-p25', 5, 'Thông hiểu', 'Ai là người thực hiện việc xây dựng thuật toán và viết chương trình, và ai là đối tượng thực thi chương trình đó để tính ra kết quả nhanh chóng?', '["Máy tính tự nghĩ thuật toán, con người ngồi tính tay", "Con người phân tích, xây dựng thuật toán và viết chương trình; Máy tính thực thi chương trình theo đúng chỉ dẫn để tạo ra kết quả đầu ra", "Máy in tự viết chương trình", "Không cần thuật toán"]'::jsonb, 1, 'Con người đóng vai trò sáng tạo thuật toán và lập trình, còn máy tính là công cụ thực thi tự động tốc độ cao.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-6', 'k9-p25', 6, 'Vận dụng', 'Mục đích của việc thiết kế các bộ dữ liệu kiểm thử (`Test cases`) gồm cặp `(Input mẫu, Output tính trước)` ở Bước 4 là gì?', '["Để làm đẹp giao diện chương trình", "Để nhập `Input mẫu` vào chương trình đang chạy rồi so sánh kết quả máy tính in ra với `Output tính trước`, từ đó phát hiện xem chương trình có lỗi lôgic hay không", "Để xóa mã nguồn chương trình", "Để đổi tên biến"]'::jsonb, 1, 'Đối chiếu kết quả thực tế của chương trình với kết quả tính tay chuẩn (`Expected Output`) là cách duy nhất để xác minh chương trình chạy đúng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-25-7', 'k9-p25', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.D2.1), khi sử dụng AI hỗ trợ sinh mã lệnh chương trình (Code Generation), tại sao người lập trình vẫn bắt buộc phải nắm vững Bước 1, Bước 2 và Bước 4?', '["Vì AI không biết gõ chữ", "Vì con người phải đặc tả đúng `Input/Output` (Bước 1), hiểu thuật toán (Bước 2) để kiểm soát mã lệnh của AI và trực tiếp chạy kiểm thử các trường hợp biên (Bước 4) để sửa lỗi", "Vì AI chỉ làm việc vào ban ngày", "Không cần kiểm thử mã do AI viết"]'::jsonb, 1, 'Mã lệnh do AI gợi ý vẫn có thể chứa lỗi lôgic ở các trường hợp biên, nên con người phải làm chủ đặc tả bài toán, thuật toán và kiểm thử.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-1', 'k9-p26', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong bài toán tính tiền lương theo giờ (SGK trang 68), hai đại lượng Đầu vào (`Input`) cần nhập từ bàn phím là số giờ làm việc `t` và mức thù lao một giờ [___]."', '["a", "nếu không", "2300", "Kiểm thử biên tại `t = 40`"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong bài toán tính tiền lương theo giờ (SGK trang 68), hai đại lượng Đầu vào (`Input`) cần nhập từ bàn phím là số giờ làm việc `t` và mức thù lao một giờ «a».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-2', 'k9-p26', 2, 'Nhận biết', 'Trong `Nhiệm vụ 1` (Bài 16 - SGK Tin học 9 trang 68), bài toán ''Tính tiền lương theo giờ'' có Đầu vào (`Input`) và Đầu ra (`Output`) là gì?', '["`Input`: Tổng tiền lương; `Output`: Số giờ làm việc", "`Input`: Số giờ làm việc `t` và mức thù lao một giờ `a`; `Output`: Tổng tiền lương nhận được", "`Input`: Tên công ty; `Output`: Số lượng nhân viên", "Không cần nhập dữ liệu"]'::jsonb, 1, 'Chương trình nhận vào số giờ `t` và đơn giá `a` từ bàn phím, sau đó tính và xuất ra Tổng tiền lương.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-3', 'k9-p26', 3, 'Nhận biết', 'Theo quy tắc tính lương trong bài thực hành, nếu một người làm việc `t = 42` giờ trong tuần với mức thù lao chuẩn `a = 100` (nghìn đồng/giờ), tổng tiền lương người đó nhận được là bao nhiêu?', '["`4200` nghìn đồng", "`4300` nghìn đồng (vì 40 giờ đầu là `4000`, cộng 2 giờ làm thêm `2 * 1.5 * 100 = 300`)", "`6300` nghìn đồng", "`4000` nghìn đồng"]'::jsonb, 1, 'Áp dụng công thức khi `t > 40`: `(40 + (42 - 40) * 1.5) * 100 = (40 + 3) * 100 = 4300`.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-4', 'k9-p26', 4, 'Thông hiểu', 'Để cài đặt hai công thức tính lương khác nhau tùy thuộc vào điều kiện `t > 40` hay không, khối lệnh điều khiển nào trong Scratch được sử dụng?', '["Khối lệnh `lặp lại (40)`", "Khối lệnh `nếu <(t) > (40)> thì ... nếu không ...` (Rẽ nhánh dạng đủ)", "Khối lệnh `liên tục`", "Khối lệnh `đợi (40) giây`"]'::jsonb, 1, 'Bài toán có 2 nhánh tính toán ứng với điều kiện Đúng (`t > 40`) và Sai (`t <= 40`) nên dùng cấu trúc rẽ nhánh dạng đủ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-5', 'k9-p26', 5, 'Thông hiểu', 'Khi lắp ghép biểu thức `((40) + (((t) - (40)) * (1.5))) * (a)` trong Scratch, phép toán nào nằm ở lớp ngoài cùng bao bọc toàn bộ biểu thức?', '["Phép trừ `(t) - (40)`", "Phép nhân `(...) * (a)`", "Phép cộng `(40) + (...)`", "Phép chia"]'::jsonb, 1, 'Tổng số giờ quy đổi `(40 + (t - 40) * 1.5)` được tính xong trước rồi mới đem nhân tất cả với đơn giá `a`, nên khối nhân với `a` nằm ở lớp ngoài cùng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-6', 'k9-p26', 6, 'Vận dụng', 'Để kiểm thử xem chương trình tính tiền lương đã hoạt động đúng ở cả hai nhánh hay chưa, bộ dữ liệu kiểm thử nào sau đây là ĐẦY ĐỦ và HỢP LÍ nhất?', '["Chỉ thử với `t = 20, a = 50`", "Chỉ thử với `t = 45, a = 50`", "Thử với cả 3 trường hợp: `t < 40` (ví dụ `t = 30`), `t = 40` (ngay tại biên) và `t > 40` (ví dụ `t = 46`)", "Không cần nhập thử số nào"]'::jsonb, 2, 'Kiểm thử đầy đủ cả nhánh `<= 40`, điểm biên `40` và nhánh `> 40` giúp đảm bảo cả hai công thức đều không có lỗi lôgic.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-26-7', 'k9-p26', 7, 'Vận dụng', 'Nếu người dùng nhập nhầm số giờ làm việc là một số âm (ví dụ `t = -5`), để chương trình thông minh hơn và báo lỗi `''Dữ liệu số giờ không hợp lệ!''`, em có thể cải tiến chương trình như thế nào?', '["Thêm một khối kiểm tra điều kiện `nếu <(t) < (0)> thì [nói (Dữ liệu không hợp lệ!)]` ở trước khi tính lương", "Xóa biến `t` đi", "Nhân `t` với `0`", "Đổi màu phông nền"]'::jsonb, 0, 'Bổ sung nhánh kiểm tra tính hợp lệ của dữ liệu đầu vào (`Input Validation`) giúp chương trình xử lí an toàn các trường hợp ngoại lệ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-1', 'k9-p27', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong thuật toán tìm giá trị lớn nhất của một dãy số, biến `Max` dùng để lưu giá trị [___] tìm được tính đến thời điểm hiện tại."', '["lớn nhất", "Max", "âm (< 0)", "Một khái niệm khác"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong thuật toán tìm giá trị lớn nhất của một dãy số, biến `Max` dùng để lưu giá trị «lớn nhất» tìm được tính đến thời điểm hiện tại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-2', 'k9-p27', 2, 'Nhận biết', 'Ý tưởng cốt lõi của thuật toán tìm giá trị lớn nhất (`Max`) trong một dãy số là gì?', '["Cộng tất cả các số trong dãy lại với nhau", "Khởi tạo `Max` bằng phần tử đầu tiên, sau đó lần lượt duyệt qua từng số tiếp theo: nếu gặp số nào lớn hơn `Max` thì cập nhật `Max` bằng số đó", "Lấy số cuối cùng của dãy làm `Max`", "Nhân tất cả các số với 0"]'::jsonb, 1, 'So sánh từng phần tử với giá trị lớn nhất tạm thời (`Max`) và cập nhật khi gặp số lớn hơn là thuật toán chuẩn tìm cực đại.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-3', 'k9-p27', 3, 'Nhận biết', 'Trong chương trình tìm `Max` (SGK trang 70), khối lệnh rẽ nhánh dạng khuyết nào được đặt bên trong vòng lặp để cập nhật `Max` khi số vừa nhập (`trả lời`) lớn hơn `Max`?', '["`nếu <(trả lời) < (Max)> thì [đặt Max thành (trả lời)]`", "`nếu <(trả lời) > (Max)> thì [đặt Max thành (trả lời)]`", "`nếu <(trả lời) = (0)> thì [đặt Max thành (0)]`", "`thay đổi [Max] một lượng (trả lời)`"]'::jsonb, 1, 'Khi giá trị mới nhập vào lớn hơn `Max` hiện tại (`trả lời > Max`), ta gán lại `Max` bằng giá trị mới đó.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-4', 'k9-p27', 4, 'Thông hiểu', 'Tại sao chương trình khởi tạo `đặt [Max] thành (0)` ở đầu bài thực hành SGK trang 70 lại chạy ĐÚNG với dãy số dương `(3, 8, 5)` nhưng lại chạy SAI với dãy toàn số âm `(-6, -2, -9)`?', '["Vì Scratch không nhập được dấu trừ", "Vì mọi số trong dãy `(-6, -2, -9)` đều nhỏ hơn `0`, điều kiện `trả lời > Max` luôn Sai nên chương trình trả về `Max = 0` (là số không có trong dãy) thay vì `-2`", "Vì máy tính bị hết pin", "Vì số `-9` lớn hơn số `0`"]'::jsonb, 1, 'Khởi tạo `Max = 0` ngầm giả định trong dãy có số `>= 0`; khi dãy toàn số âm thì `0` lớn hơn mọi phần tử trong dãy gây ra lỗi lôgic.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-5', 'k9-p27', 5, 'Thông hiểu', 'Cách sửa lỗi khởi tạo nào sau đây giúp chương trình tìm `Max` chạy ĐÚNG cho mọi dãy số (kể cả dãy toàn số dương, toàn số âm hay lẫn lộn)?', '["Đặt `Max = 100` ở đầu chương trình", "Nhập phần tử đầu tiên của dãy trước và gán `đặt [Max] thành (trả lời)` làm mốc so sánh ban đầu, sau đó mới lặp nhập và so sánh các phần tử tiếp theo", "Đặt `Max = -1`", "Xóa khối lệnh `nếu ... thì`"]'::jsonb, 1, 'Lấy chính phần tử đầu tiên của dãy làm giá trị khởi tạo cho `Max` đảm bảo `Max` luôn là một phần tử thực sự thuộc dãy số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-6', 'k9-p27', 6, 'Vận dụng', 'Cho dãy gồm 5 số lần lượt nhập vào là: `12`, `25`, `18`, `30`, `22`. Nếu khởi tạo `Max = 12` (số đầu tiên), trong quá trình duyệt 4 số còn lại, biến `Max` sẽ được cập nhật giá trị mới mấy lần?', '["1 lần", "2 lần (lần 1 cập nhật từ `12` lên `25`, lần 2 cập nhật từ `25` lên `30`)", "4 lần", "0 lần"]'::jsonb, 1, 'Khi gặp `25 > 12` (`Max` thành `25`), gặp `18 < 25` (giữ nguyên), gặp `30 > 25` (`Max` thành `30`), gặp `22 < 30` (giữ nguyên). Tổng cộng cập nhật 2 lần.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-27-7', 'k9-p27', 7, 'Vận dụng', 'Qua bài thực hành `Nhiệm vụ 2`, vai trò của việc kiểm thử chương trình với nhiều bộ dữ liệu khác nhau (số tự nhiên, số thập phân, số âm) là gì?', '["Chỉ để mất thời gian", "Giúp phát hiện những lỗi lôgic tiềm ẩn (như lỗi với dãy số âm) mà nếu chỉ thử 1 bộ dữ liệu số dương thông thường sẽ không nhận ra được", "Để làm cho tệp `.sb3` nặng hơn", "Để xóa phần mềm Scratch"]'::jsonb, 1, 'Kiểm thử đa dạng các miền giá trị dữ liệu (đặc biệt là số âm, số thực, giá trị biên) là kỹ năng cốt lõi để đảm bảo chương trình tin cậy.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-1', 'k9-p28', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Trong Chương trình Giáo dục phổ thông 2018 ở cấp THPT, môn Tin học được phân hóa thành hai định hướng chính là: Khoa học máy tính và Tin học [___]."', '["ứng dụng", "Phát triển", "mạng", "Nhóm nghề Phát triển phần mềm"]'::jsonb, 0, 'Theo SGK Tin học 9: Trong Chương trình Giáo dục phổ thông 2018 ở cấp THPT, môn Tin học được phân hóa thành hai định hướng chính là: Khoa học máy tính và Tin học «ứng dụng».'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-2', 'k9-p28', 2, 'Nhận biết', 'Hai định hướng của môn Tin học ở cấp Trung học phổ thông theo Chương trình GDPT 2018 (SGK Tin học 9 Bài 17) là gì?', '["Phần cứng và Phần mềm", "Khoa học máy tính (`Computer Science`) và Tin học ứng dụng (`Applied Informatics`)", "Soạn thảo văn bản và Bảng tính", "Trò chơi điện tử và Mạng xã hội"]'::jsonb, 1, 'Từ lớp 8–9 và lên cấp THPT, môn Tin học phân hóa rõ thành 2 định hướng: Khoa học máy tính và Tin học ứng dụng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-3', 'k9-p28', 3, 'Nhận biết', 'Một học sinh rất đam mê tìm hiểu thuật toán, thích lập trình giải các bài toán khó và mơ ước tự viết ra các phần mềm ứng dụng hoặc mô hình AI mới. Học sinh đó nên chọn định hướng nào khi lên lớp 10?', '["Định hướng Khoa học máy tính (`CS`)", "Định hướng Tin học ứng dụng (`ICT`)", "Không học môn Tin học", "Chỉ học gõ văn bản"]'::jsonb, 0, 'Định hướng Khoa học máy tính chuyên sâu về thuật toán, lập trình và nguyên lí phát triển hệ thống phần mềm/AI.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-4', 'k9-p28', 4, 'Thông hiểu', 'Một học sinh yêu thích thiết kế đồ họa kỹ thuật số, dựng video đa phương tiện, thiết kế trang web truyền thông và sử dụng phần mềm cơ sở dữ liệu phục vụ quản lí kinh doanh. Định hướng nào ở lớp 10 phù hợp nhất với bạn?', '["Định hướng Khoa học máy tính", "Định hướng Tin học ứng dụng (`ICT`)", "Chỉ học sửa chữa điện dân dụng", "Không dùng máy tính"]'::jsonb, 1, 'Định hướng Tin học ứng dụng trang bị kỹ năng thiết kế đồ họa, đa phương tiện, tạo trang web và khai thác cơ sở dữ liệu thực tiễn.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-5', 'k9-p28', 5, 'Thông hiểu', 'Sản phẩm chính của những người làm nghề ''Phát triển phần mềm'' (`Software Developer / Programmer`) là gì?', '["Dây cáp mạng và ốc vít", "Các chương trình, phần mềm máy tính, ứng dụng trên điện thoại thông minh, hệ thống web và trò chơi điện tử", "Bàn ghế văn phòng", "Hóa đơn tiền điện"]'::jsonb, 1, 'Người phát triển phần mềm thiết kế, viết mã và kiểm thử để tạo ra các sản phẩm phần mềm hoàn chỉnh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-6', 'k9-p28', 6, 'Vận dụng', 'Nhóm nghề nào có nhiệm vụ thiết kế cấu trúc lưu trữ dữ liệu lớn của ngân hàng, bệnh viện, trường học và đảm bảo dữ liệu luôn toàn vẹn, truy xuất nhanh chóng, không bị mất mát?', '["Nghề Sửa chữa màn hình", "Nghề Quản trị và thiết kế cơ sở dữ liệu (`Database Designer & Administrator`)", "Nghề Thiết kế thời trang", "Nghề Biên tập âm thanh"]'::jsonb, 1, 'Quản trị và thiết kế cơ sở dữ liệu chịu trách nhiệm về kiến trúc, hiệu năng và sự an toàn của các kho dữ liệu số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-28-7', 'k9-p28', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.A3.3), sự phát triển mạnh mẽ của Trí tuệ nhân tạo (AI) tác động như thế nào đến các nhóm nghề Tin học?', '["Xóa bỏ hoàn toàn ngành Công nghệ thông tin", "Trở thành trợ lí đắc lực giúp lập trình viên viết mã, kiểm thử nhanh hơn, đồng thời mở ra các nghề mới như Kỹ sư AI, Khoa học dữ liệu và đòi hỏi con người nâng cao tư duy thiết kế hệ thống", "Làm cho máy tính chạy chậm lại", "Không có tác động gì"]'::jsonb, 1, 'AI chuyển dịch công việc từ thao tác mã lệnh lặp lại sang tư duy kiến trúc hệ thống, kiểm chứng chất lượng và sáng tạo giải pháp mới.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-1', 'k9-p29', 1, 'Nhận biết', 'Chọn từ/cụm từ thích hợp điền vào chỗ trống: "Người làm nghề tin học có thể làm việc tại các doanh nghiệp chuyên về công nghệ thông tin hoặc tại bộ phận CNTT của mọi cơ quan, tổ chức để vận hành hệ thống và thúc đẩy [___] số."', '["chuyển đổi", "tự học", "bình đẳng", "Bình đẳng giới trong nghề nghiệp Tin học"]'::jsonb, 0, 'Theo SGK Tin học 9: Người làm nghề tin học có thể làm việc tại các doanh nghiệp chuyên về công nghệ thông tin hoặc tại bộ phận CNTT của mọi cơ quan, tổ chức để vận hành hệ thống và thúc đẩy «chuyển đổi» số.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-2', 'k9-p29', 2, 'Nhận biết', 'Người tốt nghiệp các ngành thuộc lĩnh vực Tin học có thể làm việc ở những đâu?', '["Chỉ làm việc được ở cửa hàng bán linh kiện máy tính", "Làm việc tại các công ty sản xuất phần mềm/dịch vụ CNTT, các viện nghiên cứu, hoặc tại bộ phận CNTT của hầu hết các cơ quan nhà nước, ngân hàng, bệnh viện, trường học, doanh nghiệp", "Chỉ làm việc ở phòng thực hành trường THCS", "Không thể làm việc ở ngân hàng"]'::jsonb, 1, 'Mọi tổ chức trong xã hội hiện đại đều ứng dụng CNTT và chuyển đổi số nên cơ hội việc làm của nghề Tin học rộng mở ở khắp mọi nơi.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-3', 'k9-p29', 3, 'Nhận biết', 'Đặc điểm nào sau đây phản ánh ĐÚNG yêu cầu đối với người làm nghề trong lĩnh vực Tin học?', '["Chỉ cần học một lần ở trường là dùng được suốt đời không cần đọc thêm gì mới", "Công nghệ thông tin thay đổi rất nhanh nên đòi hỏi người làm nghề phải luôn chủ động tự học, cập nhật công nghệ mới, có kỹ năng ngoại ngữ và làm việc nhóm tốt", "Làm việc hoàn toàn đơn độc không cần giao tiếp với khách hàng hay đồng nghiệp", "Chỉ cần biết gõ bàn phím bằng 10 ngón tay"]'::jsonb, 1, 'Tốc độ đổi mới công nghệ (như AI, Cloud, Cybersecurity) đòi hỏi năng lực tự học liên tục và kỹ năng hợp tác, ngoại ngữ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-4', 'k9-p29', 4, 'Thông hiểu', 'Vì sao nói cả nam giới và nữ giới đều thích hợp với các ngành nghề trong lĩnh vực Tin học?', '["Vì công việc tin học là lao động trí óc dựa trên tư duy logic, óc sáng tạo, sự kiên trì, tỉ mỉ và kỹ năng giao tiếp hợp tác — những phẩm chất mà cả nam và nữ đều có thể phát huy xuất sắc", "Vì máy tính chỉ nhận diện được khuôn mặt nữ giới", "Vì công việc tin học không cần suy nghĩ", "Vì pháp luật bắt buộc mọi người đều phải làm lập trình viên"]'::jsonb, 0, 'Lĩnh vực Tin học không đòi hỏi lao động cơ bắp nặng nhọc mà dựa vào trí tuệ và kỹ năng số, tạo sự bình đẳng hoàn toàn giữa nam và nữ.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-5', 'k9-p29', 5, 'Thông hiểu', 'Những vị trí công việc nào trong dự án phát triển phần mềm tại doanh nghiệp rất cần đến sự tỉ mỉ, cẩn thận và khả năng thấu hiểu người dùng?', '["Chỉ có việc khuân vác máy chủ", "Phân tích nghiệp vụ (`Business Analyst`), Thiết kế trải nghiệm & giao diện người dùng (`UI/UX Designer`), Kiểm thử đảm bảo chất lượng phần mềm (`QA/Tester`), Lập trình viên và Quản trị dự án", "Không có vị trí nào", "Chỉ có nhân viên bảo vệ"]'::jsonb, 1, 'Một dự án CNTT thành công cần sự phối hợp của nhiều vai trò từ phân tích, thiết kế giao diện, lập trình đến kiểm thử chất lượng.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-6', 'k9-p29', 6, 'Vận dụng', 'Kỹ năng ngoại ngữ (đặc biệt là tiếng Anh) giúp ích gì cho người học và làm nghề Tin học?', '["Không có tác dụng gì vì máy tính dùng tiếng Việt", "Giúp đọc hiểu trực tiếp các tài liệu kỹ thuật mới nhất trên thế giới, sử dụng thành thạo các ngôn ngữ lập trình/phần mềm chuẩn quốc tế và làm việc trong các dự án toàn cầu", "Chỉ để đi du lịch", "Để thay thế cho kiến thức Toán học"]'::jsonb, 1, 'Hầu hết ngôn ngữ lập trình, tài liệu công nghệ gốc và môi trường cộng tác CNTT quốc tế đều sử dụng tiếng Anh.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.practice_questions (
  id, period_id, question_index, cognitive_level, question_text, options_json, correct_index, explanation
) VALUES (
  'rq-9-29-7', 'k9-p29', 7, 'Vận dụng', 'Theo Khung năng lực AI (9.A3.3 & 9.B3.1), thông điệp hướng nghiệp nào sau đây là ĐÚNG ĐẮN NHẤT dành cho học sinh lớp 9 trước ngưỡng cửa THPT?', '["Hãy sợ hãi AI vì AI sẽ lấy hết việc làm của con người", "Dù là nam hay nữ, dù chọn chuyên sâu Khoa học máy tính hay Tin học ứng dụng hay bất kỳ ngành nghề nào khác, việc trang bị vững vàng năng lực số và làm chủ AI có đạo đức sẽ giúp em tự tin kiến tạo tương lai", "Nữ sinh không nên chọn tổ hợp có môn Tin học ở lớp 10", "Chỉ cần biết dùng AI viết văn là đủ"]'::jsonb, 1, 'Xóa bỏ định kiến giới và chủ động làm chủ năng lực số cùng Trí tuệ nhân tạo là hành trang vững chắc nhất cho thế hệ công dân số tương lai.'
) ON CONFLICT (id) DO UPDATE SET
  cognitive_level = EXCLUDED.cognitive_level, question_text = EXCLUDED.question_text, options_json = EXCLUDED.options_json, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;